                    nam       c.comp
                    ttl       program module

* Annotated 2026-07-13 (Claude Code):
*   - renamed disassembled labels (code, data and the static storage block) to meaningful names
*   - added inline comments describing the compiler's flow
*   - re-disassembled the "**** STACK OVERFLOW ****" message text (was decoded as code)
*   - verified byte-identical to the original assembly (module CRC $8FDC90)

                    use       defsfile

tylg                set       Prgrm+Objct
atrv                set       ReEnt+rev
rev                 set       $01
edition             set       $05

                    mod       eom,name,tylg,atrv,_start,size

WorkArea            rmb       4389
size                equ       .

name                equ       *
                    fcs       /c.comp/
                    fcb       edition

copybytes           lda       ,y+       load source byte
                    sta       ,u+       store byte to destination
                    leax      -$01,x    decrement byte count
                    bne       copybytes loop until count zero
                    rts                 return from copy

* Direct-page global variables.  The disassembler resolved these direct-page
* references (<$1F, <$21, ...) to code labels at the same low addresses; they
* are really the compiler's DP globals, defined here with their own names.
GlbSrcLine          equ       $001F     current source line/file info
GlbNestDepth        equ       $0021     declarator nesting / scope depth
GlbFreeList         equ       $0025     node free-list head
GlbMemLow           equ       $0046     memory low watermark
GlbMemHigh          equ       $0048     memory high watermark
GlbStrList          equ       $004C     string list / string file handle
GlbPassMode         equ       $0056     pass / init mode flag
GlbFirstCall        equ       $0058     first-call primed flag
GlbFrameLbl         equ       $005C     frame-size label number
GlbNodePtr          equ       $006A     current node / list pointer
GlbListTail         equ       $006C     list tail pointer
GlbOutPtr           equ       $0070     output buffer / destination pointer

_start              pshs      y         save incoming y
                    pshs      u         save data base pointer
                    clra                a = 0 fill value
                    clrb                b = 0, wraps to 256 count
FreeBlkList         sta       ,u+       zero a byte
                    decb                decrement fill counter
                    bne       FreeBlkList clear 256 bytes
                    ldx       ,s        x = data base
                    leau      ,x        u = data base
                    leax      $08A5,x   x = top of data plus stack
                    pshs      x         save top pointer
                    leay      WorkBlockInitImage,pcr y = init/relocation table
                    ldx       ,y++      x = first init block size
                    beq       AdvanceBss skip if block empty
                    bsr       copybytes copy initialized data block
                    ldu       $02,s     reload data base
AdvanceBss          leau      >$0078,u  advance to bss region
                    ldx       ,y++      x = second block size
                    beq       ClrBssLoop skip if empty
                    bsr       copybytes copy second block
                    clra                a = 0 fill value
ClrBssLoop          cmpu      ,s        reached top of bss yet
                    beq       InFileFlag done clearing bss
                    sta       ,u+       zero a bss byte
                    bra       ClrBssLoop continue clearing bss

InFileFlag          ldu       $02,s     reload data base
                    ldd       ,y++      d = code reloc size
                    beq       GetReloc2 skip if none
                    leax      >$0000,pcr x = code base address
                    lbsr      ApplyReloc apply code relocations
GetReloc2           ldd       ,y++      d = data reloc size
                    beq       SetupArgv skip if none
                    leax      ,u        x = data base address
                    lbsr      ApplyReloc apply data relocations
SetupArgv           leas      $04,s     drop local pointers
                    puls      x         x = top pointer
                    stx       $0356,u   store stack top
                    sty       $0316,u   store argv table pointer
                    ldd       #$0001    d = 1
                    std       $0352,u   argc = 1
                    leay      $0318,u   y = argv array
                    leax      ,s        x = command-line string
                    lda       ,x+       get first char
ScanArg             ldb       $0353,u   b = current arg count
                    cmpb      #$1d      reached 29 args
                    beq       RunMain   stop scanning
SkipSep             cmpa      #$0d      carriage return
                    beq       RunMain   end of line
                    cmpa      #$20      is it a space
                    beq       NextSepChar skip the separator
                    cmpa      #$2C      is it a comma
                    bne       CheckQuote not a separator
NextSepChar         lda       ,x+       get next char
                    bra       SkipSep   keep skipping separators

CheckQuote          cmpa      #$22      is it a double quote
                    beq       QuotedArg handle quoted arg
                    cmpa      #$27      is it a single quote
                    bne       PlainArg  handle plain arg
QuotedArg           stx       ,y++      store arg pointer
                    inc       $0353,u   increment arg count
                    pshs      a         save quote char
QuoteScan           lda       ,x+       get char inside quotes
                    cmpa      #$0d      carriage return
                    beq       QuoteEnd  unterminated quote
                    cmpa      ,s        matching quote char
                    bne       QuoteScan keep scanning quoted text
QuoteEnd            puls      b         drop saved quote char
                    clr       -$01,x    null-terminate arg
                    cmpa      #$0d      was it end of line
                    beq       RunMain   done scanning args
                    lda       ,x+       get next char
                    bra       ScanArg   scan next argument

PlainArg            leax      -$01,x    back up to first char
                    stx       ,y++      store arg pointer
                    leax      $01,x     restore scan position
                    inc       $0353,u   increment arg count
PlainScan           cmpa      #$0d      carriage return
                    beq       PlainEnd  end of argument
                    cmpa      #$20      is it a space
                    beq       PlainEnd  end of argument
                    cmpa      #$2C      is it a comma
                    beq       PlainEnd  end of argument
                    lda       ,x+       get next char
                    bra       PlainScan scan plain argument

PlainEnd            clr       -$01,x    null-terminate arg
                    bra       ScanArg   scan next argument

RunMain             leax      $0316,u   x = argv table
                    pshs      x         push argv
                    ldd       $0352,u   d = argc
                    pshs      d         push argc
                    leay      ,u        y = data base
                    bsr       stkinit   set up stack limits
                    lbsr      main      call main
                    clr       ,-s       push exit code low byte
                    clr       ,-s       push exit code high byte
                    lbsr      exit      exit with status zero
stkinit             leax      $08A5,y   x = stack top
                    stx       $0360,y   store stack base limit
                    sts       $0354,y   store initial sp
                    sts       $0362,y   store low-water mark
                    ldd       #$FF82    d = margin below sp
stkcheck            leax      d,s       x = sp minus margin
                    cmpx      $0362,y   below low-water mark
                    bcc       StkChkOk  no, still ok
                    cmpx      $0360,y   past stack base
                    bcs       StkOvfErr stack overflow
                    stx       $0362,y   update low-water mark
StkChkOk            rts                 return

StkOvfMsg           fcc       /**** STACK OVERFLOW ****/
                    fcb       $0D
StkOvfErr           leax      StkOvfMsg,pcr x = overflow message
                    ldb       #$CF      b = message length
                    pshs      b         push length
                    lda       #$02      path = stderr
                    ldy       #$0064    y = parameter block
                    os9       I$WritLn  write overflow message
                    clr       ,-s       push exit status
                    lbsr      DoExit    terminate program
                    ldd       $0354,y   d = initial sp
                    subd      $0362,y   minus low-water = bytes used
                    rts                 return
                    ldd       $0362,y   d = low-water mark
                    subd      $0360,y   minus base = bytes free
                    rts                 return

ApplyReloc          pshs      x         save base pointer
                    leax      d,y       x = descriptor plus offset
                    leax      d,x       add offset again
                    pshs      x         save end pointer
RelocLoop           ldd       ,y++      d = relocation offset
                    leax      d,u       x = target address
                    ldd       ,x        d = value at target
                    addd      $02,s     add relocation base
                    std       ,x        store fixed-up value
                    cmpy      ,s        done all entries
                    bne       RelocLoop next relocation
                    leas      $04,s     drop local pointers
                    rts                 return

main                pshs      u         save u
                    leax      FlushStringPool,pcr x = init routine pointer
                    pshs      x         push argument
                    lbsr      SetupIntercept register startup routine
                    leas      $02,s     drop argument
                    leax      $0096,y   x = work area
                    pshs      x         push argument
                    lbsr      SubstXPlaceholder initialize subsystem
                    leas      $02,s     drop argument
                    leax      StrDummy,pcr x = dummy symbol name
                    pshs      x         push name
                    ldd       $0094,y   d = flags value
                    pshs      d         push value
                    lbsr      StrCpy    create dummy symbol
                    leas      $04,s     drop arguments
                    lbsr      InstallKeywords initialize tables
                    leax      $0246,y   x = output file struct
                    stx       $0003     store output file pointer
                    leax      $0253,y   x = stderr struct
                    stx       $0005     store error file pointer
                    lbra      ArgLoopNext enter argument loop

ArgLoop             ldx       $06,s     x = argv pointer
                    leax      $02,x     advance to next arg
                    stx       $06,s     save argv pointer
                    ldu       ,x        u = current argument string
                    ldb       ,u        b = first char
                    cmpb      #$2d      is it a dash
                    lbne      InputFile no, treat as filename
                    lbra      NextOptChar yes, scan option chars

OptCharLoad         ldb       ,u        b = option char
                    sex                 sign-extend to d
                    tfr       d,x       x = option char
                    lbra      OptDispatch dispatch on option letter

OptS                ldd       #$0001    d = 1
                    std       $0015     set -s flag
                    lbra      NextOptChar next option char

OptN                ldd       $0019     d = -n counter
                    addd      #$0001    increment counter
                    std       $0019     store counter
                    lbra      NextOptChar next option char

OptO                leau      $01,u     skip the o letter
                    ldb       ,u        b = next char
                    cmpb      #$3d      is it an equals
                    bne       OptODone  no, malformed option
                    leax      StrModeW,pcr x = write-mode string
                    pshs      x         push mode
                    leau      $01,u     skip the equals
                    pshs      u         push filename
                    lbsr      BuildOperand2 fopen output file
                    leas      $04,s     drop arguments
                    std       $0005     store output file pointer
                    bne       OptODone  opened, continue
                    pshs      u         push filename
                    leax      MsgCantOpen,pcr x = can't-open format
                    pshs      x         push format
                    leax      $0260,y   x = stderr stream
                    pshs      x         push stream
                    lbsr      fprintf   print open error
                    leas      $06,s     drop arguments
                    lbsr      ExitErr   exit with failure
OptODone            leax      ,s        x = stack pointer
                    bra       OptORestore resume argument loop

OptP                ldd       #$0001    d = 1
                    std       $0017     set -p flag
                    bra       NextOptChar next option char

UnknownFlag         ldb       ,u        b = unknown flag char
                    sex                 sign-extend to d
                    pshs      d         push char
                    leax      MsgUnknownFlag,pcr x = unknown-flag format
                    pshs      x         push format
                    leax      $0260,y   x = stderr stream
                    pshs      x         push stream
                    lbsr      fprintf   print warning
                    leas      $06,s     drop arguments
                    lbsr      ExitErr   exit with failure
                    bra       NextOptChar next option char

OptDispatch         cmpx      #$0073    is option letter s
                    lbeq      OptS      handle -s
                    cmpx      #$006E    is option letter n
                    lbeq      OptN      handle -n
                    cmpx      #$006F    is option letter o
                    lbeq      OptO      handle -o
                    cmpx      #$0070    is option letter p
                    beq       OptP      handle -p
                    bra       UnknownFlag unknown flag

NextOptChar         leau      $01,u     advance in option string
                    ldb       ,u        b = next char
                    lbne      OptCharLoad more option chars
                    bra       ArgLoopNext done, go to next arg

OptORestore         leas      ,x        restore stack pointer
                    bra       ArgLoopNext next argument

InputFile           ldd       InFileFlag d = input-open flag
                    bne       ArgLoopNext already have input, skip
                    ldd       InFileFlag d = input-open flag
                    addd      #$0001    set flag to one
                    std       InFileFlag mark input opened
                    leax      $0246,y   x = input file struct
                    pshs      x         push struct
                    leax      StrModeR,pcr x = read-mode string
                    pshs      x         push mode
                    ldd       [$0a,s]   d = filename pointer
                    pshs      d         push filename
                    lbsr      BuildOperandEval fopen input file
                    leas      $06,s     drop arguments
                    std       $0003     store input file pointer
                    bne       ArgLoopNext opened, next arg
                    leax      MsgCantOpenIn,pcr x = can't-open input message
                    pshs      x         push message
                    lbsr      PrintMsg  print error
                    leas      $02,s     drop argument
ArgLoopNext         ldd       $04,s     d = argc counter
                    addd      #$FFFF    decrement counter
                    std       $04,s     store counter
                    lbgt      ArgLoop   more args to process
                    lbsr      ResetInputBuf run parser and compile
                    lbsr      ParseStatement2 generate output code
                    bra       EmitCheck enter emit-check loop

EmitItem            lbsr      ParseUnaryExpr emit one output item
EmitCheck           ldd       $003F     d = work queue head
                    cmpd      #$FFFF    queue empty
                    bne       EmitItem  more items to emit
                    lbsr      EmitProgramEnd finalize output
                    ldx       $0005     x = error file struct
                    ldd       $06,x     d = file status flags
                    clra                clear high byte
                    andb      #$20      test write-error bit
                    beq       FlushErr  no write error
                    leax      MsgWriteErr,pcr x = write-error message
                    pshs      x         push message
                    lbsr      PrintMsg  print error
                    leas      $02,s     drop argument
FlushErr            leax      $0253,y   x = stderr struct
                    pshs      x         push stream
                    lbsr      CheckWritable flush and close stream
                    leas      $02,s     drop argument
                    ldd       $0009     d = compilation error count
                    beq       MainDone  none, done
                    ldd       $0009     d = error count
                    pshs      d         push count
                    leax      MsgErrCount,pcr x = error-count format
                    pshs      x         push format
                    leax      $0260,y   x = stderr stream
                    pshs      x         push stream
                    lbsr      fprintf   print error summary
                    leas      $06,s     drop arguments
                    bsr       ExitErr   exit with failure
MainDone            puls      pc,u      return from main

ExitErr             pshs      u         save u
                    ldd       #$0001    exit code = 1
                    pshs      d         push exit code
                    lbsr      exit      exit with failure
                    leas      $02,s     drop exit code
                    puls      pc,u      return (unreached)

StrDummy            fcc       /_dummy_/
                    fcb       $00
StrModeW            fcb       $77
                    fcb       $00
MsgCantOpen         fcc       /can't open %s/
                    fcb       $0D,$00
MsgUnknownFlag      fcc       /unknown flag : -%c/
                    fcb       $0D,$00
StrModeR            fcb       $72
                    fcb       $00
MsgCantOpenIn       fcc       /can't open input file/
                    fcb       $00
MsgWriteErr         fcc       /error writing assembly code file/
                    fcb       $00
MsgErrCount         fcc       /errors in compilation : %d/
                    fcb       $0D,$00
AllocBlk            pshs      u         save u
                    ldu       $04,s     u = argument pointer
                    leas      -$06,s    allocate locals
                    ldd       FreeBlkList d = free-list head
                    std       $02,s     save head pointer
                    beq       AllocNew  list empty, allocate new
                    ldx       $02,s     x = free block
                    ldd       $10,x     d = next-block link
                    std       FreeBlkList pop block from free list
                    bra       AllocInit initialize the block

AllocNew            ldd       #$0012    size = 18 bytes
                    pshs      d         push size
                    lbsr      AllocMem  malloc a block
                    leas      $02,s     drop size
                    std       $02,s     save block pointer
AllocInit           ldd       #$0012    length = 18 bytes
                    pshs      d         push length
                    ldd       $04,s     d = source pointer
                    pshs      d         push source
                    stu       $08,s     save u as dest
                    pshs      u         push dest
                    bsr       CopyMem   copy 18 bytes into block
                    leas      $06,s     drop arguments
                    ldd       #$0009    count = 9 words
                    std       ,s        set counter
                    bra       AllocZeroChk enter zero loop

AllocZeroLoop       clra                a = 0
                    clrb                b = 0
                    std       ,u++      zero one word
AllocZeroChk        ldd       ,s        d = word counter
                    addd      #$FFFF    decrement counter
                    std       ,s        store counter
                    subd      #$FFFF    test counter for zero
                    bne       AllocZeroLoop zero more words
                    ldd       $02,s     d = block pointer
                    ldx       $04,s     x = destination struct
                    std       $0e,x     store block pointer in field
                    lbra      CleanupRet6 return the block

FreeBlk             pshs      u         save u
                    ldu       $04,s     u = block to free
                    leas      -$02,s    allocate local
                    ldd       $0e,u     d = block-pointer field
                    std       ,s        save it
                    ldd       #$0012    length = 18 bytes
                    pshs      d         push length
                    pshs      u         push block argument
                    ldd       $04,s     d = source pointer
                    pshs      d         push source
                    bsr       CopyMem   copy 18 bytes out
                    leas      $06,s     drop arguments
                    ldd       FreeBlkList d = free-list head
                    ldx       ,s        x = freed block
                    std       $10,x     link old head into block
                    ldd       ,s        d = freed block
                    std       FreeBlkList push block onto free list
                    lbra      DropArgReturn return

CopyMem             pshs      u         save u
                    ldu       $04,s     u = source pointer
                    bra       CopyMemChk enter copy loop

CopyMemLoop         ldb       ,u+       load source byte
                    ldx       $06,s     x = destination pointer
                    leax      $01,x     advance destination
                    stx       $06,s     save destination pointer
                    stb       -$01,x    store byte
CopyMemChk          ldd       $08,s     d = byte count
                    addd      #$FFFF    decrement count
                    std       $08,s     store count
                    subd      #$FFFF    test count for zero
                    bne       CopyMemLoop copy next byte
                    puls      pc,u      return

PrintNamePfx        pshs      u         save u
                    leax      $0366,y   x = name buffer
                    pshs      x         push name
                    leax      FmtNameColon,pcr x = name-prefix format
                    pshs      x         push format
                    lbsr      ErrPrintf print to stderr
                    lbra      PutCharDone return

PrintMsg            pshs      u         save u
                    ldd       $04,s     d = message pointer
                    pshs      d         push message
                    bsr       BuildMsgBuf format into buffer
                    leas      $02,s     drop argument
                    leax      $0260,y   x = stderr stream
                    pshs      x         push stream
                    lbsr      CheckWritable write buffer to stderr
                    lbra      AbortTail return

ErrMultiDef         pshs      u         save u
                    leax      MsgMultiDef,pcr x = multiple-definition message
                    pshs      x         push message
                    bsr       BuildMsgBuf format into buffer
                    lbra      DropArgReturn return

BuildMsgBuf         pshs      u         save u
                    ldd       GlbSrcLine d = buffer state global
                    pshs      d         push it
                    ldd       $06,s     d = message pointer
                    pshs      d         push message
                    leax      $0584,y   x = work buffer
                    pshs      x         push buffer
                    ldd       $0043     d = current position
                    bra       ComputeCaretCol build the message

InternalErr         pshs      u         save u
                    leas      -$32,s    allocate 50-byte buffer
                    leax      MsgCompilerErr,pcr x = compiler-error message
                    pshs      x         push message
                    leax      $02,s     point X at local arguments
                    pshs      x         push argument pointer
                    lbsr      StrCpy    call formatting helper
                    leas      $04,s     drop two arguments
                    ldd       $38,s     load caller value
                    pshs      d         push it
                    leax      $02,s     point X at locals
                    pshs      x         push pointer argument
                    lbsr      StrCat    call formatting helper
                    leas      $04,s     drop arguments
                    leax      ,s        point X at stack top
                    pshs      x         push pointer argument
                    ldd       $38,s     reload caller value
                    pshs      d         push as argument
                    bsr       ReportErrorAt report error at this location
                    leas      $04,s     drop arguments
                    leas      $32,s     release local frame
                    puls      pc,u      restore and return

ReportErrorAt       pshs      u         save U
                    ldu       $04,s     U = error record pointer
                    ldd       $0e,u     load base column field
                    pshs      d         push it
                    ldd       $08,s     load line-position argument
                    pshs      d         push it
                    leax      $0584,y   point at source line buffer
                    pshs      x         push buffer pointer
                    ldd       $10,u     load error column field
ComputeCaretCol     subd      ,s++      column = errcol minus base
                    pshs      d         push caret column
                    bsr       FormatErrorLine format and print error line
                    lbra      CleanupRet6 clean up and return

FormatErrorLine     pshs      u         save U
                    ldu       $04,s     U = source line buffer
                    lbsr      PrintNamePfx prepare output line
                    ldd       $08,s     load line number
                    pshs      d         push it
                    leax      FmtLineNum,pcr line number format string
                    pshs      x         push format pointer
                    lbsr      ErrPrintf fprintf the line number
                    leas      $04,s     drop arguments
                    ldd       $06,s     source buffer pointer
                    pshs      d         push it
                    leax      FmtStars,pcr starred source-line format
                    pshs      x         push format pointer
                    lbsr      ErrPrintf fprintf the source line
                    leas      $04,s     drop arguments
                    ldd       $08,s     load caret column
                    cmpd      $0007     compare to marker base
                    bne       CaretFromBuf2 differs, use second buffer
                    leax      $0584,y   first source buffer
                    pshs      x         push buffer pointer
                    lbsr      PutErrString print the string
                    leas      $02,s     drop argument
                    leax      ,s        X = stack pointer
                    bra       SetCaretPtr set caret pointer

CaretFromBuf2       ldd       $0007     load marker base
                    addd      #$FFFF    subtract one
                    cmpd      $08,s     compare caret column
                    bne       BumpErrorCount no caret, skip to count
                    leax      $0684,y   second source buffer
                    pshs      x         push buffer pointer
                    lbsr      PutErrString print the string
                    leas      $02,s     drop argument
                    bra       SpaceLoopTest enter space loop

SetCaretPtr         leas      ,x        restore stack to X
                    bra       SpaceLoopTest enter space loop

EmitSpaceLoop       ldd       #$0020    space character
                    pshs      d         push it
                    lbsr      PutErrChar output a space
                    leas      $02,s     drop argument
                    leau      -$01,u    decrement column count
SpaceLoopTest       cmpu      #$0000    any columns left
                    bgt       EmitSpaceLoop keep emitting spaces
                    leax      CharCaret,pcr caret marker string
                    pshs      x         push pointer
                    bsr       PutErrString print the caret
                    leas      $02,s     drop argument
BumpErrorCount      ldd       $0009     load error count
                    addd      #$0001    increment it
                    std       $0009     store back
                    cmpd      #$001E    reached 30 errors
                    ble       ErrLineDone under limit, done
                    leax      $0260,y   error stream pointer
                    pshs      x         push it
                    lbsr      CheckWritable flush the stream
                    leas      $02,s     drop argument
                    leax      MsgTooManyErr,pcr too many errors message
                    pshs      x         push pointer
                    bsr       PutErrString print abort message
AbortTail           leas      $02,s     drop argument
                    lbsr      FlushStringPool exit the compiler
ErrLineDone         puls      pc,u      restore and return

ErrPrintf           pshs      u         save U
                    ldd       $08,s     first varargs value
                    pshs      d         push it
                    ldd       $08,s     second value
                    pshs      d         push it
                    ldd       $08,s     format string pointer
                    pshs      d         push it
                    leax      $0260,y   error stream pointer
                    pshs      x         push it
                    lbsr      fprintf   formatted output
                    leas      $08,s     drop arguments
                    puls      pc,u      restore and return

PutErrString        pshs      u         save U
                    leax      $0260,y   error stream pointer
                    pshs      x         push it
                    ldd       $06,s     string pointer argument
                    pshs      d         push it
                    lbsr      CopyStringToBuf write the string
                    leas      $04,s     drop arguments
                    ldd       #$000D    carriage return character
                    pshs      d         push it
                    bsr       PutErrChar output the newline
                    bra       DropArgReturn clean up and return

PutErrChar          pshs      u         save U
                    leax      $0260,y   error stream pointer
                    pshs      x         push it
                    ldb       $07,s     load char argument
                    sex                 sign-extend to D
                    pshs      d         push it
                    lbsr      PutByte   putc to the stream
PutCharDone         leas      $04,s     drop arguments
                    puls      pc,u      restore and return

FreeExprTree        pshs      u         save U
                    ldu       $04,s     U = tree node
                    stu       -$02,s    test node pointer
                    beq       ReturnU   null, return
                    ldd       $0a,u     left child
                    pshs      d         push it
                    bsr       FreeExprTree recurse left subtree
                    leas      $02,s     drop argument
                    ldd       $0C,u     right child
                    pshs      d         push it
                    lbsr      FreeExprTree recurse right subtree
                    leas      $02,s     drop argument
                    pshs      u         push this node
                    bsr       LinkFreeNode link node onto free list
DropArgReturn       leas      $02,s     drop argument
ReturnU             puls      pc,u      restore and return

LinkFreeNode        pshs      u         save U
                    ldu       $04,s     U = node to free
                    stu       -$02,s    test pointer
                    beq       LinkNodeDone null, skip
                    ldd       $000D     current free-list head
                    std       $0a,u     chain into node
                    stu       $000D     node becomes new head
LinkNodeDone        puls      pc,u      restore and return

ReportDiag22        pshs      u         save U
                    ldd       #$0016    diagnostic code 22
                    pshs      d         push it
                    ldd       $08,s     first argument
                    pshs      d         push it
                    ldd       $08,s     second argument
                    pshs      d         push it
                    lbsr      CopyMem   report the diagnostic
CleanupRet6         leas      $06,s     drop arguments
                    puls      pc,u      restore and return

IsTypeSpecifier     pshs      u         save U
                    ldd       $003F     current token type
                    cmpd      #$0033    is it type 51
                    bne       CheckType52Tok no, check type 52
                    ldx       $0041     token value
                    cmpx      #$0001    value 1
                    lbeq      ReturnOne yes, return true
                    cmpx      #$0002    value 2
                    lbeq      ReturnOne yes, return true
                    cmpx      #$0007    value 7
                    lbeq      ReturnOne yes, return true
                    cmpx      #$000A    value 10
                    lbeq      ReturnOne yes, return true
                    cmpx      #$0008    value 8
                    lbeq      ReturnOne yes, return true
                    cmpx      #$0004    value 4
                    lbeq      ReturnOne yes, return true
                    cmpx      #$0003    value 3
                    lbeq      ReturnOne yes, return true
                    cmpx      #$0006    value 6
                    lbeq      ReturnOne yes, return true
                    cmpx      #$0005    value 5
                    lbeq      ReturnOne yes, return true
                    lbra      ReturnZero not a specifier, false

CheckType52Tok      ldd       $003F     current token type
                    cmpd      #$0034    is it type 52
                    lbne      ReturnZero no, return false
                    ldx       $0041     token value
                    ldd       $08,x     node type field
                    cmpd      #$001E    compare to 30
                    bra       TokenMatchTail test result

IsStorageKeyword    pshs      u         save U
                    ldd       $003F     current token type
                    cmpd      #$0033    is it type 51
                    lbne      ReturnZero no, return false
                    ldx       $0041     token value
                    cmpx      #$000E    value 14
                    lbeq      ReturnOne yes, return true
                    cmpx      #$000D    value 13
                    lbeq      ReturnOne yes, return true
                    cmpx      #$001E    value 30
                    lbeq      ReturnOne yes, return true
                    cmpx      #$0010    value 16
                    lbeq      ReturnOne yes, return true
                    cmpx      #$000F    value 15
                    lbeq      ReturnOne yes, return true
                    cmpx      #$0021    value 33
TokenMatchTail      lbeq      ReturnOne matched, return true
                    lbra      ReturnZero no match, return false

TypeRemoveLevel     pshs      u         save U
                    ldd       $04,s     type code argument
                    asra                shift right one bit
                    rorb                rotate low byte
                    asra                shift right second bit
                    rorb                rotate low byte
                    andb      #$F0      keep derived-type bits
                    bra       MergeTypeBase merge with base type

TypeAddLevel        pshs      u         save U
                    ldd       $04,s     type code argument
                    andb      #$F0      isolate derived bits
                    aslb                shift left one bit
                    rola                rotate high byte
                    aslb                shift left second bit
                    rola                rotate high byte
                    addd      #$0010    add one indirection level
MergeTypeBase       pshs      d         push derived bits
                    ldd       $06,s     base type argument
                    clra                clear high byte
                    andb      #$0f      keep base-type nibble
                    addd      ,s++      combine with derived bits
                    puls      pc,u      restore and return

IsTypeCodeInRange   pshs      u         save U
                    ldu       $04,s     token code argument
                    cmpu      #$004C    below range start
                    blt       ReturnZero out of range, false
                    cmpu      #$0063    above range end
                    bgt       ReturnZero out of range, false
                    ldd       #$0001    in range, true
                    bra       ReturnD   return result

GetNodeType         pshs      u         save U
                    ldu       $04,s     node pointer argument
                    stu       -$02,s    test pointer
                    beq       ReturnZero null, return zero
                    ldd       $02,u     node type field
                    bra       ReturnD   return it

ExpectToken         pshs      u         save U
                    ldd       $003F     current token type
                    cmpd      $04,s     matches expected token
                    bne       LookupTokenName no, report error
                    lbsr      ParseStatement2 consume the token
ReturnZero          clra                clear A
                    clrb                return zero on success
ReturnD             puls      pc,u      restore and return

LookupTokenName     ldu       #$0000    table index zero
                    bra       NameSearchTest enter search loop

NameSearchLoop      tfr       u,d       index to D
                    leax      $00BA,y   token-name table
                    leax      d,x       index into table
                    ldb       ,x        table byte
                    sex                 sign-extend
                    cmpd      $04,s     matches expected token
                    beq       FoundTokenName found it
                    leau      $01,u     next table index
NameSearchTest      cmpu      #$0080    end of table
                    blt       NameSearchLoop keep searching
FoundTokenName      tfr       u,d       index to D
                    stb       $00A1,y   store found name char
                    leax      $00A1,y   point at name
                    pshs      x         push it
                    lbsr      BuildMsgBuf print expected error
                    leas      $02,s     drop argument
ReturnOne           ldd       #$0001    return true
                    puls      pc,u      restore and return

SkipToRecover       pshs      u         save U
                    bra       SkipTokTest test current token

SkipTokLoop         lbsr      ParseStatement2 advance token
SkipTokTest         ldd       $003F     current token type
                    cmpd      #$0028    is it semicolon
                    beq       SkipDone  yes, stop skipping
                    ldd       $003F     current token type
                    cmpd      #$002A    is it close brace
                    beq       SkipDone  yes, stop skipping
                    ldd       $003F     current token type
                    cmpd      #$FFFF    end of input
                    bne       SkipTokLoop none yet, keep skipping
SkipDone            puls      pc,u      restore and return

FmtNameColon        fcc       /%s : /
                    fcb       $00
MsgMultiDef         fcc       /multiple definition/
                    fcb       $00
MsgCompilerErr      fcc       /compiler error - /
                    fcb       $00
FmtLineNum          fcc       /line %d  /
                    fcb       $00
FmtStars            fcc       /****  %s  ****/
                    fcb       $0D,$00
CharCaret           fcb       $5E
                    fcb       $00
MsgTooManyErr       fcc       /too many errors - ABORT/
                    fcb       $00
ParseBinaryExpr     pshs      u         save U
                    ldd       #$FFA2    frame size for stack check
                    lbsr      stkcheck  verify stack space
                    leas      -$0e,s    allocate locals
                    lbsr      ParsePrimaryExpr parse left operand
                    std       $0C,s     save operand node
                    lbne      ContinueParse non-null, parse operators
                    clra                clear A
                    clrb                null result
                    lbra      ParseExprExit return null

                    lbra      ContinueParse unreached

ParseBinOpLoop      ldd       $003F     save operator token type
                    std       $0a,s     into local
                    ldd       $0041     operator value
                    std       $08,s     save it
                    std       ,s        also at frame base
                    ldd       GlbSrcLine source line
                    std       $04,s     save it
                    ldd       $0043     source column
                    std       $02,s     save it
                    lbsr      ParseStatement2 advance past operator
                    ldx       $0a,s     X = operator token type
                    bra       ClassifyOperator classify operator

CheckOperatorRange  ldd       $0a,s     operator token type
                    cmpd      #$00A0    below operator range
                    blt       AdjustOperatorCode outside, count operand
                    ldd       $0a,s     operator token type
                    cmpd      #$00A9    within operator range
                    ble       ParseRightOperand valid operator
AdjustOperatorCode  ldd       $08,s     operator value
                    addd      #$0001    increment it
                    std       ,s        save adjusted code
                    bra       ParseRightOperand parse right operand

ClassifyOperator    cmpx      #$0064    special token 100
                    beq       ParseRightOperand yes, parse right operand
                    cmpx      #$0078    special token 120
                    beq       ParseRightOperand yes, parse right operand
                    bra       CheckOperatorRange check precedence range

ParseRightOperand   ldd       ,s        operator code
                    pshs      d         push it
                    lbsr      ParseBinaryExpr parse right operand recursively
                    leas      $02,s     drop argument
                    tfr       d,u       U = right node
                    stu       -$02,s    test result
                    lbeq      EmitOperandErr null, syntax error
                    ldd       $0a,s     operator token type
                    cmpd      #$0064    special token 100
                    lbne      BuildBinNode no, build binary node
                    ldd       #$002F    node kind 47
                    pshs      d         push it
                    lbsr      ExpectToken expect matching token
                    std       ,s++      save result and pop
                    bne       FreeAndReturn mismatch, free and return
                    ldd       $0043     source column
                    std       $02,s     save it
                    ldd       GlbSrcLine source line
                    std       $04,s     save it
                    ldd       #$0003    operand count
                    pshs      d         push it
                    lbsr      ParseBinaryExpr parse third operand
                    leas      $02,s     drop argument
                    std       $06,s     save node
                    beq       EmitTernaryErr null, error
                    ldd       $02,s     source column
                    pshs      d         push it
                    ldd       $06,s     operand node
                    pshs      d         push it
                    ldd       #$0003    node kind 3
                    pshs      d         push it
                    ldd       $0C,s     left operand
                    pshs      d         push it
                    pshs      u         push right operand
                    ldd       #$002F    node kind 47
                    pshs      d         push it
                    lbsr      AllocExprNode build expression node
                    leas      $0C,s     drop arguments
                    tfr       d,u       U = new node
                    bra       BuildBinNode continue building

EmitTernaryErr      leax      MsgThirdExprMissing,pcr error message text
                    pshs      x         push pointer
                    lbsr      BuildMsgBuf print the error
                    leas      $02,s     drop argument
FreeAndReturn       pshs      u         push right node
                    lbsr      FreeExprTree free expression tree
                    leas      $02,s     drop argument
                    leax      $0e,s     restore frame pointer
                    bra       RestoreFrame restore and return

BuildBinNode        ldd       $02,s     source column
                    pshs      d         push it
                    ldd       $06,s     source line
                    pshs      d         push it
                    ldd       $0C,s     left operand node
                    pshs      d         push it
                    pshs      u         push right operand node
                    ldd       $14,s     operator value
                    pshs      d         push it
                    ldd       $14,s     operator token type
                    pshs      d         push it
                    lbsr      AllocExprNode build binary expression node
                    leas      $0C,s     drop arguments
                    std       $0C,s     save as new left operand
                    bra       ContinueParse look for next operator

EmitOperandErr      leax      MsgOperandExpected,pcr error message text
                    pshs      x         push pointer
                    lbsr      BuildMsgBuf print the error
                    leas      $02,s     drop argument
ContinueParse       lbsr      ParseConditional get operator precedence
                    std       -$02,s    test and save precedence
                    beq       ParseExprRet none, return operand
                    ldd       $12,s     saved precedence
                    cmpd      $0041     compare token value
                    lble      ParseBinOpLoop higher precedence, keep parsing
                    bra       ParseExprRet done, return operand

RestoreFrame        leas      -$0e,x    adjust stack pointer
ParseExprRet        ldd       $0C,s     result operand node
ParseExprExit       leas      $0e,s     release locals
                    puls      pc,u      restore and return

ParsePrimaryExpr    pshs      u         save U
                    ldd       #$FFA4    frame size for stack check
                    lbsr      stkcheck  verify stack space
                    leas      -$0C,s    allocate locals
                    ldu       #$0000    clear node pointer
                    ldx       $003F     current token type
                    lbra      DispatchUnaryOp dispatch by token type

BuildLeafNode       ldd       $0043     source column
                    pshs      d         push it
                    ldd       GlbSrcLine source line
                    pshs      d         push it
                    ldd       $0041     token value
                    pshs      d         push it
                    clra                clear A
                    clrb                clear B
                    pshs      d         push null field
                    clra                clear A
                    clrb                clear B
                    pshs      d         push null field
                    ldd       $003F     token type
                    pshs      d         push it
                    lbsr      AllocExprNode build token node
                    leas      $0C,s     drop arguments
                    tfr       d,u       built node pointer to U
                    lbsr      ParseStatement2 get the next token
                    lbra      PostfixLoop resume the postfix loop

ParseParenOrCast    lbsr      ParseStatement2 get next token after (
                    lbsr      IsTypeSpecifier check if a type name follows
                    std       -$02,s    save the type result
                    beq       ParseParenExpr not a type, parse parenthesized expression
                    lbsr      ParseCast get the cast type info
                    tfr       d,u       cast type node to U
                    ldd       #$002E    expected closing ) token
                    pshs      d         push expected token
                    lbsr      ExpectToken expect and consume the )
                    leas      $02,s     drop the pushed token
                    bsr       ParsePrimaryExpr parse the operand being cast
                    std       $0a,u     store operand into the cast node
                    lbne      PostfixLoop got operand, resume postfix loop
                    pshs      u         push the cast node
                    lbsr      LinkFreeNode apply the cast conversion
                    leas      $02,s     drop the pushed node
                    ldu       #$0000    clear the current node
                    lbra      PostfixLoop resume the postfix loop

ParseParenExpr      clra                D = 0
                    clrb                D = 0
                    pshs      d         push null type context
                    lbsr      ParseBinaryExpr parse the parenthesized expression
                    leas      $02,s     drop the argument
                    tfr       d,u       expression node to U
                    stu       -$02,s    save the node
                    bne       ExpectRParenDone got a node, expect )
                    bra       MakeErrNode empty, build an error node

MakeErrNodeAdj      leas      -$0C,x    restore the local frame
MakeErrNode         lbsr      ExprMissingErr prepare error recovery
                    ldd       $0043     current line number
                    pshs      d         push line
                    ldd       GlbSrcLine source file info
                    pshs      d         push it
                    clra                D = 0
                    clrb                D = 0
                    pshs      d         push zero field
                    clra                D = 0
                    clrb                D = 0
                    pshs      d         push zero field
                    clra                D = 0
                    clrb                D = 0
                    pshs      d         push zero field
                    ldd       #$0036    node type = constant
                    pshs      d         push node type
                    lbsr      AllocExprNode build the placeholder constant node
                    leas      $0C,s     drop node arguments
                    tfr       d,u       node to U
ExpectRParenDone    ldd       #$002E    expected closing ) token
                    pshs      d         push expected token
                    lbsr      ExpectToken expect and consume the )
                    lbra      OperandDone finish this operand

ParsePrefixOp       ldd       $003F     current token type
                    std       $08,s     save the operator token
                    ldd       GlbSrcLine source file info
                    std       $06,s     save it
                    ldd       $0043     current line number
                    std       $04,s     save it
                    lbsr      ParseStatement2 get the next token
                    lbsr      ParsePrimaryExpr parse the unary operand
                    std       $0a,s     save the operand node
                    beq       PrefixOperandErr no operand, report error
                    ldd       $04,s     saved line number
                    pshs      d         push line
                    ldd       $08,s     saved operator token
                    pshs      d         push token
                    ldd       #$000E    node type = unary operator
                    pshs      d         push node type
                    clra                D = 0
                    clrb                D = 0
                    pshs      d         push zero field
                    ldd       $12,s     the operand node
                    pshs      d         push operand
                    ldd       $12,s     the operand node again
                    pshs      d         push operand
                    lbsr      AllocExprNode build the unary-operator node
                    leas      $0C,s     drop node arguments
                    tfr       d,u       node to U
                    lbra      PostfixLoop resume the postfix loop

PrefixOperandErr    leax      MsgPrimaryExpected,pcr address of error message
                    pshs      x         push message pointer
                    lbsr      BuildMsgBuf report the error
                    lbra      OperandDone finish this operand

ParseSizeof         ldd       GlbSrcLine source file info
                    std       $06,s     save it
                    ldd       $0043     current line number
                    std       $04,s     save it
                    lbsr      ParseStatement2 get the next token
                    ldd       $003F     current token type
                    cmpd      #$002D    is it (
                    bne       SizeofUnary no, sizeof a unary expression
                    lbsr      ParseStatement2 get next token after (
                    lbsr      IsTypeSpecifier check if a type name follows
                    std       -$02,s    save the type result
                    beq       SizeofExpr not a type, sizeof an expression
                    lbsr      ParseCast get the type's size
                    std       $0a,s     save the size
                    bra       SizeofExpectRParen expect the closing )

SizeofExpr          clra                D = 0
                    clrb                D = 0
                    pshs      d         push null type context
                    lbsr      ParseBinaryExpr parse the expression
                    leas      $02,s     drop the argument
                    std       $0a,s     save the expression node
                    bne       SizeofExpectRParen got a node, expect )
                    leax      $0C,s     point past the local frame
                    lbra      MakeErrNodeAdj build an error node

SizeofExpectRParen  ldd       #$002E    expected closing ) token
                    pshs      d         push expected token
                    lbsr      ExpectToken expect and consume the )
                    leas      $02,s     drop the pushed token
                    bra       BuildSizeofNode build the sizeof node

SizeofUnary         lbsr      ParsePrimaryExpr parse the unary operand
                    std       $0a,s     save the operand node
BuildSizeofNode     ldd       $0a,s     the operand/size node
                    std       ,s        stash it
                    ldd       $04,s     saved line number
                    pshs      d         push line
                    ldd       $08,s     saved token
                    pshs      d         push it
                    leax      $04,s     point to the saved fields
                    pshs      x         push pointer
                    lbsr      EmitOperand compute the operand's size
                    std       ,s        store the size
                    clra                D = 0
                    clrb                D = 0
                    pshs      d         push zero field
                    clra                D = 0
                    clrb                D = 0
                    pshs      d         push zero field
                    ldd       #$0036    node type = constant
                    pshs      d         push node type
                    lbsr      AllocExprNode build the size constant node
                    leas      $0C,s     drop node arguments
                    tfr       d,u       node to U
                    ldd       ,s        the operand node
                    pshs      d         push it
                    lbsr      FreeExprTree release the operand node
OperandDone         leas      $02,s     drop the pushed node
                    bra       PostfixLoop resume the postfix loop

DispatchUnaryOp     cmpx      #$0037    token is a unary operator
                    lbeq      BuildLeafNode build the operand node
                    cmpx      #$0034    token is an identifier
                    lbeq      BuildLeafNode build the operand node
                    cmpx      #$004A    token type
                    lbeq      BuildLeafNode build the operand node
                    cmpx      #$004B    token type
                    lbeq      BuildLeafNode build the operand node
                    cmpx      #$0036    token is a constant
                    lbeq      BuildLeafNode build the operand node
                    cmpx      #$002D    token is (
                    lbeq      ParseParenOrCast parse cast or parenthesized
                    cmpx      #$0040    prefix operator token
                    lbeq      ParsePrefixOp parse the prefix operator
                    cmpx      #$0043    prefix operator token
                    lbeq      ParsePrefixOp parse the prefix operator
                    cmpx      #$0044    prefix operator token
                    lbeq      ParsePrefixOp parse the prefix operator
                    cmpx      #$0042    prefix operator token
                    lbeq      ParsePrefixOp parse the prefix operator
                    cmpx      #$003D    prefix operator token
                    lbeq      ParsePrefixOp parse the prefix operator
                    cmpx      #$003C    prefix operator token
                    lbeq      ParsePrefixOp parse the prefix operator
                    cmpx      #$0041    prefix operator token
                    lbeq      ParsePrefixOp parse the prefix operator
                    cmpx      #$003B    token is sizeof
                    lbeq      ParseSizeof parse sizeof
PostfixLoop         cmpu      #$0000    is the current node empty
                    bne       PostfixNext no, handle postfix operators
                    clra                return null node
                    clrb                return null node
                    lbra      UnaryDone return

PostfixNext         ldx       $003F     current token type
                    lbra      DispatchPostfixOp dispatch postfix operators

ParseCall           ldd       $0043     current line number
                    std       $04,s     save it
                    ldd       GlbSrcLine source file info
                    std       $06,s     save it
                    lbsr      ParseStatement2 get next token after (
                    ldd       $04,s     saved line number
                    pshs      d         push line
                    ldd       $08,s     the function expression node
                    pshs      d         push it
                    ldd       #$000F    node type = call
                    pshs      d         push node type
                    lbsr      ParseArgList parse the argument list
                    pshs      d         push the arg-list node
                    pshs      u         push args
                    ldd       #$0065    subtype = function call
                    pshs      d         push subtype
                    lbsr      AllocExprNode build the call node
                    leas      $0C,s     drop node arguments
                    tfr       d,u       node to U
                    ldd       #$002E    expected closing ) token
                    lbra      ExpectCloseThenLoop expect ) then loop

ParseSubscript      lbsr      ParseStatement2 get next token after [
                    ldd       #$0002    assignment precedence level
                    pshs      d         push it
                    lbsr      ParseBinaryExpr parse the index expression
                    leas      $02,s     drop the argument
                    std       $0a,s     save the index node
                    bne       BuildSubscript got index, build subscript
                    lbsr      ExprMissingErr prepare error recovery
                    ldd       $0043     current line number
                    pshs      d         push line
                    ldd       GlbSrcLine source file info
                    pshs      d         push it
                    clra                D = 0
                    clrb                D = 0
                    pshs      d         push zero field
                    clra                D = 0
                    clrb                D = 0
                    pshs      d         push zero field
                    clra                D = 0
                    clrb                D = 0
                    pshs      d         push zero field
                    ldd       #$0036    node type = constant
                    pshs      d         push node type
                    lbsr      AllocExprNode build placeholder index node
                    leas      $0C,s     drop node arguments
                    std       $0a,s     save the index node
BuildSubscript      ldd       $0043     current line number
                    pshs      d         push line
                    ldd       GlbSrcLine source file info
                    pshs      d         push it
                    ldd       #$000C    node type = add
                    pshs      d         push node type
                    ldd       $10,s     the array expression node
                    pshs      d         push it
                    pshs      u         push the index node
                    ldd       #$0050    subtype
                    pshs      d         push subtype
                    lbsr      AllocExprNode build the base+index node
                    leas      $0C,s     drop node arguments
                    tfr       d,u       node to U
                    ldd       $0043     current line number
                    pshs      d         push line
                    ldd       GlbSrcLine source file info
                    pshs      d         push it
                    ldd       #$000F    node type = dereference
                    pshs      d         push node type
                    clra                D = 0
                    clrb                D = 0
                    pshs      d         push zero field
                    pshs      u         push the address node
                    ldd       #$0042    subtype = indirection
                    pshs      d         push subtype
                    lbsr      AllocExprNode build the dereference node
                    leas      $0C,s     drop node arguments
                    tfr       d,u       node to U
                    ldd       #$002C    expected closing ] token
ExpectCloseThenLoop pshs      d         push expected token
                    lbsr      ExpectToken expect and consume the token
                    leas      $02,s     drop the pushed token
                    lbra      PostfixNext resume the postfix loop

ParseMemberAccess   ldd       $003F     current token type
                    std       $08,s     save the . or -> operator
                    ldd       GlbSrcLine source file info
                    std       $06,s     save it
                    ldd       $0043     current line number
                    std       $04,s     save it
                    ldd       GlbNestDepth suppress-lookup depth
                    addd      #$0001    increment it
                    std       GlbNestDepth store it
                    lbsr      ParseStatement2 get next token, the member name
                    ldd       GlbNestDepth suppress-lookup depth
                    addd      #$FFFF    decrement it
                    std       GlbNestDepth store it
                    ldd       $003F     current token type
                    cmpd      #$0034    is it an identifier
                    beq       BuildMemberNode yes, build the member node
                    lbsr      ErrIdentMissing report the syntax error
                    lbra      CheckPostIncDec resume the dispatch

BuildMemberNode     ldd       $0043     current line number
                    pshs      d         push line
                    ldd       GlbSrcLine source file info
                    pshs      d         push it
                    ldd       $0041     the member name value
                    pshs      d         push it
                    clra                D = 0
                    clrb                D = 0
                    pshs      d         push zero field
                    clra                D = 0
                    clrb                D = 0
                    pshs      d         push zero field
                    ldd       $003F     the member token
                    pshs      d         push it
                    lbsr      AllocExprNode build the member-name node
                    leas      $0C,s     drop node arguments
                    std       $0a,s     save the member node
                    ldd       $04,s     saved line number
                    pshs      d         push line
                    ldd       $08,s     saved operator token
                    pshs      d         push it
                    ldd       #$000F    node type = member select
                    pshs      d         push node type
                    ldd       $10,s     the struct expression node
                    pshs      d         push it
                    pshs      u         push the current node
                    ldd       $12,s     the member node
                    pshs      d         push it
                    lbsr      AllocExprNode build the member-access node
                    leas      $0C,s     drop node arguments
                    tfr       d,u       node to U
                    lbsr      ParseStatement2 get the next token
                    lbra      PostfixNext resume the postfix loop

DispatchPostfixOp   cmpx      #$002D    token is (
                    lbeq      ParseCall parse a function call
                    cmpx      #$002B    token is [
                    lbeq      ParseSubscript parse an array subscript
                    cmpx      #$0045    token is .
                    lbeq      ParseMemberAccess parse member access
                    cmpx      #$0046    token is ->
                    lbeq      ParseMemberAccess parse member access
CheckPostIncDec     ldx       $003F     current token type
                    bra       DispatchPostIncDec check for ++ or --

ParsePostInc        ldd       #$003E    post-increment operator token
                    std       $003F     set the operator token
                    leax      $0C,s     point past the local frame
                    bra       BuildPostIncDecAdj build the inc/dec node

ParsePostDec        ldd       #$003F    post-decrement operator token
                    std       $003F     set the operator token
                    bra       BuildPostIncDec build the inc/dec node

BuildPostIncDecAdj  leas      -$0C,x    restore the local frame
BuildPostIncDec     ldd       $0043     current line number
                    pshs      d         push line
                    ldd       GlbSrcLine source file info
                    pshs      d         push it
                    ldd       #$000E    node type = unary operator
                    pshs      d         push node type
                    clra                D = 0
                    clrb                D = 0
                    pshs      d         push zero field
                    pshs      u         push the operand node
                    ldd       $003F     the operator token
                    pshs      d         push it
                    lbsr      AllocExprNode build the post inc/dec node
                    leas      $0C,s     drop node arguments
                    tfr       d,u       node to U
                    lbsr      ParseStatement2 get the next token
                    bra       ReturnNode return the node

DispatchPostIncDec  cmpx      #$003C    token is ++
                    beq       ParsePostInc parse post-increment
                    cmpx      #$003D    token is --
                    beq       ParsePostDec parse post-decrement
ReturnNode          tfr       u,d       move current node into D
UnaryDone           leas      $0C,s     drop the local frame
                    puls      pc,u      restore U and return

ParseArgList        pshs      u         save the caller node
                    ldd       #$FFAE    local frame size
                    lbsr      stkcheck  check for stack overflow
                    leas      -$02,s    reserve a local
                    ldu       #$0000    clear the arg-list node
                    bra       ArgLoop2  enter the argument loop

ArgLoop2            ldd       $003F     current token type
                    cmpd      #$002E    is it )
                    beq       ArgListDone end of arguments
                    ldd       #$0002    assignment precedence level
                    pshs      d         push it
                    lbsr      ParseBinaryExpr parse one argument expression
                    leas      $02,s     drop the argument
                    std       ,s        save the argument node
                    beq       ArgCheckComma none, check for comma
                    ldx       ,s        the argument node
                    ldd       $10,x     its line field
                    pshs      d         push it
                    ldx       $02,s     the argument node
                    ldd       $0e,x     its file field
                    pshs      d         push it
                    clra                D = 0
                    clrb                D = 0
                    pshs      d         push zero field
                    pshs      u         push the current arg-list
                    ldd       $08,s     the argument node
                    pshs      d         push it
                    ldd       #$000B    node type = argument link
                    pshs      d         push node type
                    lbsr      AllocExprNode build the argument-link node
                    leas      $0C,s     drop node arguments
                    std       ,s        save the link node
                    ldu       ,s        link node to U
ArgCheckComma       ldd       $003F     current token type
                    cmpd      #$0030    is it a comma
                    bne       ArgListDone no, arguments done
                    lbsr      ParseStatement2 get the next token
                    bra       ArgLoop2  parse the next argument

ArgListDone         tfr       u,d       return the arg-list node
                    bra       ConstExprExit return

ParseConstExpr      pshs      u         save the caller node
                    ldd       #$FFB8    local frame size
                    lbsr      stkcheck  check for stack overflow
                    leas      -$02,s    reserve a local
                    ldd       $06,s     caller-supplied context
                    pshs      d         push it
                    lbsr      ParseBinaryExpr parse the expression
                    std       ,s        save the node
                    lbsr      CopyExprTree constant-fold the expression
                    leas      $02,s     drop the argument
                    tfr       d,u       folded node to U
                    stu       -$02,s    save it
                    beq       ConstExprErr nothing, report error
                    ldd       $06,u     node type
                    cmpd      #$0036    is it a constant
                    bne       ConstExprErr no, report error
                    ldd       $08,u     the constant value
                    std       ,s        save it
                    bra       ConstExprCleanup clean up and return

ConstExprErr        clra                value = 0
                    clrb                value = 0
                    std       ,s        save the zero result
                    leax      MsgConstRequired,pcr constant-required message
                    pshs      x         push message pointer
                    lbsr      BuildMsgBuf report the error
                    leas      $02,s     drop the pushed pointer
ConstExprCleanup    stu       -$02,s    refresh the saved node
                    beq       ConstExprResult no node, return the value
                    pshs      u         push the node
                    lbsr      FreeExprTree release the node
                    leas      $02,s     drop the pushed node
ConstExprResult     ldd       ,s        the constant value
ConstExprExit       leas      $02,s     drop the local
                    puls      pc,u      restore U and return

ParseConditional    pshs      u         save the caller node
                    ldd       #$FFC0    local frame size
                    lbsr      stkcheck  check for stack overflow
                    ldx       $003F     current token type
                    bra       ClassifyConstType dispatch on the token

TernaryOp           ldd       #$0057    ternary operator token
                    std       $003F     set the token
                    ldd       #$0008    node subtype
                    bra       StoreTypeSize build the conditional node

SetTypeLong         ldd       #$0052    load long type code
                    std       $003F     set current type to long
                    ldd       #$000D    long type size
                    bra       StoreTypeSize store size and return valid

SetTypeInt          ldd       #$0051    load int type code
                    std       $003F     set current type to int
                    ldd       #$000C    int type size
StoreTypeSize       std       $0041     store current type size
ConstTypeValid      ldd       #$0001    result equals valid
                    puls      pc,u      return to caller

CheckTypeInRange    ldd       $003F     load current type code
                    cmpd      #$0047    below scalar range
                    blt       ReloadTypeCode try pointer range
                    ldd       $003F     reload type code
                    cmpd      #$005F    above scalar range
                    ble       ResultValid in scalar range so valid
ReloadTypeCode      ldd       $003F     reload type code
                    cmpd      #$00A0    below pointer range
                    lblt      FoldZero  not usable return zero
                    ldd       $003F     reload type code
                    cmpd      #$00A9    above pointer range
                    lbgt      FoldZero  not usable return zero
ResultValid         ldd       #$0001    result equals valid
                    lbra      FoldReturn return to caller

ClassifyConstType   cmpx      #$0041    type code A
                    beq       TernaryOp normalize that type
                    cmpx      #$0042    type code B
                    beq       SetTypeLong normalize to long
                    cmpx      #$0043    type code C
                    beq       SetTypeInt normalize to int
                    cmpx      #$0030    already usable type
                    beq       ConstTypeValid accept as valid
                    cmpx      #$0078    already usable type
                    lbeq      ConstTypeValid accept as valid
                    cmpx      #$0064    already usable type
                    lbeq      ConstTypeValid accept as valid
                    cmpx      #$002F    void or no type
                    lbeq      FoldZero  reject return zero
                    bra       CheckTypeInRange range-check other codes

                    puls      pc,u      unreachable return

FoldConstOp         pshs      u         save frame pointer
                    ldd       #$FFB8    stack frame size
                    lbsr      stkcheck  check stack space
                    ldx       $04,s     X equals operator code
                    lbra      FoldConstOpDispatch dispatch to operator handler

FoldAdd             ldd       $06,s     left operand
                    addd      $08,s     add right operand
                    puls      pc,u      return the sum

FoldSub             ldd       $06,s     left operand
                    subd      $08,s     subtract right operand
                    puls      pc,u      return the difference

FoldMul             ldd       $06,s     left operand
                    pshs      d         push as argument
                    ldd       $0a,s     right operand
                    lbsr      MulInt32  multiply operands
                    puls      pc,u      return the product

FoldDiv             ldd       $08,s     divisor operand
                    beq       FoldDivZeroErr zero divisor error
                    ldd       $06,s     dividend operand
                    pshs      d         push dividend
                    ldd       $0a,s     divisor argument
                    lbsr      SignedDivide32 divide operands
                    bra       FoldDivDone return the quotient

FoldMod             ldd       $08,s     divisor operand
                    beq       FoldDivZeroErr zero divisor error
                    ldd       $06,s     dividend operand
                    pshs      d         push dividend
                    ldd       $0a,s     divisor argument
                    lbsr      SignedDivSetup compute remainder
FoldDivDone         puls      pc,u      return the result

FoldDivZeroErr      lbsr      DivByZeroErr report divide by zero
                    lbra      FoldZero  return zero

FoldBitAnd          ldd       $06,s     left operand
                    anda      $08,s     and high byte
                    andb      $09,s     and low byte
                    puls      pc,u      return bitwise and

FoldBitOr           ldd       $06,s     left operand
                    ora       $08,s     or high byte
                    orb       $09,s     or low byte
                    puls      pc,u      return bitwise or

FoldBitXor          ldd       $06,s     left operand
                    eora      $08,s     xor high byte
                    eorb      $09,s     xor low byte
                    puls      pc,u      return bitwise xor

FoldShl             ldd       $06,s     value to shift
                    pshs      d         push value
                    ldd       $0a,s     shift count
                    lbsr      ShiftLeft shift left
                    puls      pc,u      return shifted value

FoldShr             ldd       $06,s     value to shift
                    pshs      d         push value
                    ldd       $0a,s     shift count
                    lbsr      ShiftRightSigned shift right
                    puls      pc,u      return shifted value

FoldEq              ldd       $06,s     left operand
                    cmpd      $08,s     compare operands
                    lbne      FoldZero  not equal return zero
                    ldd       #$0001    equal so result one
                    lbra      FoldReturn return result

FoldNe              ldd       $06,s     left operand
                    cmpd      $08,s     compare operands
                    lbeq      FoldZero  equal return zero
                    ldd       #$0001    not equal so result one
                    lbra      FoldReturn return result

FoldGt              ldd       $06,s     left operand
                    cmpd      $08,s     compare operands
                    lble      FoldZero  not greater return zero
                    ldd       #$0001    greater so result one
                    lbra      FoldReturn return result

FoldLt              ldd       $06,s     left operand
                    cmpd      $08,s     compare operands
                    lbge      FoldZero  not less return zero
                    ldd       #$0001    less so result one
                    lbra      FoldReturn return result

FoldGe              ldd       $06,s     left operand
                    cmpd      $08,s     compare operands
                    lblt      FoldZero  less return zero
                    ldd       #$0001    greater-or-equal result one
                    lbra      FoldReturn return result

FoldLe              ldd       $06,s     left operand
                    cmpd      $08,s     compare operands
                    lbgt      FoldZero  greater return zero
                    ldd       #$0001    less-or-equal result one
                    lbra      FoldReturn return result

FoldNeg             ldd       $06,s     operand to negate
                    nega                negate high byte
                    negb                negate low byte
                    sbca      #$00      propagate borrow
                    puls      pc,u      return negated value

FoldLogNot          ldd       $06,s     operand
                    lbne      FoldZero  nonzero return zero
                    ldd       #$0001    zero so result one
                    lbra      FoldReturn return result

FoldBitNot          ldd       $06,s     operand
                    coma                complement high byte
                    comb                complement low byte
                    puls      pc,u      return complement

FoldLogAnd          ldd       $06,s     left operand
                    lbeq      FoldZero  left zero result zero
                    ldd       $08,s     right operand
                    lbeq      FoldZero  right zero result zero
                    ldd       #$0001    both nonzero result one
                    lbra      FoldReturn return result

FoldLogOr           ldd       $06,s     left operand
                    bne       FoldLogOrTrue left nonzero result one
                    ldd       $08,s     right operand
                    lbeq      FoldZero  both zero result zero
FoldLogOrTrue       ldd       #$0001    result one
                    lbra      FoldReturn return result

FoldUnsignedCmp     leas      -$04,s    make room for locals
                    ldd       $0C,s     right operand
                    std       $02,s     save as local
                    ldd       $0a,s     left operand
                    std       ,s        save as local
                    ldx       $08,s     X equals comparison operator
                    bra       FoldUnsignedDispatch dispatch unsigned compare

FoldUle             ldd       ,s        left operand
                    cmpd      $02,s     unsigned compare
                    bhi       FoldCmpFalse if above result zero
                    ldd       #$0001    otherwise result one
                    bra       FoldCmpDone return result

FoldUlt             ldd       ,s        left operand
                    cmpd      $02,s     unsigned compare
                    bcc       FoldCmpFalse if at-or-above result zero
                    ldd       #$0001    otherwise result one
                    bra       FoldCmpDone return result

FoldUge             ldd       ,s        left operand
                    cmpd      $02,s     unsigned compare
                    bcs       FoldCmpFalse if below result zero
                    ldd       #$0001    otherwise result one
                    bra       FoldCmpDone return result

FoldUgt             ldd       ,s        left operand
                    cmpd      $02,s     unsigned compare
                    bls       FoldCmpFalse if below-or-equal result zero
                    ldd       #$0001    otherwise result one
                    bra       FoldCmpDone return result

FoldCmpFalse        clra                result zero high
                    clrb                result zero low
FoldCmpDone         leas      $04,s     drop locals
                    puls      pc,u      return result

FoldUnsignedDispatch cmpx      #$0060    unsigned less-or-equal operator
                    beq       FoldUle   fold that comparison
                    cmpx      #$0061    unsigned less-than operator
                    beq       FoldUlt   fold that comparison
                    cmpx      #$0062    unsigned greater-or-equal operator
                    beq       FoldUge   fold that comparison
                    bra       FoldUgt   else unsigned greater-than

                    leas      $04,s     unreachable drop locals
BadConstOpErr       leax      MsgConstOperator,pcr constant operator message
                    pshs      x         push message pointer
                    lbsr      BuildMsgBuf report error
                    leas      $02,s     drop argument
FoldZero            clra                result zero high
                    clrb                result zero low
FoldReturn          puls      pc,u      return result

FoldConstOpDispatch cmpx      #$0050    add operator
                    lbeq      FoldAdd   fold add
                    cmpx      #$0051    subtract operator
                    lbeq      FoldSub   fold subtract
                    cmpx      #$0052    multiply operator
                    lbeq      FoldMul   fold multiply
                    cmpx      #$0053    divide operator
                    lbeq      FoldDiv   fold divide
                    cmpx      #$0054    modulo operator
                    lbeq      FoldMod   fold modulo
                    cmpx      #$0057    bitwise-and operator
                    lbeq      FoldBitAnd fold and
                    cmpx      #$0058    bitwise-or operator
                    lbeq      FoldBitOr fold or
                    cmpx      #$0059    bitwise-xor operator
                    lbeq      FoldBitXor fold xor
                    cmpx      #$0056    shift-left operator
                    lbeq      FoldShl   fold shift left
                    cmpx      #$0055    shift-right operator
                    lbeq      FoldShr   fold shift right
                    cmpx      #$005A    equality operator
                    lbeq      FoldEq    fold equal
                    cmpx      #$005B    inequality operator
                    lbeq      FoldNe    fold not-equal
                    cmpx      #$005F    greater-than operator
                    lbeq      FoldGt    fold greater-than
                    cmpx      #$005D    less-than operator
                    lbeq      FoldLt    fold less-than
                    cmpx      #$005E    greater-or-equal operator
                    lbeq      FoldGe    fold greater-or-equal
                    cmpx      #$005C    less-or-equal operator
                    lbeq      FoldLe    fold less-or-equal
                    cmpx      #$0043    unary minus operator
                    lbeq      FoldNeg   fold negate
                    cmpx      #$0040    logical-not operator
                    lbeq      FoldLogNot fold logical not
                    cmpx      #$0044    bitwise-not operator
                    lbeq      FoldBitNot fold complement
                    cmpx      #$0047    logical-and operator
                    lbeq      FoldLogAnd fold logical and
                    cmpx      #$0048    logical-or operator
                    lbeq      FoldLogOr fold logical or
                    cmpx      #$0060    unsigned less-or-equal operator
                    lbeq      FoldUnsignedCmp fold unsigned compare
                    cmpx      #$0061    unsigned less-than operator
                    lbeq      FoldUnsignedCmp fold unsigned compare
                    cmpx      #$0062    unsigned greater-or-equal operator
                    lbeq      FoldUnsignedCmp fold unsigned compare
                    cmpx      #$0063    unsigned greater-than operator
                    lbeq      FoldUnsignedCmp fold unsigned compare
                    lbra      BadConstOpErr unknown operator error

                    puls      pc,u      unreachable return

ParseCast           pshs      u         save frame pointer
                    ldd       #$FFA2    stack frame size
                    lbsr      stkcheck  check stack space
                    leas      -$0e,s    allocate locals
                    ldd       GlbSrcLine current source position global
                    std       $04,s     save into locals
                    ldd       $0043     current type global
                    std       $02,s     save into locals
                    leax      ,s        point at locals
                    pshs      x         push pointer argument
                    leax      $0C,s     address of arg slot
                    pshs      x         push pointer argument
                    leax      $10,s     address of arg slot
                    pshs      x         push pointer argument
                    lbsr      ParseDeclSpec parse declaration specifiers
                    leas      $06,s     drop arguments
                    std       $08,s     save base type
                    pshs      d         push base type
                    leax      $0C,s     address of declarator slot
                    pshs      x         push pointer argument
                    leax      $0a,s     address of slot
                    pshs      x         push pointer argument
                    lbsr      ParseDeclarator parse abstract declarator
                    leas      $06,s     drop arguments
                    std       $08,s     save declared type
                    leax      >$0027,y  point at identifier field
                    pshs      x         push pointer argument
                    lbsr      FreeLocalSymbols check for declarator name
                    leas      $02,s     drop argument
                    ldd       $06,s     declared name present
                    beq       CastTypeOk no name type-only cast ok
                    leax      MsgNameInCast,pcr name in a cast message
                    pshs      x         push message pointer
                    lbsr      BuildMsgBuf report error
                    leas      $02,s     drop argument
CastTypeOk          ldd       $02,s     saved outer type
                    pshs      d         push type argument
                    ldd       $06,s     declared type
                    pshs      d         push type argument
                    clra                clear high byte
                    clrb                clear low byte
                    pshs      d         push null field
                    clra                clear high byte
                    clrb                clear low byte
                    pshs      d         push null field
                    clra                clear high byte
                    clrb                clear low byte
                    pshs      d         push null field
                    ldd       #$0020    cast node kind
                    pshs      d         push node kind
                    bsr       AllocExprNode allocate cast node
                    leas      $0C,s     drop node arguments
                    std       $06,s     save node pointer
                    ldd       $08,s     declared type
                    std       [$06,s]   store type into node
                    ldd       $0C,s     operand subtree
                    pshs      d         push argument
                    ldd       $0C,s     operand subtree
                    pshs      d         push argument
                    ldd       $0a,s     node pointer
                    pshs      d         push argument
                    lbsr      CalcTypeSize build cast expression
                    leas      $06,s     drop arguments
                    ldd       $06,s     result node pointer
                    leas      $0e,s     release locals
                    puls      pc,u      return node

AllocExprNode       pshs      u         save frame pointer
                    ldd       #$FFBA    stack frame size
                    lbsr      stkcheck  check stack space
                    ldd       $000D     free-node list head
                    beq       AllocNodeFromHeap empty so allocate from heap
                    ldu       $000D     take node off free list
                    ldd       $0a,u     next free node
                    std       $000D     update free list head
                    bra       FillNodeFields fill node fields

AllocNodeFromHeap   ldd       #$0016    node size in bytes
                    pshs      d         push size argument
                    lbsr      AllocMem  allocate memory
                    leas      $02,s     drop argument
                    tfr       d,u       U equals new node
FillNodeFields      ldd       $04,s     argument field zero
                    std       $06,u     store in node
                    ldd       $06,s     argument field one
                    std       $0a,u     store in node
                    ldd       $08,s     argument field two
                    std       $0C,u     store in node
                    ldd       $0a,s     argument field three
                    std       $08,u     store in node
                    ldd       $0C,s     argument field four
                    std       $0e,u     store in node
                    ldd       $0e,s     argument field five
                    std       $10,u     store in node
                    clra                clear high byte
                    clrb                clear low byte
                    std       $14,u     clear node link field
                    tfr       u,d       return node pointer
                    puls      pc,u      return to caller

ExprMissingErr      pshs      u         save frame pointer
                    ldd       #$FFBA    stack frame size
                    lbsr      stkcheck  check stack space
                    leax      MsgExprMissing,pcr expression missing message
                    pshs      x         push message pointer
                    lbsr      BuildMsgBuf report error
                    lbra      EmitOperandDone return to caller

EmitOperand         pshs      u         save frame pointer
                    ldd       #$FFB6    stack frame size
                    lbsr      stkcheck  check stack space
                    ldu       [$04,s]   U equals target node
                    ldx       $06,u     X equals node kind
                    bra       EmitOperandDispatch dispatch on node kind

EmitOperandCopy     pshs      u         save frame pointer
                    lbsr      CopyExprTree copy expression subtree
                    leas      $02,s     drop argument
                    std       [$04,s]   store copied subtree
                    tfr       d,u       U equals copied node
                    leax      ,s        point at stack slot
                    bra       EmitFromStack emit operand

EmitIndirect        ldd       [$08,u]   indirect operand value
                    std       ,u        store into node
                    pshs      u         push node argument
                    lbsr      ReportUndeclared process indirect node
                    leas      $02,s     drop argument
                    ldu       $08,u     follow pointer field
                    bra       EmitOperandDesc emit operand descriptor

EmitFromStack       leas      ,x        restore stack pointer
EmitOperandDesc     ldd       $04,u     node field two
                    pshs      d         push argument
                    ldd       $02,u     node field one
                    pshs      d         push argument
                    ldd       ,u        node field zero
                    pshs      d         push argument
                    lbsr      ResolveTypeSize emit operand
                    leas      $06,s     drop arguments
                    puls      pc,u      return to caller

EmitOffsetOperand   pshs      u         save frame pointer
                    ldd       #$000C    node record size
                    addd      ,s++      advance to next node
                    pshs      d         push node pointer
                    bsr       EmitOperand emit next operand
EmitOperandDone     leas      $02,s     drop argument
                    puls      pc,u      return to caller

EmitOperandDispatch cmpx      #$0034    indirect node kind
                    beq       EmitIndirect emit indirect operand
                    cmpx      #$0020    leaf node kind
                    beq       EmitOperandDesc emit operand descriptor
                    cmpx      #$0045    offset node kind
                    beq       EmitOffsetOperand emit offset operand
                    cmpx      #$0046    offset node kind
                    lbeq      EmitOffsetOperand emit offset operand
                    lbra      EmitOperandCopy default copy and emit

                    puls      pc,u      unreachable return

MsgThirdExprMissing fcc       /third expression missing/
                    fcb       $00
MsgOperandExpected  fcc       /operand expected/
                    fcb       $00
MsgPrimaryExpected  fcc       /primary expected/
                    fcb       $00
MsgConstRequired    fcc       /constant required/
                    fcb       $00
MsgConstOperator    fcc       /constant operator/
                    fcb       $00
MsgNameInCast       fcc       /name in a cast/
                    fcb       $00
MsgExprMissing      fcc       /expression missing/
                    fcb       $00
CopyExprTree        pshs      u         save frame pointer
                    ldd       #$FFAE    stack frame size
                    lbsr      stkcheck  check stack space
                    ldu       $04,s     U equals source node
                    leas      -$0C,s    allocate locals
                    stu       -$02,s    save source sets zero if null
                    lbeq      ReturnNode2 null node return empty
                    ldd       $0a,u     left child pointer
                    pshs      d         push child argument
                    bsr       CopyExprTree copy left child
                    leas      $02,s     drop argument
                    std       $0a,u     record copied left child
                    ldd       $0C,u     right child pointer
                    pshs      d         push child argument
                    lbsr      CopyExprTree copy right child
                    leas      $02,s     drop argument
                    std       $0C,u     record copied right child
                    pshs      u         push node argument
                    lbsr      GenExprNode duplicate node record
                    leas      $02,s     drop argument
                    tfr       d,u       U equals new node copy
                    pshs      u         push new node
                    lbsr      ReduceNode finalize copied node
                    std       ,s++      store result and pop
                    beq       FoldSelectOrMerge ReduceNode gave zero so try const-fold
                    leax      $0C,s     point X past the local frame
                    lbra      RestoreFrameX return the transformed node

FoldSelectOrMerge   pshs      u         save node for the folder
                    lbsr      FoldConstNode constant-fold this node
                    leas      $02,s     drop the argument
                    tfr       d,u       U = folded node
                    ldd       $0a,u     D = node left child
                    std       $0a,s     stash left in record
                    ldd       $0C,u     D = node right child
                    std       $08,s     stash right in record
                    ldd       $06,u     D = node opcode
                    std       $04,s     stash opcode in record
                    cmpd      #$0064    is it a conditional-select operator
                    bne       CheckPtrMerge no so try pointer merge
                    ldx       $0a,s     X = condition child
                    ldd       $06,x     D = condition opcode
                    cmpd      #$0036    is the condition a constant
                    bne       CheckPtrMerge no so cannot fold
                    ldx       $0a,s     X = condition node
                    ldd       $08,x     D = constant condition value
                    beq       SelectFalseBranch condition false so pick other branch
                    ldx       $08,s     X = branch-pair node
                    ldd       $0a,x     D = discarded branch subtree
                    std       $02,s     remember discarded branch
                    ldx       $08,s     X = branch-pair node
                    ldd       $0C,x     D = kept branch subtree
                    bra       ReduceSelect reduce to the kept branch

SelectFalseBranch   ldx       $08,s     X = branch-pair node
                    ldd       $0C,x     D = discarded branch subtree
                    std       $02,s     remember discarded branch
                    ldx       $08,s     X = branch-pair node
                    ldd       $0a,x     D = kept branch subtree
ReduceSelect        pshs      d         save the discarded subtree
                    lbsr      FreeExprTree free the discarded subtree
                    leas      $02,s     drop the argument
                    ldd       $08,s     D = branch-pair node
                    pshs      d         push it
                    lbsr      LinkFreeNode free the branch-pair node
                    leas      $02,s     drop the argument
                    ldd       $0a,s     D = condition node
                    pshs      d         push it
                    lbsr      LinkFreeNode free the condition node
                    leas      $02,s     drop the argument
                    pshs      u         push the kept node
                    bra       FreeAndReturnNode free record and return it

CheckPtrMerge       ldd       $04,s     D = node opcode
                    cmpd      #$0042    is it operator B
                    bne       CheckPtrMergeAlt no so check the A form
                    ldx       $0a,s     X = left child
                    ldd       $06,x     D = left opcode
                    cmpd      #$0041    is left operator A
                    beq       MergePtrOffset yes so merge pointer offsets
CheckPtrMergeAlt    ldd       $04,s     D = node opcode
                    cmpd      #$0041    is it operator A
                    bne       ReturnNode2 no so nothing to do
                    ldx       $0a,s     X = left child
                    ldd       $06,x     D = left opcode
                    cmpd      #$0042    is left operator B
                    bne       ReturnNode2 no so nothing to do
MergePtrOffset      ldx       $0a,s     X = left child
                    ldd       $0a,x     D = left's left field
                    std       $02,s     save that pointer
                    ldd       ,u        D = node's first word
                    std       [$02,s]   store it through saved pointer
                    ldd       $02,u     D = node offset field
                    ldx       $02,s     X = saved pointer
                    std       $02,x     write offset into inner node
                    pshs      u         push the node
                    lbsr      LinkFreeNode free the node
                    leas      $02,s     drop the argument
                    ldd       $0a,s     D = original left child
                    pshs      d         push it
FreeAndReturnNode   lbsr      LinkFreeNode free that node
                    leas      $02,s     drop the argument
                    ldu       $02,s     U = replacement node
                    bra       ReturnNode2 return the replacement

RestoreFrameX       leas      -$0C,x    restore stack from X frame
ReturnNode2         tfr       u,d       return node in D
                    leas      $0C,s     drop the local frame
                    puls      pc,u      restore U and return

FoldConstNode       pshs      u         save U
                    ldd       #$FFA8    frame size for stack check
                    lbsr      stkcheck  verify stack space
                    ldu       $04,s     U = node argument
                    leas      -$0e,s    allocate local record
                    stu       -$02,s    store node and set flags
                    bne       FoldSetup non-null so process it
                    clra                high byte of null result
                    clrb                low byte of null result
                    lbra      FoldReturn2 return null

FoldSetup           ldd       $0a,u     D = node left child
                    std       $0C,s     save left in record
                    ldd       $0C,u     D = node right child
                    std       $0a,s     save right in record
                    ldd       $06,u     D = node opcode
                    std       $06,s     save opcode in record
                    pshs      d         push opcode
                    lbsr      IsTypeCodeInRange is opcode a foldable operator
                    std       ,s++      save result and pop
                    bne       CheckConstOperands yes so try to fold
                    ldd       $06,s     D = node opcode
                    cmpd      #$0047    is it operator G
                    beq       CheckConstOperands yes so foldable
                    ldd       $06,s     D = node opcode
                    cmpd      #$0048    is it operator H
                    lbne      UnaryDispatchPrep not foldable try unary/convert
CheckConstOperands  ldx       $0C,s     X = left child
                    ldd       $06,x     D = left opcode
                    cmpd      #$0036    is left a constant literal
                    bne       LeftNotConst no
                    ldd       #$0001    flag left constant
                    bra       SaveLeftConstFlag store the flag

LeftNotConst        clra                high byte cleared
                    clrb                flag left non-constant
SaveLeftConstFlag   std       $02,s     save left-const flag
                    pshs      d         push the flag
                    ldx       $0C,s     X = left child
                    ldd       $06,x     D = left opcode
                    cmpd      #$0036    is left a constant literal
                    bne       LeftNotConst2 no
                    ldd       #$0001    flag constant
                    bra       SaveConstFlag2 store the flag

LeftNotConst2       clra                high byte cleared
                    clrb                flag non-constant
SaveConstFlag2      std       $02,s     save the flag
                    anda      ,s+       AND high byte with pushed flag
                    andb      ,s+       AND low byte with pushed flag
                    std       -$02,s    both operands constant
                    beq       TryCommute not both constant so continue
                    leax      $0e,s     point X past record
                    lbra      BinaryConstFixup fold the two constants

TryCommute          ldd       $02,s     D = left-const flag
                    beq       FoldDispatchPrep left not constant skip reorder
                    ldx       $06,s     X = node opcode
                    bra       IsCommutative test commutativity

SwapOperands        ldd       $0C,s     D = left child
                    std       $08,s     stash left
                    ldd       $0a,s     D = right child
                    std       $0C,s     record left = right
                    std       $0a,u     write swapped left into node
                    ldd       $08,s     D = stashed left
                    std       $0a,s     record right = left
                    std       $0C,u     write swapped right into node
                    ldd       #$0001    flag operands swapped
                    std       ,s        save swap flag
                    bra       FoldDispatchPrep proceed to dispatch

IsCommutative       cmpx      #$0050    operator P
                    beq       SwapOperands commutative so swap
                    cmpx      #$0052    operator R
                    lbeq      SwapOperands commutative so swap
                    cmpx      #$0057    operator W
                    lbeq      SwapOperands commutative so swap
                    cmpx      #$0058    operator X
                    lbeq      SwapOperands commutative so swap
                    cmpx      #$0059    operator Y
                    lbeq      SwapOperands commutative so swap
FoldDispatchPrep    ldx       $06,s     X = node opcode
                    lbra      FoldDispatch jump to fold dispatch

FoldZeroIdentity    ldd       ,s        D = swap flag
                    lbeq      NoFold    not swapped so no fold
                    ldx       $0a,s     X = right operand
                    ldd       $08,x     D = right value
                    lbeq      ReplaceWithOperand zero operand use the other
                    lbra      NoFold    else no fold

FoldAdd2            ldd       ,s        D = swap flag
                    lbeq      NoFold    not swapped so no fold
                    ldx       $0a,s     X = right operand
                    ldd       $08,x     D = right value
                    lbeq      ReplaceWithOperand add zero use other operand
                    ldx       $0C,s     X = left operand
                    ldx       $06,x     X = left opcode
                    lbra      CheckAddPtr check pointer arithmetic

FoldPtrOffset       ldx       $0C,s     X = left operand
                    ldx       $0a,x     X = left's operand node
                    ldd       $14,x     D = its offset field
                    leax      $14,x     X = address of offset field
                    pshs      x,d       save pointer and offset
                    ldx       $0e,s     X = right operand
                    ldd       $08,x     D = right value
                    addd      ,s++      add the saved offset
                    std       [,s++]    store folded offset back
                    bra       KeepOtherOperand reduce the node

KeepOperandFixup    leas      -$0e,x    restore stack from X
KeepOtherOperand    ldd       $0C,s     D = left operand
                    std       $08,s     stash it as keeper
                    pshs      u         push the node
                    lbsr      LinkFreeNode free the node
                    leas      $02,s     drop the argument
                    ldd       $0a,s     D = right operand
                    pshs      d         push it
                    lbsr      LinkFreeNode free the right operand
                    leas      $02,s     drop the argument
                    ldu       $08,s     U = kept operand
                    lbra      NoFold    return the kept operand

FoldNestedAdd       ldx       $0C,s     X = left operand
                    ldx       $0C,x     X = left's right child
                    ldd       $06,x     D = its opcode
                    cmpd      #$0036    is it a constant
                    lbne      NoFold    no so cannot fold
                    ldx       $0C,s     X = left operand
                    ldx       $0C,x     X = left's right child
                    ldd       $08,x     D = that constant value
                    leax      $08,x     X = address of value
                    pshs      x,d       save pointer and value
                    ldx       $0e,s     X = right operand
                    ldd       $08,x     D = right value
                    addd      ,s++      add the two constants
                    lbra      StoreFoldedConst store the folded value

CheckAddPtr         cmpx      #$0041    left is operator A
                    lbeq      FoldPtrOffset fold pointer offset
                    cmpx      #$0050    left is operator P
                    beq       FoldNestedAdd fold nested add constant
                    lbra      NoFold    else no fold

FoldSubtract        ldd       ,s        D = swap flag
                    beq       FoldZeroMinus not swapped check zero minuend
                    ldx       $0a,s     X = right operand
                    ldd       $08,x     D = right value
                    nega                negate high byte
                    negb                negate low byte
                    sbca      #$00      finish two's complement negate
                    ldx       $0a,s     X = right operand
                    std       $08,x     store negated value
                    ldd       #$0050    change opcode to add P
                    std       $06,u     subtract-const becomes add-negated
                    pshs      u         push the node
                    lbsr      FoldConstNode re-fold the node
                    leas      $02,s     drop the argument
                    lbra      FoldReturn2 return the re-folded node

FoldZeroMinus       ldd       $02,s     D = left-const flag
                    lbeq      NoFold    left not constant so no fold
                    ldx       $0C,s     X = left operand
                    ldd       $08,x     D = left value
                    lbne      NoFold    nonzero minuend so no fold
                    ldd       #$0043    set opcode to negate C
                    std       $06,u     zero minus x becomes negate
                    ldd       $0a,s     D = right operand
                    std       $0a,u     make it the child
                    clra                high byte cleared
                    clrb                low byte cleared
                    std       $0C,u     clear the right child
                    ldd       $0C,s     D = old left operand
                    lbra      FreeChildDone free it and finish

FoldZeroOperand     ldd       ,s        D = swap flag
                    lbeq      NoFold    not swapped so no fold
                    ldx       $0a,s     X = right operand
                    ldd       $08,x     D = right value
                    beq       MakeZeroFixup operand zero so result zero
                    lbra      NoFold    else no fold

FoldMultiply        ldd       ,s        D = swap flag
                    lbeq      NoFold    not swapped so no fold
                    ldx       $0a,s     X = right operand
                    ldx       $08,x     X = right value
                    bra       DispatchMultiplier dispatch on the multiplier

MakeZeroFixup       leax      $0e,s     point X past record
                    lbra      MakeZeroFixup2 make node constant zero

FoldNestedMul       ldx       $0C,s     X = left operand
                    ldd       $06,x     D = left opcode
                    cmpd      #$0052    is left a multiply R
                    lbne      NoFold    no so cannot fold
                    ldx       $0C,s     X = left operand
                    ldx       $0C,x     X = left's right child
                    ldd       $06,x     D = its opcode
                    cmpd      #$0036    is it a constant
                    lbne      NoFold    no so cannot fold
                    ldx       $0C,s     X = left operand
                    ldx       $0C,x     X = left's right child
                    ldd       $08,x     D = that constant
                    leax      $08,x     X = address of value
                    pshs      x,d       save pointer and value
                    ldx       $0e,s     X = right operand
                    ldd       $08,x     D = right multiplier
                    lbsr      MulInt32  multiply the two constants
StoreFoldedConst    std       [,s++]    store the folded product back
                    bra       ReplaceWithOperand reduce to that operand

DispatchMultiplier  stx       -$02,s    save the multiplier value
                    beq       MakeZeroFixup times zero so result zero
                    cmpx      #$0001    times one
                    beq       ReplaceWithOperand identity so use other operand
                    bra       FoldNestedMul else try nested multiply

FoldDivide          ldd       ,s        D = swap flag
                    beq       CheckZeroDividend not swapped check divide
                    ldx       $0a,s     X = right operand
                    ldd       $08,x     D = right value
                    cmpd      #$0001    divide by one
                    bne       CheckZeroDividend no so check zero dividend
ReplaceWithOperand  leax      $0e,s     point X past record
                    lbra      KeepOperandFixup replace node with kept operand

CheckZeroDividend   ldd       $02,s     D = left-const flag
                    lbeq      NoFold    left not constant so no fold
                    ldx       $0C,s     X = left operand
                    ldd       $08,x     D = left value
                    lbne      NoFold    nonzero dividend so no fold
                    bra       MakeConstZero zero divided so result zero

MakeZeroFixup2      leas      -$0e,x    restore stack from X
MakeConstZero       ldd       #$0036    constant node type
                    std       $06,u     make node a constant
                    clra                high byte cleared
                    clrb                value zero
StoreConstFreeChildren std       $08,u     store value into node
                    clra                high byte cleared
                    clrb                low byte cleared
                    std       $0C,u     clear the right child
                    std       $0a,u     clear the left child
                    ldd       $0C,s     D = old left operand
                    pshs      d         push it
                    lbsr      LinkFreeNode free old left operand
                    leas      $02,s     drop the argument
                    ldd       $0a,s     D = old right operand
FreeChildDone       pshs      d         push it
                    lbsr      LinkFreeNode free old right operand
FoldRet             leas      $02,s     drop the argument
                    lbra      NoFold    return the folded node

FoldDispatch        cmpx      #$0058    operator X
                    lbeq      FoldZeroIdentity fold zero identity
                    cmpx      #$0059    operator Y
                    lbeq      FoldZeroIdentity fold zero identity
                    cmpx      #$0050    operator P is add
                    lbeq      FoldAdd2  fold addition
                    cmpx      #$0051    operator Q is subtract
                    lbeq      FoldSubtract fold subtraction
                    cmpx      #$0057    operator W
                    lbeq      FoldZeroOperand fold zero-operand product
                    cmpx      #$0052    operator R is multiply
                    lbeq      FoldMultiply fold multiplication
                    cmpx      #$0053    operator S is divide
                    lbeq      FoldDivide fold division
                    lbra      NoFold    no handler so no fold

UnaryDispatchPrep   ldx       $06,s     X = node opcode
                    lbra      UnaryDispatch dispatch unary/convert handlers

FoldUnaryConst      ldx       $0C,s     X = left operand
                    ldd       $06,x     D = left opcode
                    cmpd      #$0036    is operand a constant
                    bne       FoldConvertJ no so try convert op
                    bra       EvalBinaryConst fold the unary constant

BinaryConstFixup    leas      -$0e,x    restore stack from X
EvalBinaryConst     ldd       #$0036    constant node type
                    std       $06,u     make node a constant
                    clra                high byte cleared
                    clrb                low byte cleared
                    std       $12,u     clear the extra field
                    ldx       $0a,s     X = right operand
                    ldd       $08,x     D = right value
                    pshs      d         push right value
                    ldx       $0e,s     X = left operand
                    ldd       $08,x     D = left value
                    pshs      d         push left value
                    ldd       $0a,s     D = operator code
                    pshs      d         push the operator
                    lbsr      FoldConstOp evaluate operator on constants
                    leas      $06,s     drop the arguments
                    lbra      StoreConstFreeChildren store result and free children

FoldConvertJ        ldx       $0C,s     X = left operand
                    ldd       $06,x     D = left opcode
                    cmpd      #$004A    is it convert-J
                    bne       FoldConvertK no so try convert-K
                    leas      -$02,s    make a scratch slot
                    ldx       $0e,s     X = left operand
                    ldd       $08,x     D = left value
                    std       ,s        save it
                    bne       ConvSetup nonzero so keep it
                    ldd       #$0004    request four bytes
                    pshs      d         push the size
                    lbsr      AllocMem  allocate a node
                    leas      $02,s     drop the argument
                    std       ,s        save new node pointer
ConvSetup           ldx       $08,s     X = target type field
                    bra       ConvDispatch dispatch the conversion

ConvSigned          ldx       ,s        X = source node
                    pshs      x         push it
                    ldx       $02,s     X = value node
                    lbsr      NegateInt32 convert as signed
                    bra       ConvFinalize apply the conversion

ConvUnsigned        ldx       ,s        X = source node
                    pshs      x         push it
                    ldx       $02,s     X = value node
                    lbsr      ComplementInt32 convert as unsigned
ConvFinalize        lbsr      StoreInt32 finalize the conversion
                    bra       StoreConverted store the converted value

ConvDispatch        cmpx      #$0043    target type C
                    beq       ConvSigned signed conversion
                    cmpx      #$0044    target type D
                    beq       ConvUnsigned unsigned conversion
StoreConverted      ldd       ,s        D = converted value
                    ldx       $0e,s     X = node
                    std       $08,x     store into node value
                    bra       FreeNodeRet free node and finish

FoldConvertK        ldx       $0C,s     X = left operand
                    ldd       $06,x     D = left opcode
                    cmpd      #$004B    is it convert-K
                    bne       NoFold    no so cannot fold
                    leas      -$02,s    make a scratch slot
                    ldx       $0e,s     X = left operand
                    ldd       $08,x     D = left value
                    std       ,s        save it
                    beq       FreeNodeRet zero so just free node
                    ldx       ,s        X = value node
                    pshs      x         push it
                    ldx       $02,s     X = node
                    lbsr      NegateConstType perform K conversion
                    lbsr      CopyFloat finalize the conversion
FreeNodeRet         pshs      u         push the node
                    lbsr      LinkFreeNode free the node
                    leas      $02,s     drop the argument
                    ldu       $0e,s     U = replacement operand
                    lbra      FoldRet   return it

UnaryDispatch       cmpx      #$0040    operator @
                    lbeq      FoldUnaryConst fold unary constant
                    cmpx      #$0044    operator D
                    lbeq      FoldUnaryConst fold unary constant
                    cmpx      #$0043    operator C
                    lbeq      FoldUnaryConst fold unary constant
NoFold              tfr       u,d       return node in D
FoldReturn2         leas      $0e,s     drop the local record
                    puls      pc,u      restore U and return

ReduceNode          pshs      u         save U
                    ldd       #$FFC0    frame size for stack check
                    lbsr      stkcheck  verify stack space
                    ldu       $04,s     U = node argument
                    stu       -$02,s    store node and set flags
                    beq       IsLvalTypeFalse null node so nothing to do
                    ldx       $06,u     X = node opcode
                    bra       ClassifyLvalType dispatch simplification

IsLvalTypeTrue      ldd       #$0001    return true, type is lvalue-capable
                    puls      pc,u      restore U and return

ClassifyLvalType    cmpx      #$0076    is node type $76
                    beq       IsLvalTypeTrue yes, return true
                    cmpx      #$006F    is node type $6F
                    lbeq      IsLvalTypeTrue yes, return true
                    cmpx      #$0036    is node type $36
                    lbeq      IsLvalTypeTrue yes, return true
                    cmpx      #$004A    is node type $4A
                    lbeq      IsLvalTypeTrue yes, return true
                    cmpx      #$004B    is node type $4B
                    lbeq      IsLvalTypeTrue yes, return true
                    cmpx      #$0034    is node type $34
                    lbeq      IsLvalTypeTrue yes, return true
                    cmpx      #$0037    is node type $37
                    lbeq      IsLvalTypeTrue yes, return true
IsLvalTypeFalse     clra                no match, result = 0
                    clrb                clear low byte
                    puls      pc,u      return false

DivByZeroErr        pshs      u         save caller U
                    ldd       #$FFBA    required stack frame size
                    lbsr      stkcheck  check stack space available
                    leax      MsgDivZero,pcr point to divide by zero message
                    pshs      x         push message pointer
                    lbsr      BuildMsgBuf report compiler error
                    leas      $02,s     drop message argument
                    puls      pc,u      restore U and return

GenExprNode         pshs      u         save caller U
                    ldd       #$FF9C    required stack frame size
                    lbsr      stkcheck  check stack space available
                    leas      -$14,s    allocate local frame
                    ldx       $18,s     X = node pointer argument
                    ldu       $0a,x     U = node child pointer
                    ldx       $18,s     reload node pointer
                    ldd       $0C,x     get node field $0C
                    std       $12,s     save into local
                    ldd       #$0002    initial value 2
                    std       $0a,s     init local operand size
                    std       $08,s     init local lvalue flag
                    clra                clear A
                    clrb                clear B
                    std       $06,s     clear result field local
                    ldd       #$0001    initial value 1
                    std       $0C,s     init local result type
                    ldx       $18,s     reload node pointer
                    ldd       $06,x     get node operator type
                    std       $0e,s     save current type local
                    tfr       d,x       X = operator type for dispatch
                    lbra      DispatchOp jump into node-type dispatch

GenVarRef           ldx       $18,s     X = node pointer
                    ldd       $08,x     get symbol subtype pointer
                    std       $10,s     save subtype pointer local
                    ldx       $10,s     X = subtype descriptor
                    ldd       $08,x     load descriptor kind
                    cmpd      #$001E    is it a typedef
                    bne       GenVarNotTypedef no, generate variable reference
                    leax      MsgTypedefNotVar,pcr point to typedef error message
                    pshs      x         push message pointer
                    ldd       $1a,s     push source context
                    pshs      d         push context argument
                    lbsr      ReportErrorAt report error at node
                    leas      $04,s     drop arguments
                    ldd       $18,s     node pointer
                    pshs      d         push node argument
                    lbsr      MakeErrorNode discard bad node
                    leas      $02,s     drop argument
                    lbra      NodeDone  handler done, return

GenVarNotTypedef    ldd       [$10,s]   load result type indirect
                    std       $0C,s     save result type local
                    ldx       $10,s     X = subtype descriptor
                    ldd       $04,x     get descriptor field $04
                    std       $06,s     save into result field
                    ldd       $0C,s     reload result type
                    clra                clear high byte
                    andb      #$0f      keep low nibble
                    cmpd      #$000A    is storage class $0A
                    bne       GenVarStorageChk no, skip offset adjust
                    leas      -$02,s    reserve temp local
                    ldx       $12,s     context pointer
                    ldd       $02,x     get base offset
                    std       ,s        save temp
                    ldd       $0e,s     current type value
                    andb      #$F0      keep high nibble
                    addd      [,s]      add member offset indirect
                    std       [$12,s]   store back into context
                    std       $0e,s     update current type
                    ldx       ,s        temp pointer
                    ldd       $02,x     get field
                    pshs      d         push argument
                    ldd       $0a,s     push argument
                    pshs      d         push argument
                    ldd       $16,s     push argument
                    pshs      d         push argument
                    lbsr      CalcTypeSize call codegen helper
                    leas      $06,s     drop arguments
                    leas      $02,s     release temp local
GenVarStorageChk    ldx       $10,s     X = subtype descriptor
                    ldd       $02,x     get descriptor field $02
                    std       $0a,s     save operand local
                    ldd       $0C,s     result type
                    clra                clear high byte
                    andb      #$30      keep storage class bits
                    cmpd      #$0020    is static/extern class $20
                    beq       GenVarStaticAddr yes, take its address
                    ldd       $0C,s     result type
                    clra                clear high byte
                    andb      #$30      keep storage class bits
                    cmpd      #$0030    is class $30
                    lbne      GenVarRegister neither, register/local branch
GenVarStaticAddr    ldu       $18,s     U = node pointer
                    ldd       $0a,s     operand local
                    std       $02,u     store into node field $02
                    ldx       $18,s     reload node
                    ldd       $10,x     get node field $10
                    pshs      d         push argument
                    ldx       $1a,s     context pointer
                    ldd       $0e,x     get field $0e
                    pshs      d         push argument
                    clra                clear A
                    clrb                clear B
                    pshs      d         push zero
                    clra                clear A
                    clrb                clear B
                    pshs      d         push zero
                    pshs      u         push node child
                    ldd       #$0041    operator $41 address-of
                    pshs      d         push operator
                    lbsr      AllocExprNode build address-of node
                    leas      $0C,s     drop arguments
                    std       $18,s     save new node pointer
                    ldd       $0C,s     result type
                    clra                clear high byte
                    andb      #$30      keep storage class bits
                    cmpd      #$0020    is static class $20
                    bne       GenVarLocalType no, use type directly
                    ldd       $06,s     result field
                    pshs      d         push argument
                    lbsr      GetNodeType convert type helper
                    leas      $02,s     drop argument
                    std       $06,s     save result field
                    ldd       $0C,s     result type
                    pshs      d         push argument
                    lbsr      TypeRemoveLevel make pointer to type
                    leas      $02,s     drop argument
                    bra       GenVarStoreType store new result type

GenVarLocalType     ldd       $0C,s     result type
GenVarStoreType     std       ,u        store type into node
                    pshs      d         push argument
                    lbsr      TypeAddLevel make pointer to type
                    leas      $02,s     drop argument
                    std       $0C,s     save result type
                    ldd       #$0001    lvalue flag one
                    std       $12,u     mark node as lvalue
                    bra       SetLvalTrue set lvalue and return

GenVarRegister      ldx       $10,s     X = subtype descriptor
                    ldd       $08,x     get descriptor kind
                    std       $04,s     save local
                    tfr       d,x       X = type kind
                    bra       GenVarRegTypeChk test register type

GenVarClearField    ldd       $04,s     type kind
                    ldx       $18,s     node pointer
                    std       $06,x     store type into node
                    clra                clear A
                    clrb                clear B
                    ldx       $18,s     node pointer
                    std       $08,x     clear node subtype field
                    bra       SetLvalTrue set lvalue and return

GenVarRegTypeChk    cmpx      #$0076    is type $76
                    beq       GenVarClearField yes, clear node fields
                    cmpx      #$006F    is type $6F
                    lbeq      GenVarClearField yes, clear node fields
SetLvalTrue         ldd       #$0001    lvalue flag one
                    bra       StoreLvalFlag store lvalue flag

SetLvalFalse        clra                clear A
                    clrb                clear B
StoreLvalFlag       std       $08,s     store lvalue flag
                    lbra      NodeDone  handler done, return

