                    ldu       $14,s     load other node
                    ldd       ,s        get saved node
                    std       $14,s     swap into slot
                    leas      $02,s     drop temp
                    ldx       $18,s     get target node
                    stu       $0a,x     store swapped operand
GenNode50Type       ldd       $02,u     get node field 2
                    std       $0a,s     save value
                    ldd       ,u        get node operator
                    std       $0C,s     save type
                    clra                clear high byte
                    andb      #$30      isolate type-class bits
                    cmpd      #$0010    is it class $10
                    bne       GenNode50Convert no, reduce
                    ldd       $04,u     get node field 4
                    std       $06,s     save it
                    leax      $14,s     point at stack frame
                    lbra      PtrSubJoin continue

GenNode50Convert    ldd       $12,s     get operand pointer
                    pshs      d         push argument
                    pshs      u         push node
                    lbsr      BalanceOperands call helper
                    leas      $04,s     drop arguments
                    std       $0C,s     save type
                    ldd       $12,u     get node field 12
                    ldx       $12,s     get operand pointer
                    addd      $12,x     add operand field 12
GenNode50Store      std       $08,s     save computed size
GenNodeDone2        lbra      NodeDone  back to dispatch loop

GenNode51           ldd       $12,u     get node field 12
                    ldx       $12,s     get operand pointer
                    addd      $12,x     sum the sizes
                    std       $08,s     save size
                    ldd       ,u        get node operator
                    std       $0C,s     save type
                    clra                clear high byte
                    andb      #$30      isolate type-class bits
                    cmpd      #$0010    is it class $10
                    lbne      CombineTypesOp not class $10
                    ldd       $02,u     get node field 2
                    std       $0a,s     save value
                    ldd       $04,u     get node field 4
                    std       $06,s     save it
                    ldd       [$12,s]   load operand operator
                    clra                clear high byte
                    andb      #$30      isolate type-class bits
                    cmpd      #$0010    is it class $10
                    lbne      PtrSubBody not class $10
                    ldd       $08,s     get size
                    ldx       $18,s     get target node
                    std       $12,x     store size field
                    ldd       $0C,s     get type
                    cmpd      [$12,s]   compare with operand type
                    bne       GenNode51TypeErr mismatch, error
                    ldd       $0a,s     get value
                    ldx       $12,s     get operand pointer
                    cmpd      $02,x     compare with operand field 2
                    beq       GenNode51Match match, fold constants
GenNode51TypeErr    leax      MsgPtrMismatch1,pcr message pointer
                    pshs      x         push message
                    ldd       $1a,s     get node argument
                    pshs      d         push argument
                    lbsr      ReportErrorAt report error
                    leas      $04,s     drop arguments
                    lbra      BuildIntResult continue

GenNode51Match      ldd       $0C,s     get type
                    pshs      d         push argument
                    lbsr      TypeRemoveLevel get base type
                    leas      $02,s     drop argument
                    std       $0C,s     save type
                    ldd       $06,s     get field
                    pshs      d         push argument
                    ldd       $0C,s     get type
                    pshs      d         push argument
                    ldd       $10,s     get argument
                    pshs      d         push argument
                    lbsr      ResolveTypeSize call runtime helper
                    leas      $06,s     drop arguments
                    std       $0a,s     save value
                    cmpd      #$0001    result equals 1
                    lbeq      BuildIntResult yes, continue
                    ldd       #$0002    op size 2
                    std       $08,s     save size
                    clra                clear high byte
                    clrb                D = 0
                    pshs      d         push zero argument
                    clra                clear high byte
                    clrb                D = 0
                    pshs      d         push zero argument
                    ldd       $0e,s     get field
                    pshs      d         push argument
                    clra                clear high byte
                    clrb                D = 0
                    pshs      d         push zero argument
                    clra                clear high byte
                    clrb                clear B for argument byte
                    pshs      d         push argument word
                    ldd       #$0036    D = type code $36
                    pshs      d         push type-$36 argument
                    lbsr      AllocExprNode build tree node
                    leas      $0C,s     drop six pushed args
                    std       $10,s     save new node pointer
                    ldx       $18,s     X = result node
                    ldd       $10,x     load node field $10
                    pshs      d         push it
                    ldx       $1a,s     X = second node
                    ldd       $0e,x     load field $0e
                    pshs      d         push it
                    clra                clear A
                    clrb                clear B
                    pshs      d         push zero word
                    ldd       $16,s     load local slot $16
                    pshs      d         push it
                    ldd       $20,s     load local slot $20
                    pshs      d         push it
                    ldd       #$0053    D = type code $53
                    pshs      d         push type-$53 argument
                    lbsr      AllocExprNode build tree node
                    leas      $0C,s     drop six pushed args
                    std       $18,s     save as result node
BuildIntResult      ldd       #$0002    D = 2
                    std       $0a,s     result field2 = 2
                    clra                clear A
                    clrb                clear B
                    std       $06,s     result field4 = 0
                    ldd       #$0001    D = int type 1
                    lbra      StoreResultType store type and finish

PtrSubJoin          leas      -$14,x    restore stack frame
PtrSubBody          ldd       $12,s     D = left operand node
                    pshs      d         push it
                    lbsr      CheckOperand check operand type
                    leas      $02,s     drop arg
                    ldd       [$12,s]   D = operand type word
                    pshs      d         push it
                    lbsr      IsIntegralType test for pointer type
                    std       ,s++      pop test result
                    bne       PtrSubScale branch if pointer
                    ldd       $12,s     D = operand node
                    pshs      d         push it
                    lbsr      ReportNotIntegral convert operand helper
                    leas      $02,s     drop arg
                    ldd       $12,s     D = operand node
                    pshs      d         push it
                    lbsr      MakeErrorNode scale operand helper
                    leas      $02,s     drop arg
PtrSubScale         ldd       #$0001    scale factor = 1
                    pshs      d         push it
                    ldd       $14,s     D = right operand node
                    pshs      d         push it
                    lbsr      CoerceExpr convert/scale operand
                    leas      $04,s     drop two args
                    ldd       $12,s     D = left node
                    pshs      d         push it
                    ldd       $08,s     D = local operand
                    pshs      d         push it
                    ldd       $10,s     D = node field $10
                    pshs      d         push it
                    ldd       $10,s     D = node field $10
                    pshs      d         push it
                    lbsr      ScaleSubscript build subtract node
                    leas      $08,s     drop four args
                    ldx       $18,s     X = result node
                    std       $0C,x     store into result type
                    ldd       $12,u     D = node offset value
                    ldx       $12,s     X = left node
                    addd      $12,x     add left offset
                    std       $08,s     save combined offset
                    lbra      NodeDone  finish node

PtrRelOp            clra                clear A
                    clrb                clear B
                    pshs      d         push zero word
                    pshs      u         push node pointer
                    lbsr      RequireLvalue fetch operands helper
                    leas      $04,s     drop two args
                    ldd       $12,s     D = left operand node
                    pshs      d         push it
                    lbsr      ReportUndeclared process left operand
                    leas      $02,s     drop arg
                    ldd       $12,s     D = operand node
                    pshs      d         push it
                    lbsr      RejectAggregate convert operand helper
                    leas      $02,s     drop arg
                    std       $02,s     save right type
                    ldd       ,u        D = left operand type
                    std       $0C,s     save left type
                    clra                clear high byte
                    andb      #$30      mask type class bits
                    cmpd      #$0010    is it pointer class
                    bne       CmpCheckRight skip if not pointer
                    ldd       $02,s     D = right type
                    clra                clear high byte
                    andb      #$30      mask type class bits
                    cmpd      #$0010    right also pointer
                    beq       CmpCheckRight skip if both pointers
                    ldd       $02,s     D = right type
                    pshs      d         push it
                    lbsr      IsIntegralType test right pointer/scalar
                    std       ,s++      pop result
                    lbeq      BadPtrErr error if not scalar
CmpCheckRight       ldd       $02,s     D = right type
                    clra                clear high byte
                    andb      #$30      mask type class bits
                    cmpd      #$0010    is right pointer
                    bne       CmpConvertJoin skip if not pointer
                    ldd       $0C,s     D = left type
                    clra                clear high byte
                    andb      #$30      mask type class bits
                    cmpd      #$0010    left also pointer
                    beq       CmpConvertJoin skip if both pointers
                    ldd       $0C,s     D = left type
                    pshs      d         push it
                    lbsr      IsIntegralType test left pointer/scalar
                    std       ,s++      pop result
                    lbeq      BadPtrErr error if not scalar
CmpConvertJoin      ldd       $0C,s     D = left type
                    pshs      d         push it
                    ldd       $14,s     D = operand node
                    pshs      d         push it
                    lbsr      CoerceExpr convert operand helper
                    leas      $04,s     drop two args
                    leax      $14,s     X = frame save pointer
                    lbra      CmpFinishJoin join comparison finish

UnaryHighOp         leas      -$14,x    restore stack frame
                    clra                clear A
                    clrb                clear B
                    pshs      d         push zero word
                    pshs      u         push node pointer
                    lbsr      RequireLvalue fetch operand helper
                    leas      $04,s     drop two args
                    ldd       $12,s     D = operand node
                    pshs      d         push it
                    lbsr      CheckOperand check operand type
                    leas      $02,s     drop arg
                    ldd       $12,s     D = operand node
                    pshs      d         push it
                    lbsr      RejectAggregate convert operand helper
                    leas      $02,s     drop arg
                    std       $02,s     save converted operand
                    ldd       ,u        D = operand type
                    std       $0C,s     save type
                    clra                clear high byte
                    andb      #$30      mask type class bits
                    cmpd      #$0010    is pointer class
                    bne       ScalarUnaryOp branch if not pointer
                    ldx       $0e,s     X = operator code
                    bra       CheckIncDecOp check inc/dec operator

IncDecScale         ldd       #$0001    scale factor = 1
                    pshs      d         push it
                    ldd       $14,s     D = operand node
                    pshs      d         push it
                    lbsr      CoerceExpr convert/scale operand
                    leas      $04,s     drop two args
                    leax      $14,s     X = frame save pointer
                    bra       AsgnOpJoin join assign-op body

BadPtrErr           leax      $14,s     X = frame save pointer
                    lbra      ReportPtrErr go report pointer error

CheckIncDecOp       cmpx      #$00A1    operator == $A1
                    beq       IncDecScale handle pointer inc/dec
                    cmpx      #$00A0    operator == $A0
                    lbeq      IncDecScale handle pointer inc/dec
                    bra       BadPtrErr else pointer error

ScalarUnaryOp       ldx       $0e,s     X = operator code
                    lbra      CheckAsgnDeref check deref assign operator

PromoteAndConvert   ldd       $0C,s     D = operand type
                    cmpd      #$0005    type == 5 (float?)
                    bne       UseOperandType skip if not
                    ldd       #$0006    promote to type 6
                    bra       ConvertOperand go convert operand

UseOperandType      ldd       $0C,s     D = operand type
ConvertOperand      pshs      d         push it
                    ldd       $14,s     D = operand node
                    pshs      d         push it
                    lbsr      CoerceExpr convert operand helper
                    leas      $04,s     drop two args
                    bra       AsgnOpBody go to assign-op body

AsgnOpJoin          leas      -$14,x    restore stack frame
AsgnOpBody          ldd       $0e,s     D = operator code
                    addd      #$FFB0    subtract $50 offset
                    ldx       $18,s     X = result node
                    std       $06,x     store adjusted operator
                    ldd       $18,s     D = result node
                    pshs      d         push it
                    lbsr      GenExprNode process node helper
                    leas      $02,s     drop arg
                    std       $18,s     save result node
                    ldd       $0C,s     D = operand type
                    cmpd      #$0002    type == 2
                    bne       AsgnOpTypeFix skip if not
                    ldd       $0a,u     D = node offset field
                    ldx       $18,s     X = result node
                    std       $0a,x     store offset field
                    pshs      u         push node pointer
                    lbsr      LinkFreeNode helper call
                    leas      $02,s     drop arg
                    ldx       $18,s     X = result node
                    ldu       $0a,x     U = node offset field
                    ldd       #$0001    D = int type 1
                    std       $0C,s     set type to int
AsgnOpTypeFix       ldd       $0e,s     D = operator code
                    addd      #$FFB0    subtract $50 offset
                    ldx       $18,s     X = result node
                    cmpd      $06,x     compare stored operator
                    bne       CmpFinish skip if different
                    ldd       $0e,s     D = operator code
                    ldx       $18,s     X = result node
                    std       $06,x     store operator field
                    bra       CmpFinish go finish comparison

CheckAsgnDeref      cmpx      #$00A6    operator == $A6
                    beq       AsgnOpBody go to assign-op body
                    cmpx      #$00A5    operator == $A5
                    lbeq      AsgnOpBody go to assign-op body
                    lbra      PromoteAndConvert else promote and convert

CmpFinishJoin       leas      -$14,x    restore stack frame
CmpFinish           ldd       $02,u     D = node field2
                    std       $0a,s     save field2
                    ldd       $12,u     D = node offset
                    ldx       $12,s     X = left node
                    addd      $12,x     add left offset
                    std       $08,s     save combined offset
                    ldd       $04,u     D = node operator field
                    lbra      StoreOpFinish store operator and finish

ReportPtrErr        leas      -$14,x    restore stack frame
                    leax      MsgTypeMismatch,pcr X = error message text
                    pshs      x         push message pointer
                    ldd       $1a,s     D = source line/node
                    pshs      d         push it
                    lbsr      ReportErrorAt report error
                    lbra      DropArgsDone drop args and finish

DerefOp             ldd       ,u        D = node type word
                    std       $0C,s     save type
                    clra                clear high byte
                    andb      #$30      mask type class bits
                    cmpd      #$0010    is pointer class
                    bne       DerefPtrType branch if not pointer
                    ldd       $02,u     D = node field2
                    std       $0a,s     save field2
                    ldd       $12,u     D = node offset
                    std       $08,s     save offset
                    ldd       $02,u     D = node field2
                    std       $06,s     save field4
                    ldd       [$12,s]   deref operand type
                    clra                clear high byte
                    andb      #$30      mask type class bits
                    cmpd      #$0010    is pointed-to pointer
                    bne       ForceIntJoin branch if not
                    ldd       $0C,s     D = node type
                    cmpd      [$12,s]   compare operand type
                    bne       IncompatPtrErr differ, error
                    ldd       $02,u     D = node field2
                    ldx       $12,s     X = operand node
                    cmpd      $02,x     compare sub-type
                    beq       ClearField4 match, clear field4
IncompatPtrErr      leax      MsgPtrMismatch2,pcr X = error message text
                    pshs      x         push message pointer
                    ldd       $1a,s     D = source line/node
                    pshs      d         push it
                    lbsr      ReportErrorAt report error
                    leas      $04,s     drop args
                    lbra      NodeDone  finish node

ClearField4         clra                clear A
                    clrb                clear B
                    std       $06,s     clear result field4
                    lbra      NodeDone  finish node

ForceIntJoin        ldd       $12,s     D = operand node
                    pshs      d         push it
ForceIntCall        lbsr      ForceIntType force operand to int
                    leas      $02,s     drop arg
                    lbra      NodeDone  finish node

DerefPtrType        ldd       [$12,s]   deref operand type
                    std       $0C,s     save type
                    clra                clear high byte
                    andb      #$30      mask type class bits
                    cmpd      #$0010    is pointer class
                    bne       CombineTypesOp branch if not pointer
                    ldx       $12,s     X = operand node
                    ldd       $02,x     D = operand field2
                    std       $0a,s     save field2
                    ldx       $12,s     X = operand node
                    ldd       $12,x     D = operand offset
                    std       $08,s     save offset
                    ldx       $12,s     X = operand node
                    ldd       $04,x     D = operand field4
                    std       $06,s     save field4
                    pshs      u         push node pointer
                    bra       ForceIntCall go force operand int

CombineTypesOp      ldd       $12,s     D = operand node
                    pshs      d         push it
                    pshs      u         push node pointer
                    lbsr      BalanceOperands combine operand types
                    leas      $04,s     drop two args
StoreResultType     std       $0C,s     store result type
                    lbra      NodeDone  finish node

CopyNodeType        ldd       [$12,s]   deref operand type
                    std       $0C,s     save type
                    ldx       $12,s     X = operand node
                    ldd       $02,x     D = operand field2
                    std       $0a,s     save field2
                    ldx       $12,s     X = operand node
                    ldd       $04,x     D = operand field4
StoreOpFinish       std       $06,s     store operator field
                    lbra      NodeDone  finish node

OpDefault           ldd       $0e,s     D = operator code
                    cmpd      #$00A0    compare against $A0
                    blt       BadOpErr  branch if below range
                    leax      $14,s     X = frame save pointer
                    lbra      UnaryHighOp handle high unary operator

BadOpErr            leax      MsgTypeCheck,pcr X = error message text
                    pshs      x         push message pointer
                    ldd       $1a,s     D = source line/node
                    pshs      d         push it
                    lbsr      InternalErr report error
DropArgsDone        leas      $04,s     drop error args
                    lbra      NodeDone  finish node

DispatchOp          cmpx      #$0034    operator == $34
                    lbeq      GenVarRef dispatch to handler
                    cmpx      #$0036    operator == $36
                    lbeq      SetLvalFalse dispatch to handler
                    cmpx      #$004A    operator == $4A
                    lbeq      GenConstType4A dispatch to handler
                    cmpx      #$004B    operator == $4B
                    lbeq      GenConstType4B dispatch to handler
                    cmpx      #$0037    operator == $37
                    lbeq      GenConstType37 dispatch to handler
                    cmpx      #$0020    operator == $20
                    lbeq      GenCast   dispatch to handler
                    cmpx      #$0041    operator == $41
                    lbeq      GenAddrOf dispatch to handler
                    cmpx      #$0042    operator == $42
                    lbeq      GenDeref  dispatch to handler
                    cmpx      #$0045    operator == $45
                    lbeq      GenBinOpType45 dispatch to handler
                    cmpx      #$0046    operator == $46
                    lbeq      GenBinOpType46 dispatch to handler
                    cmpx      #$0065    operator == $65
                    lbeq      GenNode65 dispatch to handler
                    cmpx      #$000B    operator == $0B
                    lbeq      GenNode0B dispatch to handler
                    cmpx      #$0030    operator == $30
                    lbeq      GenNode30 dispatch to handler
                    cmpx      #$0040    operator == $40
                    lbeq      GenNode40 dispatch to handler
                    cmpx      #$0043    operator == $43
                    lbeq      GenNode43 dispatch to handler
                    cmpx      #$0044    operator == $44
                    lbeq      GenNode44 dispatch to handler
                    cmpx      #$003C    operator == $3C (relational)
                    lbeq      GenRelOp  dispatch to relational handler
                    cmpx      #$003E    operator == $3E (relational)
                    lbeq      GenRelOp  dispatch to relational handler
                    cmpx      #$003D    operator == $3D (relational)
                    lbeq      GenRelOp  dispatch to relational handler
                    cmpx      #$003F    operator == $3F (relational)
                    lbeq      GenRelOp  dispatch to relational handler
                    cmpx      #$0047    operator == $47
                    lbeq      GenNode47 dispatch to handler
                    cmpx      #$0048    operator == $48
                    lbeq      GenNode47 dispatch to handler
                    cmpx      #$0053    operator == $53
                    lbeq      CombineTypesOp combine-types handler
                    cmpx      #$0052    operator == $52
                    lbeq      CombineTypesOp combine-types handler
                    cmpx      #$0057    operator == $57
                    lbeq      GenAssignNode dispatch to handler
                    cmpx      #$0058    operator == $58
                    lbeq      GenAssignNode dispatch to handler
                    cmpx      #$0059    operator == $59
                    lbeq      GenAssignNode dispatch to handler
                    cmpx      #$0054    operator == $54
                    lbeq      GenAssignNode dispatch to handler
                    cmpx      #$0056    operator == $56
                    lbeq      GenNode56 dispatch to handler
                    cmpx      #$0055    operator == $55
                    lbeq      GenNode56 dispatch to handler
                    cmpx      #$005D    operator == $5D
                    lbeq      GenNode5D dispatch to handler
                    cmpx      #$005F    operator == $5F
                    lbeq      GenNode5D dispatch to handler
                    cmpx      #$005C    operator == $5C
                    lbeq      GenNode5D dispatch to handler
                    cmpx      #$005E    operator == $5E
                    lbeq      GenNode5D dispatch to handler
                    cmpx      #$005A    operator == $5A
                    lbeq      GenNode5A dispatch to handler
                    cmpx      #$005B    operator == $5B
                    lbeq      GenNode5A dispatch to handler
                    cmpx      #$0050    operator == $50
                    lbeq      GenNode50 dispatch to handler
                    cmpx      #$0051    operator == $51
                    lbeq      GenNode51 dispatch to handler
                    cmpx      #$0078    operator == $78
                    lbeq      PtrRelOp  pointer-relational handler
                    cmpx      #$002F    operator == $2F
                    lbeq      DerefOp   dereference handler
                    cmpx      #$0064    operator == $64
                    lbeq      CopyNodeType copy-type handler
                    lbra      OpDefault default operator handler

NodeDone            ldd       $0C,s     D = result type word
                    std       [$18,s]   store type into node
                    ldd       $0a,s     D = result field2
                    ldx       $18,s     X = result node
                    std       $02,x     store field2
                    ldd       $08,s     D = result offset
                    ldx       $18,s     X = result node
                    std       $12,x     store offset field
                    ldd       $06,s     D = result field4
                    ldx       $18,s     X = result node
                    std       $04,x     store field4
                    ldd       $18,s     D = result node pointer
                    leas      $14,s     drop local frame
                    puls      pc,u      return result node

ForceIntType        pshs      u         save U on stack
                    ldd       #$FFB8    D = stack check size
                    lbsr      stkcheck  verify stack space
                    ldu       $04,s     U = target node
                    ldd       $06,u     D = node operator/type
                    cmpd      #$0036    already int type $36
                    bne       LoadNullMsg branch if not int
                    ldd       $08,u     D = node sub-type
                    beq       RetU      ok if zero
LoadNullMsg         leax      MsgShouldBeNull,pcr X = error message text
                    pshs      x         push message pointer
                    pshs      u         push node pointer
                    lbsr      ReportErrorAt report error
                    leas      $04,s     drop args
                    ldd       #$0036    force type to int $36
                    std       $06,u     store type
                    clra                clear A
                    clrb                clear B
                    std       $08,u     clear node sub-type
RetU                puls      pc,u      return

CheckOperand        pshs      u         save U on stack
                    ldd       #$FFB6    D = stack check size
                    lbsr      stkcheck  check for stack overflow
                    ldu       $04,s     U = expression node argument
                    leas      -$02,s    reserve local type slot
                    pshs      u         pass node pointer
                    lbsr      ReportUndeclared resolve node base type
                    leas      $02,s     drop argument
                    ldd       ,u        D = node type word
                    std       ,s        save current type
                    tfr       d,x       X = type for dispatch
                    bra       PromoteTypeDispatch dispatch on type

PromoteToInt        ldd       #$0001    result type = int
                    bra       StoreExprType store result type

PromoteToDouble     ldd       #$0006    result type = double
StoreExprType       std       ,s        save result type
                    pshs      d         push target type
                    pshs      u         push node pointer
                    bsr       CoerceExpr coerce node to double
                    leas      $04,s     drop arguments
                    bra       StoreTypeRet store type and return

BadTypeErr          leax      MsgTypeError,pcr point to error message text
                    pshs      x         push message pointer
                    pshs      u         push node pointer
                    lbsr      ReportErrorAt report type error
                    leas      $04,s     drop arguments
                    ldd       #$0001    default type = int
                    std       ,s        save result type
                    bra       StoreTypeRet store type and return

PromoteTypeDispatch cmpx      #$0002    type is char
                    beq       PromoteToInt promote char to int
                    cmpx      #$0005    type is unsigned long
                    beq       PromoteToDouble promote unsigned long to double
                    cmpx      #$0006    type is double
                    beq       StoreTypeRet already widest, keep
                    cmpx      #$0008    type is long
                    beq       StoreTypeRet keep as-is
                    cmpx      #$0001    type is int
                    beq       StoreTypeRet keep as-is
                    cmpx      #$0007    type is unsigned int
                    beq       StoreTypeRet keep as-is
                    bra       BadTypeErr unknown type error

StoreTypeRet        ldd       ,s        D = resolved type
                    std       ,u        store type into node
                    leas      $02,s     drop local slot
                    puls      pc,u      restore U and return

CoerceExpr          pshs      u         save node pointer
                    ldd       #$FFAC    stack frame size
                    lbsr      stkcheck  check for stack overflow
                    ldu       $04,s     U = node argument
                    leas      -$04,s    reserve local slots
                    clra                clear high byte
                    clrb                clear low byte
                    std       ,s        clear conversion opcode
                    ldx       ,u        X = source type
                    lbra      CoerceSrcDispatch dispatch on source type

CoerceFromChar      ldx       $0a,s     X = target type
