AggregateErr        leax      MsgAggregateBad,pcr error string aggregate inappropriate
                    pshs      x         push message
                    pshs      u         push node
                    lbsr      ReportErrorAt report error
                    leas      $04,s     drop arguments
                    pshs      u         push node
                    bsr       MakeErrorNode poison node
                    leas      $02,s     drop
ScalarOk            ldd       ,u        return node kind
                    puls      pc,u      restore frame and return

MakeErrorNode       pshs      u         save frame pointer
                    ldd       #$FFB6    frame size -74
                    lbsr      stkcheck  check stack space
                    ldu       $04,s     U = node argument
                    ldd       #$0006    length 6 bytes
                    pshs      d         push length
                    pshs      u         push dest node
                    leax      >$0078,y  error type template pointer
                    pshs      x         push source
                    lbsr      CopyMem   copy type descriptor
                    leas      $06,s     drop arguments
                    ldd       #$0001    flag value
                    std       $12,u     set width field
                    ldd       $0a,u     get left child
                    pshs      d         push it
                    lbsr      FreeExprTree free child node
                    leas      $02,s     drop
                    ldd       $0C,u     get right child
                    pshs      d         push it
                    lbsr      FreeExprTree free child node
                    leas      $02,s     drop
                    clra                high byte zero
                    clrb                low byte zero
                    std       $0C,u     clear right child
                    std       $0a,u     clear left child
                    ldd       #$0034    error type 52
                    std       $06,u     set node type
                    leax      >$0078,y  error type descriptor
                    stx       $08,u     point node at it
                    puls      pc,u      restore frame and return

IsIntegralType      pshs      u         save frame pointer
                    ldd       #$FFC0    frame size -64
                    lbsr      stkcheck  check stack space
                    ldx       $04,s     X = type code argument
                    bra       IntTypeChk test the type

IntTypeYes          ldd       #$0001    return true
                    puls      pc,u      return

IntTypeChk          cmpx      #$0001    type int
                    beq       IntTypeYes integral
                    cmpx      #$0002    type 2
                    lbeq      IntTypeYes integral
                    cmpx      #$0008    type long
                    lbeq      IntTypeYes integral
                    cmpx      #$0007    type 7
                    lbeq      IntTypeYes integral
                    clra                high byte zero
                    clrb                return false
                    puls      pc,u      return

ReportNotIntegral   pshs      u         save frame pointer
                    ldd       #$FFB8    frame size -72
                    lbsr      stkcheck  check stack space
                    leax      MsgMustBeIntegral,pcr error string must be integral
                    pshs      x         push message
                    ldd       $06,s     get node argument
                    pshs      d         push node
                    lbsr      ReportErrorAt report error
                    leas      $04,s     drop arguments
                    puls      pc,u      return

MsgDivZero          fcc       /divide by zero/
                    fcb       $00
MsgTypedefNotVar    fcc       /typedef - not a variable/
                    fcb       $00
MsgCannotCast       fcc       /cannot cast/
                    fcb       $00
MsgCantTakeAddr     fcc       /can't take address/
                    fcb       $00
MsgPtrRequired      fcc       /pointer required/
                    fcb       $00
MsgPtrOrIntRequired fcc       /pointer or integer required/
                    fcb       $00
MsgNotAFunction     fcc       /not a function/
                    fcb       $00
MsgBothIntegral     fcc       /both must be integral/
                    fcb       $00
MsgPtrMismatch1     fcc       /pointer mismatch/
                    fcb       $00
MsgTypeMismatch     fcc       /type mismatch/
                    fcb       $00
MsgPtrMismatch2     fcc       /pointer mismatch/
                    fcb       $00
MsgTypeCheck        fcc       /type check/
                    fcb       $00
MsgShouldBeNull     fcc       /should be NULL/
                    fcb       $00
MsgTypeError        fcc       /type error/
                    fcb       $00
MsgLvalueRequired   fcc       /lvalue required/
                    fcb       $00
MsgUndeclaredVar    fcc       /undeclared variable/
                    fcb       $00
MsgStructMember     fcc       /struct member required/
                    fcb       $00
MsgAggregateBad     fcc       /structure or union inappropriate/
                    fcb       $00
MsgMustBeIntegral   fcc       /must be integral/
                    fcb       $00
ParseStatement      pshs      u         save frame pointer
                    ldd       #$FFBA    frame size -70
                    lbsr      stkcheck  check stack space
                    ldd       $003F     load current token
                    cmpd      #$0028    is it token 0x28
                    beq       StmtDispatch yes, dispatch
                    clra                high byte zero
                    clrb                low byte zero
                    std       $002F     clear pending-label global
                    bra       StmtDispatch dispatch statement

NextStmt            leas      ,x        restore saved stack pointer
StmtDispatch        ldx       $003F     X = current token
                    lbra      DispatchStmtToken dispatch statement token

DispatchKeyword     ldx       $0041     X = keyword token
                    bra       KeywordDispatch dispatch keyword

ParseKw13           lbsr      CompileIf handle keyword 0x13
                    puls      pc,u      return

ParseKw14           lbsr      CompileWhile handle keyword 0x14
                    puls      pc,u      return

ParseKw12           lbsr      GenReturnStmt handle keyword 0x12
                    lbra      EmitStmtEnd finish statement

ParseKw17           lbsr      CompileCase handle keyword 0x17
                    puls      pc,u      return

ParseKw16           lbsr      CompileSwitch handle keyword 0x16
                    puls      pc,u      return

ParseKw18           lbsr      GenBreakStmt handle keyword 0x18
                    lbra      EmitStmtEnd finish statement

ParseKw19           lbsr      GenContinueStmt handle keyword 0x19
                    lbra      EmitStmtEnd finish statement

ParseKw1B           lbsr      CompileDefault handle keyword 0x1B
                    puls      pc,u      return

ParseKw1C           lbsr      GenForStmt handle keyword 0x1C
                    puls      pc,u      return

ParseKw1A           lbsr      CompileFor handle keyword 0x1A
                    lbra      EmitStmtEnd finish statement

ParseKwStart        lbsr      GenGotoStmt handle keyword (else body)
                    lbra      EmitStmtEnd finish statement

ElseNoIfErr         leax      MsgNoIfForElse,pcr error string no if for else
                    pshs      x         push message
                    lbsr      BuildMsgBuf report error
                    leas      $02,s     drop
                    lbsr      ParseStatement2 parse the statement
                    lbra      StmtLoop  loop for next statement

StmtNotKeyword      leax      ,s        X = stack frame
                    lbra      ParseDeclStmt parse as declaration

KeywordDispatch     cmpx      #$0013    keyword 0x13
                    beq       ParseKw13 branch to handler
                    cmpx      #$0014    keyword 0x14
                    beq       ParseKw14 branch to handler
                    cmpx      #$0012    keyword 0x12
                    beq       ParseKw12 branch to handler
                    cmpx      #$0017    keyword 0x17
                    beq       ParseKw17 branch to handler
                    cmpx      #$0016    keyword 0x16
                    beq       ParseKw16 branch to handler
                    cmpx      #$0018    keyword 0x18
                    beq       ParseKw18 branch to handler
                    cmpx      #$0019    keyword 0x19
                    beq       ParseKw19 branch to handler
                    cmpx      #$001B    keyword 0x1B
                    beq       ParseKw1B branch to handler
                    cmpx      #$001C    keyword 0x1C
                    beq       ParseKw1C branch to handler
                    cmpx      #$001A    keyword 0x1A
                    beq       ParseKw1A branch to handler
                    cmpx      #$001D    keyword (else)
                    beq       ParseKwStart branch to handler
                    cmpx      #$0015    keyword 0x15
                    beq       ElseNoIfErr branch to else error
                    bra       StmtNotKeyword none match, try declaration

ParseExprStmt       lbsr      ParseDeclarations parse expression statement
                    lbsr      ParseStatement2 parse the statement
                    puls      pc,u      return

EmptyStmtRet        puls      pc,u      empty statement returns

ParseLabelStmt      lbsr      SkipSpaces parse expression
                    ldb       $0045     get current char
                    cmpb      #$3a      is it a colon
                    bne       StmtNotLabel not a label
                    lbsr      GenLabelStmt install label
StmtLoop            leax      ,s        X = stack frame
                    lbra      NextStmt  loop for next statement

StmtNotLabel        leax      ,s        X = stack frame
                    bra       CompileExprStmt handle expression statement

ParseDeclStmt       leas      ,x        restore saved stack pointer
CheckDeclSpec       lbsr      IsStorageKeyword parse declaration specifier
                    std       -$02,s    save result
                    bne       IllegalDeclErr got one, illegal here
                    lbsr      IsTypeSpecifier try storage class
                    std       -$02,s    save result
                    beq       EvalExprStmt none, it is a real statement
IllegalDeclErr      leax      MsgIllegalDecl,pcr error string illegal declaration
                    pshs      x         push message
                    lbsr      BuildMsgBuf report error
                    leas      $02,s     drop
ParseDeclStmtBody   lbsr      ParseStatement2 parse remainder as statement
                    ldd       $003F     get current token type
                    cmpd      #$0028    is it the statement terminator
                    bne       ParseDeclStmtBody keep skipping tokens until terminator
                    bra       EmitStmtEnd emit end of statement

CompileExprStmt     leas      ,x        restore stack pointer
EvalExprStmt        clra                D = 0
                    clrb                D = 0
                    pshs      d         reserve local for expression tree
                    lbsr      MakeInvertedCond parse the expression statement
                    std       ,s++      save expression tree pointer
                    bne       EmitStmtEnd got expression, emit statement
                    leax      MsgSyntaxError,pcr point to syntax error message
                    pshs      x         push message pointer
                    lbsr      BuildMsgBuf report the error
                    leas      $02,s     drop message pointer
                    lbsr      SkipToRecover resync to next statement
                    puls      pc,u      restore and return

                    bra       EmitStmtEnd emit end of statement

DispatchStmtToken   cmpx      #$0028    is token the statement terminator
                    beq       EmitStmtEnd empty statement, done
                    cmpx      #$0033    is it a keyword token
                    lbeq      DispatchKeyword dispatch a keyword statement
                    cmpx      #$0029    is it token type $29
                    lbeq      ParseExprStmt handle it
                    cmpx      #$FFFF    end of input
                    lbeq      EmptyStmtRet return at end of file
                    cmpx      #$0034    is it an identifier
                    lbeq      ParseLabelStmt handle label or expression
                    lbra      CheckDeclSpec otherwise parse as expression

EmitStmtEnd         ldd       #$0028    load statement-terminator marker
                    pshs      d         push the marker
                    lbsr      ExpectToken emit the terminator
                    leas      $02,s     drop the marker
                    puls      pc,u      restore and return

CompileIf           pshs      u         save caller U
                    ldd       #$FFAE    frame size for stack check
                    lbsr      stkcheck  verify stack space
                    leas      -$06,s    allocate locals
                    lbsr      ParseStatement2 get next token past if
                    lbsr      ParseParenCond parse parenthesized condition
                    std       ,s        save condition tree
                    ldd       $000B     get label counter
                    addd      #$0001    allocate false-branch label
                    std       $000B     update label counter
                    tfr       d,u       U = false-branch label
                    ldd       $000B     get label counter again
                    addd      #$0001    allocate end label
                    std       $000B     update label counter
                    std       $04,s     save end label
                    ldd       $003F     get current token
                    cmpd      #$0028    is the body empty
                    bne       IfCompileBody no, compile the body
                    lbsr      ParseStatement2 get next token
                    clra                D = 0
                    clrb                D = 0
                    pshs      d         push zero operand
                    ldd       $06,s     get condition tree
                    pshs      d         push condition
                    pshs      u         push false-branch label
                    ldd       $06,s     reload condition tree
                    pshs      d         push condition
                    lbsr      EmitStmtAndFree emit conditional branch
                    leas      $08,s     drop arguments
                    ldd       $04,s     get end label
                    pshs      d         push end label
                    lbsr      EmitLocalLabel place the label
                    leas      $02,s     drop argument
                    stu       $02,s     save false-branch label
                    bra       IfCheckElse continue to else check

IfCompileBody       ldd       #$0001    push flag one
                    pshs      d         push it
                    ldd       $06,s     get condition tree
                    pshs      d         push condition
                    pshs      u         push false-branch label
                    ldd       $06,s     reload condition tree
                    pshs      d         push condition
                    lbsr      EmitStmtAndFree emit conditional branch
                    leas      $08,s     drop arguments
                    pshs      u         push false-branch label
                    lbsr      EmitLocalLabel place the label
                    leas      $02,s     drop argument
                    lbsr      ParseStatement compile the then-statement
                    ldd       $04,s     get end label
                    std       $02,s     save it as active label
IfCheckElse         ldd       $003F     get current token
                    cmpd      #$0033    is it a keyword
                    bne       IfEmitEndLabel no, no else clause
                    ldd       $0041     get keyword value
                    cmpd      #$0015    is it else
                    bne       IfEmitEndLabel no, no else clause
                    lbsr      ParseStatement2 get next token past else
                    ldd       $003F     get current token
                    cmpd      #$0028    is the else body empty
                    beq       IfEmitEndLabel yes, skip jump emit
                    cmpu      $02,s     compare active label to false label
                    beq       IfCompileElse same label, skip jump emit
                    clra                D = 0
                    clrb                D = 0
                    pshs      d         push zero operand
                    ldd       $000B     get label counter
                    addd      #$0001    allocate new end label
                    std       $000B     update label counter
                    std       $04,s     save end label
                    pshs      d         push end label
                    ldd       #$007C    jump-node marker
                    pshs      d         push marker
                    lbsr      GenNode   emit jump to end label
                    leas      $06,s     drop arguments
                    ldd       $04,s     get end label
                    pshs      d         push it
                    lbsr      EmitLocalLabel place false-branch label here
                    leas      $02,s     drop argument
IfCompileElse       lbsr      ParseStatement compile the else-statement
IfEmitEndLabel      ldd       $02,s     get end label
                    pshs      d         push it
                    lbsr      EmitLocalLabel place end label here
                    leas      $02,s     drop argument
                    leas      $06,s     release locals
                    puls      pc,u      restore and return

CompileWhile        pshs      u         save caller U
                    ldd       #$FFAA    frame size for stack check
                    lbsr      stkcheck  verify stack space
                    leas      -$0a,s    allocate locals
                    ldd       $0033     get current break label
                    std       $08,s     save outer break label
                    ldd       $0035     get current continue label
                    std       $06,s     save outer continue label
                    ldd       $0786,y   save loop-context field
                    std       $04,s     stash it
                    ldd       $0788,y   save loop-context field
                    std       $02,s     stash it
                    lbsr      ParseStatement2 get next token past while
                    ldd       $000B     get label counter
                    addd      #$0001    allocate loop-top label
                    std       $000B     update label counter
                    std       $0033     set break-target label
                    ldd       $000F     get current context value
                    std       $0788,y   store loop context
                    std       $0786,y   store loop context
                    ldd       $000B     get label counter
                    addd      #$0001    allocate continue label
                    std       $000B     update label counter
                    std       $0035     set continue-target label
                    lbsr      ParseParenCond parse parenthesized condition
                    std       ,s        save condition tree
                    ldd       $003F     get current token
                    cmpd      #$0028    is the body empty
                    bne       WhileCompileBody no, compile the body
                    ldu       $0035     get continue label
                    bra       WhileEmitTest skip body compilation

WhileCompileBody    clra                D = 0
                    clrb                D = 0
                    pshs      d         push zero operand
                    ldd       $0035     get continue label
                    pshs      d         push it
                    ldd       #$007C    jump-node marker
                    pshs      d         push marker
                    lbsr      GenNode   emit jump to loop label
                    leas      $06,s     drop arguments
                    ldd       $000B     get label counter
                    addd      #$0001    allocate loop-body label
                    std       $000B     update label counter
                    tfr       d,u       U = new label
                    pshs      u         push it
                    lbsr      EmitLocalLabel place loop-body label
                    leas      $02,s     drop argument
                    lbsr      ParseStatement compile the loop body
WhileEmitTest       ldd       $0035     get continue label
                    pshs      d         push it
                    lbsr      EmitLocalLabel place continue label here
                    leas      $02,s     drop argument
                    clra                D = 0
                    clrb                D = 0
                    pshs      d         push zero operand
                    ldd       $0033     get break/test label
                    pshs      d         push it
                    pshs      u         push loop-body label
                    ldd       $06,s     get saved condition tree
                    pshs      d         push condition
                    lbsr      EmitStmtAndFree emit conditional back-branch
                    leas      $08,s     drop arguments
                    ldd       $0033     get break label
                    pshs      d         push it
                    lbsr      EmitLocalLabel place break label here
                    leas      $02,s     drop argument
                    ldd       $08,s     get saved outer break label
                    std       $0033     restore outer break label
                    ldd       $06,s     get saved outer continue label
                    std       $0035     restore outer continue label
                    ldd       $04,s     get saved loop-context field
                    std       $0786,y   restore it
                    ldd       $02,s     get saved loop-context field
                    std       $0788,y   restore it
                    leas      $0a,s     release locals
                    puls      pc,u      restore and return

CompileSwitch       pshs      u         save caller U
                    ldd       #$FFA8    frame size for stack check
                    lbsr      stkcheck  verify stack space
                    leas      -$0e,s    allocate locals
                    lbsr      ParseStatement2 get next token past switch
                    ldd       $0037     get switch nesting depth
                    addd      #$0001    increment nesting depth
                    std       $0037     store new depth
                    ldd       $003B     get case-list tail pointer
                    std       ,s        save outer tail
                    ldd       $0039     get case-list head pointer
                    std       $0a,s     save outer head
                    clra                D = 0
                    clrb                D = 0
                    std       $0039     clear case-list head
                    ldd       $0033     get current break label
                    std       $0C,s     save outer break label
                    ldd       $0784,y   get current default label
                    std       $08,s     save outer default label
                    ldd       $0786,y   get context field
                    std       $02,s     save outer context field
                    ldd       $000B     get label counter
                    addd      #$0001    allocate break label
                    std       $000B     update label counter
                    std       $0033     set switch break label
                    ldd       $000F     get context value
                    std       $0786,y   store context field
                    clra                D = 0
                    clrb                D = 0
                    std       $0784,y   clear default label
                    ldd       #$002D    switch-start marker
                    pshs      d         push marker
                    lbsr      ExpectToken emit switch start
                    leas      $02,s     drop marker
                    clra                D = 0
                    clrb                D = 0
                    pshs      d         reserve local for expression
                    lbsr      ParseBinaryExpr parse parenthesized expression
                    std       ,s        save expression tree
                    lbsr      CopyExprTree get expression type info
                    leas      $02,s     drop argument
                    tfr       d,u       U = type node
                    stu       -$02,s    save type node
                    beq       SwitchTypeErr no type, error path
                    pshs      u         push type node
                    lbsr      ReportUndeclared resolve base type
                    leas      $02,s     drop argument
                    ldx       ,u        X = type code
                    bra       SwitchTypeDispatch dispatch on type code

SwitchPromoteInt    ldd       #$0001    push flag one
                    pshs      d         push it
                    pshs      u         push type node
                    lbsr      CoerceExpr promote integral expression
                    leas      $04,s     drop arguments
                    bra       SwitchEmitExpr continue to emit

SwitchCoerceInt     pshs      u         push type node
                    lbsr      ReportNotIntegral dereference to value
                    leas      $02,s     drop argument
                    pshs      u         push type node
                    lbsr      MakeErrorNode convert toward int
                    leas      $02,s     drop argument
                    bra       SwitchEmitExpr continue to emit

SwitchTypeDispatch  cmpx      #$0002    type code int
                    beq       SwitchPromoteInt promote it
                    cmpx      #$0008    type code $08
                    lbeq      SwitchPromoteInt promote it
                    cmpx      #$0001    type code char
                    beq       SwitchEmitExpr use directly
                    cmpx      #$0007    type code $07
                    beq       SwitchEmitExpr use directly
                    bra       SwitchCoerceInt otherwise coerce to int

SwitchEmitExpr      pshs      u         push expression node
                    lbsr      CoerceToFloat finalize expression
                    leas      $02,s     drop argument
                    pshs      u         push expression node
                    lbsr      FreeExprTree emit the expression
                    leas      $02,s     drop argument
                    bra       EmitSwitchDispatch continue to dispatch

SwitchTypeErr       lbsr      ExprMissingErr report non-integral switch error
EmitSwitchDispatch  ldd       #$002E    switch-dispatch marker
                    pshs      d         push marker
                    lbsr      ExpectToken emit dispatch marker
                    leas      $02,s     drop marker
                    clra                D = 0
                    clrb                D = 0
                    pshs      d         push zero operand
                    ldd       $000B     get label counter
                    addd      #$0001    allocate dispatch-table label
                    std       $000B     update label counter
                    std       $08,s     save table label
                    pshs      d         push it
                    ldd       #$007C    jump-node marker
                    pshs      d         push marker
                    lbsr      GenNode   emit jump to dispatch table
                    leas      $06,s     drop arguments
                    lbsr      ParseStatement compile the switch body
                    ldd       $002F     test fall-through flag
                    bne       SwitchEmitTable set, skip break jump
                    clra                D = 0
                    clrb                D = 0
                    pshs      d         push zero operand
                    ldd       $0033     get break label
                    pshs      d         push it
                    ldd       #$007C    jump-node marker
                    pshs      d         push marker
                    lbsr      GenNode   emit jump to break label
                    leas      $06,s     drop arguments
SwitchEmitTable     ldd       $06,s     get dispatch-table label
                    pshs      d         push it
                    lbsr      EmitLocalLabel place dispatch-table label
                    leas      $02,s     drop argument
                    ldu       $0039     get case-list head
                    bra       CaseEntryLoopTest enter case-emit loop

EmitCaseEntryLoop   ldd       ,u        get next-node pointer
                    std       $04,s     save it
                    ldd       $02,u     get case label word
                    pshs      d         push it
                    ldd       $04,u     get case value word
                    pshs      d         push it
                    ldd       #$007D    case-entry marker
                    pshs      d         push marker
                    lbsr      GenNode   emit case-table entry
                    leas      $06,s     drop arguments
                    ldd       GlbFreeList get free-list head
                    std       ,u        link node onto free list
                    stu       GlbFreeList update free-list head
                    ldu       $04,s     get next case node
CaseEntryLoopTest   stu       -$02,s    save case-node pointer
                    bne       EmitCaseEntryLoop loop while nodes remain
                    ldd       $0784,y   get default label
                    beq       SwitchRestore none, skip default jump
                    clra                D = 0
                    clrb                D = 0
                    pshs      d         push zero operand
                    ldd       $0784,y   get default label
                    pshs      d         push it
                    ldd       #$007C    jump-node marker
                    pshs      d         push marker
                    lbsr      GenNode   emit jump to default
                    leas      $06,s     drop arguments
SwitchRestore       ldd       $0033     get break label
                    pshs      d         push it
                    lbsr      EmitLocalLabel place break label here
                    leas      $02,s     drop argument
                    ldd       $0a,s     get saved outer case-list head
                    std       $0039     restore case-list head
                    ldd       $08,s     get saved outer default label
                    std       $0784,y   restore default label
                    ldd       $0037     get switch nesting depth
                    addd      #$FFFF    decrement nesting depth
                    std       $0037     store new depth
                    ldd       ,s        get saved outer case-list tail
                    std       $003B     restore case-list tail
                    ldd       $0C,s     get saved outer break label
                    std       $0033     restore break label
                    ldd       $02,s     get saved outer context field
                    std       $0786,y   restore context field
                    lbra      ForExit   release locals and return

CompileCase         pshs      u         save caller U
                    ldd       #$FFB8    frame size for stack check
                    lbsr      stkcheck  verify stack space
                    leas      -$02,s    allocate local
                    lbsr      ParseStatement2 get next token past case
                    clra                D = 0
                    clrb                D = 0
                    pshs      d         reserve local for value
                    lbsr      ParseConstExpr parse constant expression
                    leas      $02,s     drop argument
                    std       ,s        save case value
                    ldd       #$002F    case-label marker
                    pshs      d         push marker
                    lbsr      ExpectToken emit case marker
                    leas      $02,s     drop marker
                    ldd       $0037     get switch nesting depth
                    beq       CaseNotInSwitchErr zero, case outside switch
                    ldu       GlbFreeList get a node off the free list
                    beq       AllocCaseNode empty, allocate one
                    ldd       ,u        get next-node link
                    std       GlbFreeList advance free-list head
                    bra       LinkCaseNode use this node

AllocCaseNode       ldd       #$0006    node size six bytes
                    pshs      d         push size
                    lbsr      AllocMem  allocate case node
                    leas      $02,s     drop argument
                    tfr       d,u       U = new node
LinkCaseNode        ldd       $0039     get case-list head
                    beq       SetCaseListHead empty list, set head
                    stu       [$003B,y] link node onto previous tail
                    bra       FillCaseNode skip head assignment

SetCaseListHead     stu       $0039     set case-list head
FillCaseNode        stu       $003B     set case-list tail
                    clra                D = 0
                    clrb                D = 0
                    std       ,u        clear node next-link
                    ldd       ,s        get case value
                    std       $02,u     store value in node
                    ldd       $000B     get label counter
                    addd      #$0001    allocate case label
                    std       $000B     update label counter
                    std       $04,u     store case label in node
                    pshs      d         push case label
                    lbsr      EmitLocalLabel place case label here
                    leas      $02,s     drop argument
                    bra       CaseDefaultRet return

CaseNotInSwitchErr  bsr       NoSwitchErr report case outside switch
                    bra       CaseDefaultRet return

CompileDefault      pshs      u         save caller U
                    ldd       #$FFBA    frame size for stack check
                    lbsr      stkcheck  verify stack space
                    lbsr      ParseStatement2 get next token past default
                    ldd       $0037     get switch nesting depth
                    bne       DefaultCheckDup inside switch, continue
                    bsr       NoSwitchErr report default outside switch
DefaultCheckDup     ldd       $0784,y   get current default label
                    beq       SetDefaultLabel none yet, set it
                    leax      MsgMultipleDefaults,pcr point to multiple-defaults message
                    pshs      x         push message pointer
                    lbsr      BuildMsgBuf report the error
                    bra       DefaultEmitMarker skip label allocation

SetDefaultLabel     ldd       $000B     get label counter
                    addd      #$0001    allocate default label
                    std       $000B     update label counter
                    std       $0784,y   store default label
                    pshs      d         push it
                    lbsr      EmitLocalLabel place default label here
DefaultEmitMarker   leas      $02,s     drop argument
                    ldd       #$002F    default marker
                    pshs      d         push marker
                    lbsr      ExpectToken emit default marker
                    bra       CaseDefaultRet return

NoSwitchErr         pshs      u         save caller U
                    ldd       #$FFBA    frame size for stack check
                    lbsr      stkcheck  verify stack space
                    leax      MsgNoSwitch,pcr point to no-switch message
                    pshs      x         push message pointer
                    lbsr      BuildMsgBuf report the error
CaseDefaultRet      leas      $02,s     drop argument
                    puls      pc,u      restore and return

CompileFor          pshs      u         save caller U
                    ldd       #$FFAA    frame size for stack check
                    lbsr      stkcheck  verify stack space
                    leas      -$0a,s    allocate locals
                    ldd       $0033     get current break label
                    std       $08,s     save outer break label
                    ldd       $0035     get current continue label
                    std       $06,s     save outer continue label
                    ldd       $0788,y   get loop-context field
                    std       ,s        save token value into local
                    ldd       $0786,y   load saved loop context low
                    std       $02,s     stash it in local frame
                    ldd       $000F     zero base value
                    std       $0788,y   reset loop context high
                    std       $0786,y   reset loop context low
                    ldd       $000B     current label counter
                    addd      #$0001    allocate next label number
                    std       $000B     update label counter
                    std       $0035     set continue label
                    ldd       $000B     current label counter
                    addd      #$0001    allocate next label number
                    std       $000B     update label counter
                    std       $0033     set break label
                    lbsr      ParseStatement2 advance to next token
                    ldd       $000B     current label counter
                    addd      #$0001    allocate loop-top label
                    std       $000B     update label counter
                    std       $04,s     save loop-top label
                    pshs      d         push label argument
                    lbsr      EmitLocalLabel emit loop-top label
                    leas      $02,s     drop argument
                    lbsr      ParseStatement parse loop body statement
                    ldd       $003F     current token type
                    cmpd      #$0033    is it the while keyword
                    bne       DoWhileNoWhileErr no, report syntax error
                    ldd       $0041     token value
                    cmpd      #$0014    matches while token value
                    beq       DoWhileEmitCond yes, emit loop condition
DoWhileNoWhileErr   leax      MsgWhileExpected,pcr address of syntax error message
                    pshs      x         push message pointer
                    lbsr      BuildMsgBuf report error
                    leas      $02,s     drop argument
DoWhileEmitCond     lbsr      ParseStatement2 advance past while
                    ldd       $0035     continue label
                    pshs      d         push label argument
                    lbsr      EmitLocalLabel emit continue label
                    leas      $02,s     drop argument
                    clra                clear high byte
                    clrb                clear low byte
                    pshs      d         push zero argument
                    ldd       $0033     break label
                    pshs      d         push break label
                    ldd       $08,s     loop-top label
                    pshs      d         push loop-top label
                    lbsr      ParseParenCond parse and emit condition
                    pshs      d         push condition result
                    lbsr      EmitStmtAndFree emit conditional branch back
                    leas      $08,s     drop arguments
                    ldd       $0033     break label
                    pshs      d         push break label
                    lbsr      EmitLocalLabel emit break label
                    leas      $02,s     drop argument
                    ldd       $08,s     restore saved break label
                    std       $0033     restore break label
                    ldd       $06,s     restore saved continue label
                    std       $0035     restore continue label
                    ldd       $02,s     restore saved context low
                    std       $0786,y   restore loop context low
                    ldd       ,s        restore saved context high
                    std       $0788,y   restore loop context high
                    leas      $0a,s     release local frame
                    puls      pc,u      restore U and return

GenForStmt          pshs      u         save U register
                    ldd       #$FFA6    stack space needed
                    lbsr      stkcheck  verify stack room
                    leas      -$0e,s    allocate local frame
                    clra                clear high byte
                    clrb                clear low byte
                    std       $02,s     clear local slot
                    clra                clear high byte
                    clrb                clear low byte
                    std       ,s        clear local slot
                    ldu       $0033     save current break label
                    ldd       $0035     current continue label
                    std       $0C,s     save it in frame
                    ldd       $0786,y   saved loop context low
                    std       $06,s     save it in frame
                    ldd       $0788,y   loop context high
                    std       $04,s     save it in frame
                    ldd       $000F     zero base value
                    std       $0786,y   reset loop context low
                    std       $0788,y   reset loop context high
                    ldd       $000B     label counter
                    addd      #$0001    allocate loop-back label
                    std       $000B     update label counter
                    std       $0a,s     save loop-back label
                    ldd       $000B     label counter
                    addd      #$0001    allocate break label
                    std       $000B     update label counter
                    std       $0033     set new break label
                    lbsr      ParseStatement2 advance to next token
                    ldd       #$002D    for keyword op code
                    pshs      d         push op argument
                    lbsr      ExpectToken match for init clause
                    leas      $02,s     drop argument
                    clra                clear high byte
                    clrb                clear low byte
                    pshs      d         push zero argument
                    lbsr      MakeInvertedCond parse for init clause
                    leas      $02,s     drop argument
                    ldd       #$0028    open-paren op code
                    pshs      d         push op argument
                    lbsr      ExpectToken match opening delimiter
                    leas      $02,s     drop argument
                    ldd       $003F     current token type
                    cmpd      #$0028    is condition clause empty
                    beq       ForParseCond yes, skip condition
                    lbsr      ParseCondExpr parse condition expression
                    std       $02,s     save condition node
                    clra                clear high byte
                    clrb                clear low byte
                    pshs      d         push zero argument
                    ldd       $000B     label counter
                    addd      #$0001    allocate exit label
                    std       $000B     update label counter
                    std       $0a,s     save condition-exit label
                    pshs      d         push label argument
                    ldd       #$007C    branch-if-false op code
                    pshs      d         push op argument
                    lbsr      GenNode   emit conditional branch
                    leas      $06,s     drop arguments
ForParseCond        ldd       #$0028    open-paren op code
                    pshs      d         push op argument
                    lbsr      ExpectToken match second clause delimiter
                    leas      $02,s     drop argument
                    clra                clear high byte
                    clrb                clear low byte
                    pshs      d         push zero argument
                    lbsr      ParseBinaryExpr parse increment expression
                    std       ,s        save increment node
                    lbsr      CopyExprTree reduce increment expression
                    leas      $02,s     drop argument
                    std       ,s        save reduced increment
                    beq       ForNoIncr no increment present
                    ldd       ,s        increment node
                    pshs      d         push node argument
                    lbsr      ReportUndeclared process increment expression
                    leas      $02,s     drop argument
                    ldd       $000B     label counter
                    addd      #$0001    allocate increment label
                    std       $000B     update label counter
                    bra       ForSetContinue set continue label

ForNoIncr           ldd       $0a,s     reuse condition-exit label
ForSetContinue      std       $0035     set continue label
                    ldd       #$002E    clause-end op code
                    pshs      d         push op argument
                    lbsr      ExpectToken match closing delimiter
                    leas      $02,s     drop argument
                    ldd       $0a,s     loop-back label
                    pshs      d         push label argument
                    lbsr      EmitLocalLabel emit loop-back label
                    leas      $02,s     drop argument
                    lbsr      ParseStatement parse loop body statement
                    ldd       ,s        increment node
                    beq       ForCheckCond none, skip increment emit
                    ldd       $0035     continue label
                    pshs      d         push label argument
                    lbsr      EmitLocalLabel emit continue label
                    leas      $02,s     drop argument
                    ldd       ,s        increment node
                    pshs      d         push node argument
                    lbsr      InvertCompareNode emit increment code
                    leas      $02,s     drop argument
ForCheckCond        ldd       $02,s     condition node
                    beq       ForUncondBack none, unconditional loop back
                    ldd       $08,s     loop-back label
                    pshs      d         push label argument
                    lbsr      EmitLocalLabel emit label reference
                    leas      $02,s     drop argument
                    clra                clear high byte
                    clrb                clear low byte
                    pshs      d         push zero argument
                    ldd       $0033     break label
                    pshs      d         push break label
                    ldd       $0e,s     loop-back label
                    pshs      d         push loop-back label
                    ldd       $08,s     condition-exit label
                    pshs      d         push label argument
                    lbsr      EmitStmtAndFree emit conditional branch back
                    leas      $08,s     drop arguments
                    bra       ForEmitEnd finish for loop

ForUncondBack       clra                clear high byte
                    clrb                clear low byte
                    pshs      d         push zero argument
                    ldd       $0C,s     loop-back target label
                    pshs      d         push label argument
                    ldd       #$007C    branch op code
                    pshs      d         push op argument
                    lbsr      GenNode   emit unconditional loop back
                    leas      $06,s     drop arguments
ForEmitEnd          ldd       $0033     break label
                    pshs      d         push break label
                    lbsr      EmitLocalLabel emit break label
                    leas      $02,s     drop argument
                    stu       $0033     restore break label
                    ldd       $0C,s     saved continue label
                    std       $0035     restore continue label
                    ldd       $06,s     saved loop context low
                    std       $0786,y   restore context low
                    ldd       $04,s     saved loop context high
                    std       $0788,y   restore context high
ForExit             leas      $0e,s     release local frame
                    puls      pc,u      restore U and return

GenReturnStmt       pshs      u         save U register
                    ldd       #$FFB6    stack space needed
                    lbsr      stkcheck  verify stack room
                    lbsr      ParseStatement2 advance to next token
                    ldd       $003F     current token type
                    cmpd      #$0028    is it an empty return
                    lbeq      RetEmitDone yes, emit bare return
                    clra                clear high byte
                    clrb                clear low byte
                    pshs      d         push zero argument
                    lbsr      ParseBinaryExpr parse return expression
                    leas      $02,s     drop argument
                    tfr       d,u       U = expression node
                    stu       -$02,s    stash node below stack
                    lbeq      RetEmitDone null expression, bare return
                    pshs      u         push expression node
                    lbsr      CopyExprTree reduce expression
                    leas      $02,s     drop argument
                    tfr       d,u       U = reduced node
                    pshs      u         push node
                    lbsr      ReportUndeclared process return value
                    leas      $02,s     drop argument
                    pshs      u         push node
                    lbsr      RejectAggregate coerce to return type
                    leas      $02,s     drop argument
                    ldd       $002D     expression result type
                    clra                keep low type byte
                    andb      #$30      mask type-class bits
                    cmpd      #$0010    is it a pointer type
                    bne       RetTypeActual no, use actual type
                    ldd       #$0001    pointer type code
                    bra       RetEmitLoad proceed with load

RetTypeActual       ldd       $002D     actual expression type
RetEmitLoad         pshs      d         push type argument
                    pshs      u         push node
                    lbsr      CoerceExpr generate value load
                    leas      $04,s     drop arguments
                    ldx       $002D     expression type
                    lbra      RetTypeDispatch dispatch on return type

RetStructType       pshs      u         push node
                    lbsr      GenExpr   handle structure return
                    leas      $02,s     drop argument
                    leax      ,s        point X at result
                    bra       RetAfterStruct continue conversion

RetScalarType       pshs      u         push node
                    lbsr      GenOperand handle scalar return
                    leas      $02,s     drop argument
                    bra       RetCheckReg continue conversion

RetAfterStruct      leas      ,x        adjust stack pointer
RetCheckReg         ldd       $06,u     node type field
                    cmpd      #$0080    already in accumulator
                    lbeq      RetEmitValue yes, emit value directly
                    ldd       #$0080    target register code
                    pshs      d         push argument
                    ldd       #$006F    source operand code
                    pshs      d         push argument
                    ldd       #$007F    register move op code
                    pshs      d         push argument
                    lbsr      GenNode   emit register move
                    leas      $06,s     drop arguments
                    ldd       #$006F    operand code
                    pshs      d         push argument
                    ldd       #$007A    conversion op code
                    pshs      d         push argument
                    lbsr      GenNode   emit conversion op
                    leas      $04,s     drop arguments
                    ldx       $002D     expression type
                    bra       RetWidthDispatch dispatch on type width

RetWidenInt         ldd       $002D     expression type
                    pshs      d         push type argument
                    ldd       #$0089    operand code
                    pshs      d         push argument
                    ldd       #$0087    widen op code
                    pshs      d         push argument
                    lbsr      GenNode   emit widening op
                    leas      $06,s     drop arguments
                    bra       RetEmitValue emit return value

RetNarrow           ldd       #$0089    operand code
                    pshs      d         push argument
                    ldd       #$0088    narrow op code
                    pshs      d         push argument
                    lbsr      GenNode   emit narrowing op
                    leas      $04,s     drop arguments
                    bra       RetEmitValue emit return value

RetWidthDispatch    cmpx      #$0005    is type int
                    beq       RetWidenInt yes, widen it
                    cmpx      #$0006    is type unsigned int
                    lbeq      RetWidenInt yes, widen it
                    bra       RetNarrow else narrow it

RetOtherType        pshs      u         push node
                    lbsr      CoerceToDouble handle other return type
                    leas      $02,s     drop argument
                    bra       RetEmitValue emit return value

RetTypeDispatch     cmpx      #$0008    type is struct/pointer
                    lbeq      RetStructType handle structure return
                    cmpx      #$0005    type is int
                    lbeq      RetScalarType handle scalar return
                    cmpx      #$0006    type is unsigned int
                    lbeq      RetScalarType handle scalar return
                    bra       RetOtherType handle other type

RetEmitValue        pshs      u         push node
                    lbsr      FreeExprTree emit return value load
                    leas      $02,s     drop argument
RetEmitDone         clra                clear high byte
                    clrb                clear low byte
                    pshs      d         push zero argument
                    lbsr      EmitReserveSpace emit return marker
                    leas      $02,s     drop argument
                    clra                clear high byte
                    clrb                clear low byte
                    pshs      d         push zero argument
                    clra                clear high byte
                    clrb                clear low byte
                    pshs      d         push zero argument
                    ldd       #$0012    return op code
                    pshs      d         push argument
                    lbsr      GenNode   emit return operation
                    leas      $06,s     drop arguments
                    ldd       #$0012    return statement kind
                    lbra      StoreStmtKind store statement kind

GenBreakStmt        pshs      u         save U register
                    ldd       #$FFB6    stack space needed
                    lbsr      stkcheck  verify stack room
                    lbsr      ParseStatement2 advance to next token
                    ldd       $0033     break label
                    bne       BreakEmit inside loop, emit branch
                    leax      MsgBreakError,pcr break-outside-loop error message
                    pshs      x         push message pointer
                    lbsr      BuildMsgBuf report error
                    leas      $02,s     drop argument
                    bra       BreakDone finish break statement

BreakEmit           ldd       $0786,y   loop context value
                    pshs      d         push argument
                    lbsr      EmitReserveSpace emit label reference
                    leas      $02,s     drop argument
                    clra                clear high byte
                    clrb                clear low byte
                    pshs      d         push zero argument
                    ldd       $0033     break label
                    pshs      d         push break label
                    ldd       #$007C    branch op code
                    pshs      d         push argument
                    lbsr      GenNode   emit branch to break label
                    leas      $06,s     drop arguments
BreakDone           ldd       #$0018    break statement kind
                    lbra      StoreStmtKind store statement kind

GenContinueStmt     pshs      u         save U register
                    ldd       #$FFB6    stack space needed
                    lbsr      stkcheck  verify stack room
                    lbsr      ParseStatement2 advance to next token
                    ldd       $0035     continue label
                    bne       ContinueEmit inside loop, emit branch
                    leax      MsgContinueError,pcr continue-outside-loop error message
                    pshs      x         push message pointer
                    lbsr      BuildMsgBuf report error
                    leas      $02,s     drop argument
                    bra       ContinueDone finish continue statement

ContinueEmit        ldd       $0788,y   loop context value
                    pshs      d         push argument
                    lbsr      EmitReserveSpace emit label reference
                    leas      $02,s     drop argument
                    clra                clear high byte
                    clrb                clear low byte
                    pshs      d         push zero argument
                    ldd       $0035     continue label
                    pshs      d         push continue label
                    ldd       #$007C    branch op code
                    pshs      d         push argument
                    lbsr      GenNode   emit branch to continue label
                    leas      $06,s     drop arguments
ContinueDone        ldd       #$0019    continue statement kind
                    bra       StoreStmtKind store statement kind

GenGotoStmt         pshs      u         save U register
                    ldd       #$FFB6    stack space needed
                    lbsr      stkcheck  verify stack room
                    lbsr      ParseStatement2 advance to next token
                    ldd       $003F     current token type
                    cmpd      #$0034    is it an identifier label
                    beq       GotoResolve yes, resolve goto target
                    leax      MsgLabelRequired,pcr missing-label error message
                    pshs      x         push message pointer
                    lbsr      BuildMsgBuf report error
                    leas      $02,s     drop argument
                    bra       GotoRet   finish goto statement

GotoResolve         lbsr      LookupLabelSym look up label symbol
                    tfr       d,u       U = symbol pointer
                    stu       -$02,s    stash symbol pointer
                    beq       GotoDone  not found, skip emit
                    clra                clear high byte
                    clrb                clear low byte
                    pshs      d         push zero argument
                    ldd       $06,u     symbol label number
                    pshs      d         push label argument
                    ldd       #$001D    jump op code
                    pshs      d         push argument
                    lbsr      GenNode   emit jump to label
                    leas      $06,s     drop arguments
                    ldd       $0a,u     symbol flags
                    orb       #$02      mark label referenced
                    std       $0a,u     store flags back
GotoDone            lbsr      ParseStatement2 advance past label name
GotoRet             ldd       #$001D    goto statement kind (zero)
StoreStmtKind       std       $002F     store statement kind
                    puls      pc,u      restore U and return

GenLabelStmt        pshs      u         save U register
                    ldd       #$FFB6    stack space needed
                    lbsr      stkcheck  verify stack room
                    bsr       LookupLabelSym look up label symbol
                    tfr       d,u       U = symbol pointer
                    stu       -$02,s    stash symbol pointer
                    beq       LabelDone not found, skip
                    ldd       $08,u     symbol definition state
                    cmpd      #$000F    already defined here
                    bne       LabelDefine no, define it now
                    lbsr      ErrMultiDef report duplicate label error
                    bra       LabelDone finish label statement

LabelDefine         ldd       #$000F    defined-state marker
                    std       $08,u     mark label defined
                    clra                clear high byte
                    clrb                clear low byte
                    pshs      d         push zero argument
                    ldd       $06,u     symbol label number
                    pshs      d         push label argument
                    ldd       #$0009    label-define op code
                    pshs      d         push argument
                    lbsr      GenNode   emit label definition
                    leas      $06,s     drop arguments
                    ldd       $0a,u     symbol flags
                    orb       #$01      mark label defined
                    std       $0a,u     store flags back
LabelDone           lbsr      ParseStatement2 advance to next token
                    lbsr      ParseStatement2 advance past colon
                    puls      pc,u      restore U and return

LookupLabelSym      pshs      u         save U register
                    ldd       #$FFBA    stack space needed
                    lbsr      stkcheck  verify stack room
                    ldu       $0041     U = current token value
                    ldd       ,u        load node type field
                    cmpd      #$0009    is it already a label node type 9
                    lbeq      ReturnNode3 yes just return the node
                    ldd       ,u        reload node type field
                    beq       BuildLabelNode empty node so build label in place
                    ldd       $0C,u     load local-variable field
                    beq       FreeNodeForLabel free existing contents first
                    leax      MsgAlreadyLocal,pcr point to already-a-local-variable message
                    pshs      x         pass message pointer
                    lbsr      BuildMsgBuf report the error
                    leas      $02,s
                    clra                clear high byte of result
                    clrb                return null node
                    puls      pc,u      restore and return

FreeNodeForLabel    pshs      u         pass the node pointer
                    lbsr      AllocBlk  release old node contents
                    leas      $02,s     drop argument
BuildLabelNode      ldd       #$0009    label node type code 9
                    std       ,u        set node type to label
                    ldd       #$000D    label kind code $0D
                    std       $08,u     store kind field
                    ldd       $000B     load global label counter
                    addd      #$0001    bump the label number
                    std       $000B     save incremented counter
                    std       $06,u     store new label number in node
                    clra                clear high byte
                    clrb                clear low byte
                    std       $0a,u     clear operand field
                    ldd       $0031     load current scope value
                    std       $0C,u     store scope into node
                    ldd       $0029     load head of label list
                    std       $10,u     link node to previous head
                    stu       $0029     make node the new list head
                    lbra      ReturnNode3 return the finished node

MakeInvertedCond    pshs      u         save caller node pointer
                    ldd       #$FFBA    frame size for stack check
                    lbsr      stkcheck  verify stack space
                    ldd       $04,s     load argument node
                    pshs      d         pass it to parser
                    lbsr      ParseBinaryExpr parse expression
                    leas      $02,s     drop argument
                    tfr       d,u       result node into U
                    stu       -$02,s    save result in frame
                    lbeq      ReturnNode3 null expression so return
                    pshs      u         pass result node
                    lbsr      CopyExprTree coerce to rvalue
                    std       ,s        replace with coerced node
                    bsr       InvertCompareNode invert the condition
                    leas      $02,s     drop argument
                    tfr       d,u       inverted node into U
                    lbra      ReturnNode3 return the inverted condition

InvertCompareNode   pshs      u         save node pointer
                    ldd       #$FFBA    frame size for stack check
                    lbsr      stkcheck  verify stack space
                    ldu       $04,s     load argument node
                    pshs      u         pass it
                    lbsr      ReportUndeclared build compare tree
                    leas      $02,s     drop argument
                    ldx       $06,u     load node operator code
                    bra       CheckRelationalOp dispatch on the operator

SetInvOp3C          ldd       #$003C    inverted operator for relational $3E
                    bra       StoreInvertedOp store it

SetInvOp3D          ldd       #$003D    inverted operator for relational $3F
StoreInvertedOp     std       $06,u     replace operator in node
                    bra       FinishInvertedCond continue after inversion

CheckRelationalOp   cmpx      #$003E    is operator relational $3E
                    beq       SetInvOp3C invert it to $3C
                    cmpx      #$003F    is operator relational $3F
                    beq       SetInvOp3D invert it to $3D
FinishInvertedCond  pshs      u         pass the node
                    lbsr      EvalSubtreeType generate condition-code tree
                    leas      $02,s     drop argument
                    tfr       d,u       result into U
                    pshs      u         pass result node
                    lbsr      FreeExprTree free the working tree
                    lbra      ExprGenDone return via common exit

ParseParenCond      pshs      u         save caller node
                    ldd       #$FFB8    frame size for stack check
                    lbsr      stkcheck  verify stack space
                    leas      -$02,s    reserve a local slot
                    ldd       #$002D    expected token open paren
                    pshs      d         pass expected token
                    lbsr      ExpectToken require opening paren
                    leas      $02,s     drop argument
                    bsr       ParseCondExpr parse the condition expression
                    std       ,s        save parsed node
                    ldd       #$002E    expected token close paren
                    pshs      d         pass expected token
                    lbsr      ExpectToken require closing paren
                    leas      $02,s     drop argument
                    ldd       ,s        reload parsed node
                    lbra      EmitStmtDone return the condition

ParseCondExpr       pshs      u         save node
                    ldd       #$FFBA    frame size for stack check
                    lbsr      stkcheck  verify stack space
                    clra                clear high byte
                    clrb                clear low byte seed
                    pshs      d         pass null seed
                    lbsr      ParseBinaryExpr parse expression
                    std       ,s        save result node
                    lbsr      CopyExprTree coerce to rvalue
                    leas      $02,s     drop argument
                    tfr       d,u       result into U
                    stu       -$02,s    save in frame
                    beq       CondNeededErr null so condition-needed error
                    pshs      u         pass node
                    lbsr      ReportUndeclared build compare tree
                    bra       ExprGenDone return via common exit

CondNeededErr       leax      MsgCondNeeded,pcr point to condition-needed message
                    pshs      x         pass message pointer
                    lbsr      BuildMsgBuf report the error
ExprGenDone         leas      $02,s     drop argument
ReturnNode3         tfr       u,d       move node into D for return
                    puls      pc,u      restore and return

EmitStmtAndFree     pshs      u         save caller node
                    ldd       #$FFB4    frame size for stack check
                    lbsr      stkcheck  verify stack space
                    ldu       $04,s     load argument node
                    stu       -$02,s    save in frame
                    beq       EmitStmtRet null so nothing to emit
                    ldd       $0a,s     load first caller argument
                    pshs      d         pass it
                    ldd       $0a,s     load second caller argument
                    pshs      d         pass it
                    ldd       $0a,s     load third caller argument
                    pshs      d         pass it
                    pshs      u         pass the node
                    lbsr      GenTestExpr emit statement code
                    leas      $08,s     drop four arguments
                    pshs      u         pass node
                    lbsr      FreeExprTree free the tree
EmitStmtDone        leas      $02,s     drop argument
EmitStmtRet         puls      pc,u      restore and return

MsgNoIfForElse      fcc       /no 'if' for 'else'/
                    fcb       $00
MsgIllegalDecl      fcc       /illegal declaration/
                    fcb       $00
MsgSyntaxError      fcc       /syntax error/
                    fcb       $00
MsgMultipleDefaults fcc       /multiple defaults/
                    fcb       $00
MsgNoSwitch         fcc       /no switch statement/
                    fcb       $00
MsgWhileExpected    fcc       /while expected/
                    fcb       $00
MsgBreakError       fcc       /break error/
                    fcb       $00
MsgContinueError    fcc       /continue error/
                    fcb       $00
MsgLabelRequired    fcc       /label required/
                    fcb       $00
MsgAlreadyLocal     fcc       /already a local variable/
                    fcb       $00
MsgCondNeeded       fcc       /condition needed/
                    fcb       $00
GenExpr             pshs      u         save node
                    ldd       #$FFBA    frame size for stack check
                    lbsr      stkcheck  verify stack space
                    ldd       $04,s     load argument node
                    pshs      d         pass it
                    bsr       GenExprDispatch dispatch expression codegen
                    leas      $02,s     drop argument
                    ldd       $04,s     reload node
                    pshs      d         pass it
                    lbsr      GenTypeExtend emit result and cleanup
                    leas      $02,s     drop argument
                    puls      pc,u      restore and return

GenExprDispatch     pshs      u         save node
                    ldd       #$FFAE    frame size for stack check
                    lbsr      stkcheck  verify stack space
                    ldu       $04,s     load argument node
                    leas      -$06,s    reserve temp frame
                    ldd       $06,u     load node operator code
                    std       $02,s     save operator
                    tfr       d,x       operator into X for switch
                    lbra      OpDispatch jump to operator switch

GenIncDecOp         pshs      u         save node
                    lbsr      GenIndirection generate left operand
                    leas      $02,s     drop argument
                    pshs      u         pass node
                    lbsr      FixFlaggedNode generate right operand
                    leas      $02,s     drop argument
                    ldx       $06,u     load node operator code
                    bra       CheckIncDecOp2 check operator type

GenAutoIncDec       ldd       $08,u     load node kind field
                    lbeq      GenExprDone plain case take common exit
                    pshs      u         save node
                    ldd       #$0077    opcode $77
                    pshs      d         pass it
                    ldd       #$007B    opcode $7B
                    pshs      d         pass it
                    lbsr      GenNode   emit the operation
                    leas      $06,s     drop three arguments
                    lbra      SetLongResult continue at emit tail

CheckIncDecOp2      cmpx      #$0093    pre/post inc-dec operator
                    beq       GenAutoIncDec handle it
                    cmpx      #$0094    another inc-dec variant
                    lbeq      GenAutoIncDec handle it
                    cmpx      #$0095    third inc-dec variant
                    lbeq      GenAutoIncDec handle it
                    lbra      GenExprDone otherwise common exit

GenNegOp            ldd       $0a,u     load left operand node
                    pshs      d         pass it
                    lbsr      CoerceToDouble generate left operand
                    leas      $02,s     drop argument
                    ldd       #$0086    result operator opcode $86
                    lbra      EmitOpTail emit at common tail

GenAssignAddrOp     ldd       $0a,u     load left operand
                    pshs      d         pass it
                    lbsr      GenOperand generate address operand
                    leas      $02,s     drop argument
                    ldd       $0a,u     reload left operand
                    pshs      d         pass it
                    ldd       #$0091    opcode $91
                    pshs      d         pass it
                    ldd       #$0087    opcode $87
                    pshs      d         pass it
                    lbsr      GenNode   emit the operation
                    leas      $06,s     drop three arguments
                    lbra      SaveFrameSetResult continue at emit tail

GenLoadOp           ldd       $0a,u     load left operand
                    pshs      d         pass it
                    lbsr      CoerceToDouble generate left operand
                    leas      $02,s     drop argument
                    ldd       #$0083    opcode $83
                    pshs      d         pass it
                    ldd       #$0088    opcode $88
                    pshs      d         pass it
                    lbsr      GenNode   emit the operation
                    leas      $04,s     drop two arguments
                    bra       SetResultOp80 set result operator

RestoreFrameSetResult leas      -$06,x    restore temp frame
SetResultOp80       ldd       #$0080    result operator $80
                    std       $06,u     set node operator
                    lbra      GenExprDone common exit

GenAddrRefOp        ldd       $08,u     load node kind field
                    pshs      d         pass it
                    ldd       #$004A    opcode $4A
                    pshs      d         pass it
                    ldd       #$0088    opcode $88
                    pshs      d         pass it
                    lbsr      GenNode   emit the operation
                    leas      $06,s     drop three arguments
                    bra       SaveFrameEmitTail continue at emit tail

GenViaCallback      leax      GenExpr,pcr address of expression codegen
                    pshs      x         pass as callback
                    pshs      u         pass node
                    lbsr      GenBoolValueCB generate via callback
                    bra       DropTwoArgs continue

GenLeftWithOp       ldd       $0a,u     load left operand
                    pshs      d         pass it
                    lbsr      GenExpr   generate left operand
                    leas      $02,s     drop argument
                    ldd       $02,s     load saved operator
                    pshs      d         pass it
                    ldd       #$0088    opcode $88
                    pshs      d         pass it
                    lbsr      GenNode   emit the operation
DropTwoArgs         leas      $04,s     drop two arguments
SaveFrameEmitTail   leax      $06,s     save current frame in X
                    lbra      SetLongNorm continue at emit tail

GenLogicalOp        clra                clear high byte
                    clrb                clear low byte
                    pshs      d         pass zero value
                    ldd       #$0080    opcode $80
                    pshs      d         pass it
                    ldd       #$0071    opcode $71
                    pshs      d         pass it
                    ldd       #$007F    opcode $7F
                    pshs      d         pass it
                    lbsr      GenNode   emit the operation
                    leas      $08,s     drop four arguments
                    ldd       #$0071    opcode $71
                    pshs      d         pass it
                    ldd       #$007A    opcode $7A
                    pshs      d         pass it
                    lbsr      GenNode   emit the operation
                    leas      $04,s     drop two arguments
                    ldd       $0a,u     load left operand
                    pshs      d         pass it
                    lbsr      GenExpr   generate left operand
                    leas      $02,s     drop argument
                    ldd       $02,s     load saved operator
                    pshs      d         pass it
                    ldd       #$0088    opcode $88
                    pshs      d         pass it
                    lbsr      GenNode   emit the operation
                    leas      $04,s     drop two arguments
                    ldd       #$0089    opcode $89
                    pshs      d         pass it
                    ldd       #$0088    opcode $88
                    pshs      d         pass it
                    lbsr      GenNode   emit the operation
                    leas      $04,s     drop two arguments
                    ldd       $02,s     load saved operator
                    cmpd      #$003E    is it relational $3E
                    bne       SetResultOp3E no so use $3E result
                    ldd       #$003F    result operator $3F
                    lbra      EmitOpTail emit at common tail

SetResultOp3E       ldd       #$003E    result operator $3E
                    lbra      EmitOpTail emit at common tail

GenSimpleOp         pshs      u         save node
                    lbsr      GenExprList generate subtree
                    leas      $02,s     drop argument
                    lbra      SaveFrameSetResult continue at emit tail

GenCommutativeOp    ldx       $0a,u     load left operand node
                    ldd       $06,x     load its operator code
                    cmpd      #$004A    is left a constant node
                    bne       CheckRightConst no so keep operand order
                    leas      -$02,s    temp slot for swap
                    ldd       $0a,u     load left operand
                    std       ,s        stash it
                    ldd       $0C,u     load right operand
                    std       $0a,u     move right into left
                    ldd       ,s        reload stashed left
                    std       $0C,u     move it into right
                    leas      $02,s     drop temp slot
CheckRightConst     ldx       $0C,u     load right operand node
                    ldd       $06,x     load its operator code
                    cmpd      #$004A    is right a constant node
                    bne       GenBinaryGeneral no so general case
                    ldx       $0C,u     reload right operand
                    ldd       $08,x     load its value pointer
                    std       $04,s     save in frame
                    ldd       [$04,s]   dereference the value
                    bne       GenBinaryGeneral nonzero so general case
                    ldx       $04,s     value pointer into X
                    ldd       $02,x     load symbol field
                    pshs      d         pass it
                    lbsr      FindTableIndex look up the symbol
                    leas      $02,s     drop argument
                    std       ,s        save lookup result
                    beq       GenBinaryGeneral not found so general case
                    ldd       $0C,u     load right operand
                    std       $04,s     save in frame
                    ldd       ,s        load looked-up node
                    ldx       $04,s     right operand pointer
                    std       $08,x     store into value field
                    ldd       #$0036    operator code $36
                    ldx       $04,s     right operand pointer
                    std       $06,x     set its operator
                    ldd       #$0001    value one
                    std       [$04,s]   mark node as resolved
                    ldd       $02,s     load saved operator
                    cmpd      #$0052    is it operator $52
                    bne       SetFoldedOp55 no so use $55
                    ldd       #$0056    folded result operator $56
                    bra       StoreFoldedOp store it

SetFoldedOp55       ldd       #$0055    folded result operator $55
StoreFoldedOp       std       $02,s     save chosen result operator
                    leax      $06,s     save frame in X
                    bra       RestoreFrameEmitBin restore and emit binary

GenBinaryGeneral    ldd       $0a,u     load left operand
                    std       $04,s     save in frame
                    ldx       $04,s     left operand pointer
                    ldd       $06,x     load its operator code
                    cmpd      #$004A    is left a constant node
                    bne       GenLeftGeneral no so general codegen
                    ldd       $04,s     load left operand
                    pshs      d         pass it
                    lbsr      GenAddConst emit constant operand
                    leas      $02,s     drop argument
                    bra       GenRightOperand do the right operand

GenLeftGeneral      ldd       $04,s     load left operand
                    pshs      d         pass it
                    lbsr      GenExpr   generate left operand
                    leas      $02,s     drop argument
                    ldd       #$006E    opcode $6E
                    pshs      d         pass it
                    ldd       #$0088    opcode $88
                    pshs      d         pass it
                    lbsr      GenNode   emit the operation
                    leas      $04,s     drop two arguments
GenRightOperand     ldd       $0C,u     load right operand
                    pshs      d         pass it
                    lbsr      GenExpr   generate right operand
                    bra       LoadSavedOp emit at common tail

RestoreFrameEmitBin leas      -$06,x    restore temp frame
EmitBinLeft         ldd       $0a,u     load left operand
                    pshs      d         pass it
                    lbsr      GenExpr   generate left operand
                    leas      $02,s     drop argument
                    ldd       #$0071    opcode $71
                    pshs      d         pass it
                    ldd       #$007A    opcode $7A
                    pshs      d         pass it
                    lbsr      GenNode   emit the operation
                    leas      $04,s     drop two arguments
                    ldd       $0C,u     load right operand
                    pshs      d         pass it
                    lbsr      CoerceToDouble generate right operand
LoadSavedOp         leas      $02,s     drop argument
                    ldd       $02,s     load saved operator
EmitOpTail          pshs      d         pass operator
                    ldd       #$0088    opcode $88
                    pshs      d         pass it
                    lbsr      GenNode   emit the operation
                    leas      $04,s     drop two arguments
SaveFrameSetResult  leax      $06,s     save frame in X
                    lbra      RestoreFrameSetResult set result and exit

GenBinaryOp         ldd       $0a,u     load left operand
                    pshs      d         pass it
                    lbsr      GenExpr   generate left operand
                    leas      $02,s     drop argument
                    ldd       #$0071    opcode $71
                    pshs      d         pass it
                    ldd       #$007A    opcode $7A
                    pshs      d         pass it
                    lbsr      GenNode   emit the operation
                    leas      $04,s     drop two arguments
                    ldd       $0C,u     load right operand
                    pshs      d         pass it
                    lbsr      GenExpr   generate right operand
                    leas      $02,s     drop argument
                    leax      $06,s     save frame in X
                    bra       EmitCvtNorm continue at emit tail

GenBiasedOp         leas      -$06,x    restore temp frame
                    ldd       $0a,u     load left operand
                    std       $04,s     save in frame
                    pshs      d         pass it
                    lbsr      GenExpr   generate left operand
                    leas      $02,s     drop argument
                    ldd       #$0071    opcode $71
                    pshs      d         pass it
                    ldd       #$007A    opcode $7A
                    pshs      d         pass it
                    lbsr      GenNode   emit the operation
                    leas      $04,s     drop two arguments
                    ldd       $02,s     load saved operator
                    addd      #$FFB0    bias operator code by -80
                    std       $06,u     set node operator
                    ldd       #$0093    opcode $93
                    ldx       $04,s     X = node pointer from stack arg
                    std       $06,x     store result type into node field 6
                    pshs      u         save frame pointer
                    lbsr      GenExprDispatch generate subexpression code
                    leas      $02,s     drop pushed argument
                    bra       EmitCvtSeq join conversion emit sequence

EmitCvtNorm         leas      -$06,x    normalize stack to frame base
EmitCvtSeq          ldd       #$0089    load emit code 0089
                    pshs      d         push emit argument
                    ldd       #$0088    load emit code 0088
                    pshs      d         push emit argument
                    lbsr      GenNode   emit intermediate code
                    leas      $04,s     drop emit arguments
                    bra       SetLongResult join result-type set

SetLongNorm         leas      -$06,x    normalize stack to frame base
SetLongResult       ldd       #$0093    load long result type 0093
                    std       $06,u     set node result type
                    clra                clear high byte
                    clrb                clear low byte
                    std       $08,u     clear node value field
                    lbra      GenExprDone return from codegen

OpRangeCheck        ldd       $02,s     load operator code from frame
                    cmpd      #$00A0    compare against high-range threshold
                    blt       LongsUnsupportedErr below range, report unsupported
                    leax      $06,s     compute frame base in X
                    lbra      GenBiasedOp handle high-range operator

LongsUnsupportedErr leax      StrLongs,pcr point X at longs feature name
                    pshs      x         push message pointer
                    pshs      u         push frame pointer
                    lbsr      InternalErr report unsupported-feature error
                    leas      $04,s     drop arguments
                    lbra      GenExprDone return from codegen

OpDispatch          cmpx      #$0080    operator code is 0080
                    lbeq      GenExprDone nothing to emit, return
                    cmpx      #$0093    operator code is 0093
                    lbeq      GenExprDone nothing to emit, return
                    cmpx      #$0094    operator code is 0094
                    lbeq      GenExprDone nothing to emit, return
                    cmpx      #$0095    operator code is 0095
                    lbeq      GenExprDone nothing to emit, return
                    cmpx      #$0034    operator code is 0034
                    lbeq      GenExprDone nothing to emit, return
                    cmpx      #$0042    operator code is 0042
                    lbeq      GenIncDecOp dispatch to operator 0042 handler
                    cmpx      #$0086    operator code is 0086
                    lbeq      GenNegOp  dispatch to operator 0086 handler
                    cmpx      #$0091    operator code is 0091
                    lbeq      GenAssignAddrOp dispatch to operator 0091 handler
                    cmpx      #$0083    operator code is 0083
                    lbeq      GenLoadOp dispatch to operator 0083 handler
                    cmpx      #$004A    operator code is 004A
                    lbeq      GenAddrRefOp dispatch to operator 004A handler
                    cmpx      #$0064    operator code is 0064
                    lbeq      GenViaCallback dispatch to operator 0064 handler
                    cmpx      #$003C    operator code is 003C
                    lbeq      GenLeftWithOp dispatch to relational handler
                    cmpx      #$003D    operator code is 003D
                    lbeq      GenLeftWithOp dispatch to relational handler
                    cmpx      #$0044    operator code is 0044
                    lbeq      GenLeftWithOp dispatch to relational handler
                    cmpx      #$0043    operator code is 0043
                    lbeq      GenLeftWithOp dispatch to relational handler
                    cmpx      #$003E    operator code is 003E
                    lbeq      GenLogicalOp dispatch to relational handler
                    cmpx      #$003F    operator code is 003F
                    lbeq      GenLogicalOp dispatch to relational handler
                    cmpx      #$0065    operator code is 0065
                    lbeq      GenSimpleOp dispatch to operator 0065 handler
                    cmpx      #$0052    operator code is 0052
                    lbeq      GenCommutativeOp dispatch to operator 0052 handler
                    cmpx      #$0053    operator code is 0053
                    lbeq      GenBinaryGeneral dispatch to common operator handler
                    cmpx      #$005A    operator code is 005A
                    lbeq      GenBinaryGeneral dispatch to common operator handler
                    cmpx      #$005B    operator code is 005B
                    lbeq      GenBinaryGeneral dispatch to common operator handler
                    cmpx      #$005E    operator code is 005E
                    lbeq      GenBinaryGeneral dispatch to common operator handler
                    cmpx      #$005C    operator code is 005C
                    lbeq      GenBinaryGeneral dispatch to common operator handler
                    cmpx      #$005F    operator code is 005F
                    lbeq      GenBinaryGeneral dispatch to common operator handler
                    cmpx      #$005D    operator code is 005D
                    lbeq      GenBinaryGeneral dispatch to common operator handler
                    cmpx      #$0050    operator code is 0050
                    lbeq      GenBinaryGeneral dispatch to common operator handler
                    cmpx      #$0051    operator code is 0051
                    lbeq      GenBinaryGeneral dispatch to common operator handler
                    cmpx      #$0054    operator code is 0054
                    lbeq      GenBinaryGeneral dispatch to common operator handler
                    cmpx      #$0057    operator code is 0057
                    lbeq      GenBinaryGeneral dispatch to common operator handler
                    cmpx      #$0058    operator code is 0058
                    lbeq      GenBinaryGeneral dispatch to common operator handler
                    cmpx      #$0059    operator code is 0059
                    lbeq      GenBinaryGeneral dispatch to common operator handler
                    cmpx      #$0056    operator code is 0056
                    lbeq      EmitBinLeft dispatch to operator 0056 handler
                    cmpx      #$0055    operator code is 0055
                    lbeq      EmitBinLeft dispatch to operator 0055 handler
                    cmpx      #$0078    operator code is 0078
                    lbeq      GenBinaryOp dispatch to operator 0078 handler
                    lbra      OpRangeCheck no match, run default handler

GenExprDone         leas      $06,s     discard local frame
                    puls      pc,u      restore frame and return

GenTypeExtend       pshs      u         save frame pointer
                    ldd       #$FFB4    frame size for stack check
                    lbsr      stkcheck  verify stack space
                    ldx       $04,s     load node pointer arg
                    ldx       $06,x     load node result-type code
                    bra       ExtendDispatch dispatch on operand type

ExtendByte          ldd       $04,s     load node pointer arg
                    pshs      d         push as operand
                    ldd       #$0077    load emit code 0077
                    pshs      d         push emit argument
                    ldd       #$0071    load emit code 0071
                    pshs      d         push emit argument
                    ldd       #$007F    load emit code 007F
                    pshs      d         push emit argument
                    lbsr      GenNode   emit byte sign-extend code
                    leas      $08,s     drop arguments
                    bra       GenTypeExtendDone conversion done

ExtendWord          ldd       $04,s     load node pointer arg
                    pshs      d         push as operand
                    ldd       #$0077    load emit code 0077
                    pshs      d         push emit argument
                    ldd       #$007B    load emit code 007B
                    pshs      d         push emit argument
                    lbsr      GenNode   emit word sign-extend code
                    leas      $06,s     drop arguments
                    bra       GenTypeExtendDone conversion done

ExtendDispatch      cmpx      #$0034    type is char 0034
                    beq       ExtendByte extend as byte
                    cmpx      #$0094    type is 0094
                    beq       ExtendWord extend as word
                    cmpx      #$0095    type is 0095
                    lbeq      ExtendWord extend as word
GenTypeExtendDone   puls      pc,u      return

GenAddConst         pshs      u         save frame pointer
                    ldd       #$FFB2    frame size for stack check
                    lbsr      stkcheck  verify stack space
                    ldu       $04,s     load node pointer arg
                    leas      -$02,s    reserve local word
                    ldd       $08,u     load node value pointer
                    std       ,s        save value pointer in local
                    ldx       ,s        X = value pointer
                    lda       ,x        load value byte 0
                    ora       $01,x     or in byte 1
                    ora       $02,x     or in byte 2
                    ora       $03,x     or in byte 3
                    beq       AddConstZero value is zero, skip offset
                    ldx       ,s        reload value pointer
                    ldd       $02,x     load low word of constant
                    pshs      d         push operand
                    ldd       #$0036    load emit code 0036
                    pshs      d         push emit argument
                    ldd       #$0070    load emit code 0070
                    pshs      d         push emit argument
                    ldd       #$0075    load emit code 0075
                    pshs      d         push emit argument
                    lbsr      GenNode   emit load-constant code
                    leas      $08,s     drop arguments
                    ldd       #$0070    load emit code 0070
                    pshs      d         push emit argument
                    ldd       #$007A    load emit code 007A
                    pshs      d         push emit argument
                    lbsr      GenNode   emit add code
                    leas      $04,s     drop arguments
                    ldd       [,s]      load word indirect via value pointer
                    pshs      d         push operand
                    ldd       #$0036    load emit code 0036
                    pshs      d         push emit argument
                    ldd       #$0070    load emit code 0070
                    pshs      d         push emit argument
                    ldd       #$0075    load emit code 0075
                    pshs      d         push emit argument
                    lbsr      GenNode   emit load-constant code
                    leas      $08,s     drop arguments
                    bra       AddConstJoin join add-emit tail

AddConstZero        clra                clear high byte
                    clrb                clear low byte
                    pshs      d         push zero operand
                    ldd       #$0036    load emit code 0036
                    pshs      d         push emit argument
                    ldd       #$0070    load emit code 0070
                    pshs      d         push emit argument
                    ldd       #$0075    load emit code 0075
                    pshs      d         push emit argument
                    lbsr      GenNode   emit load-zero code
                    leas      $08,s     drop arguments
                    ldd       #$0070    load emit code 0070
                    pshs      d         push emit argument
                    ldd       #$007A    load emit code 007A
                    pshs      d         push emit argument
                    lbsr      GenNode   emit add code
                    leas      $04,s     drop arguments
AddConstJoin        ldd       #$0070    load emit code 0070
                    pshs      d         push emit argument
                    ldd       #$007A    load emit code 007A
                    pshs      d         push emit argument
                    lbsr      GenNode   emit add code
                    leas      $04,s     drop arguments
                    leas      $02,s     release local word
                    puls      pc,u      return

StrLongs            fcc       /longs/
                    fcb       $00
GenOperand          pshs      u         save frame pointer
                    ldd       #$FFBA    frame size for stack check
                    lbsr      stkcheck  verify stack space
                    ldd       $04,s     load node pointer arg
                    pshs      d         push for expression codegen
                    bsr       GenExpr2  generate expression code
                    leas      $02,s     drop argument
                    ldd       $04,s     reload node pointer
                    pshs      d         push for load/extend
                    lbsr      GenTypeExtend generate type-extend load
                    leas      $02,s     drop argument
                    puls      pc,u      return

GenExpr2            pshs      u         save frame pointer
                    ldd       #$FFAE    frame size for stack check
                    lbsr      stkcheck  verify stack space
                    ldu       $04,s     load node pointer arg
                    leas      -$08,s    reserve 8-byte local frame
                    ldd       ,u        load node type field
                    std       $02,s     save type in frame
                    ldd       $06,u     load operator code
                    std       $06,s     save operator in frame
                    tfr       d,x       X = operator code
                    lbra      TypeCodeDispatch dispatch expression codegen

GenExprLeaf         pshs      u         save frame pointer
                    lbsr      GenExprDispatch generate subexpression code
                    leas      $02,s     drop argument
                    lbra      TypeWalkDone return

GenExprChild        ldd       $0a,u     load left child pointer
                    pshs      d         push child pointer
                    lbsr      CoerceToDouble generate child code
                    leas      $02,s     drop argument
                    bra       EmitResult87 join result emit

EmitResult87Norm    leas      -$08,x    restore stack to frame base
EmitResult87        ldd       $06,s     load result value from frame
                    pshs      d         push operand
                    ldd       #$0087    load emit code 0087
                    pshs      d         push emit argument
                    lbsr      GenNode   emit result code
                    leas      $04,s     drop arguments
                    bra       SetResult80 join result-type set

SetResult80Norm     leas      -$08,x    restore stack to frame base
SetResult80         ldd       #$0080    load result type 0080
                    std       $06,u     set node result type
                    lbra      TypeWalkDone return

GenChildA           ldd       $0a,u     load left child pointer
                    pshs      d         push child pointer
                    lbsr      GenExpr   generate child code
                    bra       GenChildJoin join child tail

GenChildB           ldd       $0a,u     load left child pointer
                    pshs      d         push child pointer
                    lbsr      GenOperand generate operand code
GenChildJoin        leas      $02,s     drop argument
                    leax      $08,s     compute frame base in X
                    bra       EmitResult87Norm normalize stack and continue

EmitConstResult     ldd       $08,u     load node value field
                    pshs      d         push operand
                    ldd       #$004B    load emit code 004B
                    pshs      d         push emit argument
                    ldd       #$0087    load emit code 0087
                    pshs      d         push emit argument
                    lbsr      GenNode   emit result code
                    leas      $06,s     drop arguments
                    lbra      SetDefaultType set result and return

GenCallArgs         leax      GenOperand,pcr point X at GenOperand routine
                    pshs      x         push callback pointer
                    pshs      u         push frame pointer
                    lbsr      GenBoolValueCB generate call arguments
                    leas      $04,s     drop arguments
                    bra       GenOperandEmitDone join operand emit tail

GenOperandEmit      ldd       $0a,u     load left child pointer
                    pshs      d         push child pointer
                    lbsr      GenOperand generate operand code
                    leas      $02,s     drop argument
                    ldd       $02,s     load result value
                    pshs      d         push operand
                    ldd       $08,s     load saved value
                    pshs      d         push operand
                    ldd       #$0087    load emit code 0087
                    pshs      d         push emit argument
                    lbsr      GenNode   emit combining code
                    leas      $06,s     drop arguments
GenOperandEmitDone  leax      $08,s     compute frame base in X
                    lbra      SetDefaultTypeAdj restore stack and return

GenRelCompare       ldd       #$0080    load emit code 0080
                    pshs      d         push emit argument
                    ldd       #$0071    load emit code 0071
                    pshs      d         push emit argument
                    ldd       #$007F    load emit code 007F
                    pshs      d         push emit argument
                    lbsr      GenNode   emit code
                    leas      $06,s     drop arguments
                    ldd       #$0071    load emit code 0071
                    pshs      d         push emit argument
                    ldd       #$007A    load emit code 007A
                    pshs      d         push emit argument
                    lbsr      GenNode   emit add code
                    leas      $04,s     drop arguments
                    ldd       $0a,u     load left child pointer
                    pshs      d         push child pointer
                    lbsr      GenOperand generate operand code
                    leas      $02,s     drop argument
                    ldd       $02,s     load result value
                    pshs      d         push operand
                    ldd       $08,s     load saved value
                    pshs      d         push operand
                    ldd       #$0087    load emit code 0087
                    pshs      d         push emit argument
                    lbsr      GenNode   emit code
                    leas      $06,s     drop arguments
                    ldd       $02,s     load result value
                    pshs      d         push operand
                    ldd       #$0089    load emit code 0089
                    pshs      d         push emit argument
                    ldd       #$0087    load emit code 0087
                    pshs      d         push emit argument
                    lbsr      GenNode   emit code
                    leas      $06,s     drop arguments
                    ldd       $02,s     load result value
                    pshs      d         push operand
                    ldd       $08,s     load operator code from frame
                    cmpd      #$003E    is relational operator 003E
                    bne       RelKeepOp no, keep original operator
                    ldd       #$003F    swap to reversed operator 003F
                    bra       EmitRelCompare emit reversed compare

RelKeepOp           ldd       #$003E    keep operator 003E
EmitRelCompare      pshs      d         push operator code
                    ldd       #$0087    load emit code 0087
                    pshs      d         push emit argument
                    lbsr      GenNode   emit compare code
                    leas      $06,s     drop arguments
                    bra       GenBinaryDone join binary-done tail

GenExprSpecial      pshs      u         push frame pointer
                    lbsr      GenExprList generate special codegen
                    leas      $02,s     drop argument
                    bra       GenBinaryDone join binary-done tail

GenBinaryOp2        ldd       $0a,u     load left child pointer
                    pshs      d         push child pointer
                    lbsr      GenOperand generate operand code
                    leas      $02,s     drop argument
                    ldd       #$006E    load emit code 006E
                    pshs      d         push emit argument
                    ldd       #$0087    load emit code 0087
                    pshs      d         push emit argument
                    lbsr      GenNode   emit code
                    leas      $04,s     drop arguments
                    ldd       $0C,u     load right child pointer
                    pshs      d         push child pointer
                    lbsr      GenOperand generate operand code
                    leas      $02,s     drop argument
                    ldd       $06,s     load saved result value
                    pshs      d         push operand
                    ldd       #$0087    load emit code 0087
                    pshs      d         push emit argument
                    lbsr      GenNode   emit code
                    leas      $04,s     drop arguments
GenBinaryDone       leax      $08,s     compute frame base in X
                    lbra      SetResult80Norm set result type and return

GenAddrOffset       ldd       $0a,u     load left child pointer
                    pshs      d         push child pointer
                    lbsr      GenOperand generate operand code
                    leas      $02,s     drop argument
                    ldd       #$0071    load emit code 0071
                    pshs      d         push emit argument
                    ldd       #$007A    load emit code 007A
                    pshs      d         push emit argument
                    lbsr      GenNode   emit add code
                    leas      $04,s     drop arguments
                    ldd       $0C,u     load right child pointer
                    pshs      d         push child pointer
                    lbsr      GenOperand generate operand code
                    leas      $02,s     drop argument
                    leax      $08,s     compute frame base in X
                    lbra      GenAddrOffsetNorm restore stack and return

GenAssign           leas      -$08,x    restore stack to frame base
                    ldd       $0a,u     load left child pointer
                    std       $04,s     save child in frame
                    ldd       $02,s     load node type
                    cmpd      #$0005    is type 0005
                    bne       GenAssignSimple no, take simple path
                    ldx       $04,s     X = left child
                    ldd       $0a,x     load child left grandchild
                    pshs      d         push grandchild pointer
                    lbsr      GenOperand generate operand code
                    leas      $02,s     drop argument
                    ldd       #$0071    load emit code 0071
                    pshs      d         push emit argument
                    ldd       #$007A    load emit code 007A
                    pshs      d         push emit argument
                    lbsr      GenNode   emit add code
                    leas      $04,s     drop arguments
                    ldd       #$008C    load emit code 008C
                    pshs      d         push emit argument
                    ldd       #$0087    load emit code 0087
                    bra       EmitAssignJoin go emit assignment join

GenAssignSimple     ldd       $04,s     load left child pointer
                    pshs      d         push child pointer
                    lbsr      GenOperand generate operand code
                    leas      $02,s     drop argument
                    ldd       #$0071    load emit code 0071
                    pshs      d         push emit argument
                    ldd       #$007A    load emit code 007A
EmitAssignJoin      pshs      d         push emit argument
                    lbsr      GenNode   emit code
                    leas      $04,s     drop arguments
                    ldd       $06,s     load result value
                    addd      #$FFB0    adjust offset by minus 50
                    std       $06,u     store into node value
                    ldd       #$0093    load long result type 0093
                    ldx       $04,s     X = left child
                    std       $06,x     set child result type
                    pshs      u         push frame pointer
                    lbsr      GenExpr2  recurse expression codegen
                    leas      $02,s     drop argument
                    ldd       $02,s     load node type
                    cmpd      #$0005    is type 0005
                    bne       EmitResultCont no, skip extra emit
                    ldd       #$008D    load emit code 008D
                    pshs      d         push emit argument
                    ldd       #$0087    load emit code 0087
                    pshs      d         push emit argument
                    lbsr      GenNode   emit code
                    leas      $04,s     drop arguments
                    bra       EmitResultCont join result tail

GenAddrOffsetNorm   leas      -$08,x    restore stack to frame base
EmitResultCont      ldd       $02,s     load result value from frame
                    pshs      d         push operand
                    ldd       #$0089    load emit code 0089
                    pshs      d         save D
                    ldd       #$0087    type code $0087 argument
                    pshs      d         push the argument
                    lbsr      GenNode   build derived type
                    leas      $06,s     drop arguments
                    bra       SetDefaultType go set the result type

SetDefaultTypeAdj   leas      -$08,x    restore stack via X
SetDefaultType      ldd       #$0093    default type code $0093
                    std       $06,u     store node type field
                    clra                clear A
                    clrb                clear B
                    std       $08,u     clear node size field
                    lbra      TypeWalkDone return from type walk

TypeWalkDefault     ldd       $06,s     load current type code
                    cmpd      #$00A0    derived-type threshold
                    blt       FloatTypeErr below means base type error
                    leax      $08,s     point at subtype slot
                    lbra      GenAssign recurse on subtype

FloatTypeErr        leax      FloatsMsg,pcr floats error message
                    pshs      x         push message pointer
                    pshs      u         push node pointer
                    lbsr      InternalErr report the error
                    leas      $04,s     drop arguments
                    lbra      TypeWalkDone return

TypeCodeDispatch    cmpx      #$0080    type code $0080
                    lbeq      TypeWalkDone match returns
                    cmpx      #$0093    type code $0093
                    lbeq      TypeWalkDone match returns
                    cmpx      #$0094    type code $0094
                    lbeq      TypeWalkDone match returns
                    cmpx      #$0095    type code $0095
                    lbeq      TypeWalkDone match returns
                    cmpx      #$0034    type code $0034
                    lbeq      TypeWalkDone match returns
                    cmpx      #$0042    type code $0042
                    lbeq      GenExprLeaf dispatch handler
                    cmpx      #$0092    type code $0092
                    lbeq      GenExprChild dispatch handler
                    cmpx      #$008E    type code $008E
                    lbeq      GenExprChild dispatch handler
                    cmpx      #$0090    type code $0090
                    lbeq      GenChildA dispatch handler
                    cmpx      #$008D    type code $008D
                    lbeq      GenChildB dispatch handler
                    cmpx      #$008C    type code $008C
                    lbeq      GenChildB dispatch handler
                    cmpx      #$004B    type code $004B
                    lbeq      EmitConstResult dispatch handler
                    cmpx      #$0064    type code $0064
                    lbeq      GenCallArgs dispatch handler
                    cmpx      #$003C    type code $003C
                    lbeq      GenOperandEmit dispatch handler
                    cmpx      #$003D    type code $003D
                    lbeq      GenOperandEmit dispatch handler
                    cmpx      #$0043    type code $0043
                    lbeq      GenOperandEmit dispatch handler
                    cmpx      #$003E    type code $003E
                    lbeq      GenRelCompare dispatch handler
                    cmpx      #$003F    type code $003F
                    lbeq      GenRelCompare dispatch handler
                    cmpx      #$0065    type code $0065
                    lbeq      GenExprSpecial dispatch handler
                    cmpx      #$005A    type code $005A
                    lbeq      GenBinaryOp2 dispatch handler
                    cmpx      #$005B    type code $005B
                    lbeq      GenBinaryOp2 dispatch handler
                    cmpx      #$005E    type code $005E
                    lbeq      GenBinaryOp2 dispatch handler
                    cmpx      #$005C    type code $005C
                    lbeq      GenBinaryOp2 dispatch handler
                    cmpx      #$005F    type code $005F
                    lbeq      GenBinaryOp2 dispatch handler
                    cmpx      #$005D    type code $005D
                    lbeq      GenBinaryOp2 dispatch handler
                    cmpx      #$0050    type code $0050
                    lbeq      GenBinaryOp2 dispatch handler
                    cmpx      #$0051    type code $0051
                    lbeq      GenBinaryOp2 dispatch handler
                    cmpx      #$0052    type code $0052
                    lbeq      GenBinaryOp2 dispatch handler
                    cmpx      #$0053    type code $0053
                    lbeq      GenBinaryOp2 dispatch handler
                    cmpx      #$0078    type code $0078
                    lbeq      GenAddrOffset dispatch handler
                    lbra      TypeWalkDefault default recurse case

TypeWalkDone        leas      $08,s     drop locals
                    puls      pc,u      restore U and return

FloatsMsg           fcc       /floats/
                    fcb       $00
ParseInitializer    pshs      u         save caller U
                    ldd       #$FFB0    frame size request
                    lbsr      stkcheck  check the stack frame
                    ldu       $04,s     load node pointer arg
                    leas      -$04,s    allocate locals
                    ldx       $0a,s     load type code arg
                    bra       ClassifyInitType classify the type

InitAggregate       lbsr      ReportCannotInit begin aggregate init
                    lbra      InitReturn done

InitScalarFlag1     ldd       #$0001    init flag one
                    bra       EmitInitDef join common emit

InitScalarFlag0     clra                clear A
                    clrb                clear B for flag zero
EmitInitDef         pshs      d         push init flag
                    lbsr      EmitVsect emit init preparation
                    leas      $02,s     drop flag
                    bra       SetupInitStorage continue setup

ClassifyInitType    cmpx      #$001E    type code $001E
                    beq       InitAggregate aggregate case
                    cmpx      #$000E    type code $000E
                    lbeq      InitAggregate aggregate case
                    cmpx      #$0022    type code $0022
                    lbeq      InitAggregate aggregate case
                    cmpx      #$0021    type code $0021
                    beq       InitScalarFlag1 scalar flag-one case
                    cmpx      #$0023    type code $0023
                    lbeq      InitScalarFlag1 scalar flag-one case
                    bra       InitScalarFlag0 default scalar case

SetupInitStorage    ldd       $0031     defining/pass flag
                    bne       EmitExternRef branch if externally referenced
                    leax      $14,u     point at node data field
                    stx       $02,s     save data pointer
                    ldd       $0a,s     load type code
                    cmpd      #$000F    type $000F needs full size
                    beq       SetSize12 use size twelve
                    ldd       $0a,s     reload type code
                    cmpd      #$0023    type $0023 needs full size
                    beq       SetSize12 use size twelve
                    ldd       #$0001    default size one
                    bra       EmitDefWithSize emit with size

SetSize12           ldd       #$000C    size twelve
                    std       $08,u     store node size
                    clra                clear A
                    clrb                clear B
EmitDefWithSize     pshs      d         push the size
                    ldd       $04,s     node data pointer
                    pshs      d         push it
                    lbsr      EmitLabelDef emit the definition
                    leas      $04,s     drop arguments
                    bra       CheckStringInit continue to string check

EmitExternRef       ldd       $06,u     node type field
                    pshs      d         push it
                    lbsr      EmitLabelName emit external reference
                    leas      $02,s     drop argument
                    lbsr      EmitNewline emit follow-up
CheckStringInit     ldd       $0C,s     reload saved type code
                    cmpd      #$0022    char-array type?
                    bne       NotStringInit not a string init
                    ldd       #$0001    init mode one
                    std       GlbPassMode set init mode flag
                    lbsr      ParseStatement2 get next token
                    ldd       $003F     current token code
                    cmpd      #$0037    string constant token?
                    bne       StringNotToken not a string constant
                    ldd       $04,u     node size field pointer
                    std       $02,s     save it
                    ldd       [$02,s]   array size already set?
                    bne       StringHasRoom yes, compute padding
                    ldd       $0060     string length global
                    std       [$02,s]   set array size from string
                    bra       NextAfterString skip padding

StringHasRoom       ldd       [$02,s]   declared array size
                    subd      $0060     minus string length
                    std       ,s        save remaining bytes
                    blt       StringTooLongErr negative means too long
                    ldd       ,s        reload remaining count
                    pshs      d         push it
                    lbsr      EmitCharDecimal pad remaining bytes
                    bra       AfterStringPad continue

StringTooLongErr    leax      MsgTooLong,pcr too-long error message
                    pshs      x         push message
                    lbsr      BuildMsgBuf report the error
AfterStringPad      leas      $02,s     drop temp
NextAfterString     lbsr      ParseStatement2 advance token past string
                    leax      $04,s     compute cleanup pointer
                    lbra      InitCleanupViaX go clean up and finish

StringNotToken      ldd       #$0002    init mode two
                    std       GlbPassMode set init mode flag
                    bra       DispatchInitByClass dispatch by class

NotStringInit       ldd       #$0002    init mode two
                    std       GlbPassMode set init mode flag
                    lbsr      ParseStatement2 get next token
DispatchInitByClass ldd       $0C,s     reload type code
                    cmpd      #$0004    struct/union type?
                    bne       CheckArrayClass not a struct
                    clra                clear A
                    clrb                clear B
                    pshs      d         push flag zero
                    ldd       $0a,u     struct member list
CallAggInit         pshs      d         push member list
                    pshs      u         push node pointer
                    ldd       $12,s     depth/param
                    pshs      d         push it
                    bsr       ParseAggregateInit parse aggregate init
                    leas      $08,s     drop arguments
                    bra       FinishInit finish

CheckArrayClass     ldd       $0C,s     reload type code
                    clra                clear A
                    andb      #$30      isolate class bits
                    cmpd      #$0020    array class?
                    bne       InitScalarValue not an array
                    clra                clear A
                    clrb                clear B
                    pshs      d         push flag zero
                    ldd       $04,u     array element type
                    bra       CallAggInit parse aggregate init

InitScalarValue     ldd       #$0001    flag one for scalar
                    pshs      d         push flag
                    ldd       $04,u     scalar value/type
                    pshs      d         push it
                    pshs      u         push node pointer
                    ldd       $12,s     depth/param
                    pshs      d         push it
                    bsr       ParseAggregateInit parse scalar init
                    leas      $08,s     drop arguments
                    std       -$02,s    save result
                    bne       FinishInit non-zero means ok
                    lbsr      SkipToInitDelim flag the error
                    bra       FinishInit finish

InitCleanupViaX     leas      -$04,x    restore stack via X
FinishInit          lbsr      EmitEndsect finish the emit
                    clra                clear A
                    clrb                clear B
                    std       GlbPassMode clear init mode flag
InitReturn          leas      $04,s     drop locals
                    puls      pc,u      restore U and return

ParseAggregateInit  pshs      u         save U
                    ldd       #$FFA8    frame size request
                    lbsr      stkcheck  check the stack frame
                    ldu       $06,s     load node pointer
                    leas      -$0C,s    allocate locals
                    ldd       $16,s     brace-required flag
                    bne       CheckOpenBrace flag set, check brace
                    ldd       #$0029    expected open brace token
                    pshs      d         push expected token
                    lbsr      ExpectToken report expected-token error
                    leas      $02,s     drop argument
                    bra       CheckArrayType continue

CheckOpenBrace      ldd       $003F     current token code
                    cmpd      #$0029    open brace?
                    bne       NoOpenBrace no brace present
                    ldd       #$0001    had-brace flag one
                    std       $0a,s     store had-brace flag
                    lbsr      ParseStatement2 consume the brace
                    bra       CheckArrayType continue

NoOpenBrace         clra                clear A
                    clrb                clear B
                    std       $0a,s     store had-brace zero
CheckArrayType      ldd       $10,s     load type code
                    clra                clear A
                    andb      #$30      isolate class bits
                    cmpd      #$0020    array class?
                    lbne      InitStructOrScalar not array, try struct
                    ldd       [$14,s]   declared array count
                    std       $02,s     save it
                    bne       ArrayInitSetup count present
                    ldd       #$FFFF    unspecified size marker
                    std       $02,s     save marker
ArrayInitSetup      ldd       $10,s     reload type code
                    pshs      d         push it
                    lbsr      TypeRemoveLevel get element type/size
                    leas      $02,s     drop argument
                    std       $08,s     save element type
                    cmpd      #$0004    struct element?
                    bne       ArrayElemSubtype not a struct element
                    ldd       $0a,u     member list pointer
                    bra       ArrayLoopInit use it

ArrayElemSubtype    ldx       $14,s     element node pointer
                    ldd       $02,x     element subtype
ArrayLoopInit       std       $04,s     save subtype
                    clra                clear A
                    clrb                clear B
                    std       $06,s     element index zero
                    bra       ArrayLoopCond test loop condition

ArrayElemBody       ldd       $16,s     depth counter
                    addd      #$0001    increment depth
                    pshs      d         push depth
                    ldd       $06,s     element type
                    pshs      d         push it
                    pshs      u         push node pointer
                    ldd       $0e,s     element subtype
                    pshs      d         push it
                    lbsr      ParseAggregateInit recurse element init
                    leas      $08,s     drop arguments
                    std       -$02,s    save result
                    lbeq      InitFailure failure returns zero
                    ldd       $06,s     element index
                    addd      #$0001    increment index
                    std       $06,s     store index
                    cmpd      $02,s     compare index to count
                    bcc       ArrayCountDone reached the count limit
                    ldd       $003F     current token code
                    cmpd      #$0030    comma?
                    bne       ArrayCountDone no comma, stop
                    lbsr      ParseStatement2 consume the comma
                    bra       ArrayLoopCond continue loop

ArrayLoopCond       ldd       $003F     current token code
                    cmpd      #$002A    close brace?
                    bne       ArrayElemBody not close, parse element
ArrayCountDone      ldd       $02,s     declared count
                    cmpd      #$FFFF    was size unspecified?
                    bne       PadArrayTail count was specified
                    ldd       $06,s     actual element count
                    std       [$14,s]   set array size from count
                    bra       FinishAggregate finish aggregate

PadArrayTail        ldd       $06,s     actual element count
                    cmpd      $02,s     compare to declared
                    bcc       FinishAggregate all elements provided
                    ldx       $14,s     element node pointer
                    ldd       $02,x     element subtype
                    pshs      d         push it
                    ldd       $02,u     node data field
                    pshs      d         push it
                    ldd       $0C,s     element size
                    pshs      d         push it
                    lbsr      ResolveTypeSize compute total element bytes
                    leas      $06,s     drop arguments
                    pshs      d         push result
                    ldd       $04,s     reload value
                    subd      $08,s     remaining byte count
                    lbsr      MulInt32  scale remaining count
                    pshs      d         push it
                    lbsr      FillInitElements fill remaining elements
                    leas      $02,s     drop argument
                    bra       FinishAggregate finish aggregate

AggCleanupViaX      leas      -$0C,x    restore stack via X
FinishAggregate     ldd       $16,s     brace-required flag
                    beq       SkipTrailingComma none, skip brace close
                    ldd       $0a,s     had-brace flag
                    lbeq      InitSuccess no brace, done
SkipTrailingComma   ldd       $003F     current token code
                    cmpd      #$0030    comma?
                    bne       ExpectCloseBrace no trailing comma
                    lbsr      ParseStatement2 consume trailing comma
ExpectCloseBrace    ldd       $003F     current token code
                    cmpd      #$002A    close brace?
                    bne       TooManyElemsErr missing close brace
                    lbsr      ParseStatement2 consume the brace
                    lbra      InitSuccess done ok

TooManyElemsErr     leax      MsgTooManyElem,pcr too-many-elements message
                    pshs      x         push message
                    lbsr      BuildMsgBuf report the error
                    leas      $02,s     drop argument
                    lbsr      SkipToInitDelim flag the error
                    lbra      InitSuccess done

InitStructOrScalar  ldd       $10,s     load type code
                    cmpd      #$0004    struct type?
                    lbne      InitScalar no, handle scalar
                    ldd       $14,s     member list pointer
                    std       ,s        save it
                    bne       StructLoopCond members present
                    leax      MsgNoUnions,pcr unions-not-allowed message
                    lbra      ReportInitErr report and fail

StructMemberBody    ldx       ,s        member list entry
                    ldu       $02,x     member node pointer
                    ldd       $16,s     depth counter
                    addd      #$0001    increment depth
                    pshs      d         push depth
                    ldd       ,u        member type
                    cmpd      #$0004    struct member?
                    bne       MemberSubtype not a struct member
                    ldd       $0a,u     member sub-list
                    bra       CallMemberInit use it

MemberSubtype       ldd       $04,u     member subtype
CallMemberInit      pshs      d         push it
                    pshs      u         push node pointer
                    ldd       ,u        member type
                    pshs      d         push it
                    lbsr      ParseAggregateInit recurse member init
                    leas      $08,s     drop arguments
                    std       -$02,s    save result
                    lbeq      InitFailure failure returns zero
                    ldd       [,s]      next member link
                    std       ,s        advance member entry
                    beq       FillMemberCond no more members
                    ldd       $003F     current token code
                    cmpd      #$0030    comma?
                    bne       FillMemberCond no comma, stop
                    lbsr      ParseStatement2 consume the comma
                    bra       StructLoopCond check loop condition

StructLoopCond      ldd       $003F     current token code
                    cmpd      #$002A    close brace?
                    bne       StructMemberBody not close, next member
                    bra       FillMemberCond stop the loop

FillMemberLoop      ldx       ,s        member list entry
                    ldu       $02,x     member node pointer
                    ldd       $04,u     member subtype
                    pshs      d         push it
                    ldd       $02,u     member offset
                    pshs      d         push it
                    ldd       ,u        member type
                    pshs      d         push it
                    lbsr      ResolveTypeSize compute member size
                    leas      $06,s     drop arguments
                    pshs      d         push result
                    bsr       FillInitElements zero-fill this member
                    leas      $02,s     drop argument
                    ldd       [,s]      next member link
                    std       ,s        advance member entry
FillMemberCond      ldd       ,s        member entry present?
                    bne       FillMemberLoop more members to fill
                    leax      $0C,s     compute cleanup pointer
                    lbra      AggCleanupViaX go clean up

InitScalar          ldd       $10,s     load type code
                    pshs      d         push it
                    bsr       EmitInitExpr parse scalar init expression
                    std       ,s++      save result and pop
                    beq       ConstExprErr2 zero means const required
                    ldd       $0a,s     had-brace flag
                    beq       InitSuccess no brace, done ok
                    ldd       #$002A    expected close brace token
                    pshs      d         push expected token
                    lbsr      ExpectToken report expected-token error
                    leas      $02,s     drop argument
InitSuccess         ldd       #$0001    return one for success
                    bra       AggInitReturn go to epilogue

ConstExprErr2       leax      MsgConstExprReq,pcr constant-expression message
ReportInitErr       pshs      x         push message
                    lbsr      BuildMsgBuf report the error
                    leas      $02,s     drop argument
                    lbsr      SkipToInitDelim flag the error
InitFailure         clra                clear A
                    clrb                clear B for failure
AggInitReturn       leas      $0C,s     drop locals
                    puls      pc,u      restore U and return

FillInitElements    pshs      u         save U
                    ldd       #$FFBA    frame size request
                    lbsr      stkcheck  check stack space
                    leax      MsgRzbDirective,pcr point to rzb directive text
                    pshs      x         push string argument
                    lbsr      EmitSpacedStr output the rzb directive
                    leas      $02,s     drop argument
                    ldd       $04,s     load reserved byte count
                    pshs      d         push the count
                    lbsr      EmitNumber emit the number
                    leas      $02,s     drop argument
                    lbsr      EmitNewline emit end of line
                    puls      pc,u      restore and return

EmitInitExpr        pshs      u         save frame pointer
                    ldd       #$FFAE    stack frame size
                    lbsr      stkcheck  check stack space
                    leas      -$08,s    reserve locals
                    ldd       #$0002    constant two
                    pshs      d         push argument
                    lbsr      ParseBinaryExpr get subexpression context
                    std       ,s        save result
                    lbsr      CopyExprTree parse initializer expression
                    leas      $02,s     drop argument
                    tfr       d,u       U = expression node
                    stu       -$02,s    save node pointer
                    bne       InitExprGotNode got a node, continue
                    clra                result high byte zero
                    clrb                result low byte zero
                    lbra      InitExprRet return null result

InitExprGotNode     clra                zero high byte
                    clrb                zero low byte
                    std       $04,s     clear offset local
                    ldd       #$0001    constant one
                    std       $02,s     set flag local
                    ldd       ,u        load node kind
                    std       ,s        save node kind
                    ldd       $0C,s     load target type
                    clra                high byte zero
                    andb      #$30      mask storage-class bits
                    cmpd      #$0010    is it an aggregate
                    bne       NotArrayType no, other handling
                    ldx       ,s        X = node kind
                    bra       DispatchNodeKind dispatch on kind

KindSize1           ldd       #$0001    size one byte
                    bra       CoerceNode go coerce node

CheckAggClass       ldd       ,s        reload node kind
                    clra                high byte zero
                    andb      #$30      mask class bits
                    cmpd      #$0010    is it aggregate class
                    beq       CheckAddrNode yes, emit directly
                    bra       EmitPadded else adjust stack

DispatchNodeKind    cmpx      #$0008    node kind eight
                    beq       KindSize1 handle as size one
                    cmpx      #$0001    node kind one
                    beq       CheckAddrNode emit directly
                    cmpx      #$0007    node kind seven
                    beq       CheckAddrNode emit directly
                    bra       CheckAggClass else check class

NotArrayType        ldd       ,s        node kind
                    clra                high byte zero
                    andb      #$30      mask class bits
                    cmpd      #$0010    aggregate class
                    bne       CoerceType no, needs conversion
                    ldd       $0C,s     target type
                    pshs      d         push it
                    lbsr      IsIntegralType types compatible
                    std       ,s++      save result and drop
                    bne       CheckAddrNode compatible, emit
EmitPadded          leax      $08,s     adjust stack pointer
                    bra       EmitPaddedFix go emit padded

CoerceType          ldd       $0C,s     target type
                    cmpd      #$0005    is it float
                    bne       UseTargetType no
                    ldd       #$0006    use double type
                    bra       CoerceNode coerce node

UseTargetType       ldd       $0C,s     target type
CoerceNode          pshs      d         push type
                    pshs      u         push node
                    lbsr      CoerceExpr coerce node to type
                    leas      $04,s     drop arguments
CheckAddrNode       ldd       $06,u     node operator
                    cmpd      #$0050    address-of node
                    beq       AddrNode  yes
                    ldd       $06,u     node operator
                    cmpd      #$0051    negated-address node
                    bne       CheckStringNode neither, other emit
AddrNode            ldd       $0C,u     child node pointer
                    std       $06,s     save child pointer
                    tfr       d,x       X = child node
                    ldd       $06,x     child operator
                    cmpd      #$0036    is it a symbol ref
                    beq       SymbolAddrNode yes
                    bra       EmitZeroWord else emit zero

EmitPaddedFix       leas      -$08,x    stack fixup entry
EmitZeroWord        clra                zero high byte
                    clrb                zero low byte
                    std       $02,s     clear flag
                    leax      $08,s     restore locals pointer
                    lbra      EmitTailFix emit and return

SymbolAddrNode      ldd       $06,u     node operator
                    cmpd      #$0051    negated-address node
                    bne       PosAddrOffset no
                    ldx       $06,s     child node
                    ldd       $08,x     its offset value
                    nega                negate high byte
                    negb                negate low byte
                    sbca      #$00      finish negation
                    bra       StoreOffset store the offset

PosAddrOffset       ldx       $06,s
                    ldd       $08,x     its offset value
StoreOffset         std       $04,s     save offset
                    ldd       $06,s     child node pointer
                    pshs      d         push it
                    lbsr      FreeExprTree release the node
                    leas      $02,s     drop argument
                    stu       $06,s     save current node
                    ldu       $0a,u     follow to symbol node
                    ldd       $06,s     restore node pointer
                    pshs      d         push it
                    lbsr      LinkFreeNode release the node
                    leas      $02,s     drop argument
CheckStringNode     ldd       $06,u     node operator
                    cmpd      #$0041    string or name node
                    lbne      CheckLeafOp no, other kinds
                    ldd       $0a,u     child pointer
                    std       $06,s     save it
                    tfr       d,x       X = child node
                    ldx       $08,x     follow link
                    ldx       $08,x     follow link again
                    bra       DispatchRefKind dispatch on kind

EmitZeroFlag        clra                zero high byte
                    clrb                zero low byte
                    std       $02,s     clear flag
                    lbra      EmitTail  emit and return

EmitRefExpr         lbsr      EmitFdb   prepare data emission
                    ldd       #$0001    flag one
                    std       $005A     set reloc flag
                    ldd       $04,s     offset value
                    pshs      d         push it
                    ldd       $08,s     node value
                    pshs      d         push it
                    ldd       #$0077    reference selector
                    pshs      d         push it
                    lbsr      EmitOperand2 emit reference expression
                    leas      $06,s     drop arguments
                    clra                zero high byte
                    clrb                zero low byte
                    std       $005A     clear reloc flag
                    lbsr      EmitNewline emit end of line
                    lbra      EmitTail  return

DispatchRefKind     cmpx      #$000F    kind fifteen
                    beq       EmitRefExpr emit reference
                    cmpx      #$000E    kind fourteen
                    lbeq      EmitRefExpr emit reference
                    cmpx      #$000C    kind twelve
                    lbeq      EmitRefExpr emit reference
                    cmpx      #$0021    kind thirty-three
                    lbeq      EmitRefExpr emit reference
                    cmpx      #$0022    kind thirty-four
                    lbeq      EmitRefExpr emit reference
                    bra       EmitZeroFlag else emit zero

CheckLeafOp         ldx       $06,u     node operator
                    bra       DispatchLeafOp dispatch on operator

FloatConst          ldd       $0C,s     target type
                    cmpd      #$0005    is it float
                    bne       EmitScalar no
                    ldx       $08,u     node value pointer
                    pshs      x         push it
                    ldx       $08,u     node value pointer
                    lbsr      BuildWordType convert to float
                    lbsr      CopyInt32 push float value
EmitScalar          ldd       $0C,s     target type
                    pshs      d         push it
                    ldd       $08,u     node value
                    pshs      d         push it
                    bsr       EmitScalarByType emit scalar by type
                    leas      $04,s     drop arguments
                    bra       EmitTail  return

EmitCharVal         lbsr      EmitFdb   prepare data emission
                    ldd       $08,u     node value
                    pshs      d         push it
                    lbsr      EmitLocalLabel emit the value
                    leas      $02,s     drop argument
                    bra       EmitTail  return

DispatchLeafOp      cmpx      #$004B    operator four-B
                    beq       FloatConst float constant handling
                    cmpx      #$0036    symbol ref operator
                    beq       EmitScalar emit scalar
                    cmpx      #$004A    operator four-A
                    lbeq      EmitScalar emit scalar
                    cmpx      #$0037    operator three-seven
                    beq       EmitCharVal emit value
                    lbra      EmitZeroFlag else emit zero

EmitTailFix         leas      -$08,x    stack fixup entry
EmitTail            pshs      u         push node
                    lbsr      FreeExprTree free the node
                    leas      $02,s     drop argument
                    ldd       $02,s     load result flag
InitExprRet         leas      $08,s     release locals
                    puls      pc,u      restore and return

EmitScalarByType    pshs      u         save frame pointer
                    ldd       #$FFB6    stack frame size
                    lbsr      stkcheck  check stack space
                    ldu       $04,s     U = node argument
                    leas      -$02,s    reserve local
                    ldx       $08,s     X = type argument
                    bra       DispatchTypeSize dispatch on type

EmitTypeTwo         lbsr      EmitFcb   prepare data emission
                    pshs      u         push node
                    lbsr      EmitNumber emit number
                    leas      $02,s     drop argument
                    lbsr      EmitNewline emit end of line
                    bra       ScalarByTypeRet return

SetSize1            ldd       #$0001    size one byte
                    bra       StoreSize store size

SetSize2            ldd       #$0002    size two bytes
                    bra       StoreSize store size

SetSize4            ldd       #$0004    size four bytes
StoreSize           std       ,s        save the size
                    bra       EmitSizedVal emit value

DispatchTypeSize    cmpx      #$0002    type two
                    beq       EmitTypeTwo special emission
                    cmpx      #$0001    type one char
                    beq       SetSize1  size one
                    cmpx      #$0007    type seven
                    lbeq      SetSize1  size one
                    cmpx      #$0008    type eight
                    beq       SetSize2  size two
                    cmpx      #$0005    type five
                    lbeq      SetSize2  size two
                    cmpx      #$0006    type six
                    beq       SetSize4  size four
                    lbra      SetSize1  default size one

EmitSizedVal        ldd       ,s        load size
                    pshs      d         push size
                    pshs      u         push node
                    lbsr      EmitInlineArgs emit value of size
                    leas      $04,s     drop arguments
ScalarByTypeRet     leas      $02,s     release local
                    puls      pc,u      restore and return

ReportCannotInit    pshs      u         save frame pointer
                    ldd       #$FFBA    stack frame size
                    lbsr      stkcheck  check stack space
                    leax      MsgCannotInit,pcr cannot-initialize message
                    pshs      x         push the message
                    lbsr      BuildMsgBuf report the error
                    leas      $02,s     drop argument
                    bsr       SkipToInitDelim skip to delimiter
                    puls      pc,u      restore and return

SkipToInitDelim     pshs      u         save frame pointer
                    ldd       #$FFBC    stack frame size
                    lbsr      stkcheck  check stack space
SkipTokLoop2        ldx       $003F     current token
                    bra       TestSkipTok test the token

SkipDone2           puls      pc,u      get next token

SkipNextTok         lbsr      ParseStatement2 loop
                    bra       SkipTokLoop2

TestSkipTok         cmpx      #$0030    is it a semicolon
                    beq       SkipDone2 stop
                    cmpx      #$0028    is it a close brace
                    lbeq      SkipDone2 stop
                    cmpx      #$FFFF    end of input
                    lbeq      SkipDone2 stop
                    bra       SkipNextTok else skip token

                    puls      pc,u      return (unreachable)

MsgTooLong          fcc       /too long/
                    fcb       $00
MsgTooManyElem      fcc       /too many elements/
                    fcb       $00
MsgNoUnions         fcc       /unions not allowed/
                    fcb       $00
MsgConstExprReq     fcc       /constant expression required/
                    fcb       $00
MsgRzbDirective     fcc       /rzb /
                    fcb       $00
MsgCannotInit       fcc       /cannot initialize/
                    fcb       $00
ResetInputBuf       pshs      u         save frame pointer
                    leax      $0584,y   line buffer address
                    stx       $004A     set input pointer
                    clra                zero high byte
                    clrb                zero low byte
                    stb       $0584,y   clear the buffer
                    ldd       #$0020    space character
                    bra       StoreCurChar store as current char

SkipSpaces          pshs      u         save frame pointer
                    bra       SkipSpaceLoop enter skip loop

SkipSpaceNext       bsr       NextChar  fetch next char
SkipSpaceLoop       ldb       $0045     current char
                    cmpb      #$20      is it a space
                    beq       SkipSpaceNext skip it
                    ldb       $0045     current char
                    cmpb      #$09      is it a tab
                    lbeq      SkipSpaceNext skip it
                    puls      pc,u      return

NextChar            pshs      u         save frame pointer
                    ldx       $004A     input pointer
                    leax      $01,x     advance pointer
                    stx       $004A     save pointer
                    ldb       -$01,x    get the char
                    stb       $0045     store current char
                    bne       NextCharRet non-null, done
                    bsr       RefillLine refill line buffer
StoreCurChar        stb       $0045     store current char
NextCharRet         puls      pc,u      return

RefillLine          pshs      u         save frame pointer
                    leas      -$08,s    reserve locals
                    ldd       GlbFirstCall first-call flag
                    bne       ReadDirectiveLine already primed
                    ldd       #$0001    flag one
                    std       GlbFirstCall mark as primed
                    leax      EmptyLine,pcr initial newline string
                    stx       $004A     point input at it
                    lbra      RetSpace  return

ReadDirectiveLine   clra                zero high byte
                    clrb                zero low byte
                    std       GlbFirstCall clear the flag
                    leax      $0584,y   line buffer
                    pshs      x         push destination
                    leax      $0684,y   source buffer
                    pshs      x         push source
                    lbsr      StrCpy    read the next line
                    leas      $04,s     drop arguments
DirectiveLoop       lbsr      ReadLine  get next word
                    std       $004A     save word pointer
                    lbeq      DirectiveEof none, return end of input
                    ldb       [$004A,y] first char of word
                    cmpb      #$23      is it a hash
                    lbne      CountLine not a directive
                    ldx       $004A     word pointer
                    ldb       $01,x     second char
                    sex                 sign-extend to D
                    std       $04,s     save directive char
                    lbsr      ReadLine  get next word
                    std       -$02,s    save pointer
                    lbeq      DirectiveEof none, return end of input
                    ldx       $04,s     restore directive char
                    lbra      DirectiveDispatch dispatch on directive

SetLineNumber       leax      $0584,y   line buffer
                    pshs      x         push it
                    lbsr      ParseDecimal parse the number
                    leas      $02,s     drop argument
                    std       $0007     set current line number
                    bra       DirectiveLoop continue loop

EmitDefaultLine     lbsr      EmitCommentStar prepare default line
FormatLineDir       leax      $0584,y   line buffer
                    pshs      x         push it
                    leax      FmtLineOut,pcr default format string
                    bra       WriteFormatTail print it

MatchKeyword        leax      $0584,y   line buffer
                    pshs      x         push it
                    leax      $0366,y   compare buffer
                    pshs      x         push it
                    lbsr      StrCpy    compare or copy
                    leas      $04,s     drop arguments
                    lbsr      ReadLine  get next word
                    std       -$02,s    save pointer
                    lbne      DirectiveLoop got one, continue loop
                    lbra      DirectiveEof else return end of input

HandleLineFile      leax      $0584,y   line buffer
                    pshs      x         push it
                    leax      $078a,y   output buffer
                    pshs      x         push it
                    lbsr      StrCpy    copy line to output buffer
                    leas      $04,s     drop arguments
                    lbsr      ReadLine  get next word
                    std       -$02,s    save pointer
                    lbeq      DirectiveEof none, return end of input
                    leax      $0584,y   line buffer
                    pshs      x         push it
                    lbsr      ParseDecimal parse the number
                    std       ,s        save value
                    leax      $078a,y   output buffer
                    pshs      x         push it
                    leax      FmtPsect,pcr format string
                    pshs      x         push it
                    ldd       $0005     output file handle
                    pshs      d         push it
                    lbsr      fprintf   write formatted line
                    leas      $08,s     drop arguments
                    leax      $078a,y   output buffer
                    pshs      x         push it
                    leax      FmtNam,pcr format string
WriteFormatTail     pshs      x         push format string
                    ldd       $0005     output file handle
                    pshs      d         push it
                    lbsr      fprintf   write formatted line
                    leas      $06,s     drop arguments
                    lbra      DirectiveLoop continue loop

HandleLineRange     leax      $0584,y   line buffer
                    pshs      x         push it
                    leax      $078a,y   output buffer
                    pshs      x         push it
                    lbsr      StrCpy    copy line to output buffer
                    leas      $04,s     drop arguments
                    lbsr      ReadLine  get next word
                    std       -$02,s    save pointer
                    beq       DirectiveEof none, return end of input
                    leax      $0584,y   line buffer
                    pshs      x         push it
                    lbsr      ParseDecimal parse the number
                    leas      $02,s     drop argument
                    std       $06,s     save first value
                    lbsr      ReadLine  get next word
                    std       -$02,s    save pointer
                    beq       DirectiveEof none, return end of input
                    leax      $0584,y   line buffer
                    pshs      x         push it
                    lbsr      ParseDecimal parse the number
                    leas      $02,s     drop argument
                    std       $02,s     save second value
                    lbsr      ReadLine  get next word
                    std       -$02,s    save pointer
                    bne       DirectiveHaveVal got token, continue
DirectiveEof        ldd       #$FFFF    end-of-input result
                    lbra      DirExit   return it

DirectiveHaveVal    ldd       $06,s     first value
                    beq       ErrPrintArg zero, skip
                    ldd       $06,s     first value
                    pshs      d         push it
                    leax      $0366,y   scratch buffer
                    pshs      x         push it
                    leax      FmtFileLine,pcr format string
                    pshs      x         push it
                    lbsr      PrintfToBuf format into buffer
                    leas      $06,s     drop arguments
                    bra       ErrPrintLine continue

ErrPrintArg         leax      StrArgPrefix,pcr point X at 'argument : ' string
                    pshs      x         push the format-string argument
                    lbsr      PrintfToBuf fprintf the argument label
                    leas      $02,s     drop the pushed argument
ErrPrintLine        leax      $0584,y   point X at the input line buffer
                    pshs      x         push the line as the %s argument
                    leax      FmtErrLine,pcr point X at the '**** %s ****' format
                    pshs      x         push the format string
                    lbsr      PrintfToBuf fprintf the offending line
                    leas      $04,s     drop the two arguments
                    ldb       $078a,y   get the extra-text pointer or flag
                    beq       ErrCheckFatal none present, skip to exit check
                    leax      $078a,y   point X at the extra message
                    pshs      x         push it as the %s argument
                    lbsr      EmitStringLine print the extra string
                    leas      $02,s     drop the argument
                    bra       ErrPadTest enter the caret padding loop

ErrPadLoop          leax      $0253,y   point X at the output file handle
                    pshs      x         push the stream argument
                    ldd       #$0020    space character to emit
                    pshs      d         push the space character
                    lbsr      PutByte   fputc a padding space
                    leas      $04,s     drop the two arguments
ErrPadTest          ldd       $02,s     load the remaining pad count
                    addd      #$FFFF    decrement the count by one
                    std       $02,s     store the updated count
                    subd      #$FFFF    test whether it was nonzero
                    bne       ErrPadLoop more spaces still to emit
                    leax      StrCaret,pcr point X at the '^' caret string
                    pshs      x         push the caret argument
                    lbsr      EmitStringLine print the caret under the column
                    leas      $02,s     drop the argument
ErrCheckFatal       ldd       $04,s     load the error severity code
                    cmpd      #$0031    is it a fatal error
                    lbne      DirectiveLoop not fatal, resume reading lines
                    ldd       #$0001    exit status one
                    pshs      d         push the exit code
                    lbsr      exit      terminate the compiler
                    leas      $02,s     drop the exit code (unreached)
                    lbra      DirectiveLoop resume reading lines

DirectiveDispatch   cmpx      #$0035    directive code '5' line number
                    lbeq      SetLineNumber handle the line-number directive
                    cmpx      #$0036    directive code '6'
                    lbeq      EmitDefaultLine handle it
                    cmpx      #$0032    directive code '2'
                    lbeq      FormatLineDir handle it
                    cmpx      #$0037    directive code '7' filename
                    lbeq      MatchKeyword handle the filename directive
                    cmpx      #$0050    directive code 'P' psect
                    lbeq      HandleLineFile handle the psect directive
                    cmpx      #$0030    directive code '0'
                    lbeq      HandleLineRange handle the line/column directive
                    cmpx      #$0031    directive code '1'
                    lbeq      HandleLineRange handle the line/column directive
                    lbra      DirectiveLoop unknown code, read next line

CountLine           ldd       $0007     load the current line counter
                    addd      #$0001    bump the line count
                    std       $0007     store it back
RetSpace            ldd       #$0020    return the space status value
DirExit             leas      $08,s     discard the local frame
                    puls      pc,u      restore U and return

ParseDecimal        pshs      u         save the U register
                    ldu       $04,s     U points at the digit string
                    leas      -$04,s    reserve scratch locals
                    clra                clear accumulator high byte
                    clrb                clear accumulator low byte
                    bra       ParseDecimalBody begin the digit scan

ParseDecimalLoop    ldd       ,s        load the running value
                    pshs      d         save it for the multiply
                    ldd       #$000A    multiplier ten
                    lbsr      MulInt32  multiply the value by ten
                    pshs      d         save the product
                    ldd       $04,s     load the current digit character
                    addd      #$FFD0    subtract ASCII '0'
                    addd      ,s++      add to value times ten
ParseDecimalBody    std       ,s        store the updated accumulator
                    ldb       ,u+       fetch the next character
                    sex                 sign-extend it into D
                    std       $02,s     save the character
                    leax      $00BA,y   point X at the char-class table
                    leax      d,x       index by the character
                    ldb       ,x        load its class byte
                    cmpb      #$6b      is it a digit class
                    beq       ParseDecimalLoop yes, accumulate another digit
                    ldd       ,s        load the final value
                    leas      $04,s     release the scratch locals
                    puls      pc,u      restore U and return

ReadLine            pshs      u,d       save U and reserve a slot
                    leau      $0584,y   U points at the line buffer
                    ldd       $0003     load the input stream handle
                    pshs      d         push the stream argument
                    lbsr      GetByte   getc the first character
                    leas      $02,s     drop the argument
                    std       ,s        save the character
                    cmpd      #$FFFF    was it end of file
                    lbne      ReadLineCheckFull no, store it in the buffer
                    ldx       $0003     load the stream pointer
                    ldd       $06,x     load its status flags
                    clra                clear the high byte
                    andb      #$20      test the temp-file bit
                    beq       ReadLineEofRet clean EOF, return empty
                    leax      $0260,y   point X at the filename argument
                    pshs      x         push it as the %s argument
                    leax      MsgTempFileErr,pcr point at the temp-file error message
                    pshs      x         push the format string
                    lbsr      CopyStringToBuf print the error to stderr
                    leas      $04,s     drop the arguments
                    ldd       #$0001    exit status one
                    pshs      d         push the exit code
                    lbsr      exit      abort the compiler
                    leas      $02,s     drop the exit code (unreached)
ReadLineEofRet      clra                clear the return high byte
                    clrb                return zero for EOF
                    bra       ReadLineExit exit the reader

ReadLineNext        ldx       ,s        reload the current character
                    bra       ReadLineTest test for a line terminator

ReadLineDone        clra                clear the terminator high byte
                    clrb                zero to null-terminate
                    stb       ,u        write the string terminator
                    leax      $0584,y   point X at the buffer start
                    tfr       x,d       return the buffer pointer in D
                    bra       ReadLineExit exit the reader

ReadLineStore       ldd       ,s        load the current character
                    stb       ,u+       store it and advance
                    ldd       $0003     load the input stream handle
                    pshs      d         push the stream argument
                    lbsr      GetByte   getc the next character
                    leas      $02,s     drop the argument
                    std       ,s        save the character
                    bra       ReadLineCheckFull check the buffer capacity

ReadLineTest        cmpx      #$000D    is the character a carriage return
                    beq       ReadLineDone yes, terminate the line
                    cmpx      #$FFFF    is it end of file
                    lbeq      ReadLineDone yes, terminate the line
                    bra       ReadLineStore otherwise store the character

ReadLineCheckFull   cmpu      $00AC,y   reached the buffer limit
                    bne       ReadLineNext room left, continue reading
                    ldd       $0007     load the line counter
                    addd      #$0001    bump it
                    std       $0007     store it back
                    std       GlbSrcLine record the current line number
                    leax      $0584,y   point X at the line buffer
                    stx       $0043     save the buffer pointer for the error
                    leax      >MsgLineTooLong,pcr point at 'input line too long'
                    pshs      x         push the message argument
                    lbsr      PrintMsg  report the warning
                    leas      $02,s     drop the argument
ReadLineExit        leas      $02,s     discard the saved slot
                    puls      pc,u      restore U and return

EmptyLine           fcb       $00
FmtLineOut          fcb       $25,$73
                    fcb       $0D,$00
FmtPsect            fcc       / psect %s,0,0,%d,0,0/
                    fcb       $0D,$00
FmtNam              fcc       / nam %s/
                    fcb       $0D,$00
FmtFileLine         fcc       /%s : line %d /
                    fcb       $00
StrArgPrefix        fcc       /argument : /
                    fcb       $00
FmtErrLine          fcc       /**** %s ****/
                    fcb       $0D,$00
StrCaret            fcb       $5E
                    fcb       $00
MsgTempFileErr      fcc       /INPUT FILE ERROR : TEMPORARY FILE/
                    fcb       $0D,$00
MsgLineTooLong      fcc       /input line too long/
                    fcb       $00
GenNode             pshs      u         save the U register
                    ldu       $0a,s     U points at the node
                    leas      -$08,s    reserve the local frame
                    ldd       $0C,s     load the node opcode
                    cmpd      #$0088    is it opcode $88
                    bne       GenNodeOp87 no, try the next case
                    ldd       $10,s     load the right operand
                    pshs      d         push it
                    ldd       $10,s     load the left operand
                    pshs      d         push it
                    lbsr      GenLongOp generate the $88 operation
                    lbra      GenDone4  finish the node

GenNodeOp87         ldd       $0C,s     reload the node opcode
                    cmpd      #$0087    is it opcode $87
                    bne       GenNodeDispatch no, use the jump table
                    ldd       $10,s     load the right operand
                    pshs      d         push it
                    ldd       $10,s     load the left operand
                    pshs      d         push it
                    lbsr      GenFloatOp generate the $87 operation
                    lbra      GenDone4  finish the node

GenNodeDispatch     ldx       $0C,s     node opcode into X
                    lbra      DispatchOperator dispatch on the opcode

GenPushReg          ldd       $0e,s     load the register-code operand
                    pshs      d         push it
                    lbsr      TypeRegChar map to a register name char
                    std       ,s        save the character
                    leax      StrPshsFmt,pcr point at the ' pshs %c' format
                    pshs      x         push the format string
                    ldd       $0005     load the output stream handle
                    pshs      d         push the stream argument
                    lbsr      fprintf   emit the pshs instruction
                    leas      $06,s     drop the arguments
                    ldd       $000F     load the current stack offset
                    subd      #$0002    account for the pushed word
                    std       $000F     store the new offset
                    cmpd      $001B     compare against the low-water mark
                    lbge      Pop8Ret   not deeper, node done
                    ldd       $000F     load the new offset
                    std       $001B     record deeper stack use
                    lbra      Pop8Ret   node done

GenCondBranch       ldd       $10,s     load the node operand
                    pshs      d         push it as an argument
                    ldd       #$0036    node code $36
                    pshs      d         push it
                    ldd       #$0071    node code $71
                    pshs      d         push it
                    ldd       #$0081    node code $81
                    pshs      d         push it
                    lbsr      GenNode   recursively generate the subtree
                    leas      $08,s     drop the arguments
                    ldd       $0e,s     load the condition operand
                    std       $10,s     store it as the branch target
                    ldd       #$005A    node code $5A
                    std       $0e,s     set it as the operand
GenLongBranch       leax      StrLb,pcr point at the 'lb' branch prefix
                    pshs      x         push the mnemonic argument
                    lbsr      EmitSpacedStr emit the 'lb' prefix
                    leas      $02,s     drop the argument
                    ldd       $0e,s     load the condition code
                    pshs      d         push it
                    lbsr      GetLongMnemonic map to the branch mnemonic
                    std       ,s        save it
                    lbra      GenOperandTail emit the operand and finish

GenReturn           ldd       $0017     any pending cleanup
                    beq       GenReturnEmit none, skip it
                    lbsr      EmitFuncEpilogue emit the function-exit cleanup
GenReturnEmit       leax      StrPulsUpc,pcr point at 'puls u,pc'
                    lbra      EmitMnemDone emit and finish the node

GenCompare          pshs      u         save the node pointer
                    ldd       $12,s     load the right operand
                    pshs      d         push it
                    ldd       $10,s     load the left operand
                    pshs      d         push it
                    lbsr      EmitLogicalOperand generate the comparison
                    leas      $06,s     drop the arguments
                    lbra      Pop8Ret   node done

GenMult             leax      StrCcmult,pcr point at the 'ccmult' helper name
                    bra       GenRuntimeCall emit the runtime call

GenUDiv             leax      StrCcudiv,pcr point at the 'ccudiv' helper name
                    bra       GenRuntimeCall emit the runtime call

GenDiv              leax      StrCcdiv,pcr point at the 'ccdiv' helper name
                    bra       GenRuntimeCall emit the runtime call

GenShiftLeft        leax      StrCcasl,pcr point at the 'ccasl' helper name
                    bra       GenRuntimeCall emit the runtime call

GenShiftRight       leax      StrCcasr,pcr point at the 'ccasr' helper name
                    bra       GenRuntimeCall emit the runtime call

GenLShiftRight      leax      StrCclsr,pcr point at the 'cclsr' helper name
                    bra       GenRuntimeCall emit the runtime call

GenUMod             leax      StrCcumod,pcr point at the 'ccumod' helper name
                    bra       GenRuntimeCall emit the runtime call

GenMod              leax      StrCcmod,pcr point at the 'ccmod' helper name
GenRuntimeCall      pshs      x         push the helper name
                    lbsr      EmitInstrPush2 emit the jsr to the helper
                    lbra      EmitOpDone finish the node

GenNegate           leax      StrNegate,pcr point at the 'nega' mnemonic
                    lbra      EmitMnemDone emit and finish

GenComplement       leax      StrComplement,pcr point at the 'coma' mnemonic
                    lbra      EmitMnemDone emit and finish

GenLeaLocal         leax      StrLeax,pcr point at the 'leax ' mnemonic
                    pshs      x         push the mnemonic argument
                    lbsr      EmitSpacedStr emit 'leax '
                    leas      $02,s     drop the argument
                    ldd       $000F     load the stack offset
                    nega                negate the high byte
                    negb                negate the low byte
                    sbca      #$00      finish the two's complement
                    pshs      d         push the negated offset
                    lbsr      EmitNumber emit the offset number
                    leas      $02,s     drop the argument
                    ldd       $00B0,y   load the stack-pointer register name
                    pshs      d         push it
                    lbsr      EmitStr   emit the ',s' operand
                    leas      $02,s     drop the argument
                    lbsr      EmitNewline emit the newline
GenBaseRef          ldd       $00B4,y   load the base register name
                    pshs      d         push it
                    lbsr      EmitSpacedStr emit the register reference
                    leas      $02,s     drop the argument
                    ldd       $0e,s     load the operand value
                    bra       GenValueTail emit the operand and finish

GenTempSlot         ldd       $00B4,y   load the base register name
                    pshs      d         push it
                    lbsr      EmitSpacedStr emit the register reference
                    leas      $02,s     drop the argument
                    ldd       $000B     load the temp-label counter
                    addd      #$0001    allocate a new label number
                    std       $000B     store the updated counter
                    std       $10,s     save the label number
                    pshs      d         push it
                    lbsr      EmitLocalLabel emit the temp label
                    leas      $02,s     drop the argument
                    ldd       $0e,s     load the operand value
                    pshs      d         push it
                    lbsr      EmitLocalLabel emit it
                    leas      $02,s     drop the argument
                    leax      StrLeas,pcr point at the 'leas ' mnemonic
                    pshs      x         push the mnemonic argument
                    lbsr      EmitSpacedStr emit 'leas '
                    leas      $02,s     drop the argument
                    ldd       $000F     load the stack offset
                    pshs      d         push it
                    lbsr      EmitNumber emit the offset number
                    leas      $02,s     drop the argument
                    leax      StrCommaX,pcr point at the ',x' operand
                    pshs      x         push the operand argument
GenOperandTail      lbsr      EmitStr   emit the operand string
                    leas      $02,s     drop the argument
                    ldd       $10,s     load the value to emit
GenValueTail        pshs      d         push it
                    lbsr      EmitLocalLabel emit it
                    lbra      EmitOpDone finish the node

GenFuncCall         ldd       #$0004    operand size four
                    std       $0013     record it
                    ldx       $10,s     load the node pointer
                    ldd       $06,x     load its subtype
                    cmpd      #$0034    is it an array reference
                    bne       GenCallIndirect no, emit an indirect call
                    ldx       $10,s     reload the node pointer
                    ldd       $08,x     load the array element operand
                    std       $04,s     save it
                    beq       GenCallIndirect zero element, indirect call
                    ldd       $00B2,y   load the base register name
                    pshs      d         push it
                    lbsr      EmitSpacedStr emit the register reference
                    leas      $02,s     drop the argument
                    clra                clear the high byte
                    clrb                zero addend
                    pshs      d         push it
                    ldd       $06,s     load the saved element operand
                    addd      #$0014    offset to the element field
                    pshs      d         push the address
                    lbsr      EmitLabelDef emit the array element load
                    lbra      GenDone4  finish the node

GenCallIndirect     leax      StrJsr,pcr point at the 'jsr ' mnemonic
                    pshs      x         push the mnemonic argument
                    lbsr      EmitSpacedStr emit 'jsr '
                    leas      $02,s     drop the argument
                    clra                clear the high byte
                    clrb                zero flag
                    pshs      d         push it
                    ldd       $12,s     load the call target operand
                    pshs      d         push it
                    ldd       $12,s     load it again
                    pshs      d         push it
                    lbsr      EmitOperand2 emit the call target
                    leas      $06,s     drop the arguments
                    lbra      GenEmitDone emit newline and finish

GenSignExtend       leax      StrSex,pcr point at the 'sex' mnemonic
                    bra       EmitMnemDone emit and finish

GenLoadWord         leax      StrLd,pcr point at the 'ld' mnemonic
                    pshs      x         push the mnemonic argument
                    lbsr      EmitSpacedStr emit 'ld'
                    leas      $02,s     drop the argument
                    ldd       #$0002    operand size two
                    pshs      d         push it
                    ldd       $12,s     load the operand node
                    pshs      d         push it
                    ldd       $12,s     load it again
                    pshs      d         push it
                    ldd       #$0064    load flag $64
                    pshs      d         push it
                    lbsr      EmitInstrLine emit the load operand
                    lbra      GenDone8  finish the node

GenAslb             leax      StrAslbRola,pcr point at the 'aslb' mnemonic
                    bra       EmitMnemDone emit and finish

GenAsra             leax      StrAsraRorb,pcr point at the 'asra' mnemonic
                    bra       EmitMnemDone emit and finish

GenLsra             leax      StrLsraRorb,pcr point at the 'lsra' mnemonic
EmitMnemDone        pshs      x         push the mnemonic argument
                    lbra      EmitOpLine emit the bare mnemonic and finish

GenLoadY            leax      StrLdy,pcr point at the 'ldy ' mnemonic
                    pshs      x         push the mnemonic argument
                    lbsr      EmitSpacedStr emit 'ldy '
                    leas      $02,s     drop the argument
                    leax      $08,s     point at the operand frame slot
                    bra       GenLoadRegAdj adjust the frame and emit the operand

GenLoadU            leax      StrLdu,pcr point at the 'ldu ' mnemonic
                    pshs      x         push the mnemonic argument
                    lbsr      EmitSpacedStr emit 'ldu '
                    leas      $02,s     drop the argument
                    bra       GenLoadRegBody emit the operand

GenLoadRegAdj       leas      -$08,x    back up to the operand slot
GenLoadRegBody      ldd       $0e,s     load the operand value
                    pshs      d         push it
                    lbsr      EmitNumber emit the operand number
                    leas      $02,s     drop the argument
                    ldd       $00B0,y   load the stack register name
                    pshs      d         push it
                    lbsr      EmitStr   emit the ',s' operand
                    leas      $02,s     drop the argument
GenEmitDone         lbsr      EmitNewline emit the newline
                    lbra      Pop8Ret   finish the node

GenLeaIndexed       leax      StrLeax2,pcr point at the 'leax ' mnemonic
                    pshs      x         push the mnemonic argument
                    lbsr      EmitSpacedStr emit 'leax '
                    leas      $02,s     drop the argument
                    ldx       $0e,s     load the addressing-mode code
                    bra       DispatchIndexMode dispatch on it

GenIndexBase        ldx       $10,s     load the node pointer
                    ldd       $06,x     load its subtype
                    std       $06,s     save it
                    cmpd      #$0094    is it subtype $94
                    bne       GenIndexBaseAlt no, check the next
                    ldd       #$0079    emit code $79
                    bra       EmitIndexOperand format the operand

GenIndexBaseAlt     ldd       $06,s     reload the subtype
                    cmpd      #$0095    is it subtype $95
                    bne       RegLetterX no, use the default
                    ldd       #$0075    emit code $75
                    bra       EmitIndexOperand format the operand

RegLetterX          ldd       #$0078    default index register letter x
EmitIndexOperand    std       $06,s     save register letter local
                    pshs      d         push register letter as arg
                    ldx       $12,s     X = node pointer
                    ldd       $08,x     D = node offset field
                    pshs      d         push offset value
                    leax      StrOffRegFmt,pcr X = %d,%c format string
                    pshs      x         push format string
                    ldd       $0005     D = output file pointer
                    pshs      d         push file pointer
                    lbsr      fprintf   emit offset,reg operand
                    lbra      GenDone8  clean up and finish

EmitAccIndex        ldd       $10,s     D = operand type
                    pshs      d         push type
                    lbsr      TypeRegChar map type to register letter
                    std       ,s        store letter over arg
                    leax      StrDRegFmt,pcr X = d,%c format string
                    lbra      EmitFmtDone emit operand and finish

DispatchIndexMode   cmpx      #$0077    index mode with variable
                    beq       GenIndexBase handle register-indirect
                    cmpx      #$0070    accumulator index mode
                    beq       EmitAccIndex handle d,reg operand
                    lbra      Pop8Ret   otherwise just finish

DispatchOperator    cmpx      #$007A    opcode 0x7A
                    lbeq      GenPushReg dispatch to handler
                    cmpx      #$007D    opcode 0x7D
                    lbeq      GenCondBranch dispatch to handler
                    cmpx      #$0082    opcode 0x82
                    lbeq      GenLongBranch dispatch to handler
                    cmpx      #$0012    opcode 0x12
                    lbeq      GenReturn dispatch to handler
                    cmpx      #$0057    opcode 0x57
                    lbeq      GenCompare dispatch to handler
                    cmpx      #$0058    opcode 0x58
                    lbeq      GenCompare same handler
                    cmpx      #$0059    opcode 0x59
                    lbeq      GenCompare same handler
                    cmpx      #$0052    opcode 0x52
                    lbeq      GenMult   dispatch to handler
                    cmpx      #$004E    opcode 0x4E
                    lbeq      GenUDiv   dispatch to handler
                    cmpx      #$0053    opcode 0x53
                    lbeq      GenDiv    dispatch to handler
                    cmpx      #$0056    opcode 0x56
                    lbeq      GenShiftLeft dispatch to handler
                    cmpx      #$0055    opcode 0x55
                    lbeq      GenShiftRight dispatch to handler
                    cmpx      #$004D    opcode 0x4D
                    lbeq      GenLShiftRight dispatch to handler
                    cmpx      #$004C    opcode 0x4C
                    lbeq      GenUMod   dispatch to handler
                    cmpx      #$0054    opcode 0x54
                    lbeq      GenMod    dispatch to handler
                    cmpx      #$0043    opcode 0x43
                    lbeq      GenNegate dispatch to handler
                    cmpx      #$0044    opcode 0x44
                    lbeq      GenComplement dispatch to handler
                    cmpx      #$001D    opcode == _start value
                    lbeq      GenLeaLocal dispatch to handler
                    cmpx      #$007C    opcode 0x7C
                    lbeq      GenBaseRef dispatch to handler
                    cmpx      #$0009    opcode 0x09
                    lbeq      GenTempSlot dispatch to handler
                    cmpx      #$0065    opcode 0x65
                    lbeq      GenFuncCall dispatch to handler
                    cmpx      #$0085    opcode 0x85
                    lbeq      GenSignExtend dispatch to handler
                    cmpx      #$0084    opcode 0x84
                    lbeq      GenLoadWord dispatch to handler
                    cmpx      #$0098    opcode 0x98
                    lbeq      GenAslb   dispatch to handler
                    cmpx      #$0096    opcode 0x96
                    lbeq      GenAsra   dispatch to handler
                    cmpx      #$0097    opcode 0x97
                    lbeq      GenLsra   dispatch to handler
                    cmpx      #$0076    opcode 0x76
                    lbeq      GenLoadY  dispatch to handler
                    cmpx      #$006F    opcode 0x6F
                    lbeq      GenLoadU  dispatch to handler
                    cmpx      #$007B    opcode 0x7B
                    lbeq      GenLeaIndexed dispatch to handler
                    ldd       $0e,s     default: D = result type arg
                    pshs      d         push type
                    lbsr      TypeRegChar map to register letter
                    leas      $02,s     drop arg
                    std       $06,s     save register letter local
                    ldd       $10,s     D = operand type
                    cmpd      #$0077    is it a variable operand
                    lbne      GenOperand2 no, generate operand
                    ldd       $06,u     D = child node opcode
                    cmpd      #$0085    is child a conversion node
                    bne       CheckByteDemote no, check byte demote
                    ldd       $0a,u     D = grandchild field
                    pshs      d         push as recursion arg
                    ldd       #$0077    push type 0x77
                    pshs      d         push it
                    ldd       #$0070    push type 0x70
                    pshs      d         push it
                    ldd       $12,s     push node pointer arg
                    pshs      d         push it
                    lbsr      GenNode   recurse to gen child code
                    leas      $08,s     drop four args
                    ldx       $0C,s     X = child opcode
                    bra       DispatchExtend dispatch the extension

EmitSex             leax      StrSex2,pcr X = sex mnemonic
                    bra       EmitConvOp emit conversion line

EmitAdca            leax      StrAdca0,pcr X = adca #0 mnemonic
                    bra       EmitConvOp emit conversion line

EmitSbca            leax      StrSbca0,pcr X = sbca #0 mnemonic
EmitConvOp          pshs      x         push mnemonic string
                    lbsr      EmitLine  emit instruction line
                    leas      $02,s     drop string
                    bra       ConvDone  set type and finish

DispatchExtend      cmpx      #$0075    conversion opcode 0x75
                    beq       EmitSex   emit sex
                    cmpx      #$004F    opcode 0x4F
                    beq       EmitAdca  emit adca #0
                    cmpx      #$0050    opcode 0x50
                    lbeq      EmitAdca  emit adca #0
                    cmpx      #$0051    opcode 0x51
                    beq       EmitSbca  emit sbca #0
ConvDone            ldd       #$0070    result type d register
                    std       $06,u     store type into node
                    lbra      Pop8Ret   finish

CheckByteDemote     ldd       ,u        D = node primary type
                    cmpd      #$0002    is it a byte type
                    bne       GenOperand2 no, generate operand
                    ldd       $0C,s     local operand code
                    cmpd      #$007F    is it member access
                    beq       GenOperand2 yes, skip demote
                    ldd       $06,s     register letter local
                    cmpd      #$0078    is it letter x
                    beq       GenOperand2 yes, skip demote
                    ldd       #$0062    else use byte register b
                    std       $06,s     demote to byte register
GenOperand2         ldx       $0C,s     X = operand opcode
                    lbra      DispatchOperand dispatch operand generation

LoadVarOperand      ldd       $10,s     D = operand type
                    cmpd      #$0077    is it a variable
                    lbne      EmitLoad  no, alternate load path
                    ldd       $08,u     D = node right child
                    std       ,s        save local
                    ldd       $06,u     D = node left child opcode
                    std       $02,s     save local
                    tfr       d,x       X = child opcode
                    lbra      DispatchLoadSrc dispatch load source

EmitRegIndex        ldd       $0e,s     D = result type arg
                    cmpd      #$0070    is it d register
                    beq       EmitAddToD yes, add-into-d path
                    ldd       $06,s     register letter local
                    pshs      d         push it
                    lbsr      EmitFmtOperand emit prefix with register
                    leas      $02,s     drop arg
                    ldd       $02,s     saved child opcode
                    pshs      d         push it
                    lbsr      TypeRegChar map to register letter
                    std       ,s        store letter
                    ldd       $02,s     child opcode again
                    pshs      d         push it
                    leax      StrOffRegFmt2,pcr X = %d,%c format
                    lbra      EmitFmt2Done emit operand and finish

EmitAddToD          ldd       #$0064    push register letter d
                    pshs      d         push it
                    ldd       $04,s     local operand
                    pshs      d         push it
                    lbsr      TypeRegChar map to register letter
                    std       ,s        store letter
                    lbsr      EmitTfr   emit tfr instruction
                    leas      $04,s     drop args
                    ldd       ,s        local offset value
                    lbeq      Pop8Ret   zero means finish
                    ldd       ,s        offset value again
                    pshs      d         push it
                    ldd       #$0036    push type 0x36
                    pshs      d         push it
                    ldd       #$0070    push type 0x70
                    pshs      d         push it
                    ldd       #$0050    push add opcode 0x50
                    pshs      d         push it
                    lbsr      GenNode   recurse to gen add
                    lbra      GenDone8  finish

EmitTfrToD          ldd       $0e,s     D = result type
                    cmpd      #$0070    is it d register
                    lbeq      Pop8Ret   yes, nothing to do
                    ldd       $06,s     register letter local
                    pshs      d         push it
                    ldd       #$0064    target letter d
                    lbra      EmitTfrDone emit tfr and finish

EmitCombinedOperand ldd       $08,u     D = node right child
                    pshs      d         push it
                    ldd       $08,s     operand value
                    pshs      d         push it
                    lbsr      EmitLabelRef emit combined operand
                    lbra      GenDone4  finish

SetConstType        ldd       #$0036    constant type 0x36
                    std       $10,s     set operand type
                    ldu       ,s        U = local node pointer
                    bra       EmitLoad  go emit load

DispatchLoadSrc     cmpx      #$0071    child opcode 0x71
                    lbeq      EmitRegIndex emit register-indexed
                    cmpx      #$0076    child opcode 0x76
                    lbeq      EmitRegIndex emit register-indexed
                    cmpx      #$006F    child opcode 0x6F
                    lbeq      EmitRegIndex emit register-indexed
                    cmpx      #$0070    child opcode 0x70
                    beq       EmitTfrToD transfer into d
                    cmpx      #$0037    child opcode 0x37
                    beq       EmitCombinedOperand emit combined operand
                    cmpx      #$0036    child opcode 0x36
                    beq       SetConstType set constant type
EmitLoad            ldd       $0e,s     D = result type
                    cmpd      #$0070    is it d register
                    bne       EmitLd    no, emit ld
                    ldd       $10,s     D = operand type
                    cmpd      #$0036    is it constant
                    bne       EmitLd    no, emit ld
                    cmpu      #$0000    is node null
                    bne       EmitLd    no, emit ld
                    leax      StrClraClrb,pcr X = clra/clrb mnemonic
                    pshs      x         push it
EmitOpLine          lbsr      EmitLine  emit instruction line
EmitOpDone          leas      $02,s     drop string
                    lbra      Pop8Ret   finish

EmitLd              leax      StrLd2,pcr X = ld mnemonic
                    lbra      EmitOpStr emit op and operand

GenCompareOp        ldd       $10,s     D = operand type
                    cmpd      #$0036    is it constant
                    bne       EmitCmpOp no, emit compare
                    cmpu      #$0000    is node null
                    bne       EmitCmpOp no, emit compare
                    ldd       $06,s     register letter local
                    pshs      d         push it
                    leax      StrStTemp,pcr X = st%c -2,s format
EmitFmtDone         pshs      x         push format
                    ldd       $0005     output file pointer
                    pshs      d         push it
                    lbsr      fprintf   emit spill store
                    leas      $06,s     drop args
                    lbra      Pop8Ret   finish

EmitCmpOp           leax      StrCmp,pcr X = cmp mnemonic
                    pshs      x         push it
                    lbsr      EmitSpacedStr emit op string
                    leas      $02,s     drop string
                    ldd       $06,s     register letter local
                    cmpd      #$0062    is it byte register b
                    bne       OperandBase no, continue operand
                    ldd       #$0064    else promote to d
                    std       $06,s     store d register letter
                    bra       OperandBase continue operand

GenVarSub           ldd       $10,s     D = operand type
                    cmpd      #$0077    is it a variable
                    bne       EmitSt    no, emit sub
                    ldd       $06,u     D = node left child opcode
                    std       $02,s     save local
                    pshs      d         push it
                    lbsr      IsFloatType test if u/y register
                    std       ,s++      store result, drop arg
                    beq       EmitSt    not a register, emit sub
                    ldd       $02,s     saved opcode
                    cmpd      $0e,s     equals result type
                    lbeq      Pop8Ret   yes, finish
                    ldd       $02,s     opcode again
                    pshs      d         push it
                    lbsr      TypeRegChar map to register letter
                    std       ,s        store letter
                    ldd       $08,s     operand value
EmitTfrDone         pshs      d         push it
                    lbsr      EmitTfr   emit tfr instruction
GenDone4            leas      $04,s     drop args
                    lbra      Pop8Ret   finish

EmitSt              leax      StrSt,pcr X = st mnemonic
                    bra       EmitOpStr emit op and operand

EmitSub             leax      StrSub,pcr X = sub mnemonic
EmitOpStr           pshs      x         push mnemonic
                    lbsr      EmitSpacedStr emit op string
                    leas      $02,s     drop string
OperandBase         leax      $08,s     X = argument frame base
                    bra       BuildOperand build operand

GenAddChild         ldd       #$0043    push opcode 0x43
                    pshs      d         push it
                    lbsr      GenNode   recurse to gen code
                    leas      $02,s     drop arg
EmitAdd             leax      StrAdd,pcr X = add mnemonic
                    lbra      EmitOpAndBinary emit op and finish

BuildOperand        leas      -$08,x    S = adjusted frame
                    lbra      GenBinaryOperand generate operand

LoadMemberNode      ldd       $10,s     D = operand type
                    cmpd      #$0077    is it a variable
                    lbne      EmitLea   no, generic operand
                    ldx       $08,u     X = node right child
                    ldd       $08,x     child's field
                    std       $02,s     save local
                    tfr       d,x       X = that value
                    bra       DispatchMember dispatch member subtype

EmitMemberRef       ldd       $06,s     register letter local
                    pshs      d         push it
                    lbsr      EmitFmtOperand emit prefix with register
                    leas      $02,s     drop arg
                    ldd       #$003E    greater-than char
                    pshs      d         push it
                    lbsr      EmitChar  emit > char
                    leas      $02,s     drop arg
                    ldd       $02,s     saved value
                    cmpd      #$0023    is it subtype 0x23
                    bne       EmitOffsetRef no, offset form
                    ldx       $08,u     X = node right child
                    ldd       $06,x     child's field
                    pshs      d         push it
                    lbsr      EmitLabelName emit operand
                    bra       EmitMemberTail continue member tail

EmitOffsetRef       ldd       $08,u     D = node right child
                    addd      #$0014    add field offset 0x14
                    pshs      d         push it
                    lbsr      EmitLabelText emit operand
EmitMemberTail      leas      $02,s     drop arg
                    ldd       $14,u     node field 0x14
                    pshs      d         push it
                    lbsr      EmitSignedOffset emit number or label
                    leas      $02,s     drop arg
                    ldd       $00AE,y   global suffix field
                    pshs      d         push it
                    lbsr      EmitStr   emit suffix string
                    lbra      EmitNlDone emit newline and finish

DispatchMember      cmpx      #$0021    member subtype 0x21
