EmitProgramEnd      pshs      u         save frame pointer
                    lbsr      DumpStrings dump string literals
                    lbsr      EmitEndsect emit endsect directive
                    ldd       $0009     load source error count
                    lbeq      EmitRet   no errors, done
                    leax      StrFailSourceErrors,pcr point at "fail source errors"
                    lbra      PushAndEmit emit the fail marker

EmitVsectRmb        pshs      u         save frame pointer
                    ldd       $08,s     get direct-page flag argument
                    pshs      d         pass to vsect emitter
                    lbsr      EmitVsect emit vsect header
                    leas      $02,s     drop argument
                    ldd       $04,s     get variable name pointer
                    pshs      d         pass to name emitter
                    lbsr      EmitLabelName emit the symbol name
                    leas      $02,s     drop argument
                    ldd       $06,s     get size in bytes
                    pshs      d         pass to fprintf
                    leax      StrRmbD,pcr " rmb %d" format string
                    pshs      x         push format pointer
                    ldd       $0005     output stream handle
                    pshs      d         push stream
                    lbsr      fprintf   emit rmb reservation
                    bra       EndVsectRet close vsect and return

EmitColonRmb        pshs      u         save frame pointer
                    ldd       $08,s     get direct-page flag argument
                    pshs      d         pass to vsect emitter
                    lbsr      EmitVsect emit vsect header
                    leas      $02,s     drop argument
                    ldd       #$003A    ':' label separator
                    bra       EmitLabeledRmb emit labeled rmb

EmitSpaceRmb        pshs      u         save frame pointer
                    ldd       $08,s     get direct-page flag argument
                    pshs      d         pass to vsect emitter
                    lbsr      EmitVsect emit vsect header
                    leas      $02,s     drop argument
                    ldd       #$0020    ' ' label separator
EmitLabeledRmb      pshs      d         save separator char
                    ldd       $08,s     get variable name
                    pshs      d         push name
                    ldd       $08,s     get size
                    pshs      d         push size
                    bsr       EmitNameRmb emit "name: rmb size"
EndVsectRet         leas      $06,s     drop the three args
                    lbsr      EmitEndsect emit endsect
                    puls      pc,u      return

EmitNameRmb         pshs      u         save frame pointer
                    ldd       $06,s     get size argument
                    pshs      d         push size
                    ldb       $0b,s     get separator char
                    sex                 extend to word
                    pshs      d         push char
                    ldd       $08,s     get name record pointer
                    addd      #$0014    skip to name field
                    pshs      d         push name pointer
                    leax      Str8sCRmbD,pcr "%.8s%c rmb %d" format
                    pshs      x         push format
                    ldd       $0005     output stream handle
                    pshs      d         push stream
                    lbsr      fprintf   emit labeled reservation
                    leas      $0a,s     drop five args
                    puls      pc,u      return

EmitStringConst     pshs      u         save frame pointer
                    ldd       $06,s     get string record pointer
                    std       $005E     save current string
                    pshs      d         push it
                    lbsr      EmitLabelName emit the label name
                    leas      $02,s     drop argument
                    ldd       $04,s     get string text pointer
                    pshs      d         push text
                    leax      StrFcc,pcr " fcc \"%.8s\" fcb 0" format
                    lbra      EmitFmtArg2 emit constant and return

EmitFuncPrologue    pshs      u         save frame pointer
                    ldu       $04,s     get function name pointer
                    pshs      u         push name
                    leax      StrTtl8s,pcr " ttl %.8s" format
                    pshs      x         push format
                    ldd       $0005     output stream handle
                    pshs      d         push stream
                    lbsr      fprintf   emit module title
                    leas      $06,s     drop args
                    ldd       $06,s     get second argument
                    pshs      d         push it
                    pshs      u         push function name
                    lbsr      EmitLabelDef emit label definition
                    leas      $04,s     drop args
                    leax      StrPshsU,pcr "pshs u" prologue line
                    pshs      x         push text
                    lbsr      EmitLine  emit prologue line
                    leas      $02,s     drop arg
                    ldd       $0015     stack-check disabled flag
                    bne       EmitProfEntry skip stkcheck call
                    ldd       $000B     next label counter
                    addd      #$0001    bump it
                    std       $000B     store back
                    std       GlbFrameLbl remember frame-size label
                    pshs      d         push label number
                    leax      StrLddD,pcr " ldd #_%d / lbsr _stkcheck"
                    pshs      x         push format
                    ldd       $0005     output stream handle
                    pshs      d         push stream
                    lbsr      fprintf   emit stack-check call
                    leas      $06,s     drop args
EmitProfEntry       ldd       $0017     profiling enabled flag
                    lbeq      EmitRet   not profiling, done
                    leax      StrLeax3,pcr "leax " opcode text
                    pshs      x         push text
                    lbsr      EmitSpacedStr emit opcode text
                    leas      $02,s     drop arg
                    ldd       $08,s     get function name
                    pshs      d         push name
                    lbsr      EmitLabelName emit the name
                    leas      $02,s     drop arg
                    leax      StrPcr2,pcr ",pcr / pshs x / leax " text
                    pshs      x         push text
                    lbsr      EmitStr   emit text line
                    leas      $02,s     drop arg
                    pshs      u         push function name again
                    lbsr      EmitLabelText emit name label
                    leas      $02,s     drop arg
                    leax      StrPcr3,pcr ",pcr ... lbsr _prof" text
                    lbra      EmitTextLine emit profiling entry

EmitFuncEpilogue    pshs      u         save frame pointer
                    ldd       $0017     profiling enabled flag
                    beq       EmitEpilogueDone not profiling, skip
                    ldd       $005E     current function label
                    pshs      d         push it
                    leax      StrPshsD,pcr "_eprof" exit block format
EmitFmtArg2         pshs      x         push format
                    ldd       $0005     output stream handle
                    pshs      d         push stream
                    lbsr      fprintf   emit profile-exit code
                    leas      $06,s     drop args
EmitEpilogueDone    puls      pc,u      return

EmitFrameEqu        pshs      u         save frame pointer
                    ldd       $0015     stack-check disabled flag
                    bne       FrameEquDone skip frame equate
                    ldd       $001B     current frame offset
                    subd      $0013     minus base offset
                    addd      #$FFC0    adjust frame size
                    pshs      d         push size
                    ldd       GlbFrameLbl frame-size label number
                    pshs      d         push it
                    leax      StrDEquD,pcr "_%d equ %d" format
                    pshs      x         push format
                    ldd       $0005     output stream handle
                    pshs      d         push stream
                    lbsr      fprintf   emit frame-size equate
                    leas      $08,s     drop args
FrameEquDone        puls      pc,u      return

EmitFcb             pshs      u         save frame pointer
                    leax      StrFcb,pcr "fcb " directive prefix
                    bra       EmitDirectiveText emit it

EmitFdb             pshs      u         save frame pointer
                    leax      StrFdb,pcr "fdb " directive prefix
EmitDirectiveText   pshs      x         push text
                    lbsr      EmitSpacedStr emit directive text
                    lbra      EmitDone  return via common tail

EmitCommentStar     pshs      u         save frame pointer
                    leax      Data5F00,pcr "* " comment prefix
EmitTextLine        pshs      x         push text
                    lbsr      EmitStr   emit comment line
                    lbra      EmitDone  return via common tail

EmitVsect           pshs      u         save frame pointer
                    ldd       $04,s     direct-page flag
                    beq       EmitVsectPlain not dp, use plain vsect
                    leax      StrVsectDp,pcr "vsect dp" keyword
                    bra       PushVsectName emit it

EmitVsectPlain      leax      StrVsect,pcr "vsect" keyword
PushVsectName       tfr       x,d       keyword pointer to D
                    pshs      d         push it
                    bra       EmitStrTail emit the directive

EmitEndsect         pshs      u         save frame pointer
                    leax      StrEndsect,pcr "endsect" keyword
PushAndEmit         pshs      x         push it
EmitStrTail         lbsr      EmitLine  emit directive
                    lbra      EmitDone  return via common tail

DumpStrings         pshs      u         save frame pointer
                    ldd       GlbStrList string list head
                    lbeq      EmitRet   empty, nothing to dump
                    ldd       GlbStrList reload list head
                    pshs      d         push it
                    lbsr      RewindBuf rewind list to first
                    leas      $02,s     drop arg
                    bra       DumpStrLoop enter dump loop

DumpStrEmit         ldd       $0005     output stream handle
                    pshs      d         push stream
                    pshs      u         push string node pointer
                    lbsr      PutByte   emit one string entry
                    leas      $04,s     drop args
DumpStrLoop         ldd       GlbStrList string list
                    pshs      d         push it
                    lbsr      GetByte   get next entry
                    leas      $02,s     drop arg
                    tfr       d,u       node pointer to U
                    cmpu      #$FFFF    end of list
                    bne       DumpStrEmit emit next string
                    ldx       GlbStrList string list head
                    ldd       $06,x     load attribute flags
                    clra                keep low byte only
                    andb      #$20      test dump-debug flag
                    beq       DumpStrFree not set, skip banner
                    leax      StrDumpstrings,pcr "dumpstrings" banner
                    pshs      x         push it
                    lbsr      PrintMsg  print debug message
                    leas      $02,s     drop arg
DumpStrFree         ldd       GlbStrList string list
                    pshs      d         push it
                    lbsr      CloseBuf  release the list
                    leas      $02,s     drop arg
                    leax      $0096,y   string list variable
                    pshs      x         push its address
                    lbsr      DeletePath clear the list pointer
                    bra       EmitDone  return via common tail

FlushStringPool     pshs      u,d       save frame pointer and temp
                    ldd       $0364,y   saved count value
                    beq       FlushDefaultCount zero, default to one
                    ldd       $0364,y   reload count
                    bra       FlushStrDo use it

FlushDefaultCount   ldd       #$0001    default count of one
FlushStrDo          std       ,s        save on stack
                    ldd       GlbStrList string list head
                    beq       FlushStrCall empty, skip free
                    ldd       GlbStrList reload list head
                    pshs      d         push it
                    lbsr      CloseBuf  release the list
                    leas      $02,s     drop arg
                    leax      $0096,y   string list variable
                    pshs      x         push its address
                    lbsr      DeletePath clear the list pointer
                    leas      $02,s     drop arg
FlushStrCall        ldd       ,s        reload count
                    pshs      d         push it
                    lbsr      DoExit    flush/free with count
                    leas      $02,s     drop arg
EmitDone            leas      $02,s     drop temp slot
EmitRet             puls      pc,u      restore frame and return

