                    fcb       $0D,$0D,$00
StrFcb              fcc       /fcb /
                    fcb       $00
StrFdb              fcc       /fdb /
                    fcb       $00
Data5F00            fcb       $2A,$20
                    fcb       $00
StrVsectDp          fcc       /vsect dp/
                    fcb       $00
StrVsect            fcc       /vsect/
                    fcb       $00
StrEndsect          fcc       /endsect/
                    fcb       $00
StrDumpstrings      fcc       /dumpstrings/
                    fcb       $00
ParseStatement2     pshs      u         save frame pointer
                    leas      -$15,s    allocate line buffer
                    lbsr      SkipSpaces fetch next token
                    ldb       $0045     current token type
                    sex                 extend to word
                    cmpd      #$FFFF    end-of-input token
                    bne       GotToken  got a real token
                    ldd       #$FFFF    end-of-input sentinel
                    std       $003F     flag end of compilation
                    leas      $15,s     release line buffer
                    puls      pc,u      return

GotToken            ldd       $004A     current line position
                    addd      #$FFFF    back up one
                    std       $0043     save statement start
                    ldd       $0007     current input pointer
                    std       GlbSrcLine remember it
                    bra       StmtDispatchLoop enter dispatch loop

SkipBadToken        leax      MsgBadChar,pcr error message string
                    pshs      x         push it
                    lbsr      BuildMsgBuf print it
                    leas      $02,s     drop arg
                    lbsr      NextChar  advance past token
                    ldd       $004A     current position
                    std       $0043     update statement start
StmtDispatchLoop    ldb       $0045     current token type
                    sex                 extend to word
                    leax      $00BA,y   keyword dispatch table
                    leax      d,x       index by token type
                    ldb       ,x        read operator class from table
                    sex                 sign-extend class byte to D
                    std       $003F     save operator code
                    beq       SkipBadToken class zero means skip this token
                    ldb       $0045     reload the lookahead char
                    sex                 sign-extend to D
                    leax      $013a,y   point at attribute table
                    leax      d,x       index by char
                    ldb       ,x        read attribute byte
                    sex                 sign-extend to D
                    std       $0041     save attribute / precedence
                    ldx       $003F     X = operator code
                    lbra      ClassifyPrimaryTok dispatch on operator code

ClassifyNameTok     leax      $0a,s     point at local scratch buffer
                    pshs      x         pass scratch pointer
                    lbsr      ScanIdentifier look up the symbol
                    leas      $02,s     drop argument
                    leax      $0a,s     point at scratch again
                    pshs      x         pass pointer
                    lbsr      LookupOrAddSym resolve symbol entry
                    leas      $02,s     drop argument
                    tfr       d,u       U = symbol entry pointer
                    ldd       ,u        load entry type field
                    std       $003F     save as op code
                    cmpd      #$0033    is it an enum constant
                    bne       PlainNameTok no, treat as plain name
                    ldd       $08,u     load enum value
                    std       $0041     save as attribute
                    cmpd      #$003B    is value the sentinel $3B
                    lbne      ClassifyDone no, done
                    ldd       #$003B    force op code $3B
                    std       $003F     store op code
                    ldd       #$000E    attribute $0E
                    std       $0041     store attribute
                    lbra      ClassifyDone done

PlainNameTok        ldd       #$0034    op code = name token $34
                    std       $003F     store op code
                    stu       $0041     attribute = symbol pointer
                    lbra      ClassifyDone done

ClassifyNumConst    leax      ,s        point at stack slot
                    pshs      x         pass pointer
                    ldd       #$0001    request size 1
                    pshs      d         push size argument
                    lbsr      ParseNumber allocate work node
                    leas      $04,s     drop arguments
                    std       $13,s     save node pointer
                    bra       NumConstBuild build the constant node

NumConstRealign     leas      -$15,x    realign stack after node alloc
NumConstBuild       leax      ,s        X = stack frame base
                    stx       $08,s     save value pointer
                    ldx       $13,s     X = numeric kind
                    bra       NumKindDispatch dispatch on kind

IntConstTok         ldd       [$08,s]   load the integer value
                    bra       EmitIntConst emit int constant

LongConstTok        ldd       #$0004    request 4-byte buffer
                    pshs      d         push size argument
                    lbsr      AllocMem  allocate constant storage
                    leas      $02,s     drop argument
                    tfr       d,u       U = storage pointer
                    leax      ,u        X = storage pointer
                    pshs      x         pass destination
                    ldx       $0a,s     X = source value
                    lbsr      StoreInt32 copy long value
                    stu       $0041     attribute = value pointer
                    ldd       #$004A    op code = long constant $4A
                    bra       EmitOpDone2 emit op code

FloatConstTok       ldd       #$0008    request 8-byte buffer
                    pshs      d         push size argument
                    lbsr      AllocMem  allocate constant storage
                    leas      $02,s     drop argument
                    tfr       d,u       U = storage pointer
                    leax      ,u        X = storage pointer
                    pshs      x         pass destination
                    ldx       $0a,s     X = source value
                    lbsr      CopyFloat copy double value
                    stu       $0041     attribute = value pointer
                    ldd       #$004B    op code = float constant $4B
                    bra       EmitOpDone2 emit op code

BadConstTok         leax      MsgConstOverflow,pcr point at error message text
                    pshs      x         pass string pointer
                    lbsr      BuildMsgBuf report the message
                    leas      $02,s     drop argument
                    ldd       #$0001    default attribute 1
EmitIntConst        std       $0041     save attribute
                    ldd       #$0036    op code = int constant $36
EmitOpDone2         std       $003F     save op code
                    lbra      ClassifyDone done

NumKindDispatch     cmpx      #$0001    kind 1 = int
                    beq       IntConstTok handle int constant
                    cmpx      #$0008    kind 8 = long
                    beq       LongConstTok handle long constant
                    cmpx      #$0006    kind 6 = double
                    beq       FloatConstTok handle float constant
                    bra       BadConstTok unknown kind

IntNumberTok        lbsr      ParseCharConst parse numeric literal
                    ldd       #$0036    op code = int constant $36
                    bra       EmitConstDone emit op code

StringConstTok      lbsr      ParseStringConst parse string literal
                    ldd       #$0037    op code = string constant $37
EmitConstDone       std       $003F     save op code
                    lbra      ClassifyDone done

ClassifyOperatorTok lbsr      NextChar  consume the token character
                    ldx       $003F     X = operator code
                    lbra      ClassifyCompoundOp recognize compound operator

DotNumberTok        ldb       $0045     lookahead char
                    sex                 sign-extend to D
                    leax      $00BA,y   point at class table
                    leax      d,x       index by char
                    ldb       ,x        read class of lookahead
                    cmpb      #$6b      is it a digit class
                    lbne      ClassifyDone no, done
                    leax      ,s        point at stack slot
                    pshs      x         pass pointer
                    ldd       #$0006    request size 6
                    pshs      d         push size argument
                    lbsr      ParseNumber allocate work node
                    leas      $04,s     drop arguments
                    std       $13,s     save node pointer
                    leax      $15,s     X = node pointer plus frame
                    lbra      NumConstRealign build float constant node

AmpOpTok            ldb       $0045     lookahead char
                    sex                 sign-extend to D
                    tfr       d,x       X = lookahead char
                    bra       AmpDispatch dispatch ampersand variants

LogAndTok           ldd       #$0047    op code = logical and $47
                    std       $003F     save op code
                    lbsr      NextChar  consume second ampersand
                    ldd       #$0005    attribute $05
                    bra       SetAttrDone store attribute and finish

AndAssignTok        ldd       #$00A7    op code = and-assign $A7
                    std       $003F     save op code
                    ldd       #$0002    attribute $02
                    lbra      EmitOpConsume consume = and finish

AmpDispatch         cmpx      #$0026    next char is ampersand
                    beq       LogAndTok logical and
                    cmpx      #$003D    next char is equals
                    beq       AndAssignTok and-assign
                    lbra      ClassifyDone plain ampersand, done

EqualEqualTok       ldb       $0045     lookahead char
                    cmpb      #$3d      is it equals
                    lbne      ClassifyDone no, plain token
                    ldd       #$005A    op code = equality $5A
                    std       $003F     save op code
                    ldd       #$0009    attribute $09
                    lbra      EmitOpConsume consume = and finish

PipeOpTok           ldb       $0045     lookahead char
                    sex                 sign-extend to D
                    tfr       d,x       X = lookahead char
                    bra       PipeDispatch dispatch pipe variants

LogOrTok            ldd       #$0048    op code = logical or $48
                    std       $003F     save op code
                    lbsr      NextChar  consume second pipe
                    ldd       #$0004    attribute $04
                    bra       SetAttrDone store attribute and finish

OrAssignTok         ldd       #$00A8    op code = or-assign $A8
EmitAssignOp        std       $003F     save op code
                    lbsr      NextChar  consume equals
                    ldd       #$0002    attribute $02
SetAttrDone         std       $0041     save attribute
                    lbra      ClassifyDone done

PipeDispatch        cmpx      #$007C    next char is pipe
                    beq       LogOrTok  logical or
                    cmpx      #$003D    next char is equals
                    beq       OrAssignTok or-assign
                    lbra      ClassifyDone plain pipe, done

NotEqualTok         ldb       $0045     lookahead char
                    cmpb      #$3d      is it equals
                    lbne      ClassifyDone no, plain token
                    ldd       #$005B    op code = not-equal $5B
                    std       $003F     save op code
                    lbsr      NextChar  consume equals
                    ldd       #$0009    attribute $09
                    bra       SetAttrDone store attribute and finish

StarAssignTok       ldb       $0045     lookahead char
                    cmpb      #$3d      is it equals
                    lbne      ClassifyDone no, plain token
                    ldd       #$00A2    op code = compound assign $A2
                    bra       EmitAssignOp emit assign op

AssignFromBinaryTok ldb       $0045     lookahead char
                    cmpb      #$3d      is it equals
                    lbne      ClassifyDone no, plain token
                    ldd       $003F     current base op code
                    addd      #$0050    form assign variant
                    lbra      EmitAssignOp emit assign op

LessOpTok           ldb       $0045     lookahead char
                    sex                 sign-extend to D
                    tfr       d,x       X = lookahead char
                    bra       LessDispatch dispatch less-than variants

ShiftLeftTok        ldd       #$0056    op code = shift left $56
                    std       $003F     save op code
                    ldd       #$000B    attribute $0B
                    std       $0041     save attribute
                    lbsr      NextChar  consume second less-than
                    ldb       $0045     lookahead char
                    cmpb      #$3d      is it equals
                    lbne      ClassifyDone no, plain shift left
                    ldd       #$00A6    op code = shift-left-assign $A6
                    std       $003F     save op code
                    ldd       #$0002    attribute $02
                    lbra      EmitOpConsume consume = and finish

LessEqTok           ldd       #$005C    op code = less-or-equal $5C
                    std       $003F     save op code
                    ldd       #$000A    attribute $0A
                    lbra      EmitOpConsume consume = and finish

LessDispatch        cmpx      #$003C    next char is less-than
                    beq       ShiftLeftTok shift left
                    cmpx      #$003D    next char is equals
                    beq       LessEqTok less-or-equal
                    lbra      ClassifyDone plain less-than, done

GreaterOpTok        ldb       $0045     lookahead char
                    sex                 sign-extend to D
                    tfr       d,x       X = lookahead char
                    bra       GreaterDispatch dispatch greater-than variants

ShiftRightTok       ldd       #$0055    op code = shift right $55
                    std       $003F     save op code
                    ldd       #$000B    attribute $0B
                    std       $0041     save attribute
                    lbsr      NextChar  consume second greater-than
                    ldb       $0045     lookahead char
                    cmpb      #$3d      is it equals
                    lbne      ClassifyDone no, plain shift right
                    ldd       #$00A5    op code = shift-right-assign $A5
                    std       $003F     save op code
                    ldd       #$0002    attribute $02
                    lbra      EmitOpConsume consume = and finish

GreaterEqTok        ldd       #$005E    op code = greater-or-equal $5E
                    std       $003F     save op code
                    ldd       #$000A    attribute $0A
                    lbra      EmitOpConsume consume = and finish

GreaterDispatch     cmpx      #$003E    next char is greater-than
                    beq       ShiftRightTok shift right
                    cmpx      #$003D    next char is equals
                    beq       GreaterEqTok greater-or-equal
                    lbra      ClassifyDone plain greater-than, done

PlusOpTok           ldb       $0045     lookahead char
                    sex                 sign-extend to D
                    tfr       d,x       X = lookahead char
                    bra       PlusDispatch dispatch plus variants

IncrementTok        ldd       #$003C    op code = increment $3C
                    std       $003F     save op code
                    ldd       #$000E    attribute $0E
                    bra       EmitOpConsume consume + and finish

PlusAssignTok       ldd       #$00A0    op code = plus-assign $A0
                    std       $003F     save op code
                    ldd       #$0002    attribute $02
                    bra       EmitOpConsume consume = and finish

PlusDispatch        cmpx      #$002B    next char is plus
                    beq       IncrementTok increment
                    cmpx      #$003D    next char is equals
                    beq       PlusAssignTok plus-assign
                    lbra      ClassifyDone plain plus, done

MinusOpTok          ldb       $0045     lookahead char
                    sex                 sign-extend to D
                    tfr       d,x       X = lookahead char
                    bra       MinusDispatch dispatch minus variants

DecrementTok        ldd       #$003D    op code = decrement $3D
                    std       $003F     save op code
                    ldd       #$000E    attribute $0E
                    bra       EmitOpConsume consume - and finish

MinusAssignTok      ldd       #$00A1    op code = minus-assign $A1
                    std       $003F     save op code
                    ldd       #$0002    attribute $02
                    bra       EmitOpConsume consume = and finish

ArrowTok            ldd       #$0046    op code = arrow $46
                    std       $003F     save op code
                    ldd       #$000F    attribute $0F
EmitOpConsume       std       $0041     save attribute
                    lbsr      NextChar  consume the character
                    lbra      ClassifyDone done

MinusDispatch       cmpx      #$002D    next char is minus
                    beq       DecrementTok decrement
                    cmpx      #$003D    next char is equals
                    beq       MinusAssignTok minus-assign
                    cmpx      #$003E    next char is greater-than
                    beq       ArrowTok  arrow operator
                    lbra      ClassifyDone plain minus, done

ClassifyCompoundOp  cmpx      #$0045    base op dot
                    lbeq      DotNumberTok dot/number handler
                    cmpx      #$0041    base op ampersand
                    lbeq      AmpOpTok  ampersand handler
                    cmpx      #$0078    base op equals
                    lbeq      EqualEqualTok equality handler
                    cmpx      #$0058    base op pipe
                    lbeq      PipeOpTok pipe handler
                    cmpx      #$0040    base op not
                    lbeq      NotEqualTok not-equal handler
                    cmpx      #$0042    base op star
                    lbeq      StarAssignTok star-assign handler
                    cmpx      #$0053    base op slash
                    lbeq      AssignFromBinaryTok slash-assign handler
                    cmpx      #$0054    base op percent
                    lbeq      AssignFromBinaryTok percent-assign handler
                    cmpx      #$0059    base op caret
                    lbeq      AssignFromBinaryTok xor-assign handler
                    cmpx      #$005D    base op less-than
                    lbeq      LessOpTok less-than handler
                    cmpx      #$005F    base op greater-than
                    lbeq      GreaterOpTok greater-than handler
                    cmpx      #$0050    base op plus
                    lbeq      PlusOpTok plus handler
                    cmpx      #$0043    base op minus
                    lbeq      MinusOpTok minus handler
                    bra       ClassifyDone no compound form, done

ClassifyPrimaryTok  cmpx      #$006A    name-class token
                    lbeq      ClassifyNameTok classify identifier
                    cmpx      #$006B    number-class token
                    lbeq      ClassifyNumConst classify numeric constant
                    cmpx      #$0068    integer-literal token
                    lbeq      IntNumberTok parse integer literal
                    cmpx      #$0069    string-class token
                    lbeq      StringConstTok parse string literal
                    lbra      ClassifyOperatorTok else classify operator

ClassifyDone        leas      $15,s     release local frame
                    puls      pc,u      restore U and return

InstallKeywords     pshs      u         save caller U
                    ldd       #$0006    token value 6
                    pshs      d         push value
                    leax      KwDouble,pcr keyword string
                    pshs      x         push string pointer
                    lbsr      InstallKeyword register keyword
                    leas      $04,s     drop arguments
                    ldd       #$0005    token value 5
                    pshs      d         push value
                    leax      KwFloat,pcr keyword string
                    pshs      x         push string pointer
                    lbsr      InstallKeyword register keyword
                    leas      $04,s     drop arguments
                    ldd       #$001E    token value $1E
                    pshs      d         push value
                    leax      KwTypedef,pcr keyword string
                    pshs      x         push string pointer
                    lbsr      InstallKeyword register keyword
                    leas      $04,s     drop arguments
                    ldd       #$000F    token value $0F
                    pshs      d         push value
                    leax      KwStatic,pcr keyword string
                    pshs      x         push string pointer
                    lbsr      InstallKeyword register keyword
                    leas      $04,s     drop arguments
                    ldd       #$003B    token value $3B
                    pshs      d         push value
                    leax      KwSizeof,pcr keyword string
                    pshs      x         push string pointer
                    lbsr      InstallKeyword register keyword
                    leas      $04,s     drop arguments
                    ldd       #$0001    token value 1
                    pshs      d         push value
                    leax      KwInt,pcr keyword string
                    pshs      x         push string pointer
