                    leas      $04,s     drop arguments
                    ldd       #$0001    flag value 1
                    std       GlbNestDepth set install flag
                    ldd       #$0001    token value 1
                    pshs      d         push value
                    leax      KwInt2,pcr keyword string
                    pshs      x         push string pointer
                    lbsr      InstallKeyword register keyword
                    leas      $04,s     drop arguments
                    ldd       #$0005    token value 5
                    pshs      d         push value
                    leax      KwFloat2,pcr keyword string
                    pshs      x         push string pointer
                    lbsr      InstallKeyword register keyword
                    leas      $04,s     drop arguments
                    clra                clear flag high byte
                    clrb                clear flag low byte
                    std       GlbNestDepth reset install flag
                    ldd       #$0002    token value 2
                    pshs      d         push value
                    leax      KwChar,pcr keyword string
                    pshs      x         push string pointer
                    lbsr      InstallKeyword register keyword
                    leas      $04,s     drop arguments
                    ldd       #$000A    token value $0A
                    pshs      d         push value
                    leax      KwShort,pcr keyword string
                    pshs      x         push string pointer
                    lbsr      InstallKeyword register keyword
                    leas      $04,s     drop arguments
                    ldd       #$000D    token value $0D
                    pshs      d         push value
                    leax      KwAuto,pcr keyword string
                    pshs      x         push string pointer
                    lbsr      InstallKeyword register keyword
                    leas      $04,s     drop arguments
                    ldd       #$000E    token value $0E
                    pshs      d         push value
                    leax      KwExtern,pcr keyword string
                    pshs      x         push string pointer
                    lbsr      InstallKeyword register keyword
                    leas      $04,s     drop arguments
                    ldd       #$0021    token value $21
                    pshs      d         push value
                    leax      KwDirect,pcr keyword string
                    pshs      x         push string pointer
                    lbsr      InstallKeyword register keyword
                    leas      $04,s     drop arguments
                    ldd       #$0010    token value $10
                    pshs      d         push value
                    leax      KwRegister,pcr keyword string
                    pshs      x         push string pointer
                    lbsr      InstallKeyword register keyword
                    leas      $04,s     drop arguments
                    ldd       #$001D    token value = start address
                    pshs      d         push value
                    leax      KwGoto,pcr keyword string
                    pshs      x         push string pointer
                    lbsr      InstallKeyword register keyword
                    leas      $04,s     drop arguments
                    ldd       #$0012    token value $12
                    pshs      d         push value
                    leax      KwReturn,pcr keyword string
                    pshs      x         push string pointer
                    lbsr      InstallKeyword register keyword
                    leas      $04,s     drop previous keyword arguments
                    ldd       #$0013    keyword id
                    pshs      d         push id
                    leax      KwIf,pcr  keyword name pointer
                    pshs      x         push name
                    lbsr      InstallKeyword install keyword
                    leas      $04,s     drop keyword arguments
                    ldd       #$0014    keyword id
                    pshs      d         push id
                    leax      KwWhile,pcr keyword name pointer
                    pshs      x         push name
                    lbsr      InstallKeyword install keyword
                    leas      $04,s     drop keyword arguments
                    ldd       #$0015    keyword id
                    pshs      d         push id
                    leax      KwElse,pcr keyword name pointer
                    pshs      x         push name
                    lbsr      InstallKeyword install keyword
                    leas      $04,s     drop keyword arguments
                    ldd       #$0016    keyword id
                    pshs      d         push id
                    leax      KwSwitch,pcr keyword name pointer
                    pshs      x         push name
                    lbsr      InstallKeyword install keyword
                    leas      $04,s     drop keyword arguments
                    ldd       #$0017    keyword id
                    pshs      d         push id
                    leax      KwCase,pcr keyword name pointer
                    pshs      x         push name
                    lbsr      InstallKeyword install keyword
                    leas      $04,s     drop keyword arguments
                    ldd       #$0018    keyword id
                    pshs      d         push id
                    leax      KwBreak,pcr keyword name pointer
                    pshs      x         push name
                    lbsr      InstallKeyword install keyword
                    leas      $04,s     drop keyword arguments
                    ldd       #$0019    keyword id
                    pshs      d         push id
                    leax      KwContinue,pcr keyword name pointer
                    pshs      x         push name
                    lbsr      InstallKeyword install keyword
                    leas      $04,s     drop keyword arguments
                    ldd       #$001A    keyword id
                    pshs      d         push id
                    leax      KwDo,pcr  keyword name pointer
                    pshs      x         push name
                    lbsr      InstallKeyword install keyword
                    leas      $04,s     drop keyword arguments
                    ldd       #$001B    keyword id
                    pshs      d         push id
                    leax      KwDefault,pcr keyword name pointer
                    pshs      x         push name
                    lbsr      InstallKeyword install keyword
                    leas      $04,s     drop keyword arguments
                    ldd       #$001C    keyword id
                    pshs      d         push id
                    leax      KwFor,pcr keyword name pointer
                    pshs      x         push name
                    lbsr      InstallKeyword install keyword
                    leas      $04,s     drop keyword arguments
                    ldd       #$0004    keyword id
                    pshs      d         push id
                    leax      KwStruct,pcr keyword name pointer
                    pshs      x         push name
                    lbsr      InstallKeyword install keyword
                    leas      $04,s     drop keyword arguments
                    ldd       #$0003    keyword id
                    pshs      d         push id
                    leax      KwUnion,pcr keyword name pointer
                    pshs      x         push name
                    lbsr      InstallKeyword install keyword
                    leas      $04,s     drop keyword arguments
                    ldd       #$0007    keyword id
                    pshs      d         push id
                    leax      KwUnsigned,pcr keyword name pointer
                    pshs      x         push name
                    lbsr      InstallKeyword install keyword
                    leas      $04,s     drop keyword arguments
                    ldd       #$0008    keyword id
                    pshs      d         push id
                    leax      KwLong,pcr keyword name pointer
                    pshs      x         push name
                    lbsr      InstallKeyword install keyword
                    leas      $04,s     drop keyword arguments
                    leax      SymErrno,pcr special symbol name pointer
                    pshs      x         push name
                    lbsr      LookupOrAddSym lookup or add symbol
                    leas      $02,s     drop name argument
                    tfr       d,u       U = symbol node
                    ldd       #$0001    type value 1
                    std       ,u        set node type
                    ldd       #$000E    field value
                    std       $08,u     store node value
                    ldd       #$0002    field value
                    std       $02,u     set secondary field
                    leax      SymLseek,pcr second special name pointer
                    pshs      x         push name
                    lbsr      LookupOrAddSym lookup or add symbol
                    leas      $02,s     drop name argument
                    tfr       d,u       U = symbol node
                    ldd       #$0038    type value
                    std       ,u        set node type
                    ldd       #$000C    field value
                    std       $08,u     store node value
                    ldd       #$0004    field value
                    std       $02,u     set secondary field
                    puls      pc,u      return from keyword setup

ScanIdentifier      pshs      u         save U
                    ldu       $04,s     U = output buffer pointer
                    leas      -$02,s    reserve char counter local
                    ldd       #$0001    initial count of one
                    bra       ScanNameCheck enter scan loop

ScanNameStore       ldb       $0045     B = current char
                    stb       ,u+       store char into buffer
                    lbsr      NextChar  get next char
                    ldd       ,s        load running count
                    addd      #$0001    increment count
ScanNameCheck       std       ,s        save count
                    ldb       $0045     B = current char
                    sex                 sign-extend to D
                    pshs      d         push char
                    bsr       IsIdentChar is identifier char
                    std       ,s++      drop arg, D = result
                    beq       ScanNameEnd not ident char, stop
                    ldd       ,s        load count
                    cmpd      #$0008    reached eight chars
                    ble       ScanNameStore keep scanning if under limit
ScanNameEnd         ldd       ,s        load count
                    cmpd      #$0002    exactly two chars
                    bne       ScanNameTerm skip underscore fixup
                    ldd       #$005F    underscore character
                    stb       ,u+       append trailing underscore
ScanNameTerm        clra                clear high byte
                    clrb                clear low byte
                    stb       ,u        null-terminate name
                    bra       SkipIdentCheck skip trailing ident chars

SkipIdentLoop       lbsr      NextChar  get next char
SkipIdentCheck      ldb       $0045     B = current char
                    sex                 sign-extend to D
                    pshs      d         push char
                    bsr       IsIdentChar is identifier char
                    std       ,s++      drop arg, D = result
                    bne       SkipIdentLoop keep discarding ident chars
                    lbra      DropArgRet return via shared epilogue

IsIdentChar         pshs      u         save U
                    ldd       $04,s     D = char argument
                    leax      $00BA,y   char class table base
                    leax      d,x       index table by char
                    ldb       ,x        B = char class
                    cmpb      #$6a      letter class
                    beq       IsIdentYes matched, return true
                    ldd       $04,s     D = char argument
                    leax      $00BA,y   char class table base
                    leax      d,x       index table by char
                    ldb       ,x        B = char class
                    cmpb      #$6b      digit class
                    bne       IsIdentNo neither, return false
IsIdentYes          ldd       #$0001    return true
                    bra       IsIdentDone go to return

IsIdentNo           clra                clear high byte
                    clrb                return false
IsIdentDone         puls      pc,u      restore and return

LookupOrAddSym      pshs      u,y,x,d   save registers
                    ldd       GlbNestDepth local scope flag
                    beq       UseGlobalSyms use global table if unset
                    leax      $0484,y   local symbol hash table
                    bra       SymSearchInit skip global table

UseGlobalSyms       leax      $0384,y   global symbol hash table
SymSearchInit       tfr       x,d       move table base to D
                    std       $02,s     save table base
                    ldd       $0a,s     D = name pointer argument
                    pshs      d         push name
                    lbsr      HashName  hash the name
                    leas      $02,s     drop name argument
                    aslb                hash times two
                    rola                for word-size index
                    addd      $02,s     add table base
                    std       $04,s     save bucket address
                    ldu       [$04,s]   U = first entry in bucket
                    bra       SymChainTest enter chain search

SymCompareLoop      ldb       $14,u     entry name length
                    sex                 sign-extend
                    pshs      d         push length
                    ldb       [$0C,s]   search name length
                    sex                 sign-extend
                    cmpd      ,s++      lengths equal
                    bne       SymNextEntry mismatch, next entry
                    ldd       #$0008    compare length
                    pshs      d         push length
                    pshs      u         push entry pointer
                    ldd       #$0014    name field offset
                    addd      ,s++      point at entry name
                    pshs      d         push entry name
                    ldd       $0e,s     search name pointer
                    pshs      d         push search name
                    lbsr      StrNCmp   compare names
                    leas      $06,s     drop arguments
                    std       -$02,s    save compare result
                    beq       SymFound  match found
SymNextEntry        ldu       $12,u     next entry in chain
SymChainTest        stu       -$02,s    save current entry
                    bne       SymCompareLoop continue if entry present
                    ldu       $0062     free-list head
                    beq       AllocSymNode empty, allocate new
                    ldd       $12,u     unlink node from free list
                    std       $0062     update free-list head
                    bra       InitSymNode initialise reused node

AllocSymNode        ldd       #$001C    node size
                    pshs      d         push size
                    lbsr      AllocMem  allocate node
                    leas      $02,s     drop size
                    tfr       d,u       U = new node
InitSymNode         ldd       #$0008    name length
                    pshs      d         push length
                    ldd       $0C,s     search name pointer
                    pshs      d         push name
                    pshs      u         push node pointer
                    ldd       #$0014    name field offset
                    addd      ,s++      point at node name field
                    pshs      d         push destination
                    lbsr      StrNCpy   copy name into node
                    leas      $06,s     drop arguments
                    clra                clear high byte
                    clrb                clear low byte
                    std       ,u        clear node type
                    clra                clear high byte
                    clrb                clear low byte
                    std       $08,u     clear node value
                    ldd       [$04,s]   old bucket head
                    std       $12,u     link node into chain
                    stu       [$04,s]   node becomes bucket head
                    ldd       $04,s     bucket address
                    std       $0e,u     store back-pointer
SymFound            tfr       u,d       return node pointer
                    leas      $06,s     drop locals
                    puls      pc,u      restore and return

InstallKeyword      pshs      u         save U
                    leas      -$09,s    reserve temp name buffer
                    ldd       #$0008    copy length of eight
                    pshs      d         push length
                    ldd       $0f,s     name argument
                    pshs      d         push source name
                    leax      $04,s     temp buffer address
                    pshs      x         push destination
                    lbsr      StrNCpy   copy name into buffer
                    leas      $06,s     drop arguments
                    clra                clear high byte
                    clrb                clear low byte
                    stb       $08,s     null-terminate temp name
                    leax      ,s        temp buffer address
                    pshs      x         push name
                    lbsr      LookupOrAddSym lookup or add symbol
                    leas      $02,s     drop name argument
                    tfr       d,u       U = symbol node
                    ldd       #$0033    reserved-word type
                    std       ,u        set node type
                    ldd       $0f,s     keyword id
                    std       $08,u     store id as node value
                    leas      $09,s     drop temp buffer
                    puls      pc,u      restore and return

HashName            pshs      u         save U
                    ldu       $04,s     U = name string
                    leas      -$04,s    reserve hash locals
                    clra                clear high byte
                    clrb                clear low byte
                    bra       HashLoop  enter hash loop

HashAddChar         ldd       $02,s     running hash sum
                    addd      ,s        add current char
HashLoop            std       $02,s     save sum
                    ldb       ,u+       load next char
                    sex                 sign-extend
                    std       ,s        store char
                    bne       HashAddChar continue until null
                    ldd       $02,s     final sum
                    clra                clear high byte
                    andb      #$7f      mask to bucket range
                    leas      $04,s     drop locals
                    puls      pc,u      restore and return

AllocMem            pshs      u,d       save registers
                    ldd       $06,s     requested size
                    pshs      d         push size
                    lbsr      SbrkGrow  allocate memory
                    leas      $02,s     drop size
                    std       ,s        save pointer
                    cmpd      #$FFFF    allocation failed
                    bne       TrackMemLow ok, skip error
                    leax      MsgOutOfMemory,pcr out-of-memory message
                    pshs      x         push message
                    lbsr      PrintMsg  report fatal error
                    leas      $02,s     drop message
TrackMemLow         ldd       GlbMemLow memory low watermark
                    bne       TrackMemHigh already set, skip
                    ldd       ,s        allocated pointer
                    std       GlbMemLow record low watermark
TrackMemHigh        ldd       ,s        allocated pointer
                    addd      $06,s     plus size
                    std       GlbMemHigh update high watermark
                    ldd       ,s        return pointer
DropArgRet          leas      $02,s     drop pointer local
                    puls      pc,u      restore and return

ParseNumber         pshs      u         save U
                    ldu       $06,s     U = result token pointer
                    leas      -$10,s    reserve number workspace
                    clra                clear high byte
                    clrb                clear low byte
                    std       $02,s     clear accumulator
                    leax      $08,s     workspace buffer
                    pshs      x         push buffer
                    bsr       NumBufInit call past inline data
                    fcb       $00,$00,$00,$00,$00,$00,$00,$00
NumBufInit          puls      x         X = inline buffer address
                    lbsr      CopyFloat init number accumulator
                    leax      $08,s     workspace buffer
                    stx       ,s        store buffer pointer
                    ldd       $14,s     incoming token type
                    cmpd      #$0006    already a float
                    bne       NumCheckZero not float, parse integer
                    leax      $10,s     float workspace
                    lbra      FloatFracEntry parse floating-point value

NumCheckZero        ldb       $0045     B = current char
                    cmpb      #$30      is it '0'
                    lbne      NumCheckDigit nonzero digit, decimal
                    leas      -$06,s    reserve local
                    lbsr      NextChar  get next char
                    ldb       $0045     B = char after zero
                    cmpb      #$2e      is it '.'
                    bne       NumTryHex not float prefix
                    lbsr      NextChar  consume decimal point
                    leax      $16,s     float workspace
                    lbra      FloatFracEntry parse floating-point value

NumTryHex           leax      $02,s     workspace pointer
                    pshs      x         push pointer
                    bsr       NumHexProbe call past inline data
                    fcb       $00,$00,$00,$00
NumHexProbe         puls      x         X = inline data address
                    lbsr      StoreInt32 release temporary
                    ldb       $0045     B = current char
                    cmpb      #$78      is it 'x'
                    beq       NumHexStart load current char
                    ldb       $0045     B = current char
                    cmpb      #$58      is it 'X'
                    lbne      DecNextChar not hex, treat as octal
NumHexStart         leas      -$02,s    reserve local
                    bra       HexNextChar start hex accumulation

HexDigitLoop        leax      $04,s     value pointer
                    pshs      x         push pointer
                    leax      $06,s     value pointer
                    pshs      x         push pointer
                    ldd       #$0004    shift count of four bits
                    lbsr      ShiftLeft32 accumulator shift left four
                    ldd       $02,x     high word of value
                    pshs      d         push it
                    ldd       ,x        low word of value
                    pshs      d         push it
                    ldd       $06,s     hex digit char
                    cmpd      #$0041    letter 'A' or above
                    blt       HexDigitBase numeric digit, use '0' base
                    ldd       #$0037    letter base value
                    bra       HexAddDigit add digit

HexDigitBase        ldd       #$0030    numeric digit base '0'
HexAddDigit         pshs      d         push base
                    ldd       $08,s     digit char
                    subd      ,s++      subtract base value
                    lbsr      SignExtendTo32 add digit into accumulator
                    lbsr      AddInt32  propagate result
                    lbsr      StoreInt32 release temporary
HexNextChar         lbsr      NextChar  get next char
                    ldb       $0045     B = current char
                    sex                 sign-extend
                    pshs      d         push char
                    lbsr      IsHexDigit is hex digit
                    leas      $02,s     drop argument
                    std       ,s        save result
                    bne       HexDigitLoop continue hex digits
                    leas      $02,s     drop local
                    bra       NumSuffix go check suffix

DecDigitLoop        leax      $02,s     value pointer
                    pshs      x         push pointer
                    leax      $04,s     value pointer
                    pshs      x         push pointer
                    ldd       #$0003    radix multiplier index
                    lbsr      ShiftLeft32 accumulator times radix
                    ldd       $02,x     high word of value
                    pshs      d         push it
                    ldd       ,x        low word of value
                    pshs      d         push it
                    ldb       $0045     digit char
                    sex                 sign-extend
                    addd      #$FFD0    subtract '0'
                    lbsr      SignExtendTo32 add digit into accumulator
                    lbsr      AddInt32  propagate result
                    lbsr      StoreInt32 release temporary
                    lbsr      NextChar  get next char
DecNextChar         ldb       $0045     B = current char
                    sex                 sign-extend
                    pshs      d         push char
                    lbsr      IsOctalDigit is octal or decimal digit
                    std       ,s++      drop argument, D = result
                    bne       DecDigitLoop continue digits
NumSuffix           leax      $02,s     value pointer
                    stx       ,s        store pointer
                    ldb       $0045     B = current char
                    cmpb      #$4C      is it 'L'
                    beq       NumLongSuffix long suffix
                    ldb       $0045     load current char
                    cmpb      #$6C      is it 'l'
                    bne       NumStore  no suffix, store value
NumLongSuffix       lbsr      NextChar  consume long suffix
                    leax      $16,s     long workspace
                    bra       NumLongType mark as long type

NumStore            ldd       [,s]      high word nonzero
                    bne       NumEmit   overflow, use long path
                    ldd       $04,s     computed value
                    std       ,u        store into token
                    ldd       #$0001    int type flag
                    bra       NumRet    return value

                    bra       NumEmit   go emit long

NumLongType         leas      -$16,x    adjust for long workspace
NumEmit             leax      ,u        point at token
                    pshs      x         push pointer
                    leax      $04,s     value pointer
                    lbsr      StoreInt32 release temporary
                    ldd       #$0008    long type flag
NumRet              leas      $16,s     drop workspace
                    puls      pc,u      restore and return

                    bra       NumCheckDigit retry digit dispatch

NumScanDigits       ldb       $0045     B = current char
                    sex                 sign-extend
                    pshs      d         push char
                    leax      $0a,s     digit workspace
                    pshs      x         push pointer
                    lbsr      BignumMul10AddDigit scan digit sequence
                    leas      $04,s     drop arguments
                    std       -$02,s    save result
                    bne       FracDigitOverflow nonzero, handle overflow
                    lbsr      NextChar  get next char
NumCheckDigit       ldb       $0045     B = current char
                    sex                 sign-extend
                    leax      $00BA,y   char class table base
                    leax      d,x       index by char
                    ldb       ,x        B = char class
                    cmpb      #$6b      digit class
                    beq       NumScanDigits parse digit sequence
                    ldb       $0045     B = current character
                    cmpb      #$2e      is it a decimal point
                    beq       ParseFloatFrac dot starts a float
                    ldb       $0045     reload current character
                    cmpb      #$65      is it lowercase e
                    beq       ParseFloatFrac exponent means float
                    ldb       $0045     reload current character
                    cmpb      #$45      is it uppercase E
                    lbne      CheckIntRange otherwise parse an integer literal
ParseFloatFrac      ldb       $0045     B = current character
                    cmpb      #$2e      is it a decimal point
                    bne       FloatSetExp no fraction, check exponent
                    lbsr      NextChar  consume the decimal point
                    bra       FracDigitLoop go scan fractional digits

FloatFracEntry      leas      -$10,x    set up float parse frame from X
                    bra       FracDigitLoop join fractional digit scan

AccumFracDigit      ldb       $0045     B = fraction digit char
                    sex                 sign extend to word
                    pshs      d         push digit value
                    leax      $0a,s     point at mantissa accumulator
                    pshs      x         push accumulator pointer
                    lbsr      BignumMul10AddDigit scale digit into the fraction
                    leas      $04,s     drop arguments
                    std       -$02,s    save scaled mantissa
                    beq       FracCountDigit zero result, skip count bump
FracDigitOverflow   lbsr      NextChar  consume the digit
                    lbra      ReturnZero2 mantissa overflow, return zero

FracCountDigit      lbsr      NextChar  consume the digit
                    ldd       $02,s     load fraction digit count
                    addd      #$0001    increment it
                    std       $02,s     store back
FracDigitLoop       ldb       $0045     B = current character
                    sex                 sign extend to word
                    leax      $00BA,y   point at char class table
                    leax      d,x       index by character
                    ldb       ,x        B = character class
                    cmpb      #$6b      is it a digit class
                    beq       AccumFracDigit yes, accumulate fraction digit
FloatSetExp         ldd       #$00B8    floating type tag
                    ldx       ,s        get result descriptor pointer
                    stb       $07,x     mark type as float
                    leax      $08,s     point at mantissa
                    pshs      x         push mantissa pointer
                    leax      $0a,s     point at exponent
                    pshs      x         push exponent pointer
                    lbsr      TypeOfNode normalize the float value
                    leas      $02,s     drop argument
                    lbsr      CopyFloat release temporary
                    ldb       $0045     B = current character
                    cmpb      #$45      is it uppercase E
                    beq       HaveExponent exponent follows
                    ldb       $0045     reload current character
                    cmpb      #$65      is it lowercase e
                    lbne      FinalizeDecExp no exponent, finalize sign
HaveExponent        ldd       #$0001    exponent sign = positive
                    std       $04,s     store exponent sign
                    lbsr      NextChar  consume the e or E
                    ldb       $0045     B = current character
                    cmpb      #$2b      is it a plus sign
                    bne       ExpCheckMinus not plus, check minus
                    lbsr      NextChar  consume the plus
                    bra       ExpDigitInit start exponent digits

ExpCheckMinus       ldb       $0045     B = current character
                    cmpb      #$2d      is it a minus sign
                    bne       ExpDigitInit no sign, start digits
                    lbsr      NextChar  consume the minus
                    clra                clear high byte
                    clrb                clear low byte
                    std       $04,s     mark exponent negative
ExpDigitInit        clra                clear high byte
                    clrb                clear low byte
                    std       $06,s     exponent accumulator = 0
                    bra       ExpDigitLoop test for a digit

AccumExpDigit       ldd       $06,s     load exponent so far
                    pshs      d         push it
                    ldd       #$000A    multiplier ten
                    lbsr      MulInt32  multiply exponent by ten
                    pshs      d         push product
                    ldb       $0045     B = digit char
                    sex                 sign extend
                    addd      #$FFD0    subtract ascii zero
                    addd      ,s++      add to exponent times ten
                    std       $06,s     store new exponent
                    lbsr      NextChar  consume the digit
ExpDigitLoop        ldb       $0045     B = current character
                    sex                 sign extend
                    leax      $00BA,y   point at char class table
                    leax      d,x       index by character
                    ldb       ,x        B = character class
                    cmpb      #$6b      is it a digit class
                    beq       AccumExpDigit yes, accumulate exponent digit
                    ldd       $06,s     load exponent value
                    cmpd      #$0028    compare against forty
                    lbge      ReturnZero2 exponent too large, return zero
                    ldd       $02,s     load fraction digit count
                    pshs      d         push it
                    ldd       $06,s     load exponent
                    beq       ExpPositive zero exponent, no negate
                    ldd       $08,s     load exponent magnitude
                    nega                negate high byte
                    negb                negate low byte
                    sbca      #$00      finish two's complement
                    bra       ExpCombine combine with fraction count

ExpPositive         ldd       $08,s     load exponent value
ExpCombine          addd      ,s++      add fraction digit count
                    std       $02,s     store total decimal exponent
FinalizeDecExp      ldd       $02,s     load decimal exponent
                    bge       ExpSignZero non-negative, sign zero
                    ldd       $02,s     reload exponent
                    nega                negate high byte
                    negb                negate low byte
                    sbca      #$00      finish two's complement
                    std       $02,s     store magnitude
                    ldd       #$0001    sign flag = negative
                    bra       ApplyDecExp store sign

ExpSignZero         clra                clear high byte
                    clrb                clear low byte
ApplyDecExp         std       $04,s     store exponent sign
                    leax      ,u        point at result value
                    pshs      x         push it
                    ldd       $06,s     load exponent magnitude
                    pshs      d         push it
                    ldd       $06,s     load exponent sign
                    pshs      d         push it
                    leax      $0e,s     point at mantissa argument
                    lbsr      PushFloat prepare the operand
                    lbsr      ScaleFloatByExp scale mantissa by ten to the exponent
                    leas      $0C,s     drop arguments
                    lbsr      CopyFloat release temporary
                    ldd       #$0006    type code = double
                    lbra      ReturnValue return the float result

CheckIntRange       ldb       [,s]      high byte of integer value
                    bne       ReturnZero2 nonzero, overflow
                    ldx       ,s        get value pointer
                    ldb       $01,x     second byte
                    bne       ReturnZero2 nonzero, overflow
                    ldx       ,s        get value pointer
                    ldb       $02,x     third byte
                    beq       CheckLongSuffix fits, check for suffix
ReturnZero2         clra                clear high byte
                    clrb                clear low byte
                    lbra      ReturnValue return zero-typed value

CheckLongSuffix     ldb       $0045     B = current character
                    cmpb      #$6C      is it lowercase l
                    beq       LongSuffix long suffix present
                    ldb       $0045     reload current character
                    cmpb      #$4C      is it uppercase L
                    bne       CheckIntMagnitude no suffix, check magnitude
LongSuffix          leas      -$02,s    reserve temp word
                    lbsr      NextChar  consume the l or L
                    bra       BuildLong build a long constant

LongEntry           leas      -$12,x    set up long frame from X
BuildLong           ldd       $02,s     load low value
                    addd      #$0003    advance to value slot
                    std       ,s        save destination offset
                    leax      ,u        point at result
                    pshs      x         push it
                    ldx       $02,s     value pointer
                    lbsr      StoreInt32 store the long value
                    ldd       #$0008    type code = long
                    bra       ReturnLong return the long

CheckIntMagnitude   ldx       ,s        value pointer
                    ldb       $03,x     high word byte
                    bne       ForceLong nonzero, force long
                    ldx       ,s        value pointer
                    ldb       $04,x     high word byte
                    beq       BuildInt  fits in an int
ForceLong           leax      $10,s     point at frame
                    bra       LongEntry build a long constant

BuildInt            leas      -$02,s    reserve temp word
                    ldd       $02,s     load low value
                    addd      #$0005    advance to value slot
                    std       ,s        save destination offset
                    ldd       [,s]      load int value
                    std       ,u        store into result
                    ldd       #$0001    type code = int
ReturnLong          leas      $12,s     clean up long frame
                    puls      pc,u      return

ReturnValue         leas      $10,s     clean up float frame
                    puls      pc,u      return

ScaleFloatByExp     pshs      u         save frame pointer
                    ldd       $0C,s     load exponent
                    cmpd      #$0009    more than nine
                    ble       ScaleFinalStep small exponent, single step
                    leax      $04,s     point at value
                    pshs      x         push it
                    ldd       $10,s     push exponent copy
                    pshs      d         push it
                    ldd       $10,s     push exponent copy
                    pshs      d         push it
                    ldd       #$000A    base ten
                    lbsr      SignedDivide32 compute exponent minus nine
                    addd      #$0009    scale factor nine
                    pshs      d         push it
                    leax      $0a,s     point at operand
                    lbsr      PushFloat prepare the operand
                    bsr       MulByPow10 apply the power of ten
                    leas      $0C,s     drop arguments
                    lbsr      CopyFloat release temporary
ScaleFinalStep      ldd       $0e,s     load remaining exponent
                    pshs      d         push it
                    ldd       $0e,s     load remaining exponent
                    pshs      d         push it
                    ldd       #$000A    base ten
                    lbsr      SignedDivSetup reduce the exponent
                    pshs      d         push it
                    leax      $08,s     point at operand
                    lbsr      PushFloat prepare the operand
                    bsr       MulByPow10 apply the power of ten
                    leas      $0C,s     drop arguments
                    puls      pc,u      return

MulByPow10          pshs      u         save frame pointer
                    ldd       $0C,s     load power count
                    beq       Pow10Copy zero power, copy as is
                    leas      -$02,s    reserve temp word
                    leax      $01BA,y   point at power-of-ten table
                    stx       ,s        save table base
                    ldd       ,s        load table base
                    pshs      d         push it
                    ldd       $10,s     load power index
                    aslb                shift index left
                    rola                rotate into high byte
                    aslb                shift index left
                    rola                rotate into high byte
                    aslb                shift index left
                    rola                rotate into high byte
                    addd      ,s++      table entry address
                    std       ,s        save entry pointer
                    ldd       $10,s     load power index
                    beq       Pow10Alt  zero, use multiply variant
                    leax      $06,s     point at operand
                    lbsr      PushFloat prepare the operand
                    ldx       $08,s     table entry pointer
                    lbsr      UnaryOpTypeA multiply value by ten to the n
                    bra       Pow10Store store the scaled result

Pow10Alt            leax      $06,s     point at operand
                    lbsr      PushFloat prepare the operand
                    ldx       $08,s     table entry pointer
                    lbsr      UnaryOpTypeB alternate scale by ten to the n
Pow10Store          leau      $0358,y   point at work buffer
                    pshs      u         push it
                    lbsr      CopyFloat release temporary
                    lbra      EscReturn return the scaled value

Pow10Copy           leax      $04,s     point at value
                    leau      $0358,y   point at work buffer
                    pshs      u         push it
                    lbsr      CopyFloat release temporary
                    puls      pc,u      return

ParseCharConst      pshs      u         save frame pointer
                    lbsr      NextChar  get next character
                    ldb       $0045     B = current character
                    cmpb      #$5C      is it a backslash
                    bne       CharPlain not an escape
                    lbsr      ParseEscape parse the escape sequence
                    std       $0041     store character value
                    bra       CharCheckQuote check the closing quote

CharPlain           ldb       $0045     B = current character
                    sex                 widen to word
                    std       $0041     store character value
                    lbsr      NextChar  get next character
CharCheckQuote      ldb       $0045     B = current character
                    cmpb      #$27      is it a closing quote
                    lbeq      ConstDone yes, done
                    leax      MsgUntermCharConst,pcr missing-quote message
                    pshs      x         push it
                    lbsr      BuildMsgBuf report the error
                    leas      $02,s     drop argument
                    lbra      ConstReturn return

ParseStringConst    pshs      u         save frame pointer
                    ldx       GlbPassMode load pass mode flag
                    bra       SelectStream select the output stream

OpenStringFile      ldd       GlbStrList is the string file open
                    bne       StringFileReady already open
                    leax      StrModeWplus,pcr open-mode string
                    pshs      x         push it
                    leax      $0096,y   string file name
                    pshs      x         push it
                    lbsr      BuildOperand2 open the string file
                    leas      $04,s     drop arguments
                    std       GlbStrList save the file handle
                    bne       StringFileReady opened ok
                    leax      MsgCantOpenStrings,pcr cannot-open message
                    pshs      x         push it
                    lbsr      PrintMsg  fatal error
                    leas      $02,s     drop argument
StringFileReady     ldd       GlbStrList load string file handle
                    bra       SetOutStream set the output stream

UseStdout           ldd       $0005     use the standard stream
SetOutStream        std       $0064     record the output file
                    bra       EmitStringBody emit the string body

SelectStream        stx       -$02,s    save mode value
                    beq       OpenStringFile mode zero uses string file
                    cmpx      #$0002    compare mode two
                    lbeq      OpenStringFile mode two uses string file
                    cmpx      #$0001    compare mode one
                    beq       UseStdout mode one uses stdout
EmitStringBody      clra                clear high byte
                    clrb                clear low byte
                    std       $0060     reset character count
                    ldd       GlbPassMode load pass mode flag
                    cmpd      #$0001    is it mode one
                    lbeq      StringAdvance skip label emission
                    ldd       $000B     load string counter
                    addd      #$0001    increment it
                    std       $000B     store new count
                    std       $0041     save as label number
                    pshs      d         push it
                    ldd       #$005F    underscore prefix character
                    pshs      d         push it
                    leax      FmtCharLabel,pcr string label format
                    pshs      x         push it
                    ldd       $0064     output file
                    pshs      d         push it
                    lbsr      fprintf   emit the string label
                    leas      $08,s     drop arguments
                    bra       StringAdvance get the first character

StringCharLoop      leax      $0584,y   point at string buffer limit
                    pshs      x         push it
                    ldd       $004A     current buffer position
                    subd      ,s++      reached the limit
                    bne       StringNextChar room remains
                    leax      MsgUntermString,pcr string-too-long message
                    pshs      x         push it
                    lbsr      BuildMsgBuf report the error
                    leas      $02,s     drop argument
                    bra       StringTerminate terminate the string

StringNextChar      ldb       $0045     B = current character
                    cmpb      #$5C      is it a backslash
                    bne       StringPlainChar not an escape
                    lbsr      ParseEscape parse the escape sequence
                    pshs      d         push character value
                    bsr       EmitStringByte emit the character
                    leas      $02,s     drop argument
                    bra       StringCheckClose check for closing quote

StringPlainChar     ldb       $0045     B = current character
                    sex                 widen to word
                    pshs      d         push character value
                    bsr       EmitStringByte emit the character
                    leas      $02,s     drop argument
StringAdvance       lbsr      NextChar  get next character
StringCheckClose    ldb       $0045     B = current character
                    cmpb      #$22      is it a closing quote
                    bne       StringCharLoop no, keep scanning
StringTerminate     clra                clear high byte
                    clrb                clear low byte
                    pshs      d         push null terminator
                    bsr       EmitStringByte emit the terminating null
                    leas      $02,s     drop argument
                    ldd       $0064     output file
                    pshs      d         push it
                    ldd       #$000D    carriage return
                    pshs      d         push it
                    lbsr      PutByte   write end of line
                    leas      $04,s     drop arguments
                    clra                clear high byte
                    clrb                clear low byte
                    std       $003D     reset line byte count
ConstDone           lbsr      NextChar  get next character
ConstReturn         puls      pc,u      restore frame and return

EmitStringByte      pshs      u         save frame pointer
                    ldd       $003D     bytes on current line
                    bne       ByteCheckPrintable mid line, no label
                    leax      AsmFccOpen,pcr data-line label format
                    pshs      x         push it
                    ldd       $0064     output file
                    pshs      d         push it
                    lbsr      fprintf   emit the line label
                    leas      $04,s     drop arguments
ByteCheckPrintable  ldd       $04,s     load the character
                    cmpd      #$0020    below space
                    blt       EmitByteNumeric emit as a number
                    ldd       $04,s     reload the character
                    cmpd      #$0022    is it a quote
                    bne       EmitBytePrintable printable, emit as text
EmitByteNumeric     ldd       $04,s     load the character
                    pshs      d         push it
                    leax      AsmFcbHex,pcr numeric byte format
                    pshs      x         push it
                    ldd       $0064     output file
                    pshs      d         push it
                    lbsr      fprintf   emit the numeric byte
                    leas      $06,s     drop arguments
                    bra       ResetLine start a new line

EmitBytePrintable   ldd       $0064     output file
                    pshs      d         push it
                    ldd       $06,s     the character
                    pshs      d         push it
                    lbsr      PutByte   write the character
                    leas      $04,s     drop arguments
                    ldd       $003D     bytes on line
                    addd      #$0001    increment count
                    std       $003D     store back
                    subd      #$0001    recover the count
                    cmpd      #$004B    reached seventy-five columns
                    blt       BumpCharCount line not full
                    leax      AsmCloseQuote,pcr end-of-line format
                    pshs      x         push it
                    ldd       $0064     output file
                    pshs      d         push it
                    lbsr      fprintf   close the data line
                    leas      $04,s     drop arguments
ResetLine           clra                clear high byte
                    clrb                clear low byte
                    std       $003D     reset line byte count
BumpCharCount       ldd       $0060     total character count
                    addd      #$0001    increment it
                    std       $0060     store back
                    puls      pc,u      return

EmitCharDecimal     pshs      u         save frame pointer
                    ldd       $04,s     the character value
                    pshs      d         push it
                    leax      AsmRzb,pcr decimal format string
                    pshs      x         push it
                    ldd       $0064     output file
                    pshs      d         push it
                    lbsr      fprintf   emit char as decimal
                    leas      $06,s     drop arguments
                    puls      pc,u      return

ParseEscape         pshs      u,d       save frame and value
                    lbsr      NextChar  consume the backslash
                    ldb       $0045     B = escape character
                    sex                 widen to word
                    tfr       d,u       U = escape character
                    lbsr      NextChar  get next character
                    leax      ,u        X = escape character
                    bra       DispatchEscape dispatch on the escape char

EscNewline          ldd       #$000A    newline escape value
                    lbra      EscReturn return escape value

EscTab              ldd       #$0009    tab escape value
                    lbra      EscReturn return escape value

EscBackspace        ldd       #$0008    backspace escape value
                    lbra      EscReturn return escape value

EscVtab             ldd       #$000B    vertical-tab escape value
                    lbra      EscReturn return computed escape value

EscCarriageRet      ldd       #$000D    escape value carriage return $0D
                    lbra      EscReturn return escape value

EscFormFeed         ldd       #$000C    escape value form feed $0C
                    lbra      EscReturn return escape value

EscSpace            ldd       #$0020    escape value space $20
                    lbra      EscReturn return escape value

DispatchEscape      cmpx      #$006E    is escape letter n
                    beq       EscCarriageRet yes map to carriage return
                    cmpx      #$006C    is escape letter l
                    beq       EscNewline handle l escape
                    cmpx      #$0074    is escape letter t
                    beq       EscTab    handle tab escape
                    cmpx      #$0062    is escape letter b
                    beq       EscBackspace handle backspace escape
                    cmpx      #$0076    is escape letter v
                    beq       EscVtab   handle vertical tab escape
                    cmpx      #$0072    is escape letter r
                    lbeq      EscCarriageRet map to carriage return
                    cmpx      #$0066    is escape letter f
                    beq       EscFormFeed handle form feed escape
                    cmpx      #$000D    is escape carriage return
                    beq       EscSpace  map to space
                    cmpu      #$0078    is escape letter x
                    lbne      TryDecEscape no try decimal escape
                    leas      -$02,s    reserve local accumulator slot
                    clra                clear high byte
                    clrb                clear low byte
                    std       $02,s     store initial value zero
                    tfr       d,u       U holds running hex value
                    bra       HexNextDigit enter hex digit loop

HexAccumLoop        tfr       u,d       get running accumulator
                    aslb                shift accumulator left
                    rola                carry into high byte
                    aslb                shift accumulator left
                    rola                carry into high byte
                    aslb                shift accumulator left
                    rola                carry into high byte
                    aslb                shift accumulator left one nibble total
                    rola                carry into high byte
                    pshs      d         save shifted accumulator
                    ldd       $02,s     get the digit char
                    cmpd      #$0041    is it a letter A-F
                    bge       HexLetterDigit yes convert hex letter
                    ldd       $02,s     reload digit char
                    addd      #$FFD0    convert 0-9 to value
                    bra       HexAddDigit2 add digit to accumulator

HexLetterDigit      ldd       $02,s     reload digit char
                    addd      #$FFC9    convert A-F to value
HexAddDigit2        addd      ,s++      add digit to shifted accumulator
                    tfr       d,u       update running value
                    lbsr      NextChar  advance to next input char
HexNextDigit        ldb       $0045     get current input char
                    sex                 sign extend to D
                    pshs      d         pass char to validator
                    lbsr      IsHexDigit is it a hex digit
                    leas      $02,s     drop the argument
                    std       ,s        save digit-valid flag
                    beq       HexEscDone not a hex digit so finish
                    ldd       $02,s     get loop counter
                    addd      #$0001    increment digit count
                    std       $02,s     save the count
                    subd      #$0001    restore pre-increment value
                    cmpd      #$0002    done two hex digits
                    blt       HexAccumLoop no accumulate another
HexEscDone          leas      $02,s     release local slot
                    lbra      EscReturnU return value in U

TryDecEscape        cmpu      #$0064    is escape letter d
                    bne       OctEscape no do octal escape
                    clra                clear high byte
                    clrb                clear low byte
                    std       ,s        store initial value zero
                    tfr       d,u       U holds running value
                    bra       DecNextDigit enter decimal digit loop

DecAccumLoop        pshs      u         save accumulator
                    ldd       #$000A    multiplier ten
                    lbsr      MulInt32  multiply accumulator by ten
                    pshs      d         save the product
                    ldb       $0045     get current input char
                    sex                 sign extend to D
                    addd      ,s++      add char to product
                    addd      #$FFD0    convert digit subtract zero
                    tfr       d,u       update accumulator
                    lbsr      NextChar  advance to next input char
DecNextDigit        ldb       $0045     get current input char
                    sex                 sign extend to D
                    leax      $00BA,y   point to char-class table
                    leax      d,x       index by char code
                    ldb       ,x        get class byte
                    cmpb      #$6b      is it a digit class
                    lbne      EscReturnU not a digit so finish
                    ldd       ,s        get loop counter
                    addd      #$0001    increment digit count
                    std       ,s        save the count
                    subd      #$0001    restore pre-increment value
                    cmpd      #$0003    done three decimal digits
                    blt       DecAccumLoop no accumulate another
                    bra       EscReturnU return value

OctEscape           pshs      u         save escape char
                    lbsr      IsOctalDigit is char an octal digit
                    std       ,s++      save flag and drop
                    beq       EscReturnU not octal so return char as-is
                    leau      -$30,u    convert first octal digit to value
                    clra                clear high byte
                    clrb                clear low byte
                    std       ,s        zero the loop counter
                    bra       OctNextDigit enter octal digit loop

OctAccumLoop        tfr       u,d       get running accumulator
                    aslb                shift accumulator left
                    rola                carry into high byte
                    aslb                shift accumulator left
                    rola                carry into high byte
                    aslb                shift accumulator left three total
                    rola                carry into high byte
                    pshs      d         save shifted accumulator
                    ldb       $0045     get current input char
                    sex                 sign extend to D
                    addd      #$FFD0    convert digit subtract zero
                    addd      ,s++      add to shifted accumulator
                    tfr       d,u       update accumulator
                    lbsr      NextChar  advance to next input char
OctNextDigit        ldb       $0045     get current input char
                    sex                 sign extend to D
                    pshs      d         pass char to validator
                    bsr       IsOctalDigit is char an octal digit
                    std       ,s++      save flag and drop arg
                    beq       EscReturnU not octal so finish
                    ldd       ,s        get loop counter
                    addd      #$0001    increment digit count
                    std       ,s        save the count
                    subd      #$0001    restore pre-increment value
                    cmpd      #$0003    done three octal digits
                    blt       OctAccumLoop no accumulate another
EscReturnU          tfr       u,d       move result into D
EscReturn           leas      $02,s     release local slot
                    puls      pc,u      restore U and return

IsOctalDigit        pshs      u         save U
                    ldb       $05,s     get char argument
                    cmpb      #$37      above 7
                    bgt       NotValidDigit not an octal digit
                    ldb       $05,s     reload char
                    cmpb      #$30      below 0
                    blt       NotValidDigit not an octal digit
                    ldd       #$0001    valid octal digit flag
                    bra       DigitCheckDone return the flag

IsHexDigit          pshs      u         save U
                    ldb       $05,s     get char argument
                    sex                 sign extend to D
                    leax      $00BA,y   point to char-class table
                    leax      d,x       index by char code
                    ldb       ,x        get class byte
                    cmpb      #$6b      is it a digit class
                    beq       HexDigitOk yes it is a hex digit
                    ldb       $05,s     reload char
                    clra                clear high byte
                    andb      #$5f      fold to uppercase
                    stb       $05,s     store folded char
                    cmpd      #$0041    below A
                    blt       NotValidDigit not a hex letter
                    ldb       $05,s     reload folded char
                    cmpb      #$46      above F
                    bgt       NotValidDigit not a hex letter
HexDigitOk          ldb       $05,s     get the digit char
                    sex                 sign extend to D
                    bra       DigitCheckDone return it

NotValidDigit       clra                clear high byte
                    clrb                clear low byte return zero
DigitCheckDone      puls      pc,u      restore U and return

MsgBadChar          fcc       /bad ch/
MsgBadCharCont      fcc       /aracter/
                    fcb       $00
MsgConstOverflow    fcc       /constant overflow/
                    fcb       $00
KwDouble            fcc       /double/
                    fcb       $00
KwFloat             fcc       /float/
                    fcb       $00
KwTypedef           fcc       /typedef/
                    fcb       $00
KwStatic            fcc       /static/
                    fcb       $00
KwSizeof            fcc       /sizeof/
                    fcb       $00
KwInt               fcb       $69,$6E,$74
                    fcb       $00
KwInt2              fcb       $69,$6E,$74
                    fcb       $00
KwFloat2            fcc       /float/
                    fcb       $00
