                    bra       EmitListStmt emit the statement

CheckInReg          cmpx      #$0070    result type $70
                    beq       EmitListStmt yes, already usable
                    cmpx      #$0071    result type $71
                    beq       EmitListStmt yes, already usable
                    cmpx      #$006F    result type $6F
                    beq       EmitListStmt yes, already usable
                    cmpx      #$0076    result type $76
                    beq       EmitListStmt yes, already usable
                    bra       ForceToReg otherwise force into register

EmitListStmt        ldd       $06,u     result operand
                    pshs      d         push it
                    ldd       #$007A    statement opcode $7A
EmitListOp          pshs      d         push it
                    lbsr      GenNode   emit statement code
                    leas      $04,s     drop arguments
GenListLoop         ldx       $02,s     current list node
                    ldd       $0C,x     next-in-list link
                    std       $02,s     advance iterator
                    lbne      GenListItem process it if not end of list
                    ldx       $08,s     list head node
                    ldd       $0a,x     head expression
                    pshs      d         push it
                    lbsr      EvalSubtreeType evaluate final expression
                    leas      $02,s     drop argument
                    ldx       $08,s     list head node
                    ldd       $0a,x     head expression again
                    pshs      d         push it
                    ldd       #$0077    operand $77
                    pshs      d         push it
                    ldd       #$0065    opcode $65
                    pshs      d         push it
                    lbsr      GenNode   emit final operation
                    leas      $06,s     drop arguments
                    ldd       ,s        saved global pointer
                    pshs      d         push it
                    lbsr      EmitReserveSpace restore and emit
                    leas      $02,s     drop argument
                    std       $000F     restore global $000F
                    ldd       #$0070    result type $70
                    ldx       $08,s     list node
                    std       $06,x     mark result type
                    lbra      OperandRet jump to common exit

IsIndexable         pshs      u         save u
                    ldd       #$FFB8    frame size -72 bytes
                    lbsr      stkcheck  check for stack space
                    ldu       $04,s     node pointer argument
                    leas      -$02,s    allocate a local
                    ldx       $06,u     node operand type
                    bra       ClassifyNode classify the node

InspectDeref        ldd       $0a,u     left child pointer
                    std       ,s        save the child
                    tfr       d,x       child into X
                    ldx       $06,x     child operand type
                    bra       ClassifyChild classify the child

IndexTrue           ldd       #$0001    result true
                    bra       IsIndexableExit go return it

TestChildAddr       ldd       ,s        saved child
                    pshs      d         push it
                    bsr       IsConstOffset is child a constant-offset address
                    leas      $02,s     drop argument
                    bra       IsIndexableExit go return result

ClassifyChild       cmpx      #$0036    child type $36
                    beq       IndexTrue yes, indexable
                    cmpx      #$0034    child type $34
                    lbeq      IndexTrue yes, indexable
                    cmpx      #$0076    child type $76
                    lbeq      IndexTrue yes, indexable
                    cmpx      #$006F    child type $6F
                    lbeq      IndexTrue yes, indexable
                    bra       TestChildAddr else test via IsConstOffset

ClassifyNode        cmpx      #$0034    node type $34
                    lbeq      IndexTrue indexable
                    cmpx      #$0036    node type $36
                    lbeq      IndexTrue indexable
                    cmpx      #$0042    node type $42 (deref)
                    beq       InspectDeref inspect its child
                    clra                clear high byte
                    clrb                result false
IsIndexableExit     leas      $02,s     drop local
                    puls      pc,u      restore and return

IsConstOffset       pshs      u         save u
                    ldd       #$FFBA    frame size -70 bytes
                    lbsr      stkcheck  check for stack space
                    ldu       $04,s     node pointer argument
                    ldx       $06,u     node operand type
                    bra       IsConstOffsetCheck classify the node

CheckAddrOperands   ldx       $0a,u     left child pointer
                    ldd       $06,x     child operand type
                    pshs      d         push it
                    lbsr      IsFloatType is it a constant
                    std       ,s++      save result and drop
                    lbeq      PredFalse not constant, return zero
                    ldx       $0C,u     right child pointer
                    ldd       $06,x     right operand type
                    cmpd      #$0036    is base type $36
                    lbne      PredFalse no, return zero
                    bra       PredTrue  yes, return one

                    lbra      PredFalse (unreached) return zero

IsConstOffsetCheck  cmpx      #$0050    op $50 (add)
                    beq       CheckAddrOperands check operands
                    cmpx      #$0051    op $51 (subtract)
                    lbeq      CheckAddrOperands check operands
                    bra       PredFalse else return zero

IsLowRefCount       pshs      u         save u
                    ldd       #$FFC0    frame size -64 bytes
                    lbsr      stkcheck  check for stack space
                    ldx       $04,s     node pointer argument
                    ldd       $12,x     node use/size field
                    cmpd      #$0002    is it two or more
                    bge       PredFalse yes, return zero
                    ldd       #$0001    else return one
                    bra       PredExit  go return it

IsLocalAddr         pshs      u         save u
                    ldd       #$FFC0    frame size -64 bytes
                    lbsr      stkcheck  check for stack space
                    ldu       $04,s     node pointer argument
                    ldx       $06,u     node operand type
                    bra       ClassifyFrameNode classify the node

CheckFrameChild     ldx       $0a,u     left child pointer
                    ldd       $06,x     child operand type
                    cmpd      #$0041    is it type $41
                    bne       PredFalse no, return zero
PredTrue            ldd       #$0001    return one
                    puls      pc,u      restore and return

                    bra       PredFalse (unreached) return zero

ClassifyFrameNode   cmpx      #$0050    op $50
                    beq       CheckFrameChild check the child
                    cmpx      #$0051    op $51
                    lbeq      CheckFrameChild check the child
                    cmpx      #$0037    node type $37
                    beq       PredTrue  return one
                    cmpx      #$0041    node type $41
                    lbeq      PredTrue  return one
PredFalse           clra                clear high byte
                    clrb                return zero
PredExit            puls      pc,u      restore and return

FixFlaggedNode      pshs      u         save u
                    ldd       #$FFB4    frame size -76 bytes
                    lbsr      stkcheck  check for stack space
                    ldu       $04,s     node pointer argument
                    ldd       $06,u     node operand type
                    anda      #$80      test high flag bit
                    clrb                clear low byte
                    std       -$02,s    save the flag
                    beq       FixFlaggedDone bit clear, nothing to do
                    ldd       $06,u     node operand type
                    anda      #$7f      clear the flag bit
                    std       $06,u     store cleaned type back
                    pshs      u         push node
                    ldd       #$0077    operand $77
                    pshs      d         push it
                    ldd       #$0071    result type $71
                    pshs      d         push it
                    ldd       #$0075    load-immediate opcode $75
                    pshs      d         push it
                    lbsr      GenNode   emit load for flagged node
                    leas      $08,s     drop arguments
                    ldd       #$0093    new result type $93
                    std       $06,u     update node type
                    clra                clear high byte
                    clrb                value zero
                    std       $08,u     clear node field $08
FixFlaggedDone      puls      pc,u      restore and return

GenIndexedBinOp     pshs      u         save u
                    ldd       #$FFB0    frame size -80 bytes
                    lbsr      stkcheck  check for stack space
                    leas      -$04,s    allocate locals
                    ldx       $08,s     node pointer argument
                    ldd       $0C,x     right child pointer
                    std       ,s        save the right child
                    ldx       $08,s     node pointer argument
                    ldu       $0a,x     left child pointer
                    ldd       $06,u     left operand type
                    pshs      d         push it
                    lbsr      IsFloatType is left a constant
                    std       ,s++      save result and drop
                    lbeq      GenAddrFold not constant, take other path
                    ldd       ,s        right child
                    pshs      d         push it
                    lbsr      IsConstOffset is right a constant-offset address
                    std       ,s++      save result and drop
                    beq       GenPlainOperand no, plain evaluation
                    ldd       ,s        right child
                    pshs      d         push it
                    lbsr      EvalOperand generate indexed via address expr
                    bra       GenIndexedNext continue

GenPlainOperand     ldd       ,s        right child
                    pshs      d         push it
                    lbsr      EvalSubtreeType evaluate right operand
GenIndexedNext      leas      $02,s     drop argument
                    ldx       ,s        reload local
                    ldx       $06,x     get subtree operator field
                    bra       SubOpDispatch dispatch on operator

EmitLoad41          ldx       ,s        X = saved node pointer
                    ldd       $0a,x     D = node subtree field
                    pshs      d         push as emit operand
                    ldd       #$0077    code template $77
                    pshs      d         push template
                    ldd       $06,u     D = subtree operator
                    pshs      d         push operand
                    ldd       #$007F    code template $7F
                    bra       EmitLoadTail join shared emit tail

EmitLoad85          ldd       ,s        D = saved value
                    pshs      d         push operand
                    ldd       #$0077    code template $77
                    pshs      d         push template
                    ldd       #$0070    code template $70
                    pshs      d         push template
                    ldd       #$0075    code template $75
                    pshs      d         push template
                    lbsr      GenNode   emit code
                    leas      $08,s     drop four args
EmitLoadDefault     ldd       ,s        D = saved value
                    pshs      d         push operand
                    ldd       #$0077    code template $77
                    pshs      d         push template
                    ldd       $06,u     D = subtree operator
                    pshs      d         push operand
                    ldd       #$0075    code template $75
EmitLoadTail        pshs      d         push template
                    lbsr      GenNode   emit code
                    leas      $08,s     drop four args
                    lbra      StoreResultOp go store result

SubOpDispatch       cmpx      #$0041    operator $41
                    beq       EmitLoad41 yes, emit case $41
                    cmpx      #$0085    operator $85
                    beq       EmitLoad85 yes, emit case $85
                    bra       EmitLoadDefault else default emit

GenAddrFold         pshs      u         save node pointer
                    lbsr      IsIndexable test node type
                    std       ,s++      save result, pop
                    beq       TryFieldOpt false, try field path
                    ldd       ,u        D = node type field
                    cmpd      #$0002    compare to 2
                    beq       TryFieldOpt equal, field path
                    ldd       ,s        D = local operand
                    pshs      d         push arg
                    lbsr      IsConstOffset test node type
                    std       ,s++      save result, pop
                    bne       GenAddrSub true, generate address
                    ldd       ,s        reload operand
                    pshs      d         push arg
                    lbsr      IsLocalAddr test node type
                    std       ,s++      save result, pop
                    beq       TryFieldOpt false, field path
GenAddrSub          pshs      u         push node pointer
                    lbsr      EvalSubtreeType generate subexpression
                    leas      $02,s     drop arg
                    ldd       ,s        D = local operand
                    pshs      d         push arg
                    lbsr      ForceRegister emit address code
                    lbra      DropArg   go finish

TryFieldOpt         ldx       ,s        X = node pointer
                    ldd       $06,x     D = node operator
                    pshs      d         push arg
                    lbsr      IsFloatType test node type
                    std       ,s++      save result, pop
                    beq       TryAutoOpt false, try auto path
                    pshs      u         push node pointer
                    lbsr      EvalSubtreeType generate subexpression
                    leas      $02,s     drop arg
                    ldd       ,u        D = node type field
                    cmpd      #$0002    compare to 2
                    lbne      EmitAddrResult not 2, emit result
                    ldd       ,s        D = local operand
                    pshs      d         push arg
                    lbsr      CoerceToDouble emit code
                    bra       DropArg   go finish

TryAutoOpt          pshs      u         push node pointer
                    lbsr      IsLowRefCount test node type
                    std       ,s++      save result, pop
                    beq       GenPtrAddr false, try pointer path
                    ldd       ,s        D = local operand
                    pshs      d         push arg
                    lbsr      CoerceToDouble emit code
                    leas      $02,s     drop arg
                    pshs      u         push node pointer
                    lbsr      EvalSubtreeType generate subexpression
                    bra       DropArg   go finish

GenPtrAddr          pshs      u         push node pointer
                    lbsr      EvalSubtreeType generate subexpression
                    leas      $02,s     drop arg
                    ldd       ,s        D = local operand
                    pshs      d         push arg
                    lbsr      IsIndexable test node type
                    std       ,s++      save result, pop
                    bne       EmitAddrOp true, emit address op
                    ldd       $06,u     D = node operator
                    anda      #$7f      mask indirect bit
                    tfr       d,x       X = operator
                    bra       CheckSkipNorm check operator

NormalizeSub        pshs      u         push node pointer
                    lbsr      NormalizeNode normalize node
                    leas      $02,s     drop arg
                    bra       EmitAddrOp emit address op

CheckSkipNorm       cmpx      #$0095    operator $95
                    beq       EmitAddrOp skip normalize
                    cmpx      #$0094    operator $94
                    beq       EmitAddrOp skip normalize
                    bra       NormalizeSub else normalize node

EmitAddrOp          ldd       ,s        D = local operand
                    pshs      d         push arg
                    lbsr      ResolveExprType emit code
DropArg             leas      $02,s     drop arg
EmitAddrResult      pshs      u         push node pointer
                    ldd       #$0077    code template $77
                    pshs      d         push template
                    ldx       $04,s     X = node pointer
                    ldd       $06,x     D = node operator
                    pshs      d         push operand
                    ldd       #$0079    code template $79
                    pshs      d         push template
                    lbsr      GenNode   emit code
                    leas      $08,s     drop four args
                    ldx       ,s        X = node pointer
                    ldd       $06,x     D = node operator
                    lbra      StoreResult go store result

GenIndexAddr        pshs      u         save caller U
                    ldd       #$FFB0    frame size -80
                    lbsr      stkcheck  check and extend stack
                    leas      -$04,s    allocate locals
                    ldx       $08,s     X = arg node pointer
                    ldd       $0C,x     D = node field $0C
                    std       $02,s     save to local
                    ldx       $08,s     X = arg node pointer
                    ldu       $0a,x     U = subtree pointer
                    pshs      u         push subtree
                    lbsr      EvalSubtreeType generate subexpression
                    leas      $02,s     drop arg
                    ldd       $0a,s     D = saved field
                    addd      #$FFB0    adjust by -80
                    std       $0a,s     store back
                    ldd       ,u        D = subtree type field
                    cmpd      #$0007    compare to 7
                    bne       AfterIndexSel not 7, skip reg select
                    ldx       $0a,s     X = adjusted value
                    bra       RegIndexSel dispatch register

SelTmpl4E           ldd       #$004E    code template $4E
                    bra       StoreIndexTmpl store template

SelTmpl4D           ldd       #$004D    code template $4D
                    bra       StoreIndexTmpl store template

SelTmpl4C           ldd       #$004C    code template $4C
StoreIndexTmpl      std       $0a,s     save selected template
                    bra       AfterIndexSel continue

RegIndexSel         cmpx      #$0053    register code $53
                    beq       SelTmpl4E select template $4E
                    cmpx      #$0055    register code $55
                    beq       SelTmpl4D select template $4D
                    cmpx      #$0054    register code $54
                    beq       SelTmpl4C select template $4C
AfterIndexSel       ldd       $06,u     D = subtree operator
                    anda      #$7f      mask indirect bit
                    std       ,s        save operator local
                    pshs      d         push arg
                    lbsr      IsFloatType test node type
                    std       ,s++      save result, pop
                    lbeq      EmitIndirectLoad false, emit indirect load
                    ldx       $0a,s     X = index value
                    lbra      IndexOpDispatch dispatch index operator

GenConstIndex       ldx       $02,s     X = local node field
                    ldd       $06,x     D = operator
                    cmpd      #$0036    constant operator $36
                    bne       GenExprIndex not constant, expr index
                    ldd       $0a,s     D = index value
                    cmpd      #$0050    operator $50
                    bne       NegConstIndex else negate index
                    ldx       $02,s     X = node pointer
                    ldd       $08,x     D = constant value
                    bra       EmitConstIndex emit constant index

NegConstIndex       ldx       $02,s     X = node pointer
                    ldd       $08,x     D = constant value
                    nega                negate high byte
                    negb                negate low byte
                    sbca      #$00      finish two's complement
EmitConstIndex      pshs      d         push const index
                    ldd       #$0036    code template $36
                    pshs      d         push template
                    ldd       $04,s     D = operand
                    pshs      d         push operand
                    ldd       #$0074    code template $74
                    pshs      d         push template
                    lbsr      GenNode   emit code
                    leas      $08,s     drop four args
                    bra       StoreResultOp go store result

GenExprIndex        ldd       $02,s     D = local node field
                    pshs      d         push arg
                    lbsr      CoerceToDouble emit index code
                    leas      $02,s     drop arg
                    ldd       $0a,s     D = index value
                    cmpd      #$0051    operator $51
                    bne       EmitExprIndex skip complement emit
                    ldd       #$0043    code template $43
                    pshs      d         push template
                    lbsr      GenNode   emit code
                    leas      $02,s     drop arg
EmitExprIndex       ldd       #$0070    code template $70
                    pshs      d         push template
                    ldd       $02,s     D = local operand
                    pshs      d         push operand
                    ldd       #$0074    code template $74
                    pshs      d         push template
                    lbsr      GenNode   emit code
                    leas      $06,s     drop three args
StoreResultOp       ldd       $06,u     D = subtree operator
StoreResult         ldx       $08,s     X = result node
                    std       $06,x     store result operator
                    clra                zero A
                    clrb                zero B
                    ldx       $08,s     X = result node
                    std       $08,x     clear node value field
                    lbra      OperandRet return

RegIndexIndirect    leax      $04,s     X = frame base +4
                    bra       RestoreStack go restore stack

EmitAddrIndex       ldd       $06,u     D = subtree operator
                    pshs      d         push operand
                    ldd       #$007A    code template $7A
                    pshs      d         push template
                    lbsr      GenNode   emit code
                    leas      $04,s     drop two args
                    ldd       $02,s     D = local operand
                    pshs      d         push arg
                    lbsr      CoerceToDouble emit code
                    leas      $02,s     drop arg
                    ldd       $0a,s     D = index value
                    pshs      d         push operand
                    lbsr      GenNode   emit code
                    leas      $02,s     drop arg
                    lbra      EmitLoadResult emit load result

IndexOpDispatch     cmpx      #$0050    operator $50
                    lbeq      GenConstIndex constant/expr index
                    cmpx      #$0051    operator $51
                    lbeq      GenConstIndex constant/expr index
                    cmpx      #$0057    operator $57
                    beq       RegIndexIndirect register index
                    cmpx      #$0058    operator $58
                    lbeq      RegIndexIndirect register index
                    cmpx      #$0059    operator $59
                    lbeq      RegIndexIndirect register index
                    bra       EmitAddrIndex else emit address index

RestoreStack        leas      -$04,x    reset stack from X
EmitIndirectLoad    pshs      u         push node pointer
                    ldd       #$0077    code template $77
                    pshs      d         push template
                    ldd       #$0070    code template $70
                    pshs      d         push template
                    ldd       #$0075    code template $75
                    pshs      d         push template
                    lbsr      GenNode   emit code
                    leas      $08,s     drop four args
                    ldd       ,u        D = node type field
                    cmpd      #$0002    compare to 2
                    bne       AfterMoveEmit not 2, skip extra emit
                    ldd       #$0085    code template $85
                    pshs      d         push template
                    lbsr      GenNode   emit code
                    leas      $02,s     drop arg
AfterMoveEmit       ldx       $0a,s     X = index value
                    lbra      IndirectOpDispatch dispatch indirect operator

GenRegIndirect      ldd       $02,s     D = local node field
                    pshs      d         push arg
                    lbsr      IsIndexable test node type
                    std       ,s++      save result, pop
                    beq       GenMemIndirect false, memory indirect
                    ldd       $02,s     D = local node field
                    pshs      d         push arg
                    lbsr      EvalSubtreeType generate subexpression
                    leas      $02,s     drop arg
                    ldx       $0a,s     X = index value
                    bra       SpillRegDispatch dispatch spill

SpillRegAddr        ldd       $02,s     D = local node field
                    pshs      d         push arg
                    lbsr      FixFlaggedNode spill register address
                    leas      $02,s     drop arg
                    bra       EmitRegLoad emit register load

SpillRegDispatch    cmpx      #$0057    operator $57
                    beq       SpillRegAddr spill register
                    cmpx      #$0058    operator $58
                    lbeq      SpillRegAddr spill register
                    cmpx      #$0059    operator $59
                    lbeq      SpillRegAddr spill register
EmitRegLoad         ldd       $02,s     D = local node field
                    pshs      d         push operand
                    ldd       #$0077    code template $77
                    pshs      d         push template
                    ldd       #$0070    code template $70
                    pshs      d         push template
                    ldd       $10,s     D = frame operand
                    pshs      d         push operand
                    lbsr      GenNode   emit code
                    leas      $08,s     drop four args
                    lbra      EmitLoadResult emit load result

GenMemIndirect      ldd       ,s        D = local template
                    cmpd      #$0094    template $94
                    beq       EmitMemDeref skip normalize
                    ldd       ,s        reload template
                    cmpd      #$0095    template $95
                    beq       EmitMemDeref skip normalize
                    pshs      u         push node pointer
                    lbsr      NormalizeNode normalize node
                    leas      $02,s     drop arg
EmitMemDeref        ldd       #$0070    code template $70
                    pshs      d         push template
                    ldd       #$007A    code template $7A
                    pshs      d         push template
                    lbsr      GenNode   emit code
                    leas      $04,s     drop two args
                    ldd       $02,s     D = local node field
                    pshs      d         push arg
                    lbsr      CoerceToDouble emit code
                    leas      $02,s     drop arg
                    ldd       $0a,s     D = index value
                    cmpd      #$0051    operator $51
                    bne       EmitMemLoad skip template swap
                    ldd       #$004F    code template $4F
                    std       $0a,s     replace index with $4F
EmitMemLoad         ldd       #$006E    code template $6E
                    pshs      d         push template
                    ldd       #$0070    code template $70
                    pshs      d         push template
                    ldd       $0e,s     D = frame operand
                    pshs      d         push operand
                    lbsr      GenNode   emit code
                    leas      $06,s     drop three args
                    bra       EmitLoadResult emit load result

IndirectOpDispatch  cmpx      #$0057    operator $57
                    lbeq      GenRegIndirect register indirect
                    cmpx      #$0058    operator $58
                    lbeq      GenRegIndirect register indirect
                    cmpx      #$0059    operator $59
                    lbeq      GenRegIndirect register indirect
                    cmpx      #$0050    operator $50
                    lbeq      GenRegIndirect register indirect
                    cmpx      #$0051    operator $51
                    lbeq      GenRegIndirect register indirect
                    lbra      GenMemIndirect else memory indirect

EmitLoadResult      pshs      u         push node pointer
                    ldd       #$0077    code template $77
                    pshs      d         push template
                    ldd       #$0070    code template $70
                    pshs      d         push template
                    ldd       #$0079    code template $79
                    pshs      d         push template
                    lbsr      GenNode   emit code
                    leas      $08,s     drop four args
                    ldd       #$0070    result operator $70
                    ldx       $08,s     X = result node
                    std       $06,x     store result operator
                    lbra      OperandRet return

NormalizeNode       pshs      u         save caller U
                    ldd       #$FFB4    frame size -76
                    lbsr      stkcheck  check and extend stack
                    ldu       $04,s     U = arg node pointer
                    ldd       $06,u     D = node operator
                    anda      #$7f      mask indirect bit
                    cmpd      #$0034    operator $34 leaf
                    bne       NormEmitBase not leaf, process node
                    puls      pc,u      already normal, return

NormEmitBase        pshs      u         push node pointer
                    lbsr      FixFlaggedNode emit base address
                    leas      $02,s     drop arg
                    ldd       $08,u     D = node value field
                    beq       NormFinishOp zero offset, skip emit
                    ldd       $08,u     D = node value
                    pshs      d         push operand
                    ldd       #$0036    code template $36
                    pshs      d         push template
                    ldd       #$0071    code template $71
                    pshs      d         push template
                    ldd       #$0074    code template $74
                    pshs      d         push template
                    lbsr      GenNode   emit code
                    leas      $08,s     drop four args
NormFinishOp        ldd       #$0071    code template $71
                    pshs      d         push template
                    ldd       #$007A    code template $7A
                    pshs      d         push template
                    lbsr      GenNode   emit code
                    leas      $04,s     drop two args
                    ldd       #$806E    operator $6E with indirect bit
                    std       $06,u     store node operator
                    puls      pc,u      return

GenIndirection      pshs      u         save caller U
                    ldd       #$FFB0    frame size -80
                    lbsr      stkcheck  check and extend stack
                    ldu       $04,s     U = arg node pointer
                    leas      -$04,s    allocate locals
                    ldd       $0a,u     D = subtree pointer
                    std       $02,s     save to local
                    pshs      d         push arg
                    lbsr      EvalOperand process subtree
                    leas      $02,s     drop arg
                    ldx       $02,s     X = subtree pointer
                    ldd       $06,x     D = subtree operator
                    std       ,s        save operator local
                    anda      #$80      isolate indirect bit
                    clrb                clear low byte
                    std       -$02,s    save indirect flag
                    lbeq      ClassifyTop not indirect, other path
                    ldd       ,s        reload operator
                    anda      #$7f      mask indirect bit
                    std       ,s        save masked operator
                    tfr       d,x       X = operator
                    bra       OperandIsAddr dispatch operator

EmitIndConst        ldx       $02,s     X = subtree pointer
                    ldd       $08,x     D = subtree value
                    pshs      d         push operand
                    ldd       $02,s     D = local operand
                    pshs      d         push operand
                    ldd       #$0071    code template $71
                    pshs      d         push template
                    ldd       #$0075    code template $75
                    pshs      d         push template
                    lbsr      GenNode   emit code
                    leas      $08,s     drop four args
                    bra       MakePtrResult continue

IndirectionErr      leax      StrIndirection,pcr X = indirection message
                    pshs      x         push message pointer
                    ldd       $04,s     D = line/node arg
                    pshs      d         push arg
                    lbsr      InternalErr report error
                    leas      $04,s     drop two words of locals
                    bra       MakePtrResult build pointer-type result

OperandIsAddr       cmpx      #$0034    operand a constant node
                    beq       EmitIndConst yes, already address form
                    cmpx      #$0093    operand a pointer type
                    lbeq      EmitIndConst yes, already address form
                    cmpx      #$0094    operand a pointer type
                    lbeq      EmitIndConst yes, already address form
                    cmpx      #$0095    operand a pointer type
                    lbeq      EmitIndConst yes, already address form
                    bra       IndirectionErr not address, take value path

MakePtrResult       ldd       #$8093    indirect pointer result code
                    std       ,s        set top result code
                    clra                clear high byte
                    clrb                clear low byte
                    std       $08,u     clear result node value field
                    lbra      SetResultOp store op and return

ClassifyTop         ldx       ,s        load top operand op code
                    lbra      ClassifyOperand classify and convert operand

MapCode95           ldd       #$0095    map to load-form code 95
                    bra       StoreConvCode store converted code

MapCode94           ldd       #$0094    map to load-form code 94
                    bra       StoreConvCode store converted code

MapCode93           ldd       #$0093    map to load-form code 93
                    bra       StoreConvCode store converted code

SetIndirectBit      ldd       ,s        load existing operand code
                    ora       #$80      set indirect high bit
StoreConvCode       std       ,s        store converted code on stack
                    leax      $04,s     point past operand slot
                    bra       RealignStack continue with value load

ConstOperand        ldd       #$8034    indirect constant result code
                    std       ,s        store result code
                    ldx       $02,s     get operand node pointer
                    ldd       $14,x     copy operand offset field
                    std       $14,u     into result node
                    bra       LoadOperandVal load operand value

RealignStack        leas      -$04,x    realign stack pointer
LoadOperandVal      ldx       $02,s     get operand node pointer
                    ldd       $08,x     load operand value field
                    bra       StoreOperandVal store into result

RegOperand2         ldd       $02,s     operand node pointer as arg
                    pshs      d         push for emitter
                    ldd       #$0077    emit opcode 77
                    pshs      d         push arg
                    ldd       #$0071    register operand code
                    pshs      d         push arg
                    ldd       #$0075    load-into-register op
                    pshs      d         push arg
                    lbsr      GenNode   emit register load
                    leas      $08,s     drop emit args
                    ldd       #$0093    result now register code
                    std       ,s        store result code
                    clra                clear high byte
                    clrb                clear low byte
StoreOperandVal     std       $08,u     set result node value
                    bra       SetResultOp store op and return

FieldOperand        clra                clear high byte
                    clrb                clear low byte
                    std       $08,u     clear result value
                    ldx       $02,s     operand node pointer
                    ldd       $08,x     operand value field
                    std       $14,u     save as result offset
                    ldd       #$0034    constant result code
                    bra       StoreCodeExit store code and return

OperandErr          leax      StrIndirection2,pcr address of error message
                    pshs      x         push message pointer
                    pshs      u         push result node
                    lbsr      InternalErr report compiler error
                    leas      $04,s     drop args
                    ldd       #$0093    default register code
StoreCodeExit       std       ,s        store result code
                    bra       SetResultOp store op and return

ClassifyOperand     cmpx      #$006F    operand op is 6F
                    lbeq      MapCode95 map to code 95
                    cmpx      #$0076    operand op is 76
                    lbeq      MapCode94 map to code 94
                    cmpx      #$0071    operand op is 71
                    lbeq      MapCode93 map to code 93
                    cmpx      #$0093    operand already pointer 93
                    lbeq      SetIndirectBit set indirect bit
                    cmpx      #$0094    pointer 94
                    lbeq      SetIndirectBit set indirect bit
                    cmpx      #$0095    pointer 95
                    lbeq      SetIndirectBit set indirect bit
                    cmpx      #$0034    constant node
                    lbeq      ConstOperand handle constant
                    cmpx      #$0070    register node
                    lbeq      RegOperand2 handle register
                    cmpx      #$0036    field/member node
                    beq       FieldOperand handle field
                    bra       OperandErr unknown, error

SetResultOp         ldd       ,s        final result code
                    std       $06,u     set result node op
OperandRet          leas      $04,s     drop locals
                    puls      pc,u      restore u and return

GenBinOp2           pshs      u         save node pointer
                    ldd       #$FFAC    stack need
                    lbsr      stkcheck  check stack space
                    leas      -$08,s    allocate locals
                    ldx       $0C,s     get node pointer arg
                    ldu       $0a,x     get right child pointer
                    pshs      u         push child
                    lbsr      EvalSubtreeType evaluate right subtree
                    leas      $02,s     drop arg
                    ldx       $0C,s     node pointer
                    ldd       $06,x     node op code
                    std       $02,s     save in local
                    ldd       $06,u     right child op
                    std       ,s        save in local
                    pshs      d         push child op
                    lbsr      IsFloatType classify operand type
                    std       ,s++      pop result
                    beq       NormLeftMem zero: needs load
                    ldx       $02,s     node op into x
                    bra       ChkLeftOp dispatch on op

LeftIsIndexed       ldd       $0e,s     left operand code
                    cmpd      #$0070    is register form
                    bne       SetLeftCode no, just store code
                    pshs      u         push node
                    ldd       #$0077    emit opcode 77
                    pshs      d         push arg
                    ldd       $12,s     left operand value
                    pshs      d         push arg
                    ldd       #$0075    register load op
                    pshs      d         push arg
                    lbsr      GenNode   emit register load
                    leas      $08,s     drop args
                    bra       LoadRightChild continue

SetLeftCode         ldd       ,s        child code
                    std       $0e,s     store as left code
                    bra       LoadRightChild continue

ChkLeftOp           cmpx      #$003E    op is 3E
                    beq       LeftIsIndexed handle indexed left
                    cmpx      #$003F    op is 3F
                    lbeq      LeftIsIndexed handle indexed left
                    bra       SetLeftCode plain left

NormLeftMem         ldd       $0e,s     left code
                    cmpd      #$0071    is memory form
                    bne       EmitLeftLoad no, emit as-is
                    ldd       ,s        child code
                    anda      #$7f      strip indirect bit
                    cmpd      #$0034    is constant
                    beq       EmitLeftLoad yes, keep code
                    ldd       #$0070    force register form
                    std       $0e,s     update left code
EmitLeftLoad        pshs      u         push node
                    ldd       #$0077    emit opcode 77
                    pshs      d         push arg
                    ldd       $12,s     left operand value
                    pshs      d         push arg
                    ldd       #$0075    register load op
                    pshs      d         push arg
                    lbsr      GenNode   emit register load
                    leas      $08,s     drop args
                    ldd       $0e,s     left code
                    std       ,s        into child slot
LoadRightChild      ldx       $0C,s     node pointer
                    ldd       $08,x     node value field
                    std       $06,s     save right value
                    ldx       $02,s     node op
                    bra       ChkRightOp dispatch on op

NegRight            ldd       $06,s     right value
                    nega                negate high byte
                    negb                negate low byte
                    sbca      #$00      carry into high byte
                    std       $06,s     store negated
EmitRight           ldd       ,s        child code
                    cmpd      #$0070    is register form
                    bne       EmitRightMem no, memory path
                    ldd       $06,s     right value
                    pshs      d         push arg
                    ldd       #$0036    field op
                    pshs      d         push arg
                    ldd       $04,s     child operand code
                    pshs      d         push arg
                    ldd       #$0050    register add op
                    bra       EmitRightNode emit

EmitRightMem        ldd       $06,s     right value
                    pshs      d         push arg
                    ldd       #$0036    field op
                    pshs      d         push arg
                    ldd       $04,s     child operand code
                    pshs      d         push arg
                    ldd       #$0074    memory add op
EmitRightNode       pshs      d         push arg
                    lbsr      GenNode   emit add
                    leas      $08,s     drop args
                    bra       EmitCombine continue

ChkRightOp          cmpx      #$003D    op is 3D
                    beq       NegRight  negate right
                    cmpx      #$003F    op is 3F
                    lbeq      NegRight  negate right
                    bra       EmitRight no negate

EmitCombine         pshs      u         push node
                    ldd       #$0077    emit opcode 77
                    pshs      d         push arg
                    ldd       $04,s     operand value for emit
                    pshs      d         push arg
                    ldd       #$0079    combine op
                    pshs      d         push arg
                    lbsr      GenNode   emit combine
                    leas      $08,s     drop args
                    ldx       $02,s     node op
                    bra       ChkFinalOp dispatch on op

ZeroFinalize        clra                clear high byte
                    clrb                zero result value
                    bra       StoreFinalVal store result

FinalizeReg         ldd       ,s        child code
                    cmpd      #$0070    is register form
                    bne       NegFinalize no, negate path
                    ldd       $06,s     right value
                    pshs      d         push arg
                    ldd       #$0036    field op
                    pshs      d         push arg
                    ldd       #$0070    register operand
                    pshs      d         push arg
                    ldd       #$0051    register op
                    pshs      d         push arg
                    lbsr      GenNode   emit
                    leas      $08,s     drop args
                    bra       BinOpDone finish

NegFinalize         ldd       $06,s     right value
                    nega                negate high byte
                    negb                negate low byte
                    sbca      #$00      carry into high byte
StoreFinalVal       ldx       $0C,s     node pointer
                    std       $08,x     store result value
                    bra       BinOpDone finish

ChkFinalOp          cmpx      #$003E    op is 3E
                    beq       FinalizeReg indexed finalize
                    cmpx      #$003F    op is 3F
                    lbeq      FinalizeReg indexed finalize
                    bra       ZeroFinalize zero-value finalize

BinOpDone           ldd       $0e,s     left/result code
                    ldx       $0C,s     node pointer
                    std       $06,x     set node op
                    clra                clear high byte
                    clrb                clear low byte
                    std       $0066     clear global flag
                    lbra      XlatDone  common exit

ForceRegister       pshs      u         save node pointer
                    ldd       #$FFB4    stack need
                    lbsr      stkcheck  check stack space
                    ldu       $04,s     get operand node
                    pshs      u         push operand
                    bsr       EvalOperand evaluate operand
                    leas      $02,s     drop arg
                    ldd       $06,u     operand op
                    cmpd      #$0071    already register form
                    bne       EmitReg71Load no, emit load
                    ldd       $08,u     operand value
                    beq       SetReg71Ret zero: skip load
EmitReg71Load       pshs      u         push operand
                    ldd       #$0077    emit opcode 77
                    pshs      d         push arg
                    ldd       #$0071    register operand
                    pshs      d         push arg
                    ldd       #$0075    register load op
                    pshs      d         push arg
                    lbsr      GenNode   emit register load
                    leas      $08,s     drop args
SetReg71Ret         ldd       #$0071    register result code
                    std       $06,u     set operand op
                    puls      pc,u      restore and return

EvalOperand         pshs      u         save node pointer
                    ldd       #$FFAC    stack need
                    lbsr      stkcheck  check stack space
                    leas      -$08,s    allocate locals
                    ldx       $0C,s     node pointer
                    ldu       $0a,x     left child pointer
                    ldx       $0C,s     node pointer
                    ldd       $0C,x     node right value
                    std       $06,s     save in local
                    ldd       #$0071    register code
                    std       ,s        init child slot
                    ldx       $0C,s     node pointer
                    ldd       $06,x     node op
                    std       $02,s     save in local
                    tfr       d,x       op into x
                    lbra      XlatTypeDisp2 dispatch on op

CaseSubExpr         ldd       $0C,s     node pointer arg
                    pshs      d         push arg
                    lbsr      GenIndirection generate subexpression
                    lbra      XlatAfterEmit merge

CaseAssignReg       ldd       #$0071    register operand
                    pshs      d         push arg
                    ldd       $0e,s     operand value
                    pshs      d         push arg
                    lbsr      GenBinOp2 generate binary op
                    leas      $04,s     drop args
                    lbra      XlatDone  common exit

CaseUnary7F         pshs      u         push node
                    ldd       #$0077    emit opcode 77
                    pshs      d         push arg
                    ldd       #$0071    register operand
                    pshs      d         push arg
                    ldd       #$007F    unary op
                    pshs      d         push arg
                    lbsr      GenNode   emit unary op
                    leas      $08,s     drop args
                    clra                clear high byte
                    clrb                clear low byte
                    lbra      XlatStoreHi merge

CaseGenOperand      ldd       $0C,s     node pointer arg
                    pshs      d         push arg
                    lbsr      CoerceToDouble generate operand code
                    lbra      XlatAfterEmit merge

CaseStore           ldd       $06,u     left child op
                    cmpd      #$0041    is special op 41
                    beq       ChkLvalueType yes, handle
                    ldx       $06,s     right node pointer
                    ldd       $12,x     right type field
                    lbne      StoreDone non-zero: done
ChkLvalueType       ldd       $06,u     left child op
                    pshs      d         push arg
                    lbsr      IsFloatType classify operand type
                    std       ,s++      pop result
                    bne       ChkFieldStore non-zero: proceed
                    ldd       $06,u     left child op
                    cmpd      #$0041    is op 41
                    bne       MaybeSwapOperands no, other path
ChkFieldStore       ldx       $06,s     right node pointer
                    ldd       $06,x     right op
                    cmpd      #$0036    is field op
                    bne       EmitStoreGeneral no, general path
                    pshs      u         push node
                    lbsr      EvalOperand evaluate operand
                    leas      $02,s     drop arg
                    ldd       $06,u     operand op
                    std       ,s        into child slot
                    ldx       $06,s     right node pointer
                    ldd       $08,x     right value
                    lbra      XlatSaveOff merge

EmitStoreGeneral    ldd       $06,s     right value/pointer
                    pshs      d         push arg
                    lbsr      CoerceToDouble generate operand code
                    leas      $02,s     drop arg
                    pshs      u         push node
                    lbsr      EvalOperand evaluate operand
                    leas      $02,s     drop arg
                    ldd       $02,s     saved op
                    cmpd      #$0051    is register op 51
                    bne       EmitStoreOp no, skip
                    ldd       #$0043    emit opcode 43
                    pshs      d         push arg
                    lbsr      GenNode   emit
                    leas      $02,s     drop arg
EmitStoreOp         ldd       $06,u     operand op
                    pshs      d         push arg
                    ldd       #$0070    register operand
                    pshs      d         push arg
                    ldd       #$007B    store op
                    pshs      d         push arg
                    lbsr      GenNode   emit store
                    leas      $06,s     drop args
                    lbra      XlatZeroOff merge

MaybeSwapOperands   ldd       $02,s     saved op
                    cmpd      #$0050    is register op 50
                    bne       TryCommute2 no, skip swap
                    ldd       $12,u     left type field
                    ldx       $06,s     right node pointer
                    cmpd      $12,x     compare type ranks
                    bge       TryCommute2 left larger, no swap
                    leas      -$02,s    make room
                    stu       ,s        save left pointer
                    ldu       $08,s     load right pointer
                    ldd       ,s        get temp word
                    std       $08,s     swap operand slots
                    leas      $02,s     drop temp
TryCommute2         ldd       $06,s     right node/value
                    pshs      d         push arg
                    lbsr      IsIndexable process operand
                    std       ,s++      pop result
                    bne       ReEvalOperand non-zero: reeval
                    ldx       $06,s     right node pointer
                    ldd       $06,x     right op
                    pshs      d         push arg
                    lbsr      IsFloatType classify operand type
                    std       ,s++      pop result
                    bne       ReEvalOperand non-zero: reeval
StoreDone           leax      $08,s     point past locals
                    lbra      XlatRestoreB merge/exit

ReEvalOperand       pshs      u         push node
                    lbsr      EvalOperand evaluate operand
                    leas      $02,s     drop arg
                    ldd       $06,u     operand op
                    anda      #$7f      strip indirect bit
                    tfr       d,x       op into x
                    lbra      XlatTypeDisp dispatch

HandleReg50         ldd       $02,s     saved op
                    cmpd      #$0050    is register op 50
                    bne       EmitDefaultLoad no, default emit
                    ldx       $06,s     right node pointer
                    ldd       $06,x     right op
                    cmpd      #$0036    is field op
                    beq       EmitDefaultLoad yes, default emit
                    ldd       $06,s     right value
                    pshs      d         push arg
                    lbsr      CoerceToFloat generate operand code
                    leas      $02,s     drop arg
                    clra                clear high byte
                    clrb                clear low byte
                    std       $08,u     clear operand value
                    leax      $08,s     point past locals
                    lbra      XlatRestoreA merge

EmitDefaultLoad     pshs      u         push node
                    ldd       #$0077    emit opcode 77
                    pshs      d         push arg
                    ldd       #$0071    register operand
                    pshs      d         push arg
                    ldd       #$0075    register load op
                    pshs      d         push arg
                    lbsr      GenNode   emit register load
                    leas      $08,s     drop args
                    clra                clear high byte
                    clrb                clear low byte
                    std       $08,u     clear operand value
                    bra       XlatOperand merge

SaveOpMerge         ldd       $06,u     operand op
                    std       ,s        into child slot
                    bra       XlatOperand merge

XlatTypeErr         leax      StrXTranslate,pcr point to 'x translate' message
                    pshs      x         push message pointer arg
                    pshs      u         push node pointer arg
                    lbsr      InternalErr print translation error
                    leas      $04,s     drop the two args
                    bra       XlatOperand continue building node

XlatTypeDisp        cmpx      #$0070    node type $70
                    lbeq      HandleReg50 handle that type
                    cmpx      #$0034    node type $34
                    beq       EmitDefaultLoad handle that type
                    cmpx      #$0037    node type $37
                    lbeq      EmitDefaultLoad handle that type
                    cmpx      #$0093    node type $93
                    lbeq      EmitDefaultLoad handle that type
                    cmpx      #$0094    node type $94
                    lbeq      EmitDefaultLoad handle that type
                    cmpx      #$0095    node type $95
                    lbeq      EmitDefaultLoad handle that type
                    cmpx      #$0071    node type $71
                    beq       XlatOperand process as operand
                    cmpx      #$0076    node type $76 double
                    beq       SaveOpMerge handle float branch
                    cmpx      #$006F    node type $6F float
                    lbeq      SaveOpMerge handle float branch
                    bra       XlatTypeErr unknown type, error path

XlatOperand         ldx       $06,s     get operand node pointer
                    ldd       $06,x     load its type field
                    cmpd      #$0036    integer constant node
                    bne       XlatEvalOp no, evaluate operand
                    ldx       $06,s     reload node pointer
                    ldd       $08,x     load the constant value
                    bra       XlatSaveOff use it as offset

XlatEvalOp          ldd       $06,s     operand node pointer
                    pshs      d         push as arg
                    lbsr      CoerceToDouble evaluate operand subtree
                    leas      $02,s     drop arg
                    ldd       $02,s     load operand type code
                    cmpd      #$0051    type $51
                    bne       XlatEmitDeref no, skip conversion
                    clra                zero high
                    clrb                zero low
                    pshs      d         push arg
                    clra                zero high
                    clrb                zero low
                    pshs      d         push arg
                    ldd       #$0043    conversion opcode $43
                    pshs      d         push it
                    lbsr      GenNode   emit conversion
                    leas      $06,s     drop the args
                    bra       XlatEmitDeref join emit deref

XlatRestoreA        leas      -$08,x    restore stack from saved X
XlatEmitDeref       ldd       ,s        top value
                    pshs      d         push arg
                    ldd       #$0070    code $70
                    pshs      d         push it
                    ldd       #$007B    code $7B
                    pshs      d         push it
                    lbsr      GenNode   emit deref node
                    leas      $06,s     drop the args
                    ldd       #$0071    result type $71
                    std       ,s        store it
XlatZeroOff         clra                zero high
                    clrb                zero low offset
XlatSaveOff         std       $04,s     save offset value
                    ldd       $02,s     operand type code
                    cmpd      #$0050    type $50 additive
                    bne       XlatNegOff no, negate offset
                    ldd       $04,s     load offset
                    bra       XlatAddBase add base

XlatNegOff          ldd       $04,s     load offset
                    nega                negate high
                    negb                negate low
                    sbca      #$00      finish sixteen-bit negate
XlatAddBase         addd      $08,u     add base address
XlatStoreHi         ldx       $0C,s     result node pointer
                    std       $08,x     store high word
                    bra       XlatStoreLo store low word next

XlatRestoreB        leas      -$08,x    restore stack from saved X
XlatEmitNode        ldd       $0C,s     result node pointer
                    pshs      d         push it
                    lbsr      EvalSubtreeType emit node via helper
XlatAfterEmit       leas      $02,s     drop arg
                    bra       XlatDone  return

XlatTypeDisp2       cmpx      #$0042    node type $42
                    lbeq      CaseSubExpr handle that type
                    cmpx      #$0034    node type $34
                    beq       XlatDone  just return
                    cmpx      #$0076    node type $76
                    beq       XlatDone  just return
                    cmpx      #$006F    node type $6F
                    beq       XlatDone  just return
                    cmpx      #$0036    node type $36
                    beq       XlatDone  just return
                    cmpx      #$0037    node type $37
                    beq       XlatDone  just return
                    cmpx      #$003E    node type $3E
                    lbeq      CaseAssignReg handle that type
                    cmpx      #$003C    node type $3C
                    lbeq      CaseAssignReg handle that type
                    cmpx      #$003D    node type $3D
                    lbeq      CaseAssignReg handle that type
                    cmpx      #$003F    node type $3F
                    lbeq      CaseAssignReg handle that type
                    cmpx      #$0041    node type $41
                    lbeq      CaseUnary7F handle that type
                    cmpx      #$0085    node type $85
                    lbeq      CaseGenOperand handle that type
                    cmpx      #$0051    node type $51
                    lbeq      CaseStore handle that type
                    cmpx      #$0050    node type $50
                    lbeq      ChkLvalueType handle that type
                    bra       XlatEmitNode default, emit node

XlatStoreLo         ldd       ,s        offset low word
                    ldx       $0C,s     result node pointer
                    std       $06,x     store low word
XlatDone            leas      $08,s     free locals
                    puls      pc,u      return

IsFloatType         pshs      u         save frame pointer
                    ldd       #$FFC0    frame size for check
                    lbsr      stkcheck  check stack room
                    ldd       $04,s     arg node type code
                    cmpd      #$006F    is it float
                    beq       FloatTypeTrue yes, return true
                    ldd       $04,s     reload type code
                    cmpd      #$0076    is it double
                    bne       FloatTypeFalse no, return false
FloatTypeTrue       ldd       #$0001    return true
                    bra       FloatTypeRet go return

FloatTypeFalse      clra                zero high
                    clrb                zero low, return false
FloatTypeRet        puls      pc,u      return

StrTranslation      fcc       /translation/
                    fcb       $00
Data815F            fcb       $25,$78
                    fcb       $0D,$00
StrBinaryOp         fcc       /binary op./
                    fcb       $00
StrIndirection      fcc       /indirection/
                    fcb       $00
StrIndirection2     fcc       /indirection/
                    fcb       $00
StrXTranslate       fcc       /x translate/
                    fcb       $00
ParseUnaryExpr      pshs      u         save frame pointer
                    ldd       #$FFA2    frame size for check
                    lbsr      stkcheck  check stack room
                    leas      -$14,s    allocate locals
                    bra       UnaryStarLoop enter token loop

UnaryStar           leax      MsgTooManyBrackets,pcr point to indirection message
                    pshs      x         push it
                    lbsr      BuildMsgBuf print trace
                    leas      $02,s     drop arg
                    lbsr      ParseStatement2 advance to next token
UnaryStarLoop       ldd       $003F     load current token
                    cmpd      #$002A    is it star
                    beq       UnaryStar loop on indirection
                    ldd       $003F     load current token
                    cmpd      #$0029    is it close paren
                    bne       UnaryPrimary no, parse primary
                    leax      MsgFuncHdrMissing,pcr point to message
                    pshs      x         push it
                    lbsr      BuildMsgBuf print trace
                    leas      $02,s     drop arg
                    clra                zero high
                    clrb                zero low
                    pshs      d         push null arg
                    lbsr      ParseDeclarations parse enclosed group
                    leas      $02,s     drop arg
                    leax      >$0029,y  node builder base offset
                    pshs      x         push it
                    lbsr      FreeLocalSymbols build node
                    leas      $02,s     drop arg
                    lbsr      ParseStatement2 advance to next token
                    lbra      UnaryRet  return

UnaryPrimary        lbsr      ParseTypeName parse primary expression
                    std       $0a,s     save operand type
                    tfr       d,x       copy to X for classify
                    bra       UnaryClassify classify it

UnaryTypeErr        leax      MsgStorageErr1,pcr point to message
                    pshs      x         push it
                    lbsr      BuildMsgBuf print trace
                    leas      $02,s     drop arg
UnarySetDefault     ldd       #$000C    default type code $0C
                    std       $0a,s     store it
                    bra       UnaryProcess process operand

UnaryClassify       cmpx      #$0010    type $10
                    beq       UnaryTypeErr invalid type error
                    cmpx      #$000D    type $0D
                    lbeq      UnaryTypeErr invalid type error
                    stx       -$02,s    save type, test for zero
                    beq       UnarySetDefault zero, use default
UnaryProcess        leax      ,s        pointer to local
                    pshs      x         push it
                    leax      $06,s     pointer to local
                    pshs      x         push it
                    leax      $16,s     pointer to local
                    pshs      x         push it
                    lbsr      ParseDeclSpec parse subscript expression
                    leas      $06,s     drop args
                    std       $08,s     save result
                    bne       UnarySubscrLoop nonzero, keep it
                    ldd       #$0001    default to one
                    std       $08,s     store it
UnarySubscrLoop     ldd       $04,s     load type
                    std       $0C,s     save type copy
                    ldd       $08,s     load result
                    pshs      d         push it
                    leax      $0e,s     pointer to local
                    pshs      x         push it
                    leax      $06,s     pointer to local
                    pshs      x         push it
                    lbsr      ParseDeclarator emit member access
                    leas      $06,s     drop args
                    std       $06,s     save returned code
                    ldu       $02,s     load node pointer
                    bne       UnaryHaveNode nonzero, have node
                    ldd       $06,s     load result code
                    cmpd      #$0004    code $04
                    beq       UnaryNoNode ok, finish
                    ldd       $06,s     load result code
                    cmpd      #$0003    code $03
                    beq       UnaryNoNode ok, finish
                    lbsr      ErrIdentMissing otherwise report error
UnaryNoNode         leax      $14,s     pointer past locals
                    lbra      UnaryJoinB restore and tail

UnaryHaveNode       ldd       $06,s     load result code
                    clra                clear high
                    andb      #$30      mask storage class bits
                    cmpd      #$0030    both class bits set
                    bne       UnaryKeepType no, keep saved type
                    ldd       $003F     current token
                    cmpd      #$0030    token $30
                    beq       UnarySetE select code fourteen
                    ldd       $003F     current token
                    cmpd      #$0028    is it open paren
                    bne       UnarySetC no, select code twelve
UnarySetE           ldd       #$000E    code fourteen
                    bra       UnaryStoreCode store it

UnarySetC           ldd       #$000C    code twelve
                    bra       UnaryStoreCode store it

UnaryKeepType       ldd       $0a,s     keep saved type
UnaryStoreCode      std       $0e,s     store selected code
                    ldd       ,u        node existing field
                    beq       UnaryInitNode empty, init new node
                    ldd       ,s        first arg
                    pshs      d         push it
                    ldd       $08,s     result code arg
                    pshs      d         push it
                    pshs      u         push node pointer
                    lbsr      CheckTypeMatch compatibility check merge
                    leas      $06,s     drop args
                    std       -$02,s    save flag
                    lbne      UnaryDeref mismatch, do deref
                    ldd       $0e,s     selected code
                    cmpd      #$000E    is code fourteen
                    lbeq      UnaryDeref yes, do deref
                    ldd       $08,u     node current code
                    cmpd      #$000E    is code fourteen
                    beq       UnaryFillNode yes, fill node
                    ldd       $08,u     node current code
                    cmpd      #$0022    is code $22
                    beq       UnaryFillNode yes, fill node
                    lbsr      ErrMultiDef incompatible, report error
                    lbra      UnaryDeref then do deref

UnaryFillNode       ldd       $0e,s     selected code
                    std       $08,u     set node type
                    ldd       $0C,s     type copy
                    std       $04,u     store into node
                    ldd       ,s        first field
                    std       $0a,u     store into node
                    leax      $14,s     pointer past locals
                    bra       UnaryJoinA join emit

UnaryInitNode       ldd       $06,s     result code
                    std       ,u        init node field
                    clra                zero high
                    clrb                zero low
                    std       $0C,u     clear node field
                    ldd       $0e,s     selected code
                    std       $08,u     store into node
                    ldd       ,s        first field
                    std       $0a,u     store into node
                    bra       UnaryEmitIndir emit indirection

UnaryJoinA          leas      -$14,x    restore stack from saved X
UnaryEmitIndir      ldd       $12,s     local arg
                    pshs      d         push it
                    ldd       $0e,s     selected code
                    pshs      d         push it
                    pshs      u         push node pointer
                    lbsr      CalcTypeSize build indirection node
                    leas      $06,s     drop args
                    std       $10,s     save result
                    ldd       $06,s     result code
                    clra                clear high
                    andb      #$30      mask storage class bits
                    cmpd      #$0030    both set, do deref
                    lbeq      UnaryDeref skip conversion
                    ldd       $003F     current token
                    cmpd      #$0078    token $78
                    bne       UnaryCheckConv no, other conversion
                    ldd       $06,s     result code
                    pshs      d         push it
                    ldd       $10,s     result value
                    pshs      d         push it
                    pshs      u         push node pointer
                    lbsr      ParseInitializer emit special node
UnaryPopArgs        leas      $06,s     drop args
                    lbra      UnaryFixCode go fix code

UnaryCheckConv      ldd       $10,s     result value
                    bne       UnaryConvDispatch nonzero, convert
                    ldd       $0e,s     selected code
                    cmpd      #$000E    is code fourteen
                    beq       UnaryConvDispatch yes, convert
                    lbsr      ErrCannotEvalSize otherwise report error
                    lbra      UnaryFixCode go fix code

UnaryConvDispatch   ldx       $0e,s     selected code
                    bra       UnaryConvSwitch dispatch conversion

UnaryConv23         ldd       $0e,s     selected code
                    cmpd      #$0023    is code $23
                    bne       UnaryConv23Zero no, flag zero
                    ldd       #$0001    flag one
                    bra       UnaryEmitConvA emit conversion

UnaryConv23Zero     clra                zero high
                    clrb                zero low flag
UnaryEmitConvA      pshs      d         push flag
                    ldd       $12,s     node arg
                    pshs      d         push it
                    pshs      u         push node pointer
                    lbsr      EmitSpaceRmb emit conversion helper
                    bra       UnaryPopArgs continue

UnaryConv21         ldd       $0e,s     selected code
                    cmpd      #$0021    is code $21
                    bne       UnaryConv21Zero no, flag zero
                    ldd       #$0001    flag one
                    bra       UnaryEmitConvB emit conversion

UnaryConv21Zero     clra                zero high
                    clrb                zero low flag
UnaryEmitConvB      pshs      d         push flag
                    ldd       $12,s     node arg
                    pshs      d         push it
                    pshs      u         push node pointer
                    lbsr      EmitColonRmb emit conversion helper
                    lbra      UnaryPopArgs continue

UnaryConvSwitch     cmpx      #$0023    code $23
                    beq       UnaryConv23 handle it
                    cmpx      #$000F    code $0F
                    lbeq      UnaryConv23 handle it
                    cmpx      #$0021    code $21
                    beq       UnaryConv21 handle it
                    cmpx      #$000C    code $0C
                    lbeq      UnaryConv21 handle it
UnaryFixCode        ldd       $0e,s     selected code
                    cmpd      #$000F    is code $0F
                    bne       UnaryFixCode2 no, check $23
                    ldd       #$000C    remap to $0C
                    bra       UnaryStoreType store it

UnaryFixCode2       ldd       $0e,s     selected code
                    cmpd      #$0023    is code $23
                    bne       UnaryDeref no, do deref
                    ldd       #$0021    remap to $21
UnaryStoreType      std       $08,u     store into node
UnaryDeref          ldd       $06,s     result code
                    clra                clear high
                    andb      #$30      mask storage class bits
                    cmpd      #$0030    not pointer, go tail
                    lbne      UnaryTail
                    ldd       $06,s     result code
                    pshs      d         push it
                    lbsr      TypeRemoveLevel get referenced base type
                    leas      $02,s     drop arg
                    std       $06,s     save base type
                    clra                clear high
                    andb      #$30      mask storage class bits
                    cmpd      #$0020    class $20
                    beq       UnaryDerefErr cannot deref
                    ldd       $06,s     base type
                    clra                clear high
                    andb      #$30      mask storage class bits
                    cmpd      #$0030    class $30
                    beq       UnaryDerefErr cannot deref
                    ldd       $06,s     base type
                    cmpd      #$0004    code $04
                    beq       UnaryDerefErr cannot deref
                    ldd       $06,s     base type
                    cmpd      #$0003    code $03
                    bne       UnaryCheckVoid no, ok to deref
UnaryDerefErr       leax      MsgFuncTypeErr,pcr point to message
                    pshs      x         push it
                    lbsr      BuildMsgBuf print trace
                    leas      $02,s     drop arg
                    ldd       #$0031    fallback type $31
                    std       ,u        store into node
                    ldd       #$0001    type one
                    std       $06,s     store result code
UnaryCheckVoid      ldd       $0e,s     selected code
                    cmpd      #$000E    is code fourteen
                    bne       UnaryFinish no, finish emit
                    leax      >$0027,y  node builder base offset
                    pshs      x         push it
                    lbsr      FreeLocalSymbols build node
                    leas      $02,s     drop arg
                    bra       UnaryTail go tail

UnaryFinish         ldd       $06,s     result code
                    std       $002D     store result type global
                    ldd       $0a,s     saved value
                    pshs      d         push it
                    pshs      u         push node pointer
                    lbsr      ParseStructBody finish and emit
                    leas      $04,s     drop args
                    bra       UnaryRet  return

                    bra       UnaryTail dead fallthrough to tail

UnaryJoinB          leas      -$14,x    restore stack from saved X
UnaryTail           ldd       $003F     current token
                    cmpd      #$0030    token $30
                    bne       UnaryExpectParen no, expect paren
                    lbsr      ParseStatement2 advance to next token
                    lbra      UnarySubscrLoop loop for next member

UnaryExpectParen    ldd       #$0028    open paren token
                    pshs      d         push expected
                    lbsr      ExpectToken match token
                    std       ,s++      consume result
                    beq       UnaryRet  matched, return
                    lbsr      SkipToRecover report syntax error
UnaryRet            leas      $14,s     free locals
                    puls      pc,u      return

ParsePostfixExpr    pshs      u         save frame pointer
                    ldd       #$FFA4    frame size for check
                    lbsr      stkcheck  check stack room
                    leas      -$12,s    allocate locals
                    lbsr      ParseTypeName parse primary expression
                    std       $10,s     save token result on stack
                    tfr       d,x       copy token into x
                    bra       ValidateToken go validate the token

OperandErr2         leax      MsgArgStorage,pcr point to error message
                    pshs      x         push message pointer
                    lbsr      BuildMsgBuf report the error
                    leas      $02,s     drop argument
UseDefaultTypeA     ldd       #$000D    default type code $000D
                    std       $10,s     store default type
                    bra       ParseOperandA continue parsing operand

ValidateToken       stx       -$02,s    save token, test for zero
                    beq       UseDefaultTypeA none, use default type
                    cmpx      #$0010    is it expected token $0010
                    beq       ParseOperandA yes, proceed
                    bra       OperandErr2 otherwise report error

ParseOperandA       leax      ,s        point to result slot
                    pshs      x         push destination
                    leax      $0C,s     point to type argument
                    pshs      x         push it
                    leax      $0C,s     point to node argument
                    pshs      x         push it
                    lbsr      ParseDeclSpec parse the operand
                    leas      $06,s     drop arguments
                    std       $0e,s     save returned size
                    bne       OperandLoop nonzero, enter loop
                    ldd       #$0001    default size 1
                    std       $0e,s     store size
OperandLoop         ldd       $0a,s     load node pointer
                    std       $0C,s     copy into working slot
                    ldd       $0e,s     load size
                    pshs      d         push size
                    leax      $0e,s     point to size argument
                    pshs      x         push it
                    leax      $06,s     point to node argument
                    pshs      x         push it
                    lbsr      ParseDeclarator get expression type
                    leas      $06,s     drop arguments
                    std       $04,s     save type
                    ldu       $02,s     load node pointer
                    ldd       $04,s     reload type
                    clra                clear high byte
                    andb      #$30      isolate type class bits
                    cmpd      #$0030    is it class $30
                    beq       InvalidOperandErr yes, invalid operand
                    ldd       $04,s     reload type
                    cmpd      #$0004    is it void type
                    beq       InvalidOperandErr yes, invalid operand
                    ldd       $04,s     reload type
                    cmpd      #$000A    is it type $000A
                    bne       CheckPointerType no, keep checking
InvalidOperandErr   leax      MsgArgErr,pcr point to error message
                    pshs      x         push message
                    lbsr      BuildMsgBuf report the error
                    leas      $02,s     drop argument
                    bra       CleanupA  go cleanup

CheckPointerType    ldd       $04,s     reload type
                    clra                clear high byte
                    andb      #$30      isolate class bits
                    cmpd      #$0020    is it pointer class
                    bne       CheckType5 no, check next
                    ldd       $04,s     load type
                    pshs      d         push type
                    lbsr      TypeRemoveLevel dereference pointer type
                    std       ,s        store result
                    lbsr      TypeAddLevel finalize dereference
                    leas      $02,s     drop argument
                    bra       StoreOperandType store new type

CheckType5          ldd       $04,s     load type
                    cmpd      #$0005    is it type $0005
                    bne       CheckNullNode no, skip promotion
                    ldd       #$0006    promote to type $0006
StoreOperandType    std       $04,s     store type
CheckNullNode       cmpu      #$0000    is node pointer null
                    bne       BuildOperandNode no, build node
                    lbsr      ErrIdentMissing push error node
CleanupA            leax      $12,s     point past frame
                    lbra      RestoreStackA go restore stack

BuildOperandNode    ldd       $04,s     push type argument
                    pshs      d
                    ldd       $12,s     push token argument
                    pshs      d
                    lbsr      CoerceOperandNode coerce operand node
                    leas      $04,s     drop arguments
                    std       $06,s     save result size
                    ldx       $08,u     load node operator field
                    bra       DispatchOperator2 dispatch on operator

EmitOperandNode     ldd       $04,s     store type into node
                    std       ,u
                    ldd       $06,s     store size into node
                    std       $08,u
                    ldd       ,s        store operand into node
                    std       $0a,u
                    ldd       $08,s     push token argument
                    pshs      d
                    ldd       $0e,s     push size argument
                    pshs      d
                    pshs      u         push node pointer
                    lbsr      CalcTypeSize generate code for node
                    leas      $06,s     drop arguments
                    std       -$02,s    save result
                    bne       CheckNextToken success, continue
                    lbsr      ErrCannotEvalSize mark node invalid
                    bra       CheckNextToken continue

EmitEndMarker       lbsr      ErrMultiDef emit end marker
                    bra       CheckNextToken continue

BadOperatorErr      leax      MsgNotArg,pcr point to error message
                    pshs      x         push message
                    lbsr      BuildMsgBuf report the error
                    leas      $02,s     drop argument
                    bra       CheckNextToken continue

DispatchOperator2   cmpx      #$000B    operator is $000B
                    beq       EmitOperandNode build binary node
                    cmpx      #$000D    operator is $000D
                    beq       EmitEndMarker emit end marker
                    cmpx      #$0010    operator is $0010
                    lbeq      EmitEndMarker emit end marker
                    bra       BadOperatorErr otherwise bad operator

RestoreStackA       leas      -$12,x    restore stack via x
CheckNextToken      ldd       $003F     load current token
                    cmpd      #$0078    is it token $0078
                    bne       CheckContinueA no, check continue
                    lbsr      ReportCannotInit handle $0078 token
CheckContinueA      ldd       $003F     reload current token
                    cmpd      #$0030    is it operator $0030
                    bne       ExpressionDone no, expression done
                    lbsr      ParseStatement2 get next token
                    lbra      OperandLoop loop for next operand

ExpressionDone      ldd       #$0028    node size $0028
                    pshs      d         push size
                    lbsr      ExpectToken free the node
                    std       ,s++      drop and store result
                    lbeq      ExprEpilogue done, exit
                    lbsr      SkipToRecover finalize node
                    lbra      ExprEpilogue exit

ParseAssignExpr     pshs      u         save frame pointer
                    ldd       #$FF9E    frame size for check
                    lbsr      stkcheck  check stack space
                    leas      -$12,s    allocate local frame
                    lbsr      ParseTypeName parse the operand
                    std       $10,s     save returned token
                    tfr       d,x       copy into x
                    bra       ValidateAssignToken validate the token

AssignOperandErr    leax      MsgStorageErr2,pcr point to error message
                    pshs      x         push message
                    lbsr      BuildMsgBuf report the error
                    leas      $02,s     drop argument
UseDefaultTypeB     ldd       #$000D    default type $000D
                    std       $10,s     store default
                    bra       ParseAssignOperand continue parsing

ValidateAssignToken cmpx      #$0021    token is $0021
                    beq       AssignOperandErr yes, report error
                    stx       -$02,s    save token, test zero
                    beq       UseDefaultTypeB none, use default
ParseAssignOperand  leax      $02,s     point to type slot
                    pshs      x         push destination
                    leax      $0C,s     point to type argument
                    pshs      x         push it
                    leax      $0C,s     point to node argument
                    pshs      x         push it
                    lbsr      ParseDeclSpec parse the operand
                    leas      $06,s     drop arguments
                    std       $0e,s     save size
                    bne       AssignLoop nonzero, continue
                    ldd       #$0001    default size 1
                    std       $0e,s     store size
AssignLoop          leas      -$06,s    allocate temp slots
                    ldd       $10,s     load token
                    std       ,s        stash it
                    ldd       $14,s     load node pointer
                    pshs      d         push node argument
                    leax      $02,s     point to size argument
                    pshs      x         push it
                    leax      $0e,s     point to type argument
                    pshs      x         push it
                    lbsr      ParseDeclarator get expression type
                    leas      $06,s     drop arguments
                    std       $12,s     save type
                    ldu       $0a,s     load node pointer
                    bne       CheckLValue non-null, handle assign
                    ldd       $12,s     load type
                    cmpd      #$0004    is it void type
                    lbeq      AssignCleanup yes, cleanup
                    ldd       $12,s     reload type
                    cmpd      #$0003    is it type $0003
                    lbeq      AssignCleanup yes, cleanup
                    lbsr      ErrIdentMissing push error node
                    lbra      AssignCleanup cleanup

CheckLValue         ldd       $12,s     load type
                    clra                clear high byte
                    andb      #$30      isolate class bits
                    cmpd      #$0030    is it class $30
                    beq       BuildEmptyAssign yes, simple assign
                    ldd       $16,s     load node kind
                    cmpd      #$000E    is it kind $000E
                    bne       BuildAssignNode no, build node
BuildEmptyAssign    ldd       ,u        load node type field
                    bne       CheckAssignTypes non-zero, check types
                    ldd       $12,s     store type into node
                    std       ,u
                    ldd       #$000E    node kind $000E
                    std       $08,u     store kind
                    clra                zero value
                    clrb
                    std       $0C,u     clear flags field
                    ldd       $08,s     store token into node
                    std       $0a,u
                    ldd       $0e,s     push size argument
                    pshs      d
                    ldd       $02,s     push type argument
                    pshs      d
                    pshs      u         push node
                    lbsr      CalcTypeSize generate code
                    bra       AssignEmitted done

CheckAssignTypes    ldd       $08,s     push token argument
                    pshs      d
                    ldd       $14,s     push type argument
                    pshs      d
                    pshs      u         push node
                    lbsr      CheckTypeMatch check type match
AssignEmitted       leas      $06,s     drop arguments
                    bra       AssignCleanup cleanup

BuildAssignNode     ldd       $12,s     push type argument
                    pshs      d
                    ldd       $18,s     push token argument
                    pshs      d
                    lbsr      CoerceOperandNode coerce operand node
                    leas      $04,s     drop arguments
                    std       $04,s     save size
                    ldd       ,u        load node type field
                    beq       EmitAssignNode empty, emit node
                    ldd       $0C,u     load node flag field
                    cmpd      $0031     compare flag with global $0031
                    bne       FreeOldNode differ, save old node
                    lbsr      ErrMultiDef emit end marker
AssignCleanup       leax      $18,s     point past frame
                    lbra      RestoreStackB restore and exit

FreeOldNode         pshs      u         push node pointer
                    lbsr      AllocBlk  free old type
                    leas      $02,s     drop argument
EmitAssignNode      ldd       $12,s     store type into node
                    std       ,u
                    ldd       $04,s     store size into node
                    std       $08,u
                    ldd       $08,s     store token into node
                    std       $0a,u
                    ldd       $0031     load global $0031 value
                    std       $0C,u     store into node flags
                    ldd       $002B     load current node chain
                    std       $10,u     link previous into node
                    stu       $002B     make node current chain
                    ldd       $0e,s     push size argument
                    pshs      d
                    ldd       $02,s     push type argument
                    pshs      d
                    pshs      u         push node
                    lbsr      CalcTypeSize generate code
                    leas      $06,s     drop arguments
                    std       $02,s     save result
                    bne       AfterAssignEmit success, continue
                    ldd       $003F     load current token
                    cmpd      #$0078    is it token $0078
                    beq       AfterAssignEmit yes, continue
                    lbsr      ErrCannotEvalSize mark node invalid
AfterAssignEmit     ldx       $04,s     load node kind
                    bra       DispatchNodeKind2 dispatch on kind

AdjustStackOffset   ldd       $0011     load stack offset
                    subd      $02,s     subtract node size
                    std       $0011     update stack offset
                    ldd       $0011     reload offset
                    bra       StoreNodeSize store node size

BumpTempCounter     ldd       $000B     load temp counter
                    addd      #$0001    increment counter
                    std       $000B     save counter
StoreNodeSize       std       $06,u     store size into node
                    bra       CheckAssignToken continue

DispatchNodeKind2   cmpx      #$000D    kind is $000D
                    beq       AdjustStackOffset adjust stack offset
                    cmpx      #$0023    kind is $0023
                    beq       BumpTempCounter bump temp counter
                    cmpx      #$000F    kind is $000F
                    lbeq      BumpTempCounter bump temp counter
CheckAssignToken    ldd       $003F     load current token
                    cmpd      #$0078    is it token $0078
                    lbne      CheckOtherToken no, handle other
                    ldd       $04,s     load node kind
                    cmpd      #$000F    is it kind $000F
                    beq       EmitInitializer yes, emit initializer
                    ldd       $04,s     reload kind
                    cmpd      #$0023    is it kind $0023
                    bne       HandlePostAssign no, handle other
EmitInitializer     ldd       $12,s     push type argument
                    pshs      d
                    ldd       $06,s     push node-size argument
                    pshs      d
                    pshs      u         push node
                    lbsr      ParseInitializer emit initializer code
AssignReturn        leas      $06,s     drop arguments
                    lbra      AssignEnd go to assign end

HandlePostAssign    lbsr      ParseStatement2 get next token
                    ldd       $12,s     load type
                    clra                clear high byte
                    andb      #$30      isolate class bits
                    cmpd      #$0020    is it pointer class
                    lbeq      PostAssignErr yes, report error
                    ldd       $12,s     reload type
                    cmpd      #$0004    is it void type
                    lbeq      PostAssignErr yes, report error
                    ldd       #$0002    request 2 bytes
                    pshs      d
                    lbsr      ParseBinaryExpr allocate expression slot
                    leas      $02,s     drop argument
                    std       $0C,s     save slot pointer
                    beq       PostAssignErr null, report error
                    ldd       $006E     load node free list
                    beq       AllocInitNode empty, allocate fresh
                    ldd       $006E     load free list head
                    std       $06,s     save it
                    tfr       d,x       copy into x
                    ldd       ,x        load next free pointer
                    std       $006E     unlink from free list
                    clra                clear reused node
                    clrb
                    std       [$06,s]
                    bra       LinkInitNode link node

AllocInitNode       ldd       #$0006    node size 6
                    pshs      d
                    lbsr      AllocMem  allocate node
                    leas      $02,s     drop argument
                    std       $06,s     save node pointer
LinkInitNode        ldd       $0C,s     load slot value
                    ldx       $06,s     load node pointer
                    std       $02,x     store slot into node
                    ldx       $06,s     reload node pointer
                    stu       $04,x     store expression into node
                    ldd       GlbNodePtr load list head
                    beq       SetInitListHead empty, set head
                    ldd       $06,s     load node
                    std       [GlbListTail,y] append after tail
                    bra       SetInitListTail update tail

SetInitListHead     ldd       $06,s     load node
                    std       GlbNodePtr set list head
SetInitListTail     ldd       $06,s     load node
                    std       GlbListTail set list tail
                    bra       AssignEnd assign end

PostAssignErr       lbsr      ReportCannotInit handle error token
                    bra       AssignEnd assign end

CheckOtherToken     ldx       $04,s     load node kind
                    bra       DispatchOtherKind dispatch on kind

EmitCompareNode     ldd       $04,s     load node kind
                    cmpd      #$0023    is it kind $0023
                    bne       ZeroCompareFlag no, use zero flag
                    ldd       #$0001    flag value 1
                    bra       PushCompareArgs push flag

ZeroCompareFlag     clra                flag value 0
                    clrb
PushCompareArgs     pshs      d         push flag
                    ldd       $04,s     push node kind
                    pshs      d
                    ldd       $06,u     push node size
                    pshs      d
                    lbsr      EmitVsectRmb emit comparison
                    lbra      AssignReturn return

DispatchOtherKind   cmpx      #$000F    kind is $000F
                    beq       EmitCompareNode emit comparison
                    cmpx      #$0023    kind is $0023
                    lbeq      EmitCompareNode emit comparison
                    bra       AssignEnd assign end

RestoreStackB       leas      -$18,x    restore stack via x
AssignEnd           ldd       $003F     load current token
                    cmpd      #$0030    is it operator $0030
                    beq       ContinueAssign yes, continue assign
                    leas      $06,s     drop temp slots
                    bra       FreeAndExitB free and exit

ContinueAssign      lbsr      ParseStatement2 get next token
                    leas      $06,s     drop temp slots
                    lbra      AssignLoop loop for next assign

FreeAndExitB        ldd       #$0028    node size $0028
                    pshs      d         push size
                    lbsr      ExpectToken free the node
                    leas      $02,s     drop argument
ExprEpilogue        leas      $12,s     release local frame
                    puls      pc,u      restore and return

CheckTypeMatch      pshs      u         save frame pointer
                    ldd       #$FFBA    frame size for check
                    lbsr      stkcheck  check stack space
                    ldu       $04,s     load node pointer
                    ldd       ,u        load node type field
                    cmpd      $06,s     compare with expected type
                    bne       TypeMismatchErr mismatch, report error
                    ldd       $06,s     reload expected type
                    cmpd      #$0004    is it void type
                    bne       TypesMatchOk no, types ok
                    ldd       $0a,u     load node operand
                    cmpd      $08,s     compare with argument
                    beq       TypesMatchOk equal, types ok
TypeMismatchErr     leax      MsgDeclMismatch,pcr point to error message
                    pshs      x         push message
                    lbsr      BuildMsgBuf report the error
                    leas      $02,s     drop argument
                    ldd       #$0001    return failure 1
                    puls      pc,u      restore and return

TypesMatchOk        clra                return success 0
                    clrb
                    puls      pc,u      restore and return

CoerceOperandNode   pshs      u         save frame pointer
                    ldd       #$FFC0    frame size for check
                    lbsr      stkcheck  check stack space
                    ldd       $04,s     load type argument
                    cmpd      #$0010    is it pointer type $0010
                    bne       ReturnInputType no, skip pointer scan
                    ldd       SetupArgv load pointer nesting count
                    cmpd      #$0001    already at level 1
                    bge       ReturnType0D yes, skip scan
                    ldx       $06,s     load node pointer
                    bra       CheckXTypeCode scan pointer chain

ScanPointerLoop     ldd       $06,s     load node kind
                    clra                clear high byte
                    andb      #$30      isolate class bits
                    cmpd      #$0010    is it pointer class
                    bne       ReturnType0D no, stop scan
MarkPointerLevel    ldd       SetupArgv load nesting count
                    addd      #$0001    increment nesting
                    std       SetupArgv save count
                    cmpd      #$0001    reached level 1
                    bne       TypeCode76 no, continue scan
                    ldd       #$006F    load scale table base
                    bra       ClassifyRet return with type code

TypeCode76          ldd       #$0076    D = derived type tag $76
ClassifyRet         puls      pc,u      return type in D

CheckXTypeCode      cmpx      #$0001    base type code == 1
                    beq       MarkPointerLevel yes, bump type counter
                    cmpx      #$0007    base type code == 7
                    lbeq      MarkPointerLevel yes, bump type counter
                    bra       ScanPointerLoop else classify by mask

ReturnType0D        ldd       #$000D    D = type code $0D
                    puls      pc,u      return type in D

ReturnInputType     ldd       $04,s     D = input type unchanged
                    puls      pc,u      return type in D

ParseStructBody     pshs      u         save U frame pointer
                    ldd       #$FFAC    stack space needed
                    lbsr      stkcheck  check stack overflow
                    leas      -$0a,s    allocate 10 local bytes
                    ldd       #$0001    initial nesting depth 1
                    std       $0031     set nesting depth
                    clra                clear A
                    clrb                clear B
                    std       $000F     clear working field $000F
                    std       $001B     clear max offset
                    std       $0011     clear current offset
                    std       SetupArgv clear field counter
                    std       $0013     clear field $0013
                    bra       MemberLoopTest enter member loop test

ParseMemberLoop     lbsr      ParsePostfixExpr parse one struct member
MemberLoopTest      ldd       $003F     D = current token
                    cmpd      #$0029    token == close brace
                    bne       ParseMemberLoop no, parse more members
                    ldd       $0e,s     D = local temp
                    addd      #$0014    add base displacement
                    std       $02,s     save member list pointer
                    ldd       $0017     anonymous tag flag
                    beq       LayoutSetup skip if no tag
                    ldd       $000B     D = tag counter
                    addd      #$0001    increment tag counter
                    std       $000B     store bumped counter
                    std       ,s        save as argument
                    pshs      d         push argument
                    ldd       $04,s     D = list pointer
                    pshs      d         push argument
                    lbsr      EmitStringConst create struct-tag symbol
                    leas      $04,s     drop arguments
LayoutSetup         ldd       ,s        D = member list pointer
                    pshs      d         push argument
                    ldd       $12,s     D = base type field
                    cmpd      #$000F    is type code $0F
                    beq       PackedFlagZero yes, packed flag zero
                    ldd       #$0001    flag = 1
                    bra       StoreStructSym store flag

PackedFlagZero      clra                clear A
                    clrb                packed flag zero
StoreStructSym      pshs      d         push packed flag
                    ldd       $06,s     D = tag pointer
                    pshs      d         push argument
                    lbsr      EmitFuncPrologue create struct symbol entry
                    leas      $06,s     drop arguments
                    ldu       $0027     U = member list head
                    ldd       #$0004    initial offset = 4
                    std       $08,s     seed running offset
                    lbra      LayoutNext enter layout loop

LayoutMemberLoop    leas      -$02,s    reserve loop temp
                    ldd       $0a,s     D = running offset
                    std       $06,u     store offset into member
                    ldx       ,u        X = member type code
                    bra       SizeForType dispatch size by type

MemberSize4         ldd       #$0004    member size 4
                    bra       StoreMemberSize store size

MemberSize8         ldd       #$0008    member size 8
                    bra       StoreMemberSize store size

MemberSize2Bump     ldd       $06,u     D = member offset
                    addd      #$0001    add one for int
                    std       $06,u     bump member offset
MemberSize2         ldd       #$0002    member size 2
StoreMemberSize     std       ,s        save member size
                    bra       LayoutSubtype continue layout

SizeForType         cmpx      #$0008    type code == 8
                    beq       MemberSize4 size 4
                    cmpx      #$0005    type code == 5
                    lbeq      MemberSize4 size 4
                    cmpx      #$0006    type code == 6
                    beq       MemberSize8 size 8
                    cmpx      #$0002    type code == 2
                    beq       MemberSize2Bump int, size 2 with bump
                    bra       MemberSize2 default size 2

LayoutSubtype       ldd       $08,u     D = member subtype
                    std       $08,s     save subtype
                    tfr       d,x       X = subtype
                    bra       DispatchSubtype dispatch subtype

BuildMemberType     ldd       $0a,s     D = running offset
                    pshs      d         push argument
                    ldd       $0a,s     D = running offset
                    pshs      d         push argument
                    lbsr      GenNode   emit/build member type
                    leas      $04,s     drop arguments
                    bra       AdvanceMember advance member

SetSubtype0D        ldd       #$000D    subtype $0D
                    std       $08,u     store subtype
                    bra       AdvanceMember advance member

DispatchSubtype     cmpx      #$006F    subtype == $6F
                    beq       BuildMemberType build member type
                    cmpx      #$0076    subtype == $76
                    lbeq      BuildMemberType build member type
                    cmpx      #$000B    subtype == $0B
                    beq       SetSubtype0D set subtype $0D
AdvanceMember       ldd       $0a,s     D = running offset
                    addd      ,s        add member size
                    std       $0a,s     advance running offset
                    ldu       $10,u     U = next member
                    leas      $02,s     drop loop temp
LayoutNext          stu       -$02,s    save current member pointer
                    lbne      LayoutMemberLoop loop while members remain
                    ldd       $0027     D = member list head
                    std       $04,s     save it
                    clra                clear A
                    clrb                clear B
                    std       $0027     clear member list head
                    lbsr      ParseDeclarations parse declarations
                    leax      $04,s     X = saved list pointer
                    pshs      x         push argument
                    lbsr      FreeLocalSymbols restore saved global
                    leas      $02,s     drop argument
                    leax      >$0029,y  X = address of global $0029
                    pshs      x         push argument
                    lbsr      FreeLocalSymbols restore saved global
                    leas      $02,s     drop argument
                    ldd       $002F     D = current type field
                    cmpd      #$0012    already type $12
                    beq       AfterTypeEmit skip type emission
                    clra                clear A
                    clrb                clear B
                    pshs      d         push zero
                    clra                clear A
                    clrb                clear B
                    pshs      d         push zero
                    ldd       #$0012    type tag $12
                    pshs      d         push type tag
                    lbsr      GenNode   emit/build type
                    leas      $06,s     drop arguments
AfterTypeEmit       clra                clear A
                    clrb                clear B
                    std       $002F     clear type field $002F
                    lbsr      EmitFrameEqu finalize struct type
                    clra                clear A
                    clrb                clear B
                    std       $0031     clear nesting depth
                    ldd       $003F     D = current token
                    cmpd      #$FFFF    end-of-input token
                    bne       StructBodyDone no, continue
                    leax      MsgFuncUnfinished,pcr X = error message
                    pshs      x         push argument
                    lbsr      BuildMsgBuf print error message
                    leas      $02,s     drop argument
StructBodyDone      lbsr      ParseStatement2 get next token
                    leas      $0a,s     release locals
                    puls      pc,u      return

ParseDeclarations   pshs      u         save U frame pointer
                    ldd       #$FFAA    stack space needed
                    lbsr      stkcheck  check stack overflow
                    leas      -$06,s    allocate 6 local bytes
                    ldd       $002B     D = saved global $002B
                    std       $02,s     save old value
                    clra                clear A
                    clrb                clear B
                    std       $002B     clear global $002B
                    lbsr      ParseStatement2 get next token
                    ldd       $0031     D = nesting depth
                    addd      #$0001    increment depth
                    std       $0031     bump nesting depth
                    ldd       $0011     D = current offset
                    std       ,s        save entry offset
                    bra       ParseDeclLoop enter parse loop

ProcessDeclLoop     lbsr      ParseAssignExpr process the declaration
ParseDeclLoop       lbsr      IsStorageKeyword parse one declaration
                    std       -$02,s    save parse result
                    bne       ProcessDeclLoop loop while declaration parsed
                    lbsr      IsTypeSpecifier parse trailing declaration
                    std       -$02,s    save parse result
                    lbne      ProcessDeclLoop loop while declaration parsed
                    ldd       $001B     D = max offset
                    cmpd      $0011     vs current offset
                    ble       OffsetChecked skip if max already larger
                    ldd       $0011     D = current offset
                    std       $001B     raise max offset
OffsetChecked       ldd       $0011     D = current offset
                    pshs      d         push argument
                    lbsr      EmitReserveSpace compute/allocate offset
                    leas      $02,s     drop argument
                    std       $000F     save resulting frame size
                    lbra      ReverseListTest enter list-reverse loop

ReverseListLoop     ldd       GlbNodePtr D = declaration list head
                    std       $04,s     save node pointer
                    ldx       $04,s     X = node
                    ldu       $02,x     U = node type pointer
                    ldd       $10,u     D = type high word
                    pshs      d         push argument
                    ldd       $0e,u     D = type field
                    pshs      d         push argument
                    ldx       $08,s     X = node pointer
                    ldd       $04,x     D = node size
                    pshs      d         push argument
                    clra                clear A
                    clrb                clear B
                    pshs      d         push zero
                    clra                clear A
                    clrb                clear B
                    pshs      d         push zero
                    ldd       #$0034    type tag $34
                    pshs      d         push tag
                    lbsr      AllocExprNode build type node
                    leas      $0C,s     drop arguments
                    tfr       d,u       U = new type node
                    ldd       $10,u     D = type high word
                    pshs      d         push argument
                    ldd       $0e,u     D = type field
                    pshs      d         push argument
                    clra                clear A
                    clrb                clear B
                    pshs      d         push zero
                    ldx       $0a,s     X = node pointer
                    ldd       $02,x     D = node type
                    pshs      d         push argument
                    pshs      u         push node
                    ldd       #$0078    type tag $78
                    pshs      d         push tag
                    lbsr      AllocExprNode build type node
                    leas      $0C,s     drop arguments
                    tfr       d,u       U = new type node
                    pshs      u         push node
                    lbsr      CopyExprTree resolve/apply type
                    std       ,s        save result
                    lbsr      EvalSubtreeType finalize type node
                    std       ,s        save result
                    lbsr      FreeExprTree emit declaration
                    leas      $02,s     drop argument
                    ldd       [$04,s]   D = node next pointer
                    std       $04,s     save next node
                    ldd       $006E     D = reversed list head
                    std       [GlbNodePtr,y] link node into reversed list
                    ldd       GlbNodePtr D = current node
                    std       $006E     advance reversed head
                    ldd       $04,s     D = next node
                    std       GlbNodePtr advance to next node
ReverseListTest     ldd       GlbNodePtr D = list head
                    lbne      ReverseListLoop loop while nodes remain
                    bra       StmtLoopTest begin statement parsing

ParseStmtLoop       lbsr      ParseStatement parse one statement
StmtLoopTest        ldd       $003F     D = current token
                    cmpd      #$002A    token == close $2A
                    beq       BlockDone yes, block done
                    ldd       $003F     D = current token
                    cmpd      #$FFFF    end-of-input token
                    bne       ParseStmtLoop no, parse more statements
BlockDone           leax      >$002b,y  X = address of global $002B
                    pshs      x         push argument
                    lbsr      FreeLocalSymbols restore saved global
                    leas      $02,s     drop argument
                    ldd       $02,s     D = saved $002B value
                    std       $002B     restore global $002B
                    ldd       $0031     D = nesting depth
                    addd      #$FFFF    decrement
                    std       $0031     pop nesting depth
                    ldd       ,s        D = entry offset
                    std       $0011     restore current offset
                    ldd       $002F     D = type field
                    cmpd      #$0012    already type $12
                    beq       UseOffsetAsIs use offset as-is
                    ldd       ,s        D = entry offset
                    pshs      d         push argument
                    lbsr      EmitReserveSpace compute offset
                    leas      $02,s     drop argument
                    bra       StoreFrameSize store frame size

UseOffsetAsIs       ldd       ,s        D = entry offset
StoreFrameSize      std       $000F     save frame size
                    leas      $06,s     release locals
                    puls      pc,u      return

ParseEnumMembers    pshs      u         save U frame pointer
                    ldd       #$FFB8    stack space needed
                    lbsr      stkcheck  check stack overflow
                    leas      -$02,s    allocate 2 local bytes
                    clra                clear A
                    clrb                clear B
                    std       [$06,s]   clear list head
EnumMemberLoop      lbsr      ParseStatement2 get next token
                    ldd       $003F     D = current token
                    cmpd      #$002E    token == close $2E
                    lbeq      EnumListDone end of member list
                    ldd       $003F     D = current token
                    cmpd      #$0034    token == identifier
                    bne       ParseOtherEnum no, handle otherwise
                    ldu       $0041     U = symbol pointer
                    ldd       $08,u     D = symbol type
                    cmpd      #$000B    already enum constant
                    bne       CheckSymUnset no
                    leax      MsgNamedTwice,pcr X = redefinition error message
                    pshs      x         push argument
                    lbsr      BuildMsgBuf print error message
                    bra       AfterFreeNode skip free

CheckSymUnset       ldd       ,u        D = symbol flags
                    beq       DefineEnumConst skip if unset
                    pshs      u         push symbol
                    lbsr      AllocBlk  free old node
AfterFreeNode       leas      $02,s     drop argument
DefineEnumConst     ldd       #$0001    mark value 1
                    std       ,u        mark symbol defined
                    ldd       #$000B    enum-const type $0B
                    std       $08,u     set symbol type
                    ldd       #$0001    storage class 1
                    std       $0C,u     set storage class
                    ldd       #$0002    size 2
                    std       $02,u     set symbol size
                    ldd       [$06,s]   D = current list head
                    beq       SetListHead first member
                    ldx       ,s        X = previous member
                    stu       $10,x     link previous to this
                    bra       LinkEnumConst skip head set

SetListHead         stu       [$06,s]   set list head
LinkEnumConst       clra                clear A
                    clrb                clear B
                    std       $10,u     clear next pointer
                    stu       ,s        remember as previous
                    lbsr      ParseStatement2 get next token
                    bra       EnumSepTest test separator

ParseOtherEnum      lbsr      ErrIdentMissing handle other construct
EnumSepTest         ldd       $003F     D = current token
                    cmpd      #$0030    token == comma $30
                    lbeq      EnumMemberLoop continue member list
EnumListDone        ldd       #$002E    expected token $2E
                    pshs      d         push argument
                    lbsr      ExpectToken require closing token
                    leas      $02,s     drop argument
                    bra       TypeNameRet finish

ParseTypeName       pshs      u         save U frame pointer
                    ldd       #$FFBA    stack space needed
                    lbsr      stkcheck  check stack overflow
                    leas      -$02,s    allocate 2 local bytes
                    lbsr      IsStorageKeyword parse declarator/type
                    std       -$02,s    save result
                    beq       ReturnNoType none, return 0
                    ldd       $0041     D = token value
                    std       ,s        save type node
                    lbsr      ParseStatement2 get next token
                    ldd       $003F     D = current token
                    cmpd      #$0033    token == keyword $33
                    bne       ReturnType no, return type
                    ldd       $0041     D = keyword value
                    cmpd      #$0021    value == $21
                    bne       ReturnType no, return type
                    ldx       ,s        X = type node
                    bra       CheckBaseType check base type

MapTypeUnsigned23   ldd       #$0023    mapped type $23
                    bra       StoreMappedType store it

MapTypeUnsigned22   ldd       #$0022    mapped type $22
StoreMappedType     std       ,s        store mapped type
                    bra       ConsumeUnsigned consume keyword

CheckBaseType       cmpx      #$000F    base type == $0F
                    beq       MapTypeUnsigned23 map to $23
                    cmpx      #$000E    base type == $0E
                    beq       MapTypeUnsigned22 map to $22
ConsumeUnsigned     lbsr      ParseStatement2 consume unsigned keyword
ReturnType          ldd       ,s        D = type node
                    bra       TypeNameRet return type

ReturnNoType        clra                clear A
                    clrb                return zero
TypeNameRet         leas      $02,s     release locals
                    puls      pc,u      return

ParseDeclSpec       pshs      u         save U frame pointer
                    ldd       #$FF98    stack space needed
                    lbsr      stkcheck  check stack overflow
                    leas      -$1a,s    allocate locals
                    clra                clear A
                    clrb                clear B
                    std       $02,s     clear type field
                    ldd       #$0002    default size 2
                    std       ,s        set default size
                    clra                clear A
                    clrb                clear B
                    std       [$22,s]   clear output pointer
                    ldd       $003F     D = current token
                    cmpd      #$0033    token == keyword $33
                    lbne      CheckTypedefName not a type keyword
                    ldd       $0041     D = keyword value
                    std       $02,s     save keyword
                    tfr       d,x       X = keyword
                    lbra      KeywordDispatch2 dispatch keyword

SetTypeShort        ldd       #$0001    type code 1
                    std       $02,s     save type
SpecKeywordLoop     lbsr      ParseStatement2 get next token
                    ldd       $003F     D = current token
                    cmpd      #$0033    token == keyword $33
                    lbne      ReturnDefaultType done with specifiers
                    ldd       $0041     D = keyword value
                    cmpd      #$0001    value == $01
                    lbne      ReturnDefaultType done
                    bra       NextSpecTok consume specifier

SetFlag1            ldd       #$0001    flag = 1
                    bra       StoreSpecSize store flag

SetSizeLong         lbsr      ParseStatement2 get next token
                    ldd       #$0004    size 4
                    std       ,s        set size
                    ldd       $003F     D = current token
                    cmpd      #$0033    token == keyword $33
                    lbne      ReturnDefaultType done
                    ldd       $0041     D = keyword value
                    cmpd      #$0001    value == $01
                    beq       NextSpecTok consume specifier
                    ldd       $0041     D = keyword value
                    cmpd      #$0005    value == $05
                    lbne      ReturnDefaultType done
SetTypeDouble2      ldd       #$0006    type code 6 double
                    std       $02,s     save type
                    ldd       #$0008    size 8
                    bra       StoreSpecSize store size

SetSize42           ldd       #$0004    size 4
StoreSpecSize       std       ,s        set size
NextSpecTok         lbsr      ParseStatement2 get next token
                    lbra      ReturnDefaultType done with specifiers

SetTypeVoid         clra                clear A
                    clrb                clear B
                    std       $02,s     save void type
                    lbra      ReturnDefaultType done

ResetSpecState      clra                clear A
                    clrb                clear B
                    std       $16,s     clear field $16
                    std       ,s        clear size
                    ldd       GlbNestDepth D = specifier counter
                    addd      #$0001    increment
                    std       GlbNestDepth bump specifier counter
                    clra                clear high byte of tag slot
                    clrb                clear low byte of tag slot
                    std       $18,s     clear the tag symbol pointer slot
                    lbsr      ParseStatement2 get next token
                    ldd       GlbNestDepth load nesting depth counter
                    addd      #$FFFF    decrement it
                    std       GlbNestDepth save nesting depth
                    ldd       $003F     D = current token type
                    cmpd      #$0034    is it an identifier (tag name)
                    lbne      StructNoTagBody no tag name, expect the brace
                    ldd       $0041     D = tag symbol pointer
                    std       $18,s     save the tag symbol
                    ldd       [$18,s]   load tag symbol kind field
                    bne       TagPreDeclared nonzero, tag already declared
                    ldd       #$000A    new tag kind marker
                    std       [$18,s]   mark symbol as a tag
                    ldd       #$0008    initial struct size
                    ldx       $18,s     X = tag symbol pointer
                    std       $08,x     store initial size
                    bra       AfterTagName continue after the tag

TagPreDeclared      ldx       $18,s     X = existing tag symbol
                    ldd       $08,x     load its kind/size field
                    cmpd      #$0008    is it an incomplete tag
                    beq       AfterTagName yes, allow the definition
                    leax      MsgNameClash,pcr point to redeclaration error text
                    pshs      x         push message pointer
                    lbsr      BuildMsgBuf report the error
                    leas      $02,s     drop the argument
AfterTagName        lbsr      ParseStatement2 get next token
                    ldd       $003F     D = current token
                    cmpd      #$0029    is it an opening brace
                    beq       TagBraceCheck yes, parse the body
                    ldd       [$18,s]   load tag kind
                    cmpd      #$0004    is it a complete type
                    bne       ForwardTagRef no, treat as forward reference
                    ldx       $18,s     X = tag symbol
                    ldd       $02,x     load tag type
                    std       [$1e,s]   return type to caller
                    ldx       $18,s     X = tag symbol
                    ldd       $0a,x     load tag size
                    std       [$22,s]   return size to caller
                    ldd       #$0004    result kind = struct type
                    lbra      TypeSpecReturn return

ForwardTagRef       ldd       $18,s     D = tag symbol pointer
                    std       [$1e,s]   return the tag pointer
                    ldd       #$000A    result kind = incomplete tag
                    lbra      TypeSpecReturn return

TagBraceCheck       ldd       [$18,s]   load tag kind
                    cmpd      #$0004    already complete
                    bne       StructNoTagBody no, parse the body
                    lbsr      ErrMultiDef report redefinition error
StructNoTagBody     ldd       $003F     D = current token
                    cmpd      #$0029    is it an opening brace
                    beq       ParseStructBody2 yes, parse struct body
                    leax      MsgStructSyntax,pcr point to open-brace expected error
                    pshs      x         push message
                    lbsr      BuildMsgBuf report the error
                    leas      $02,s     drop the argument
                    lbra      ReturnDefaultType return

ParseStructBody2    ldd       GlbNestDepth load nesting depth
                    addd      #$0001    increment it
                    std       GlbNestDepth save nesting depth
MemberLoop          ldd       GlbNestDepth load nesting depth
                    std       $10,s     save it on the frame
                    clra                clear high byte
                    clrb                clear low byte
                    std       GlbNestDepth reset nesting depth
                    lbsr      ParseStatement2 get next token
                    ldd       $10,s     restore saved depth
                    std       GlbNestDepth back into the global
                    ldd       $003F     D = current token
                    cmpd      #$002A    is it a closing brace
                    lbeq      EndStructBody yes, end of member list
                    leax      $04,s     address of a local slot
                    pshs      x         push arg pointer
                    leax      $0e,s     address of a local slot
                    pshs      x         push arg pointer
                    leax      $18,s     address of tag slot
                    pshs      x         push arg pointer
                    lbsr      ParseDeclSpec parse member type specifier (recurse)
                    leas      $06,s     drop the three args
                    std       $12,s     save member base type
                    bra       DeclaratorLoop parse the declarators

DeclaratorLoop      leas      -$04,s    make room for declarator temps
                    ldd       $10,s     load saved depth
                    std       $02,s     store into frame
                    ldd       $003F     D = current token
                    cmpd      #$0028    is it a semicolon
                    lbeq      DropDeclTemps yes, empty declarator
                    ldd       $0031     load member level counter
                    addd      #$0001    increment it
                    std       $0031     save it
                    ldd       $16,s     push type argument
                    pshs      d         onto the stack
                    leax      $04,s     address of temp
                    pshs      x         push arg pointer
                    leax      $04,s     address of temp
                    pshs      x         push arg pointer
                    lbsr      ParseDeclarator parse member declarator
                    leas      $06,s     drop the args
                    std       $12,s     save member name/type
                    ldu       ,s        U = declarator result
                    ldd       $0031     load level counter
                    addd      #$FFFF    decrement it
                    std       $0031     save it
                    cmpu      #$0000    was declarator empty
                    bne       CheckMemberDup no, add the member
                    lbsr      ErrIdentMissing report missing member name
                    leax      $1e,s     compute restore pointer
                    lbra      RestoreFrame2 continue after member

CheckMemberDup      ldd       ,u        load member name field
                    beq       FillMember unnamed, just link it
                    ldd       $0C,u     load member scope level
                    cmpd      $0031     same nesting level
                    bne       AllocMemberSym different, link as new
                    ldd       ,u        load member name
                    cmpd      $12,s     matches the new name
                    bne       MemberRedeclErr no, redeclaration
                    ldd       $08,u     load member kind
                    cmpd      #$0011    is it a field kind
                    bne       MemberRedeclErr no, redeclaration
                    ldd       $06,u     load field type
                    cmpd      $1a,s     same type as before
                    beq       FillMember yes, reuse the entry
MemberRedeclErr     leax      MsgStructMemberMismatch,pcr point to redeclaration error
                    pshs      x         push message
                    lbsr      BuildMsgBuf report the error
                    bra       AfterAllocSym continue

AllocMemberSym      pshs      u         allocate a new symbol entry
                    lbsr      AllocBlk  drop the argument
AfterAllocSym       leas      $02,s     load member name
FillMember          ldd       $12,s     is name a reserved value
                    cmpd      #$000A    no, store the fields
                    bne       StoreMemberFields point to error text
                    leax      MsgUndefStruct,pcr push message
                    pshs      x         report the error
                    lbsr      BuildMsgBuf drop the argument
                    leas      $02,s     load member name
StoreMemberFields   ldd       $12,s     store into the symbol
                    std       ,u        kind = struct field
                    ldd       #$0011    store the kind
                    std       $08,u     load field type
                    ldd       $1a,s     store the type
                    std       $06,u     load member attribute
                    ldd       $08,s     store the attribute
                    std       $0a,u     push type argument
                    ldd       $18,s     onto the stack
                    pshs      d         push size argument
                    ldd       $04,s     onto the stack
                    pshs      d         push member symbol
                    pshs      u         compute member size/offset
                    lbsr      CalcTypeSize drop the args
                    leas      $06,s     save returned size
                    std       $0e,s     zero size, report incomplete
                    beq       IncompleteMemberErr load aggregate kind
                    ldd       $06,s     is it a struct (accumulate)
                    cmpd      #$0004    no, union (take max)
                    bne       UnionMemberSize load current offset
                    ldd       $1a,s     add member size
                    addd      $0e,s     update the offset
                    std       $1a,s     done with this member
                    bra       StoreUnionSize

UnionMemberSize     ldd       $0e,s     load member size
                    cmpd      $04,s     compare with union max
                    ble       KeepUnionSize not larger, keep max
                    ldd       $0e,s     take the member size
                    bra       StoreUnionSize store the union size

KeepUnionSize       ldd       $04,s     keep the current max
StoreUnionSize      std       $04,s     store the union size
                    bra       LinkMemberSym finish the member

IncompleteMemberErr lbsr      ErrCannotEvalSize report incomplete member
LinkMemberSym       ldd       $0031     load level counter
                    std       $0C,u     store into symbol scope
                    ldd       $002B     load symbol list head
                    std       $10,u     chain the previous head
                    stu       $002B     make this the new head
                    ldd       $06,s     load aggregate kind
                    cmpd      #$0004    is it a struct field
                    bne       AfterMember no, skip node linking
                    ldd       #$0004    allocate a 4 byte node
                    pshs      d         onto the stack
                    lbsr      AllocMem  allocate the node
                    leas      $02,s     drop the argument
                    std       $0C,s     save the node pointer
                    ldx       $0C,s     X = node
                    stu       $02,x     store member symbol in node
                    ldd       [$26,s]   load member list head
                    beq       SetMemberListHead empty list
                    ldd       $0C,s     load the new node
                    std       [$0a,s]   append to list tail
                    bra       UpdateMemberTail continue

SetMemberListHead   ldd       $0C,s     load the new node
                    std       [$26,s]   set list head
UpdateMemberTail    ldd       $0C,s     load the node
                    std       $0a,s     update list tail
                    bra       AfterMember continue

RestoreFrame2       leas      -$1e,x    restore stack after error
AfterMember         ldd       $003F     D = current token
                    cmpd      #$0030    is it a comma
                    beq       NextDeclarator yes, another declarator
DropDeclTemps       leas      $04,s     drop declarator temps
                    bra       CheckMemberSemi check for semicolon

NextDeclarator      lbsr      ParseStatement2 get next token
                    leas      $04,s     drop declarator temps
                    lbra      DeclaratorLoop parse the next declarator

CheckMemberSemi     ldd       $003F     D = current token
                    cmpd      #$0028    is it a semicolon
                    lbeq      MemberLoop yes, parse next member
EndStructBody       ldd       GlbNestDepth load nesting depth
                    addd      #$FFFF    decrement it
                    std       GlbNestDepth save nesting depth
                    ldd       $18,s     D = tag symbol pointer
                    beq       ExpectCloseBrace2 no tag, skip finalize
                    ldd       ,s        load computed struct size
                    ldx       $18,s     X = tag symbol
                    std       $02,x     store size into tag
                    ldd       #$0004    kind = complete struct
                    std       [$18,s]   mark the tag complete
                    ldd       [$22,s]   load total size
                    ldx       $18,s     X = tag symbol
                    std       $0a,x     store the size field
ExpectCloseBrace2   ldd       #$002A    expected closing brace token
                    pshs      d         push it
                    lbsr      ExpectToken expect/consume the token
                    leas      $02,s     drop the argument
                    bra       ReturnDefaultType return

KeywordDispatch2    cmpx      #$000A    match keyword id $0A
                    lbeq      SetTypeShort handle that keyword
                    cmpx      #$0007    match keyword id $07
                    lbeq      SpecKeywordLoop handle that keyword
                    cmpx      #$0002    match keyword id $02
                    lbeq      SetFlag1  handle that keyword
                    cmpx      #$0001    match keyword id $01
                    lbeq      NextSpecTok handle that keyword
                    cmpx      #$0008    match keyword id $08
                    lbeq      SetSizeLong handle that keyword
                    cmpx      #$0006    match keyword id $06
                    lbeq      SetTypeDouble2 handle that keyword
                    cmpx      #$0005    match keyword id $05
                    lbeq      SetSize42 handle that keyword
                    cmpx      #$0003    match keyword struct
                    lbeq      ResetSpecState parse struct body
                    cmpx      #$0004    match keyword union
                    lbeq      ResetSpecState parse union body
                    lbra      SetTypeVoid not a type keyword

CheckTypedefName    ldd       $003F     D = current token
                    cmpd      #$0034    is it an identifier
                    bne       ReturnDefaultType no, use default type
                    ldu       $0041     U = symbol pointer
                    ldd       $08,u     load symbol kind
                    cmpd      #$001E    is it a typedef name
                    bne       ReturnDefaultType no, use default type
                    ldd       $02,u     load typedef type
                    std       [$1e,s]   return the type
                    ldd       $04,u     load typedef attribute
                    std       [$20,s]   return the attribute
                    ldd       $0a,u     load typedef size
                    std       [$22,s]   return the size
                    lbsr      ParseStatement2 consume the typedef name
                    ldd       ,u        load typedef base kind
                    bra       TypeSpecReturn return

ReturnDefaultType   ldd       ,s        load the parsed type code
                    std       [$1e,s]   return type to caller
                    clra                clear high byte
                    clrb                clear low byte
                    std       [$20,s]   clear attribute return
                    ldd       $02,s     load result kind
TypeSpecReturn      leas      $1a,s     drop the local frame
                    puls      pc,u      restore U and return

ParseDeclarator     pshs      u         save U (declarator parser)
                    ldd       #$FFAA    stack limit constant
                    lbsr      stkcheck  check stack space
                    leas      -$0C,s    allocate local frame
                    clra                clear high byte
                    clrb                clear low byte
                    std       [$10,s]   clear output type pointer
                    std       $0a,s     clear accumulated type
                    bra       DeclaratorTop enter the pointer loop

PointerLoop         ldd       $0a,s     load accumulated type
                    pshs      d         push it
                    lbsr      TypeAddLevel build pointer-to type
                    leas      $02,s     drop the argument
                    std       $0a,s     save updated type
                    lbsr      ParseStatement2 get next token
DeclaratorTop       ldd       $003F     D = current token
                    cmpd      #$0042    is it a pointer star
                    beq       PointerLoop yes, another pointer level
                    ldd       $003F     D = current token
                    cmpd      #$0034    is it an identifier
                    bne       CheckGroupParen no, check for group/params
                    ldd       $0041     D = identifier symbol
                    std       [$10,s]   return the declared name
                    lbsr      ParseStatement2 consume the name
                    bra       CheckFuncParams check for function/array suffix

CheckGroupParen     ldd       $003F     D = current token
                    cmpd      #$002D    is it a grouping paren
                    bne       CheckFuncParams no, check for params
                    lbsr      ParseStatement2 consume the open paren
                    ldd       $0031     load nesting level
                    addd      #$0001    increment it
                    std       $0031     save it
                    ldd       $14,s     push arg
                    pshs      d         onto the stack
                    ldd       $14,s     push arg
                    pshs      d         onto the stack
                    ldd       $14,s     push arg
                    pshs      d         onto the stack
                    lbsr      ParseDeclarator parse nested declarator (recurse)
                    leas      $06,s     drop the args
                    std       $14,s     save the result
                    ldd       $0031     load nesting level
                    addd      #$FFFF    decrement it
                    std       $0031     save it
                    ldd       #$002E    expected closing paren token
                    pshs      d         push it
                    lbsr      ExpectToken expect the close paren
                    leas      $02,s     drop the argument
CheckFuncParams     ldd       $003F     D = current token
                    cmpd      #$002D    is it a function paren
                    bne       ArraySetup no, check for array
                    ldd       $0a,s     load current type
                    aslb                shift low byte left
                    rola                rotate into high byte
                    aslb                shift low byte again
                    rola                rotate into high byte
                    addd      #$0030    mark as function type
                    std       $0a,s     save the type
                    ldd       $0031     load nesting level
                    bne       NestedParams nested, use local scope
                    leax      >$0027,y  point to parameter buffer
                    pshs      x         push it
                    lbsr      ParseEnumMembers parse the parameter list
                    bra       AfterParams continue after params

NestedParams        leax      ,s        push it
                    pshs      x         parse the parameter list
                    lbsr      ParseEnumMembers drop the argument
                    leas      $02,s     address of local
                    leax      ,s        push it
                    pshs      x         discard nested params
                    lbsr      FreeLocalSymbols drop the argument
AfterParams         leas      $02,s     finish the declarator
                    lbra      FinishDeclarator

ArraySetup          clra                clear high byte
                    clrb                clear low byte
                    std       $06,s     clear array list head
                    std       $04,s     clear dimension count
                    std       $02,s     clear list tail
                    ldd       GlbNestDepth save nesting depth
                    std       $08,s     onto the frame
                    clra                clear high byte
                    clrb                clear low byte
                    std       GlbNestDepth reset nesting depth
                    lbra      ArrayDimTop enter the array loop

ArrayDimLoop        ldd       $0a,s     load current type
                    aslb                shift low byte left
                    rola                rotate into high byte
                    aslb                shift low byte again
                    rola                rotate into high byte
                    addd      #$0020    mark as array type
                    std       $0a,s     save the type
                    lbsr      ParseStatement2 consume the open bracket
                    ldd       #$0004    allocate a 4 byte node
                    pshs      d         onto the stack
                    lbsr      AllocMem  allocate the dimension node
                    leas      $02,s     drop the argument
                    tfr       d,u       U = the new node
                    ldd       $04,s     load dimension count
                    bne       ParseDimSize not the first, need a size
                    ldd       $003F     D = current token
                    cmpd      #$002C    is it a closing bracket
                    bne       ParseDimSize no, parse a size
                    clra                clear high byte
                    clrb                unspecified dimension = 0
                    bra       StoreDim  store the dimension

ParseDimSize        clra                clear high byte
                    clrb                clear low byte
                    pshs      d         push it
                    lbsr      ParseConstExpr parse constant dimension expr
                    leas      $02,s     drop the argument
StoreDim            std       ,u        store dimension into node
                    ldd       $06,s     load list head
                    beq       SetDimListHead empty list
                    ldx       $06,s     X = list tail
                    stu       $02,x     append the node
                    bra       AfterDimLink continue

SetDimListHead      stu       $02,s     update the list tail
AfterDimLink        stu       $06,s     expected closing bracket token
                    ldd       #$002C    push it
                    pshs      d         expect the close bracket
                    lbsr      ExpectToken drop the argument
                    leas      $02,s     load dimension count
                    ldd       $04,s     increment it
                    addd      #$0001    save it
                    std       $04,s     D = current token
ArrayDimTop         ldd       $003F     is it an open bracket
                    cmpd      #$002B    yes, another dimension
                    lbeq      ArrayDimLoop restore saved nesting depth
                    ldd       $08,s     back into the global
                    std       GlbNestDepth load array list head
                    ldd       $02,s     none, done
                    beq       FinishDeclarator load existing suffix chain
                    ldd       [$12,s]   link into new node
                    std       $02,u     load list head
                    ldd       $02,s     store into the output
                    std       [$12,s]   push accumulated type
FinishDeclarator    ldd       $0a,s     onto the stack
                    pshs      d         push arg
                    ldd       $16,s     onto the stack
                    pshs      d         finalize declarator type
                    bsr       FinalizeDeclType drop the args
                    leas      $04,s     drop the locals
                    leas      $0C,s     restore U and return
                    puls      pc,u

FinalizeDeclType    pshs      u         save U (finalize entry)
                    ldd       #$FFBC    stack limit constant
                    lbsr      stkcheck  check stack space
                    leas      -$02,s    allocate a local
                    ldd       $06,s     load the type chain
                    std       ,s        save a working copy
                    bra       DerivationTop enter the walk loop

DerivationLoop      ldd       ,s        load the type code
                    pshs      d         push it
                    ldd       #$0002    level width
                    lbsr      ShiftRightSigned extract next derivation level
                    std       ,s        save remaining chain
                    ldd       $08,s     load the argument
                    pshs      d         push it
                    ldd       #$0002    level width
                    lbsr      ShiftLeft apply derivation to type
                    std       $08,s     save updated type
DerivationTop       ldd       ,s        load the type code
                    clra                keep only the low byte
                    andb      #$30      mask the derivation bits
                    bne       DerivationLoop more derivations, loop
                    ldd       $06,s     load the final type
                    addd      $08,s     add saved base offset to result
                    lbra      RetPop2   return with result

CalcTypeSize        pshs      u         save caller frame pointer
                    ldd       #$FFB2    reserve for stack check
                    lbsr      stkcheck  check stack room
                    ldu       $04,s     U = type node pointer
                    leas      -$04,s    allocate local words
                    ldd       ,u        load type word
                    std       $02,s     save type word
                    clra                clear high byte
                    andb      #$0f      isolate base type nibble
                    tfr       d,x       X = base type code
                    bra       SizeDispatch dispatch on base type

SizeOne             ldd       #$0001    size = 1 for char
                    bra       StoreSize2 go store size

SizeTwo             ldd       #$0002    size = 2 for int
                    bra       StoreSize2 go store size

SizeFour            ldd       #$0004    size = 4 for long
                    bra       StoreSize2 go store size

SizeEight           ldd       #$0008    size = 8 for double
                    bra       StoreSize2 go store size

SizeFromArg         ldd       $0C,s     size from caller argument
                    bra       StoreSize2 go store size

SizeZero            clra                clear high byte
                    clrb                size = 0 for void
StoreSize2          std       ,s        store computed size
                    bra       ApplySize apply size to node

SizeDispatch        cmpx      #$0002    base type char
                    beq       SizeOne   take size 1
                    cmpx      #$0001    base type int
                    beq       SizeTwo   take size 2
                    cmpx      #$0007    unsigned int type
                    lbeq      SizeTwo   take size 2
                    cmpx      #$0008    long type
                    beq       SizeFour  take size 4
                    cmpx      #$0005    float type
                    lbeq      SizeFour  take size 4
                    cmpx      #$0006    double type
                    beq       SizeEight take size 8
                    cmpx      #$0003    struct type
                    beq       SizeFromArg take arg size
                    cmpx      #$0004    union type
                    lbeq      SizeFromArg take arg size
                    cmpx      #$000A    void type
                    beq       SizeZero  take size 0
ApplySize           ldd       ,s        load computed size
                    beq       UseArgSize zero means use arg size
                    ldd       ,s        reload nonzero size
                    bra       StoreSizeFields store size fields

UseArgSize          ldd       $0C,s     use caller-supplied size
StoreSizeFields     std       $02,u     store size into node
                    ldd       $0a,s     load align/flags arg
                    std       $04,u     store align into node
                    pshs      d         push flags
                    ldd       $02,s     type word
                    pshs      d         push type word
                    ldd       $06,s     storage class
                    pshs      d         push storage class
                    bsr       ResolveTypeSize resolve storage size
                    leas      $06,s     drop pushed args
                    leas      $04,s     drop local words
                    puls      pc,u      return

ResolveTypeSize     pshs      u         save caller frame pointer
                    ldd       #$FFB8    reserve for stack check
                    lbsr      stkcheck  check stack room
                    ldu       $08,s     U = type node
                    leas      -$02,s    allocate local word
                    ldd       $06,s     load storage flags
                    clra                clear high byte
                    andb      #$30      isolate storage bits
                    cmpd      #$0010    register storage class
                    beq       SizePointer pointer size 2
                    ldd       $06,s     reload storage flags
                    clra                clear high byte
                    andb      #$30      isolate storage bits
                    cmpd      #$0030    absolute storage class
                    bne       CheckArrayClass2 not pointer-like
SizePointer         ldd       #$0002    size = 2 for pointer
                    lbra      RetPop2   return size

CheckArrayClass2    ldd       $06,s     reload storage flags
                    clra                clear high byte
                    andb      #$30      isolate storage bits
                    cmpd      #$0020    array storage class
                    bne       ReturnBaseSize not array, return size
                    ldd       #$0001    running total = 1
                    std       ,s        store running total
ArrayDimLoop2       ldd       ,s        load running total
                    pshs      d         push total
                    ldd       ,u        element type word
                    lbsr      MulInt32  multiply by dimension
                    std       ,s        update running total
                    ldu       $02,u     follow to element type
                    ldd       $06,s     current type word
                    pshs      d         push type word
                    lbsr      TypeRemoveLevel peel one array level
                    leas      $02,s     drop arg
                    std       $06,s     store reduced type
                    clra                clear high byte
                    andb      #$30      isolate storage bits
                    cmpd      #$0020    still an array
                    beq       ArrayDimLoop2 loop for next dimension
                    ldd       ,s        total element count
                    pshs      d         push count
                    ldd       $08,s     element type word
                    clra                clear high byte
                    andb      #$30      isolate storage bits
                    cmpd      #$0010    pointer element
                    bne       ElemBaseSize use base element size
                    ldd       #$0002    pointer element size 2
                    bra       MultElemSize multiply total

ElemBaseSize        ldd       $0a,s     base element size
MultElemSize        lbsr      MulInt32  total = count times elem size
                    lbra      RetPop2   return total size

ReturnBaseSize      ldd       $08,s     return base size
                    lbra      RetPop2   return

FreeLocalSymbols    pshs      u         save caller frame pointer
                    ldd       #$FF74    reserve for stack check
                    lbsr      stkcheck  check stack room
                    leas      -$40,s    allocate work buffer
                    ldu       [$44,s]   U = symbol list head
                    lbra      ScopeLoopTest enter loop test

ScopeSymLoop        ldd       $10,u     load next symbol pointer
                    std       $3C,s     save next pointer
                    ldd       ,u        load symbol type
                    cmpd      #$0009    is it a label
                    bne       CheckSymTag not a label
                    ldd       $0a,u     load label flags
                    clra                clear high byte
                    andb      #$01      isolate defined bit
                    bne       CheckSymTag skip if defined
                    ldd       #$0008    error message length
                    pshs      d         push length
                    pshs      u         push symbol pointer
                    ldd       #$0014    name field offset
                    addd      ,s++      point at label name
                    pshs      d         push name pointer
                    leax      MsgLabelUndefined,pcr label undefined message
                    pshs      x         push message pointer
                    leax      $06,s     point at buffer
                    pshs      x         push buffer pointer
                    lbsr      StrCpy    build message string
                    leas      $04,s     drop args
                    pshs      d         push result
                    lbsr      StrNCat   append label name
                    leas      $06,s     drop args
                    pshs      d         push result
                    lbsr      BuildMsgBuf report error
                    leas      $02,s     drop arg
CheckSymTag         ldx       $08,u     load symbol tag
                    bra       IsTagSym  check tag kind

DecTagCount         ldd       SetupArgv struct/union nesting count
                    addd      #$FFFF    decrement count
                    std       SetupArgv store count
                    bra       UnlinkSym continue unlink

IsTagSym            cmpx      #$006F    struct tag
                    beq       DecTagCount decrement tag count
                    cmpx      #$0076    union tag
                    lbeq      DecTagCount decrement tag count
UnlinkSym           ldd       $0e,u     load hash/scope link
                    std       $3e,s     save link
                    cmpd      GlbMemLow below hash table
                    bls       UnlinkFromBucket treat as bucket unlink
                    ldd       $3e,s     reload link
                    cmpd      GlbMemHigh above hash table
                    bcc       UnlinkFromBucket treat as bucket unlink
                    pshs      u         symbol in nested chain
                    lbsr      FreeBlk   unlink from chain
                    leas      $02,s     drop arg
                    bra       NextScopeSym go to next symbol

UnlinkFromBucket    cmpu      [$3e,s]   symbol head of bucket
                    bne       BucketFirst not head
                    ldd       $12,u     load next in bucket
                    std       [$3e,s]   bucket head = next
                    bra       FreeSymbol free the symbol

BucketFirst         ldd       [$3e,s]   load first in bucket
                    bra       ChainAdvance start chain walk

ChainWalkLoop       ldx       $3e,s     predecessor pointer
                    ldd       $12,x     load its next
ChainAdvance        std       $3e,s     advance walk pointer
                    ldx       $3e,s     reload pointer
                    cmpu      $12,x     found predecessor
                    bne       ChainWalkLoop keep walking chain
                    ldd       $12,u     symbol's next pointer
                    ldx       $3e,s     predecessor pointer
                    std       $12,x     unlink symbol
FreeSymbol          ldd       $0062     free list head
                    std       $12,u     link symbol to free list
                    stu       $0062     free list = symbol
NextScopeSym        ldu       $3C,s     load saved next symbol
ScopeLoopTest       stu       -$02,s    save/test current symbol
                    lbne      ScopeSymLoop loop while symbols remain
                    clra                clear high byte
                    clrb                clear low byte
                    std       [$44,s]   clear list head
                    leas      $40,s     release work buffer
                    puls      pc,u      return

ErrCannotEvalSize   pshs      u         save caller frame pointer
                    ldd       #$FFBA    reserve for stack check
                    lbsr      stkcheck  check stack room
                    leax      MsgCannotEvalSize,pcr cannot-evaluate-size message
                    bra       ReportErr go report

ErrIdentMissing     pshs      u         save caller frame pointer
                    ldd       #$FFBA    reserve for stack check
                    lbsr      stkcheck  check stack room
                    leax      MsgIdentMissing,pcr identifier-missing message
ReportErr           pshs      x         push message pointer
                    lbsr      BuildMsgBuf report error
RetPop2             leas      $02,s     drop local word
                    puls      pc,u      return

MsgTooManyBrackets  fcc       /too many brackets/
                    fcb       $00
MsgFuncHdrMissing   fcc       /function header missing/
                    fcb       $00
MsgStorageErr1      fcc       /storage error/
                    fcb       $00
MsgFuncTypeErr      fcc       /function type error/
                    fcb       $00
MsgArgStorage       fcc       /argument storage/
                    fcb       $00
MsgArgErr           fcc       /argument error/
                    fcb       $00
MsgNotArg           fcc       /not an argument/
                    fcb       $00
MsgStorageErr2      fcc       /storage error/
                    fcb       $00
MsgDeclMismatch     fcc       /declaration mismatch/
                    fcb       $00
MsgFuncUnfinished   fcc       /function unfinished/
                    fcb       $00
MsgNamedTwice       fcc       /named twice/
                    fcb       $00
MsgNameClash        fcc       /name clash/
                    fcb       $00
MsgStructSyntax     fcc       /struct syntax/
                    fcb       $00
MsgStructMemberMismatch fcc       /struct member mismatch/
                    fcb       $00
MsgUndefStruct      fcc       /undefined structure/
                    fcb       $00
MsgLabelUndefined   fcc       /label undefined : /
                    fcb       $00
MsgCannotEvalSize   fcc       /cannot evaluate size/
                    fcb       $00
MsgIdentMissing     fcc       /identifier missing/
                    fcb       $00
GenTestExpr         pshs      u         save caller frame pointer
                    ldd       #$FFAE    reserve for stack check
                    lbsr      stkcheck  check stack room
                    ldu       $04,s     U = expression node
                    leas      -$04,s    allocate local words
                    ldd       $06,u     load node operator
                    std       $02,s     save operator
                    tfr       d,x       X = operator code
                    lbra      GenExprDispatch2 dispatch on operator

GenLogAnd           ldd       #$0001    sense = true
                    pshs      d         push sense
                    ldd       $0e,s     caller true label
                    pshs      d         push label
                    ldd       $000B     label counter
                    addd      #$0001    allocate new label
                    std       $000B     store counter
                    std       $04,s     new false label
                    pshs      d         push label
                    ldd       $0a,u     left operand
                    pshs      d         push operand
