StrToFpDone         puls      pc,u      restore U and return

BignumMul10AddDigit ldx       $02,s     X = pointer to 7-byte accumulator
                    leas      -$08,s    allocate 8-byte scratch
                    ldd       $05,x     load low word of value
                    aslb                shift low byte left (times two)
                    rola                rotate carry into high byte
                    std       $05,x     store doubled low word
                    std       $05,s     save times-two copy on stack
                    ldd       $03,x     next word up
                    rolb                continue shift with carry
                    rola                rotate high with carry
                    std       $03,x     store doubled word
                    std       $03,s     save times-two copy
                    ldd       $01,x     load next word
                    rolb                shift with carry
                    rola                rotate high with carry
                    std       $01,x     store doubled word
                    std       $01,s     save times-two copy
                    lda       ,x        load top byte
                    rola                shift top with carry
                    sta       ,x        store doubled top byte
                    sta       ,s        save times-two copy top byte
                    asl       $06,x     shift value left again (now times four)
                    rol       $05,x     propagate carry up
                    rol       $04,x     propagate carry up
                    rol       $03,x     propagate carry up
                    rol       $02,x     propagate carry up
                    rol       $01,x     propagate carry up
                    rol       ,x        propagate carry into top
                    bcs       Mul10Overflow overflow means return error
                    asl       $06,x     shift value left again (now times eight)
                    rol       $05,x     propagate carry up
                    rol       $04,x     propagate carry up
                    rol       $03,x     propagate carry up
                    rol       $02,x     propagate carry up
                    rol       $01,x     propagate carry up
                    rol       ,x        propagate carry into top
                    bcs       Mul10Overflow overflow means return error
                    ldd       $05,x     times-eight low word
                    addd      $05,s     add times-two low word (gives times ten)
                    std       $05,x     store combined low word
                    ldd       $03,x     next word
                    adcb      $04,s     add with carry
                    adca      $03,s     add with carry
                    std       $03,x     store word
                    ldd       $01,x     next word
                    adcb      $02,s     add with carry
                    adca      $01,s     add with carry
                    std       $01,x     store word
                    ldb       ,x        top byte
                    adcb      ,s        add top with carry
                    stb       ,x        store top byte
                    bcs       Mul10Overflow overflow means return error
                    ldb       $0d,s     get the digit argument
                    andb      #$0f      mask to a single digit
                    clra                clear high byte
                    addd      $05,x     add digit to low word
                    std       $05,x     store low word
                    ldd       #$0000    zero for carry propagation
                    adcb      $04,x     propagate carry up
                    adca      $03,x     propagate carry up
                    std       $03,x     store word
                    ldd       #$0000    zero for carry propagation
                    adcb      $02,x     propagate carry up
                    adca      $01,x     propagate carry up
                    std       $01,x     store word
                    lda       #$00      zero for carry propagation
                    adca      ,x        carry into top byte
                    sta       ,x        store top byte
                    bcs       Mul10Overflow overflow means return error
                    leas      $08,s     release scratch
                    clra                clear high byte of result
                    clrb                clear low byte (return zero success)
                    rts                 return to caller

Mul10Overflow       ldd       #$0001    return 1 to signal overflow
                    leas      $08,s     release scratch
                    rts                 return to caller

PrintfToBuf         pshs      u         save caller U
                    leax      $0253,y   X = internal output buffer
                    stx       GlbOutPtr set output destination
                    ldd       #$0001    mode 1 (file style output)
                    std       $0076     store output mode
                    leax      $06,s     X = address of first vararg
                    pshs      x         push the vararg pointer
                    ldd       $06,s     D = format string pointer
                    bra       PrintfTail join common printf tail

fprintf             pshs      u         save caller U
                    ldd       $04,s     D = FILE pointer
                    std       GlbOutPtr set output destination
                    ldd       #$0001    mode 1 (file style output)
                    std       $0076     store output mode
                    leax      $08,s     X = vararg list address
                    pshs      x         push the vararg pointer
                    ldd       $08,s     D = format string pointer
PrintfTail          pshs      d         push format string pointer
                    bsr       doprnt    run the formatter
                    leas      $04,s     drop pushed args
                    puls      pc,u      restore U and return

Sprintf             pshs      u         save caller U
                    ldd       $04,s     D = destination buffer
                    std       GlbOutPtr set output destination
                    ldd       #$0002    mode 2 (string output)
                    std       $0076     store output mode
                    leax      $08,s     X = vararg list address
                    pshs      x         push the vararg pointer
                    ldd       $08,s     D = format string pointer
                    pshs      d         push format string pointer
                    bsr       doprnt    run the formatter
                    leas      $04,s     drop pushed args
                    clra                clear high byte
                    clrb                clear low byte
                    stb       [GlbOutPtr,y] null-terminate the output string
                    puls      pc,u      restore U and return

doprnt              pshs      u         save caller U
                    ldu       $04,s     U = format string pointer
                    leas      -$0b,s    allocate local variables
                    bra       FormatLoop enter the format loop

OutputLiteralChar   ldb       $08,s     B = current character
                    lbeq      DoPrntDone null terminator ends formatting
                    ldb       $08,s     reload the character
                    sex                 sign-extend to D
                    pshs      d         push the character
                    lbsr      PutChar   output the character
                    leas      $02,s     drop the pushed char
FormatLoop          ldb       ,u+       get next format character
                    stb       $08,s     save as current character
                    cmpb      #$25      is it a percent
                    bne       OutputLiteralChar no, print it literally
                    ldb       ,u+       get char after the percent
                    stb       $08,s     save as current character
                    clra                clear high byte
                    clrb                clear low byte
                    std       $02,s     precision = 0
                    std       $06,s     width = 0
                    ldb       $08,s     B = flag char
                    cmpb      #$2d      is it a minus (left justify)
                    bne       NoLeftFlag no left-justify flag
                    ldd       #$0001    flag value 1
                    std       $0072     set left-justify flag
                    ldb       ,u+       consume flag, next char
                    stb       $08,s     save as current character
                    bra       CheckZeroPad continue to pad selection

NoLeftFlag          clra                clear high byte
                    clrb                clear low byte
                    std       $0072     clear left-justify flag
CheckZeroPad        ldb       $08,s     B = current char
                    cmpb      #$30      is it a zero
                    bne       SpacePad  no, use space padding
                    ldd       #$0030    pad char = zero
                    bra       StorePadChar store the pad char

SpacePad            ldd       #$0020    pad char = space
StorePadChar        std       $0074     store the pad character
                    bra       WidthScan enter the width scan

AccumWidthDigit     ldd       $06,s     D = current width value
                    pshs      d         push width
                    ldd       #$000A    multiplier ten
                    lbsr      MulInt32  width times ten
                    pshs      d         push scaled width
                    ldb       $0a,s     B = digit character
                    sex                 sign-extend
                    addd      #$FFD0    subtract ASCII zero
                    addd      ,s++      add to width times ten
                    std       $06,s     store new width
                    ldb       ,u+       next format character
                    stb       $08,s     save as current character
WidthScan           ldb       $08,s     B = current char
                    sex                 extend to table index
                    leax      $00BA,y   X = character class table
                    leax      d,x       index by character
                    ldb       ,x        B = class code
                    cmpb      #$6b      is it a digit class
                    beq       AccumWidthDigit yes, accumulate width digit
                    ldb       $08,s     B = current char
                    cmpb      #$2e      is it a dot
                    bne       NoPrecision no precision follows
                    ldd       #$0001    flag value 1
                    std       $04,s     set precision-present flag
                    bra       PrecisionScan enter precision scan

AccumPrecDigit      ldd       $02,s     D = current precision value
                    pshs      d         push precision
                    ldd       #$000A    multiplier ten
                    lbsr      MulInt32  precision times ten
                    pshs      d         push scaled precision
                    ldb       $0a,s     B = digit character
                    sex                 sign-extend
                    addd      #$FFD0    subtract ASCII zero
                    addd      ,s++      add to precision times ten
                    std       $02,s     store new precision
PrecisionScan       ldb       ,u+       next format character
                    stb       $08,s     save as current character
                    ldb       $08,s     B = current char
                    sex                 extend to table index
                    leax      $00BA,y   X = character class table
                    leax      d,x       index by character
                    ldb       ,x        B = class code
                    cmpb      #$6b      is it a digit class
                    beq       AccumPrecDigit yes, accumulate precision digit
                    bra       GetConvChar done, get conversion char

NoPrecision         clra                clear high byte
                    clrb                clear low byte
                    std       $04,s     clear precision-present flag
GetConvChar         ldb       $08,s     B = conversion specifier
                    sex                 sign-extend
                    tfr       d,x       X = conversion char
                    lbra      DispatchConv dispatch the conversion

ConvDecimal         ldd       $06,s     push width for field output
                    pshs      d         push it
                    ldx       $13,s     X = vararg pointer
                    leax      $02,x     advance past the int arg
                    stx       $13,s     save vararg pointer
                    ldd       -$02,x    D = the int argument
                    pshs      d         push value
                    lbsr      IntToDecStr convert int to decimal string
                    bra       NumFieldTail go output the number field

ConvHex             ldd       $06,s     push width for field output
                    pshs      d         push it
                    ldx       $13,s     X = vararg pointer
                    leax      $02,x     advance past the int arg
                    stx       $13,s     save vararg pointer
                    ldd       -$02,x    D = the int argument
                    pshs      d         push value
                    lbsr      IntToHexStr convert int to hex string
NumFieldTail        std       ,s        save the result string pointer
                    lbra      OutputStrField output the number field

ConvChar            ldx       $11,s     X = vararg pointer
                    leax      $02,x     advance past the char arg
                    stx       $11,s     save vararg pointer
                    ldd       -$02,x    D = the char argument
                    lbra      OutputCharField output the single character

ConvString          ldx       $11,s     X = vararg pointer
                    leax      $02,x     advance past the string arg
                    stx       $11,s     save vararg pointer
                    ldd       -$02,x    D = the string pointer
                    std       $09,s     save string pointer
                    ldd       $04,s     precision present
                    beq       PrintFullStr none, print the full string
                    ldd       $09,s     reload string pointer
                    std       $04,s     reuse slot as scan pointer
                    bra       StrScanCount start precision-limited scan

StrScanLoop         ldb       [$09,s]   B = current string byte
                    beq       PrintTruncStr null ends the scan
                    ldd       $09,s     scan pointer
                    addd      #$0001    advance one byte
                    std       $09,s     save scan pointer
StrScanCount        ldd       $02,s     precision counter
                    addd      #$FFFF    decrement it
                    std       $02,s     store counter
                    subd      #$FFFF    test the original value
                    bne       StrScanLoop nonzero means more allowed
PrintTruncStr       ldd       $06,s     push width
                    pshs      d         push it
                    ldd       $0b,s     end scan pointer
                    subd      $06,s     compute truncated length
                    pshs      d         push length
                    ldd       $08,s     push string pointer
                    pshs      d         push it
                    lbsr      EmitCountedField output the truncated string field
                    leas      $06,s     drop args
                    bra       ConvDone2 return to format loop

PrintFullStr        ldd       $06,s     push width
                    pshs      d         push it
                    ldd       $0b,s     push string pointer
                    pshs      d         push it
OutputStrField      lbsr      OutputStrWithWidth output string padded to width
                    leas      $04,s     drop args
ConvDone2           lbra      FormatLoop back to the format loop

ConvLiteral         ldb       $08,s     B = literal conversion char
                    sex                 sign-extend
OutputCharField     pshs      d         push the character
                    lbsr      PutChar   output the character
                    leas      $02,s     drop the pushed char
                    lbra      FormatLoop back to the format loop

DispatchConv        cmpx      #$0064    is conversion a d
                    lbeq      ConvDecimal decimal handler
                    cmpx      #$0078    is it an x
                    lbeq      ConvHex   hex handler
                    cmpx      #$0063    is it a c
                    lbeq      ConvChar  char handler
                    cmpx      #$0073    is it an s
                    lbeq      ConvString string handler
                    bra       ConvLiteral unknown, print literally

DoPrntDone          leas      $0b,s     release doprnt locals
                    puls      pc,u      restore U and return

IntToDecStr         pshs      u,d       save U and the value
                    leax      $088a,y   X = number buffer
                    stx       ,s        save buffer pointer
                    ldd       $06,s     D = the integer value
                    bge       ConvertDecDigits non-negative, convert directly
                    ldd       $06,s     reload value
                    nega                negate the value
                    negb                negate low byte
                    sbca      #$00      finish two's complement negate
                    std       $06,s     store absolute value
                    bge       StoreSign negation succeeded, add sign
                    leax      IntMinStr,pcr X = the minus-32768 literal
                    pshs      x         push it
                    leax      $088a,y   X = number buffer
                    pshs      x         push it
                    lbsr      StrCpy    copy literal into buffer
                    leas      $04,s     drop args
                    lbra      FieldEmitDone return the buffer

StoreSign           ldd       #$002D    minus sign character
                    ldx       ,s        buffer pointer
                    leax      $01,x     advance
                    stx       ,s        save pointer
                    stb       -$01,x    store the minus sign
ConvertDecDigits    ldd       $06,s     reload value
                    pshs      d         push value
                    ldd       $02,s     buffer pointer
                    pshs      d         push it
                    bsr       UtoaDecimal convert the decimal digits
                    leas      $04,s     drop args
                    leax      $088a,y   X = buffer start
                    tfr       x,d       D = buffer pointer
                    lbra      FieldEmitDone return the result

UtoaDecimal         pshs      u,y,x,d   save regs and allocate locals
                    ldu       $0a,s     U = output pointer
                    clra                clear high byte
                    clrb                clear low byte
                    std       $02,s     nonzero-seen flag = 0
                    clra                clear high byte
                    clrb                clear low byte
                    std       ,s        digit counter = 0
                    bra       MagnitudeLoop enter magnitude search

AdjustMagnitude     ldd       ,s        digit counter
                    addd      #$0001    increment it
                    std       ,s        store counter
                    ldd       $0C,s     value
                    subd      $023e,y   subtract a power of ten
                    std       $0C,s     store value
MagnitudeLoop       ldd       $0C,s     value
                    blt       AdjustMagnitude still negative, keep adjusting
                    leax      $023e,y   X = power-of-ten table
                    stx       $04,s     save table pointer
                    bra       DecDigitLoop2 enter digit loop

CountDigit          ldd       ,s        digit counter
                    addd      #$0001    increment digit
                    std       ,s        store counter
DigitSubLoop        ldd       $0C,s     value
                    subd      [$04,s]   subtract the current power
                    std       $0C,s     store value
                    bge       CountDigit still fits, count again
                    ldd       $0C,s     value went negative
                    addd      [$04,s]   add the power back
                    std       $0C,s     store value
                    ldd       ,s        the digit value
                    beq       CheckLeadingZero zero digit
                    ldd       #$0001    flag value 1
                    std       $02,s     mark a nonzero digit seen
CheckLeadingZero    ldd       $02,s     nonzero-seen flag
                    beq       NextPower suppress leading zeros
                    ldd       ,s        the digit
                    addd      #$0030    convert to ASCII
                    stb       ,u+       store digit character
NextPower           clra                clear high byte
                    clrb                clear low byte
                    std       ,s        reset digit counter
                    ldd       $04,s     table pointer
                    addd      #$0002    advance to next power
                    std       $04,s     store pointer
DecDigitLoop2       ldd       $04,s     table pointer
                    cmpd      $0001     reached end-of-table marker
                    bne       DigitSubLoop more digits to extract
                    ldd       $0C,s     remaining value is last digit
                    addd      #$0030    convert to ASCII
                    stb       ,u+       store last digit
                    clra                clear high byte
                    clrb                clear low byte
                    stb       ,u        null-terminate the string
                    ldd       $0a,s     return the output pointer
                    leas      $06,s     release locals
                    puls      pc,u      restore U and return

IntToHexStr         pshs      u,x,d     save regs and value
                    leax      $088a,y   X = number buffer
                    stx       $02,s     save buffer pointer
                    leau      $0894,y   U = scratch buffer end
HexNibbleLoop       ldd       $08,s     the value
                    clra                clear high byte
                    andb      #$0f      isolate the low nibble
                    std       ,s        save nibble
                    pshs      d         push nibble copy
                    ldd       $02,s     reload nibble value
                    cmpd      #$0009    is nibble above nine
                    ble       HexDigitBase2 no, use digit base
                    ldd       #$0057    hex letter base (a minus ten)
                    bra       StoreHexChar store the hex char

HexDigitBase2       ldd       #$0030    digit base zero
StoreHexChar        addd      ,s++      add nibble and pop
                    stb       ,u+       store hex character
                    ldd       $08,s     the value
                    lsra                shift right one bit
                    rorb                rotate low
                    lsra                shift right one bit
                    rorb                rotate low
                    lsra                shift right one bit
                    rorb                rotate low
                    lsra                shift right one bit
                    rorb                rotate low (shifted right four)
                    anda      #$0f      mask unsigned shift result
                    std       $08,s     store shifted value
                    bne       HexNibbleLoop more nibbles remain
                    bra       HexReverseLoop begin reverse copy

HexReverseCopy      ldb       ,u        B = char from scratch
                    ldx       $02,s     output buffer pointer
                    leax      $01,x     advance
                    stx       $02,s     save pointer
                    stb       -$01,x    store reversed char
HexReverseLoop      leau      -$01,u    step back through scratch
                    pshs      u         push scratch pointer
                    leax      $0894,y   X = scratch start
                    cmpx      ,s++      reached the start
                    bls       HexReverseCopy copy next char
                    clra                clear high byte
                    clrb                clear low byte
                    stb       [$02,s]   null-terminate the buffer
                    leax      $088a,y   X = result buffer
                    tfr       x,d       D = buffer pointer
                    lbra      PutCharFileDone return the result

OutputStrWithWidth  pshs      u         save caller U
                    ldu       $06,s     U = string pointer
                    leas      -$02,s    allocate local
                    ldd       $06,s     string pointer
                    pshs      d         push it
                    lbsr      StrLen    compute string length
                    leas      $02,s     drop arg
                    nega                negate the length
                    negb                negate low byte
                    sbca      #$00      finish two's complement negate
                    leau      d,u       back up pointer by length
                    ldd       $0072     left-justify flag
                    bne       PadStrNext left-justified output path
                    bra       PadLeadTest right-justified output path

EmitPadChar         ldd       $0074     load the pad character
                    pshs      d         push the fill char to emit
                    lbsr      PutChar   emit one fill character
                    leas      $02,s     drop the pushed arg
PadLeadTest         tfr       u,d       D = remaining leading pad count
                    leau      -$01,u    decrement pad counter
                    std       -$02,s    save updated count
                    bgt       EmitPadChar loop while pad remains
                    bra       PadStrNext done padding, emit the string

PadStrLoop          ldd       ,s        get current string char
                    pshs      d         push as putc arg
                    lbsr      PutChar   emit the character
                    leas      $02,s     drop the arg
PadStrNext          ldx       $06,s     X = string pointer
                    leax      $01,x     advance the pointer
                    stx       $06,s     save advanced pointer
                    ldb       -$01,x    B = char just consumed
                    sex                 sign-extend to word
                    std       ,s        save the current char
                    bne       PadStrLoop loop until nul terminator
                    ldd       $0072     left-justify flag
                    lbeq      FieldEmitDone right-justified, skip trailing pad
                    bra       PadTrailTest emit trailing pad

PadTrailLoop        ldd       $0074     fill char
                    pshs      d         push putc arg
                    lbsr      PutChar   emit the fill char
                    leas      $02,s     drop the arg
PadTrailTest        tfr       u,d       D = remaining trailing pad
                    leau      -$01,u    decrement counter
                    std       -$02,s    save the count
                    bgt       PadTrailLoop loop while pad remains
                    lbra      FieldEmitDone padding complete

EmitCountedField    pshs      u         save caller U
                    ldu       $04,s     U = source buffer pointer
                    leas      -$02,s    reserve local pad counter
                    ldd       $0a,s     field width
                    subd      $08,s     minus the string length
                    std       ,s        store pad count
                    ldd       $0072     left-justify flag
                    bne       CntStrTest left-justified, skip leading pad
                    bra       CntLeadTest do the leading pad

CntLeadLoop         ldd       $0074     fill char
                    pshs      d         push putc arg
                    bsr       PutChar   emit the fill char
                    leas      $02,s     drop the arg
CntLeadTest         ldd       ,s        pad count
                    addd      #$FFFF    decrement by one
                    std       ,s        save the count
                    subd      #$FFFF    restore value for the test
                    bgt       CntLeadLoop loop while pad remains
                    bra       CntStrTest leading pad done

CntStrLoop          ldb       ,u+       next source byte
                    sex                 sign-extend
                    pshs      d         push putc arg
                    bsr       PutChar   emit the byte
                    leas      $02,s     drop the arg
CntStrTest          ldd       $08,s     remaining byte count
                    addd      #$FFFF    decrement
                    std       $08,s     save the count
                    subd      #$FFFF    restore value for the test
                    bne       CntStrLoop loop until all bytes emitted
                    ldd       $0072     left-justify flag
                    beq       FieldEmitDone right-justified, done
                    bra       CntTrailTest emit trailing pad

CntTrailLoop        ldd       $0074     fill char
                    pshs      d         push putc arg
                    bsr       PutChar   emit the fill char
                    leas      $02,s     drop the arg
CntTrailTest        ldd       ,s        pad count
                    addd      #$FFFF    decrement
                    std       ,s        save the count
                    subd      #$FFFF    restore value for the test
                    bgt       CntTrailLoop loop while pad remains
FieldEmitDone       leas      $02,s     drop the local
                    puls      pc,u      restore and return

PutChar             pshs      u         save caller U
                    ldd       $0076     output mode
                    cmpd      #$0002    is it sprintf-to-buffer mode
                    bne       PutCharFile no, write to file
                    ldd       $04,s     the character to emit
                    ldx       GlbOutPtr output buffer pointer
                    leax      $01,x     advance the pointer
                    stx       GlbOutPtr save the pointer
                    stb       -$01,x    store char in the buffer
                    bra       PutCharDone2 done

PutCharFile         ldd       GlbOutPtr output file path
                    pshs      d         push it
                    ldd       $06,s     the character
                    pshs      d         push it
                    lbsr      PutByte   write char to the file
PutCharFileDone     leas      $04,s     drop the write args
PutCharDone2        puls      pc,u      restore and return

IntMinStr           fcc       /-32768/
                    fcb       $00
                    pshs      u         save caller U
                    leau      $0246,y   U = start of descriptor table
AllocSlotLoop       ldd       $06,u     entry type field
                    clra                keep only low byte
                    andb      #$03      isolate usage bits
                    lbeq      ReturnEntry free slot found, return it
                    leau      $0d,u     advance to next 13-byte entry
                    pshs      u         save the pointer
                    leax      $0316,y   table end address
                    cmpx      ,s++      compare against end
                    bhi       AllocSlotLoop loop while entries remain
                    ldd       #$00C8    error 200, table full
                    std       $0364,y   store the error code
                    lbra      ReturnNull return null

                    puls      pc,u      restore and return

InitOperandEntry    pshs      u         save caller U
                    ldu       $08,s     U = existing entry pointer
                    bne       EntryReady use it if non-null
                    bsr       $9DED     else allocate a new entry
                    tfr       d,u       U = the new entry
EntryReady          stu       -$02,s    save entry pointer
                    beq       ReturnNull allocation failed, return null
                    ldd       $04,s     operand value
                    std       $08,u     store it in the entry
                    ldx       $06,s     format string pointer
                    ldb       $01,x     second char
                    cmpb      #$2b      is it a plus
                    beq       MarkPointer pointer/register-pair operand
                    ldx       $06,s     reload string pointer
                    ldb       $02,x     third char
                    cmpb      #$2b      is it a plus
                    bne       ClassifyBySize no, classify by size letter
MarkPointer         ldd       $06,u     current type flags
                    orb       #$03      mark pointer/register-pair
                    bra       StoreEntryFlags store the flags

ClassifyBySize      ldd       $06,u     current type flags
                    pshs      d         save them
                    ldb       [$08,s]   deref value to size letter
                    cmpb      #$72      is it r
                    beq       RegSizeCode1 register size code 1
                    ldb       [$08,s]   deref again
                    cmpb      #$64      is it d
                    bne       RegSizeCode2 else size code 2
RegSizeCode1        ldd       #$0001    size code 1
                    bra       CombineHiFlags combine flags

RegSizeCode2        ldd       #$0002    size code 2
CombineHiFlags      ora       ,s+       OR back saved high flags
                    orb       ,s+       OR back saved low flags
StoreEntryFlags     std       $06,u     store combined type flags
                    ldd       $02,u     base offset
                    addd      $0b,u     plus operand size
                    std       $04,u     store end offset
                    std       ,u        and current offset
ReturnEntry         tfr       u,d       return the entry pointer
                    puls      pc,u      restore and return

ReturnNull          clra                return null high
                    clrb                return null low
                    puls      pc,u      restore and return

ParseOperandType    pshs      u         save caller U
                    ldu       $04,s     U = operand entry pointer
                    leas      -$04,s    reserve locals
                    clra                zero
                    clrb                clear flag byte
                    std       ,s        clear flag accumulator
                    ldx       $0a,s     format string pointer
                    ldb       $01,x     second char
                    sex                 extend to word
                    tfr       d,x       X = the char
                    bra       ClassifySecondChar classify second char

IndexedThirdChar    ldx       $0a,s     string pointer
                    ldb       $02,x     third char
                    cmpb      #$2b      is it a plus
                    bne       ModeIndexed no
                    ldd       #$0007    mode 7, indexed post-increment
                    bra       StoreMode store mode

ModeIndexed         ldd       #$0004    mode 4, indexed
                    bra       StoreMode store mode

ModeAuto            ldd       #$0003    mode 3, auto
StoreMode           std       ,s        save addressing mode
                    bra       GetSizeLetter classify size letter

BadOperandChar      leax      $04,s     drop locals pointer
                    lbra      RestoreAndErr bad operand type error

ClassifySecondChar  stx       -$02,s    save second char
                    beq       GetSizeLetter nul, classify first letter
                    cmpx      #$0078    is it x
                    beq       IndexedThirdChar indexed operand
                    cmpx      #$002B    is it a plus
                    beq       ModeAuto  auto-increment operand
                    bra       BadOperandChar unknown, error out

GetSizeLetter       ldb       [$0a,s]   deref first size letter
                    sex                 extend
                    tfr       d,x       X = the letter
                    lbra      ClassifySizeLetter classify size letter

RegisterOperand     ldd       ,s        flags
                    orb       #$01      mark register operand
                    bra       AllocRegSlot allocate register operand

AddressOperand      ldd       ,s        flags
                    orb       #$02      mark address operand
                    pshs      d         save flags
                    pshs      u         save entry pointer
                    lbsr      OpenPath  allocate operand slot
                    leas      $04,s     drop args
                    std       $02,s     save result
                    cmpd      #$FFFF    allocation failed
                    beq       WordOperand fall back to memory operand
                    ldd       #$0002    count arg
                    pshs      d         push it
                    clra                zero
                    clrb                zero
                    pshs      d         push
                    pshs      d         push
                    ldd       $08,s     operand entry
                    pshs      d         push it
                    lbsr      SeekPath  emit address load
                    leas      $08,s     drop args
                    bra       LoadResult return result

WordOperand         ldd       ,s        flags
                    orb       #$02      mark word operand
                    pshs      d         save flags
                    pshs      u         save entry pointer
                    lbsr      CreatePath allocate memory operand
                    bra       FinishOperand finish

DoubleOperand       ldd       ,s        flags
                    orb       #$81      mark double/long operand
AllocRegSlot        pshs      d         save flags
                    pshs      u         save entry pointer
                    lbsr      OpenPath  allocate operand slot
FinishOperand       leas      $04,s     drop args
                    std       $02,s     save result
                    bra       LoadResult return result

RestoreAndErr       leas      -$04,x    restore stack pointer from X
OperandTypeErr      ldd       #$00CB    error 203, bad operand type
                    std       $0364,y   store the error code
                    clra                return zero high
                    clrb                return zero low
                    bra       OperandRet2 clean up and return

ClassifySizeLetter  cmpx      #$0072    is the letter r
                    lbeq      RegisterOperand register operand
                    cmpx      #$0061    is the letter a
                    lbeq      AddressOperand address operand
                    cmpx      #$0077    is the letter w
                    beq       WordOperand word operand
                    cmpx      #$0064    is the letter d
                    beq       DoubleOperand double operand
                    bra       OperandTypeErr unknown letter, error

LoadResult          ldd       $02,s     load the result value
OperandRet2         leas      $04,s     drop locals
                    puls      pc,u      restore and return

                    pshs      u         save caller U
                    clra                zero
                    clrb                zero
                    pshs      d         push null descriptor
                    ldd       $08,s     arg
                    pshs      d         push it
                    ldd       $08,s     arg
                    pshs      d         push it
                    lbra      CallInitEntry fill operand entry

BuildOperand2       pshs      u         save caller U
                    ldd       $06,s     second arg
                    pshs      d         push it
                    ldd       $06,s     first arg
                    pshs      d         push it
                    lbsr      ParseOperandType parse operand descriptor
                    leas      $04,s     drop args
                    tfr       d,u       U = the result
                    cmpu      #$FFFF    parse failed
                    bne       NoSecondOperand parse ok
                    clra                return zero high
                    clrb                return zero low
                    bra       BuildOperandRet return

NoSecondOperand     clra                zero high
                    clrb                null second operand
                    bra       EmitOperandPair emit operand pair

BuildOperandEval    pshs      u         save caller U
                    ldd       $08,s     operand arg
                    pshs      d         push it
                    lbsr      CloseBuf  evaluate/convert operand
                    leas      $02,s     drop the arg
                    ldd       $06,s     second arg
                    pshs      d         push it
                    ldd       $06,s     first arg
                    pshs      d         push it
                    lbsr      ParseOperandType parse operand descriptor
                    leas      $04,s     drop args
                    tfr       d,u       U = the result
                    stu       -$02,s    save it
                    bge       HaveSecondOperand parse ok
                    clra                return zero high
                    clrb                return zero low
                    bra       BuildOperandRet return

HaveSecondOperand   ldd       $08,s     second operand value
EmitOperandPair     pshs      d         push it
                    ldd       $08,s     first operand value
                    pshs      d         push it
                    pshs      u         push descriptor
CallInitEntry       lbsr      InitOperandEntry fill operand entry
                    leas      $06,s     drop args
BuildOperandRet     puls      pc,u      restore and return

EmitStringLine      pshs      u         save caller U
                    leax      $0253,y   work buffer
                    pshs      x         push dest pointer
                    ldd       $06,s     source string arg
                    pshs      d         push it
                    bsr       CopyStringToBuf copy string into buffer
                    leas      $04,s     drop args
                    leax      $0253,y   work buffer
                    pshs      x         push the buffer
                    ldd       #$000D    carriage return / length
                    pshs      d         push it
                    lbsr      PutByte   write buffer to output
                    leas      $04,s     drop args
                    puls      pc,u      restore and return

CopyStringToBuf     pshs      u         save caller U
                    ldu       $04,s     U = source string
                    leas      -$01,s    reserve a char local
                    bra       CopyNextChar start the scan

CopyCharLoop        ldd       $07,s     destination pointer arg
                    pshs      d         push it
                    ldb       $02,s     current char
                    sex                 extend
                    pshs      d         push it
                    lbsr      PutByte   append char to buffer
                    leas      $04,s     drop args
CopyNextChar        ldb       ,u+       next source char
                    stb       ,s        save it
                    bne       CopyCharLoop loop until nul
                    leas      $01,s     drop the char local
                    puls      pc,u      restore and return

SubstXPlaceholder   pshs      u,d       save U and the value
                    ldu       $06,s     U = template string
                    bra       ScanCharTest start the scan

ScanNextChar        leau      $01,u     advance the pointer
ScanCharTest        ldb       ,u        current char
                    sex                 extend
                    std       ,s        save the char
                    beq       PlaceholderFound end of string
                    ldd       ,s        reload the char
                    cmpd      #$0058    is it the X placeholder
                    bne       ScanNextChar keep scanning
PlaceholderFound    ldd       ,s        char at the stop
                    beq       SubstDone no placeholder, done
                    lbsr      GetProcId get substitution number
                    pshs      d         push the number
                    leax      >FmtDecimal,pcr %d format
                    pshs      x         push the format
                    pshs      u         push placeholder position
                    lbsr      Sprintf   sprintf number into place
                    leas      $06,s     drop args
SubstDone           ldd       $06,s     return template pointer
                    leas      $02,s     drop saved value
                    puls      pc,u      restore and return

FmtDecimal          fcc       /%d/
                    fcb       $00
                    pshs      u         save caller U
                    ldu       $04,s     U = operand descriptor
                    leas      -$06,s    reserve locals
                    cmpu      #$0000    null descriptor
                    beq       ReturnNoOp return -1
                    ldd       $06,u     type flags
                    clra                clear high byte
                    andb      #$03      usage bits
                    bne       CheckHighFlag allocated, proceed
ReturnNoOp          ldd       #$FFFF    return -1
                    lbra      SeekExit  exit

CheckHighFlag       ldd       $06,u     type flags
                    anda      #$80      test high flag bit
                    clrb                clear low byte
                    std       -$02,s    save the test
                    bne       CheckRegBit flag set path
                    pshs      u         push descriptor
                    lbsr      ResolveStorage resolve simple operand
                    leas      $02,s     drop the arg
                    lbra      ClearDirtyFlag done

CheckRegBit         ldd       $06,u     type flags
                    anda      #$01      test register bit
                    clrb                clear low byte
                    std       -$02,s    save the test
                    beq       CompareOffset not a register
                    pshs      u         push descriptor
                    lbsr      CheckWritable free the register
                    leas      $02,s     drop the arg
                    ldd       $06,u     type flags
                    anda      #$FE      clear register bit
                    std       $06,u     save the flags
                    ldd       $02,u     base offset
                    addd      $0b,u     plus operand size
                    std       $04,u     store end offset
                    lbra      StoreBufPos done

CompareOffset       ldd       ,u        current offset
                    cmpd      $04,u     compare end offset
                    lbcc      ClearDirtyFlag at/past end, done
                    leax      $02,s     locals pointer
                    pshs      x         push it
                    leax      $0e,s     arg pointer
                    lbsr      StoreInt32 set up range value
                    ldx       $10,s     reload the pointer
                    lbra      WhenceDispatch continue

EmitIndexedRef2     leax      $02,s     local operand pointer
                    pshs      x         push it
                    ldd       $02,x     high word
                    pshs      d         push it
                    ldd       ,x        low word
                    pshs      d         push it
                    pshs      u         push descriptor
                    lbsr      SeekFileToBuf emit indexed reference
                    leas      $02,s     drop one arg
                    lbsr      SubInt32  advance the range
                    lbsr      StoreInt32 set up range value
ScaleBySize         ldd       $0b,u     element size
                    lbsr      SignExtendTo32 scale by the size
                    ldd       $02,x     high word
                    pshs      d         push it
                    ldd       ,x        low word
                    pshs      d         push it
                    leax      $06,s     second operand pointer
                    ldd       $02,x     high word
                    pshs      d         push it
                    ldd       ,x        low word
                    pshs      d         push it
                    bsr       CompareRanges compare the two ranges
                    fcb       $00,$00,$00,$00
CompareRanges       puls      x         X = inline data pointer
                    lbsr      CompareInt32 compare range values
                    bge       RangeSecondPtr first >= second
                    leax      $06,s     pointer to second
                    lbsr      NegateInt32 take the second value
                    bra       RangeCompare2 merged

RangeSecondPtr      leax      $06,s     pointer to second
RangeCompare2       lbsr      CompareInt32 compare again
                    blt       SeekAdjust first < second, branch away
                    ldd       $04,s     the value
                    addd      ,u        plus current offset
                    std       ,s        save it
                    cmpd      $02,u     compare against high offset
                    bcs       SeekAdjust if new position below, take slow path
                    ldd       ,s        get saved new position
                    cmpd      $04,u     compare with buffer end
                    bcc       SeekAdjust at or past end, take slow path
                    ldd       ,s        reload new position
                    std       ,u        set buffer current pointer
                    ldd       $06,u     get flag word
                    andb      #$EF      clear the dirty bit
                    std       $06,u     store flags back
                    lbra      SeekOk    return success

                    bra       SeekAdjust otherwise fall to slow path

WhenceDispatch      stx       -$02,s    save whence result
                    lbeq      EmitIndexedRef2 whence zero, seek-set path
                    cmpx      #$0001    whence equals one
                    lbeq      ScaleBySize seek-current path
SeekAdjust          ldd       $10,s     get direction or mode argument
                    cmpd      #$0001    is it write mode
                    bne       LoadBufEnd not write, skip flush
                    leax      $0C,s     point at saved position pair
                    pshs      x         push pointer argument
                    ldd       $02,x     high word of position
                    pshs      d         push it
                    ldd       ,x        low word of position
                    pshs      d         push it
                    ldd       $04,u     buffer end pointer
                    subd      ,u        minus current gives pending length
                    lbsr      SignExtendTo32 emit pending length
                    lbsr      SubInt32  emit seek operation
                    lbsr      StoreInt32 finalize the emit
LoadBufEnd          ldd       $04,u     load buffer end pointer
StoreBufPos         std       ,u        set current equal to end
ClearDirtyFlag      ldd       $06,u     get flags
                    andb      #$EF      clear the dirty bit
                    std       $06,u     store flags
                    ldd       $10,s     get mode argument
                    pshs      d         push mode
                    leax      $0e,s     point at position arguments
                    ldd       $02,x     high word
                    pshs      d         push
                    ldd       ,x        low word
                    pshs      d         push
                    ldd       $08,u     file handle
                    pshs      d         push handle
                    lbsr      SeekPath  perform the low-level seek
                    leas      $08,s     drop seek arguments
                    ldd       $02,x     result high word
                    pshs      d         push
                    ldd       ,x        result low word
                    pshs      d         push
                    bsr       CheckSeekResult check result against sentinel
                    fcb       $FF,$FF,$FF,$FF
CheckSeekResult     puls      x         x points at inline sentinel
                    lbsr      CompareInt32 compare result to sentinel
                    bne       SeekOk    not error, success
                    ldd       #$FFFF    load failure code
                    bra       SeekExit  return failure

SeekOk              clra                success high byte
                    clrb                success low byte
SeekExit            leas      $06,s     drop temporaries
                    puls      pc,u      restore u and return

RewindBuf           pshs      u         save u
                    clra                zero
                    clrb                zero
                    pshs      d         push zero position high
                    clra                zero
                    clrb                zero
                    pshs      d         push zero position low
                    pshs      d         push another zero
                    ldd       $0a,s     get file handle argument
                    pshs      d         push handle
                    lbsr      $A00D     seek file to position zero
                    leas      $08,s     drop arguments
                    puls      pc,u      return

SeekFileToBuf       pshs      u         save u
                    ldu       $04,s     u = buffer control block
                    beq       BufNullErr null block, error
                    ldd       $06,u     get flags
                    clra                keep low byte only
                    andb      #$03      mask open-mode bits
                    bne       DoSeek    open, proceed
BufNullErr          bsr       ReportBufErr report error via sentinel
                    fcb       $FF,$FF,$FF,$FF
ReportBufErr        puls      x         x points at inline sentinel
                    leau      $0358,y   u = error message block
                    pshs      u         push message pointer
                    lbsr      StoreInt32 emit the error
                    puls      pc,u      return

DoSeek              ldd       $06,u     get flags
                    anda      #$80      test active bit seven
                    clrb                clear low byte
                    std       -$02,s    save the test result
                    bne       QueryFilePos already active, skip init
                    pshs      u         push block
                    lbsr      ResolveStorage initialize the buffer
                    leas      $02,s     drop argument
QueryFilePos        ldd       #$0001    whence = current
                    pshs      d         push whence
                    clra                zero
                    clrb                zero
                    pshs      d         push offset high zero
                    pshs      d         push offset low zero
                    ldd       $08,u     file handle
                    pshs      d         push handle
                    lbsr      SeekPath  query current file position
                    leas      $08,s     drop arguments
                    ldd       $02,x     position high word
                    pshs      d         push
                    ldd       ,x        position low word
                    pshs      d         push
                    ldd       $06,u     flags
                    anda      #$01      test read/write direction
                    clrb                clear low byte
                    std       -$02,s    save test
                    beq       UseBufEnd write side uses end pointer
                    ldd       $02,u     read side uses base pointer
                    bra       EmitSeekDelta skip end-pointer load

UseBufEnd           ldd       $04,u     use buffer end pointer
EmitSeekDelta       pshs      d         push chosen pointer
                    ldd       ,u        current pointer
                    subd      ,s++      compute buffered byte count
                    lbsr      SignExtendTo32 emit the adjustment
                    lbsr      AddInt32  finalize
                    puls      pc,u      return

PutByte             pshs      u         save u
                    ldu       $06,s     u = buffer control block
                    ldd       $06,u     flags
                    anda      #$80      keep bit seven
                    andb      #$22      keep write bits
                    cmpd      #$8002    already write active
                    beq       PutBuffered if so, write directly
                    ldd       $06,u     flags
                    clra                clear high byte
                    andb      #$22      mask mode bits
                    cmpd      #$0002    open for write
                    lbne      IoErr     not writable, error
                    pshs      u         push block
                    lbsr      ResolveStorage prepare write buffer
                    leas      $02,s     drop argument
PutBuffered         ldd       $06,u     flags
                    clra                clear high byte
                    andb      #$04      test unbuffered bit
                    beq       PutToBuffer buffered, use the buffer
                    ldd       #$0001    count is one byte
                    pshs      d         push count
                    leax      $07,s     point at the character
                    pshs      x         push data pointer
                    ldd       $08,u     file handle
                    pshs      d         push handle
                    ldd       $06,u     flags
                    clra                clear high byte
                    andb      #$40      test text/line mode
                    beq       UseBinaryWrite binary, use other writer
                    leax      WriteLnPath,pcr select text write routine
                    bra       CallWriteFunc go call it

UseBinaryWrite      leax      WritePath,pcr select binary write routine
CallWriteFunc       tfr       x,d       move address to d
                    tfr       d,x       back into x
                    jsr       ,x        call chosen writer
                    leas      $06,s     drop arguments
                    cmpd      #$FFFF    write failed
                    bne       PutDone   success, done
                    ldd       $06,u     flags
                    orb       #$20      set error bit
                    std       $06,u     store flags
                    lbra      IoErr     return failure

PutToBuffer         ldd       $06,u     flags
                    anda      #$01      test read-direction bit
                    clrb                clear low byte
                    std       -$02,s    save test
                    bne       StoreByte not read side, store byte
                    pshs      u         push block
                    lbsr      FlushBuf  flush pending read buffer
                    leas      $02,s     drop argument
StoreByte           ldd       ,u        current pointer
                    addd      #$0001    advance
                    std       ,u        store pointer
                    subd      #$0001    recover store address
                    tfr       d,x       x = store address
                    ldd       $04,s     the character
                    stb       ,x        write byte into buffer
                    ldd       ,u        new pointer
                    cmpd      $04,u     reached buffer end
                    bcc       FlushAfterPut full, flush
                    ldd       $06,u     flags
                    clra                clear high byte
                    andb      #$40      line-buffered mode
                    beq       PutDone   if not, done
                    ldd       $04,s     the character
                    cmpd      #$000D    is it carriage return
                    bne       PutDone   not newline, done
FlushAfterPut       pshs      u         push block
                    lbsr      FlushBuf  flush the buffer
                    std       ,s++      save flush status
                    lbne      IoErr     flush failed, error
PutDone             ldd       $04,s     return the character
                    puls      pc,u      return

                    pshs      u         save u
                    ldu       $04,s     u = buffer control block
                    ldd       $06,s     the word argument
                    pshs      d         push word
                    pshs      u         push block
                    ldd       #$0008    shift count eight
                    lbsr      ShiftRightUnsigned high byte = word >> 8
                    pshs      d         push high byte
                    lbsr      PutByte   put high byte
                    leas      $04,s     drop arguments
                    ldd       $06,s     the word argument
                    pshs      d         push word
                    pshs      u         push block
                    lbsr      PutByte   put low byte
                    lbra      FlushExit return status

FlushAllBufs        pshs      u,d       save u and make index slot
                    leau      $0246,y   u = buffer table base
                    clra                zero
                    clrb                zero
                    std       ,s        index = zero
                    bra       FlushAllLoop enter loop condition

FlushNextBuf        tfr       u,d       d = current entry
                    leau      $0d,u     advance to next entry
                    pshs      d         push current entry pointer
                    bsr       CloseBuf  close this buffer
                    leas      $02,s     drop argument
FlushAllLoop        ldd       ,s        get index
                    addd      #$0001    increment
                    std       ,s        store index
                    subd      #$0001    back to current
                    cmpd      #$0010    done all sixteen
                    blt       FlushNextBuf loop while more remain
                    lbra      BufFlushExit return

CloseBuf            pshs      u         save u
                    ldu       $04,s     u = buffer control block
                    leas      -$02,s    make local slot
                    cmpu      #$0000    null block
                    beq       CloseBufNull skip if unused
                    ldd       $06,u     open, close it
                    bne       CloseBufValid
CloseBufNull        ldd       #$FFFF    nothing to close
                    lbra      BufFlushExit return

CloseBufValid       ldd       $06,u     flags
                    clra                clear high byte
                    andb      #$02      write-active bit
                    beq       NoFlushNeeded not dirty, skip flush
                    pshs      u         push block
                    bsr       CheckWritable flush before close
                    leas      $02,s     drop argument
                    bra       CloseFile go store status

NoFlushNeeded       clra                zero
                    clrb                zero status
CloseFile           std       ,s        save close status
                    ldd       $08,u     file handle
                    pshs      d         push handle
                    lbsr      ClosePath close the file
                    leas      $02,s     drop argument
                    clra                zero
                    clrb                zero
                    std       $06,u     clear flags, mark free
                    ldd       ,s        return saved status
                    bra       BufFlushExit go return

CheckWritable       pshs      u         save u
                    ldu       $04,s     u = buffer control block
                    beq       IoErr     null, error
                    ldd       $06,u     flags
                    clra                clear high byte
                    andb      #$22      mask mode bits
                    cmpd      #$0002    open for write
                    beq       FlushWritable if so, flush it
IoErr               ldd       #$FFFF    error code
                    puls      pc,u      return

FlushWritable       ldd       $06,u     flags
                    anda      #$80      active bit seven
                    clrb                clear low byte
                    std       -$02,s    save test
                    bne       DoBufFlush already active, flush
                    pshs      u         push block
                    lbsr      ResolveStorage activate the buffer
                    leas      $02,s     drop argument
DoBufFlush          pshs      u         push block
                    bsr       FlushBuf  flush the buffer
BufFlushExit        leas      $02,s     drop local
                    puls      pc,u      return

FlushBuf            pshs      u         save u
                    ldu       $04,s     u = buffer control block
                    leas      -$04,s    local storage
                    ldd       $06,u     flags
                    anda      #$01      read direction
                    clrb                clear low byte
                    std       -$02,s    save test
                    bne       FlushComputeLen read side, skip seek
                    ldd       ,u        current pointer
                    cmpd      $04,u     equals end
                    beq       FlushComputeLen nothing buffered, skip
                    clra                zero
                    clrb                zero
                    pshs      d         push zero argument
                    pshs      u         push block
                    lbsr      SeekFileToBuf seek file to buffer start
                    leas      $02,s     drop argument
                    ldd       $02,x     seek result high
                    pshs      d         push
                    ldd       ,x        seek result low
                    pshs      d         push
                    ldd       $08,u     file handle
                    pshs      d         push handle
                    lbsr      SeekPath  reposition the file
                    leas      $08,s     drop arguments
FlushComputeLen     ldd       ,u        current pointer
                    subd      $02,u     minus base gives byte count
                    std       $02,s     save count
                    lbeq      ResetBufEmpty nothing to write, reset
                    ldd       $06,u     flags
                    anda      #$01      read direction
                    clrb                clear low byte
                    std       -$02,s    save test
                    lbeq      ResetBufEmpty read side, just reset
                    ldd       $06,u     flags
                    clra                clear high byte
                    andb      #$40      text/line mode
                    beq       WriteWhole binary, block write
                    ldd       $02,u     base pointer
                    bra       StoreWritePos go store pointer

WriteLoop           ldd       $02,s     remaining count
                    pshs      d         push count
                    ldd       ,u        current pointer
                    pshs      d         push pointer
                    ldd       $08,u     file handle
                    pshs      d         push handle
                    lbsr      WriteLnPath write text chunk
                    leas      $06,s     drop arguments
                    std       ,s        save bytes written
                    cmpd      #$FFFF    write error
                    bne       LoadRemCount ok, continue
                    leax      $04,s     point at return slot
                    bra       WriteErrAdjust handle the error

LoadRemCount        ldd       $02,s     remaining count
                    subd      ,s        minus bytes written
                    std       $02,s     update remaining
                    ldd       ,u        current pointer
                    addd      ,s        advance by written
StoreWritePos       std       ,u        store pointer
                    ldd       $02,s     remaining count
                    bne       WriteLoop more, loop
                    bra       ResetBufEmpty done, reset buffer

WriteWhole          ldd       $02,s     byte count
                    pshs      d         push count
                    ldd       $02,u     base pointer
                    pshs      d         push pointer
                    ldd       $08,u     file handle
                    pshs      d         push handle
                    lbsr      WritePath write the whole buffer
                    leas      $06,s     drop arguments
                    cmpd      $02,s     all bytes written
                    beq       ResetBufEmpty yes, reset buffer
                    bra       MarkBufErr no, mark error

WriteErrAdjust      leas      -$04,x    adjust to error slot
MarkBufErr          ldd       $06,u     flags
                    orb       #$20      set error bit
                    std       $06,u     store flags
                    ldd       $04,u     buffer end
                    std       ,u        reset current to end
                    ldd       #$FFFF    error code
                    bra       FlushExit go return

ResetBufEmpty       ldd       $06,u     flags
