                    subd      $02,x     subtract X low word
                    std       $035a,y   store result low word
                    ldd       $02,s     high word of stack operand
                    sbcb      $01,x     subtract X high with borrow
                    sbca      ,x        finish high subtract
                    std       $0358,y   store result high word
                    lbra      ReturnScratch return scratch result

CompareInt32        ldd       $02,s     high word of operand
                    cmpd      ,x        compare with X high
                    bne       CompareDone unequal, use carry flag
                    ldd       $04,s     low word of operand
                    cmpd      $02,x     compare with X low
                    beq       CompareDone equal
                    bcs       CmpLess2  operand below
                    lda       #$01      operand above marker
                    andcc     #$FE      clear carry
                    bra       CompareDone finish compare

CmpLess2            clra                clear A
                    cmpa      #$01      set carry for less
CompareDone         pshs      cc        save condition codes
                    ldd       $01,s     reposition result byte
                    std       $05,s     store it
                    puls      cc        restore condition codes
                    leas      $04,s     clean the frame
                    rts                 return

NegateInt32         lbsr      CopyToScratch32 copy operand to scratch
                    ldd       #$0000    zero for low negate
                    subd      $02,x     negate low word
                    std       $02,x     store low word
                    ldd       #$0000    zero for high negate
                    sbcb      $01,x     negate high word with borrow
                    sbca      ,x        finish high negate
                    std       ,x        store high word
                    rts                 return

ComplementInt32     ldd       ,x        load high word
                    coma                complement high byte
                    comb                complement low byte
                    std       $0358,y   store to scratch
                    ldd       $02,x     load low word
                    coma                complement high byte
                    comb                complement low byte
                    leax      $0358,y   point X at scratch
                    std       $02,x     store low word
                    rts                 return

SignExtendTo32      leax      $0358,y   point X at scratch
                    std       $02,x     store low word
                    tfr       a,b       copy high byte
                    sex                 sign extend into A
                    tfr       a,b       copy back to B
                    std       ,x        store sign-extended high word
                    rts                 return
                    leax      $0358,y   point X at scratch
                    std       $02,x     store low word
                    clr       ,x        zero high word
                    clr       $01,x     zero high byte
                    rts                 return zero-extended

StoreInt32          pshs      y         save Y
                    ldy       $04,s     get destination pointer argument
                    ldd       ,x        load high word
                    std       ,y        store to destination
                    ldd       $02,x     load low word
                    std       $02,y     store to destination
                    puls      x         restore X from argument slot
                    exg       y,x       swap back
                    puls      d         pop return address
                    std       ,s        fix up stack
                    rts                 return

ShiftLeft32         ldx       $02,s     get value pointer
                    pshs      b         save shift count
                    lbsr      CopyToScratch32 copy value to scratch
                    puls      b         restore shift count
                    tstb                zero shifts
                    beq       ShiftLeftDone nothing to do
ShiftLeftLoop       asl       $03,x     shift left one bit
                    rol       $02,x     rotate through byte 2
                    rol       $01,x     rotate through byte 1
                    rol       ,x        rotate through byte 0
                    decb                decrement count
                    bne       ShiftLeftLoop loop
ShiftLeftDone       puls      d         pop return address
                    std       ,s        fix up stack
                    rts                 return
                    ldx       $02,s     get value pointer
                    pshs      b         save shift count
                    lbsr      CopyToScratch32 copy value to scratch
                    puls      b         restore shift count
                    tstb                zero shifts
                    beq       ShiftRightDone nothing to do
ShiftRightLoop      asr       ,x        arithmetic shift right one bit
                    ror       $01,x     rotate through byte 1
                    ror       $02,x     rotate through byte 2
                    ror       $03,x     rotate through byte 3
                    decb                decrement count
                    bne       ShiftRightLoop loop
ShiftRightDone      puls      d         pop return address
                    std       ,s        fix up stack
                    rts                 return

ReturnScratch       tfr       cc,a      save condition codes
                    puls      x         pop return address
                    stx       $02,s     stash it
                    leas      $02,s     drop operand slot
                    leax      $0358,y   point X at scratch result
                    tfr       a,cc      restore condition codes
                    rts                 return

CopyToScratch32     ldd       ,x        load high word
                    std       $0358,y   store to scratch
                    ldd       $02,x     load low word
                    leax      $0358,y   point X at scratch
                    std       $02,x     store low word
                    rts                 return

MulInt32            tsta                high byte of multiplier zero
                    bne       MulFull   no, full multiply
                    tst       $02,s     high byte of multiplicand zero
                    bne       MulFull   no, full multiply
                    lda       $03,s     eight-bit operand
                    mul                 eight by eight multiply
                    ldx       ,s        reposition low result
                    stx       $02,s     store it
                    ldx       #$0000    zero high result
                    std       ,s        store product low
                    puls      pc,d      return product

MulFull             pshs      d         save multiplier
                    ldd       #$0000    zero accumulator
                    pshs      d         reserve result accumulator
                    pshs      d         reserve result accumulator
                    lda       $05,s     first partial product operands
                    ldb       $09,s     low by low
                    mul                 multiply
                    std       $02,s     store partial
                    lda       $05,s     next partial operand
                    ldb       $08,s     low by high
                    mul                 multiply
                    addd      $01,s     accumulate
                    std       $01,s     store partial
                    bcc       MulStep2  no carry
                    inc       ,s        propagate carry
MulStep2            lda       $04,s     next partial operand
                    ldb       $09,s     high by low
                    mul                 multiply
                    addd      $01,s     accumulate
                    std       $01,s     store partial
                    bcc       MulStep3  no carry
                    inc       ,s        propagate carry
MulStep3            lda       $04,s     final partial operand
                    ldb       $08,s     high by high
                    mul                 multiply
                    addd      ,s        accumulate top
                    std       ,s        store top
                    ldx       $06,s     reposition high word
                    stx       $08,s     stash it
                    ldx       ,s        high word of product
                    ldd       $02,s     low word of product
                    leas      $08,s     clean the frame
                    rts                 return product
                    clr       $089e,y   clear divide sign flag
                    leax      >UDivRoutine,pcr point at unsigned divide routine
                    stx       $089f,y   store divide routine pointer
                    bra       DivCheckZero go check divisor

SignedDivSetup      leax      >SignedDivide32,pcr point at signed divide routine
                    stx       $089f,y   store divide routine pointer
                    clr       $089e,y   clear sign flag
                    tst       $02,s     test dividend sign
                    bpl       DivCheckZero positive dividend
                    inc       $089e,y   mark negative result
DivCheckZero        subd      #$0000    test divisor for zero
                    bne       DoDivide  nonzero, do divide
                    puls      x         pop return address
                    ldd       ,s++      discard operand
                    jmp       ,x        return

DoDivide            ldx       $02,s     get dividend pointer
                    pshs      x         push argument
                    jsr       [$089f,y] call selected divide routine
                    ldd       ,s        fetch result low
                    std       $02,s     reposition it
                    tfr       x,d       result to D
                    tst       $089e,y   negative result flag
                    beq       DivResult positive, keep as is
                    nega                negate result high
                    negb                negate result low
                    sbca      #$00      finish negate
DivResult           std       ,s++      store result and return
                    rts                 return

UDivRoutine         subd      #$0000    test divisor for zero
                    beq       DivZeroErr zero, error
                    pshs      d         save divisor
                    leas      -$02,s    reserve workspace
                    clr       ,s        clear it
                    clr       $01,s     clear it
                    bra       DivNormInit perform the division

DivZeroErr          puls      d         discard slot
                    std       ,s        restore
                    ldd       #$002D    load error code 45
                    lbra      SendSignal report divide by zero

SignedDivide32      subd      #$0000    test divisor low word for zero
                    beq       DivZeroErr divide by zero, handle above
                    pshs      d         save divisor low word
                    leas      -$02,s    allocate sign/shift scratch
                    clr       ,s        clear shift counter slot
                    clr       $01,s     clear result sign flag
                    tsta                test divisor sign
                    bpl       DivAbsDividend positive divisor, skip negate
                    nega                negate divisor high byte
                    negb                negate divisor low byte
                    sbca      #$00      propagate the borrow
                    inc       $01,s     note divisor was negative
                    std       $02,s     store absolute divisor
DivAbsDividend      ldd       $06,s     load dividend
                    bpl       DivNormInit positive dividend, skip negate
                    nega                negate dividend high byte
                    negb                negate dividend low byte
                    sbca      #$00      propagate the borrow
                    com       $01,s     flip result sign flag
                    std       $06,s     store absolute dividend
DivNormInit         lda       #$01      seed normalize shift count
DivNormLoop         inca                count one more shift
                    asl       $03,s     shift divisor left
                    rol       $02,s     through high byte
                    bpl       DivNormLoop until top bit set
                    sta       ,s        save shift count
                    ldd       $06,s     load dividend
                    clr       $06,s     clear quotient high
                    clr       $07,s     clear quotient low
DivBitLoop2         subd      $02,s     trial subtract divisor
                    bcc       DivBitSet fits, record a one bit
                    addd      $02,s     restore, did not fit
                    andcc     #$FE      clear carry for zero bit
                    bra       DivBitShift join shift

DivBitSet           orcc      #$01      set carry for one bit
DivBitShift         rol       $07,s     shift bit into quotient low
                    rol       $06,s     into quotient high
                    lsr       $02,s     shift divisor right
                    ror       $03,s     through low byte
                    dec       ,s        decrement shift count
                    bne       DivBitLoop2 loop over all bits
                    std       $02,s     store remainder
                    tst       $01,s     test result sign flag
                    beq       DivApplySign positive quotient, skip negate
                    ldd       $06,s     load quotient
                    nega                negate quotient high byte
                    negb                negate quotient low byte
                    sbca      #$00      propagate the borrow
                    std       $06,s     store signed quotient
DivApplySign        ldx       $04,s     grab return address
                    ldd       $06,s     load quotient
                    std       $04,s     overwrite arg slot with quotient
                    stx       $06,s     move return address down
                    ldx       $02,s     remainder into X
                    ldd       $04,s     quotient into D
                    leas      $06,s     drop scratch and args
                    rts                 return quotient D remainder X

ShiftRightSigned    tstb                shift count zero
                    beq       ShiftReturn nothing to shift
AsrLoop             asr       $02,s     arithmetic shift high byte
                    ror       $03,s     through low byte
                    decb                count down shifts
                    bne       AsrLoop   repeat for each bit
                    bra       ShiftReturn done shifting

ShiftRightUnsigned  tstb                shift count zero
                    beq       ShiftReturn nothing to shift
LsrLoop             lsr       $02,s     logical shift high byte
                    ror       $03,s     through low byte
                    decb                count down shifts
                    bne       LsrLoop   repeat for each bit
ShiftReturn         ldd       $02,s     load shifted value
                    pshs      d         stash result
                    ldd       $02,s     reload value
                    std       $04,s     slide into return slot
                    ldd       ,s        pop result into D
                    leas      $04,s     drop scratch and arg
                    rts                 return shifted value

ShiftLeft           tstb                shift count zero
                    beq       ShiftReturn nothing to shift
AslLoop             asl       $03,s     shift low byte left
                    rol       $02,s     through high byte
                    decb                count down shifts
                    bne       AslLoop   repeat for each bit
                    bra       ShiftReturn done shifting

SendSignal          std       $0364,y   stash signal value
                    pshs      y,b       save globals and signal
                    os9       F$ID      get current process id
                    puls      y,b       restore signal in B
                    os9       F$Send    send signal to self
                    rts                 return

GetStatCall         lda       $05,s     A = path number
                    ldb       $03,s     B = getstat function code
                    beq       GetStatCode0 code 0, size query
                    cmpb      #$01      code 1
                    beq       GetStatDo do plain getstat
                    cmpb      #$06      code 6
                    beq       GetStatDo do plain getstat
                    cmpb      #$02      code 2
                    beq       GetStatUParam getstat with U param
                    cmpb      #$05      code 5
                    beq       GetStatUParam getstat with U param
                    ldb       #$D0      E$UnkSvc unknown code
                    lbra      ReturnError return error

GetStatUParam       pshs      u         save U
                    os9       I$GetStt  get status
                    bcc       GetStatStore success, store result
                    puls      u         restore U
                    lbra      ReturnError return error

GetStatStore        stx       [$08,s]   store X result via pointer arg
                    ldx       $08,s     reload result pointer
                    stu       $02,x     store U result word
                    puls      u         restore U
                    clra                clear high byte
                    clrb                success zero
                    rts                 return

GetStatCode0        ldx       $06,s     X = size result buffer
GetStatDo           os9       I$GetStt  get status
                    lbra      ReturnStatus return status

                    lda       $05,s     A = path number
                    ldb       $03,s     B = setstat function code
                    beq       SetStatSimple code 0, plain setstat
                    cmpb      #$02      code 2
                    beq       SetStatUParam setstat with U param
                    ldb       #$D0      E$UnkSvc unknown code
                    lbra      ReturnError return error

SetStatSimple       ldx       $06,s     X = parameter
                    os9       I$SetStt  set status
                    lbra      ReturnStatus return status

SetStatUParam       pshs      u         save U
                    ldx       $08,s     X = parameter
                    ldu       $0a,s     U = parameter
                    os9       I$SetStt  set status
                    puls      u         restore U
                    lbra      ReturnStatus return status

                    ldx       $02,s     X = pathname
                    lda       $05,s     A = access mode
                    os9       I$Open    try to open file
                    bcs       AccessDone failed, skip close
                    os9       I$Close   close it immediately
AccessDone          lbra      ReturnStatus return status

OpenPath            ldx       $02,s     X = pathname
                    lda       $05,s     A = access mode
                    os9       I$Open    open file
                    lbcs      ReturnError failed, return error
                    tfr       a,b       path number to B
                    clra                clear high byte
                    rts                 return path number

ClosePath           lda       $03,s     A = path number
                    os9       I$Close   close file
                    lbra      ReturnStatus return status

                    ldx       $02,s     X = pathname
                    ldb       $05,s     B = attributes
                    os9       I$MakDir  make directory
                    lbra      ReturnStatus return status

CreatePath          ldx       $02,s     X = pathname
                    lda       $05,s     A = requested mode
                    tfr       a,b       copy mode to B
                    andb      #$24      keep write access bits
                    orb       #$0b      force base access attributes
                    os9       I$Create  create file
                    bcs       CreateExists failed, check exists
CreateOk            tfr       a,b       path number to B
                    clra                clear high byte
                    rts                 return path number

CreateExists        cmpb      #$DA      E$CEF already exists
                    lbne      ReturnError other error, return it
                    lda       $05,s     reload mode
                    bita      #$80      exclusive create bit set
                    lbne      ReturnError exclusive, fail
                    anda      #$07      keep access bits
                    ldx       $02,s     X = pathname
                    os9       I$Open    open existing file
                    lbcs      ReturnError open failed, return error
                    pshs      u,a       save path and U
                    ldx       #$0000    truncate to zero length
                    leau      ,x        U = 0
                    ldb       #$02      SS.Size setstat code
                    os9       I$SetStt  truncate file
                    puls      u,a       restore path and U
                    bcc       CreateOk  truncate ok, return path
                    pshs      b         save error code
                    os9       I$Close   close file
                    puls      b         restore error code
                    lbra      ReturnError return error

DeletePath          ldx       $02,s     X = pathname
                    os9       I$Delete  delete file
                    lbra      ReturnStatus return status

                    lda       $03,s     A = path number
                    os9       I$Dup     duplicate path
                    lbcs      ReturnError failed, return error
                    tfr       a,b       new path to B
                    clra                clear high byte
                    rts                 return new path number

ReadPath            pshs      y         save Y
                    ldx       $06,s     X = buffer
                    lda       $05,s     A = path number
                    ldy       $08,s     Y = byte count
                    pshs      y         save count for return
                    os9       I$Read    read bytes
ReadResult          bcc       ReadOk    success
                    cmpb      #$D3      E$EOF end of file
                    bne       ReadErr   other error
                    clra                return zero
                    clrb                count on eof
                    puls      pc,y,x    restore and return

ReadErr             puls      y,x       restore Y and X
                    lbra      ReturnError return error

ReadOk              tfr       y,d       bytes read into D
                    puls      pc,y,x    restore and return count

ReadLnPath          pshs      y         save Y
                    lda       $05,s     A = path number
                    ldx       $06,s     X = buffer
                    ldy       $08,s     Y = byte count
                    pshs      y         save count for return
                    os9       I$ReadLn  read a line
                    bra       ReadResult share read result

WritePath           pshs      y         save Y
                    ldy       $08,s     Y = byte count
                    beq       WriteOk   zero length, return
                    lda       $05,s     A = path number
                    ldx       $06,s     X = buffer
                    os9       I$Write   write bytes
WriteResult         bcc       WriteOk   success
                    puls      y         restore Y
                    lbra      ReturnError return error

WriteOk             tfr       y,d       bytes written into D
                    puls      pc,y      restore and return count

WriteLnPath         pshs      y         save Y
                    ldy       $08,s     Y = byte count
                    beq       WriteOk   zero length, return
                    lda       $05,s     A = path number
                    ldx       $06,s     X = buffer
                    os9       I$WritLn  write a line
                    bra       WriteResult share write result

SeekPath            pshs      u         save U
                    ldd       $0a,s     D = whence
                    bne       SeekWhenceCheck nonzero whence
                    ldu       #$0000    base high = 0
                    ldx       #$0000    base low = 0
                    bra       SeekDo    compute new position

SeekWhenceCheck     cmpd      #$0001    SEEK_CUR
                    beq       SeekFromCur use current position
                    cmpd      #$0002    SEEK_END
                    beq       SeekFromEnd use end position
                    ldb       #$F7      E$Param bad whence
SeekErr             clra                clear high byte
                    std       $0364,y   store errno
                    ldd       #$FFFF    return -1
                    leax      $0358,y   X = seek result buffer
                    std       ,x        store -1 high
                    std       $02,x     store -1 low
                    puls      pc,u      restore and return

SeekFromEnd         lda       $05,s     A = path number
                    ldb       #$02      SS.Size get file size
                    os9       I$GetStt  query file size
                    bcs       SeekErr   failed
                    bra       SeekDo    compute new position

SeekFromCur         lda       $05,s     A = path number
                    ldb       #$05      SS.Pos get current position
                    os9       I$GetStt  query position
                    bcs       SeekErr   failed
SeekDo              tfr       u,d       base low into D
                    addd      $08,s     add offset low
                    std       $035a,y   save new position low
                    tfr       d,u       keep low in U
                    tfr       x,d       base high into D
                    adcb      $07,s     add offset high with carry
                    adca      $06,s     propagate carry
                    bmi       SeekErr   negative position, fail
                    tfr       d,x       new high into X
                    std       $0358,y   save new position high
                    lda       $05,s     A = path number
                    os9       I$Seek    seek to new position
                    bcs       SeekErr   failed
                    leax      $0358,y   X = position result
                    puls      pc,u      restore and return

SbrkGrow            ldd       $0356,y   D = current break pointer
                    pshs      d         save it
                    ldd       $04,s     D = requested size
                    cmpd      $08A1,y   compare to free bytes
                    bcs       SbrkAllocPool enough, allocate directly
                    addd      $0356,y   extend past current break
                    pshs      y         save global base
                    subd      ,s        adjust to memory size
                    os9       F$Mem     request more memory
                    tfr       y,d       new memory top into D
                    puls      y         restore global base
                    bcc       SbrkGrowOk got memory
                    ldd       #$FFFF    return failure
                    leas      $02,s     drop saved break
                    rts                 return -1

SbrkGrowOk          std       $0356,y   update break pointer
                    addd      $08A1,y   add previous free count
                    subd      ,s        minus old break
                    std       $08A1,y   store new free count
SbrkAllocPool       leas      $02,s     drop saved break
                    ldd       $08A1,y   D = free byte count
                    pshs      d         save it
                    subd      $04,s     subtract requested size
                    std       $08A1,y   reduce free count
                    ldd       $0356,y   D = break pointer
                    subd      ,s++      minus free, drop saved
                    pshs      d         save allocation start
                    clra                zero fill value
                    ldx       ,s        X = allocation start
SbrkZeroLoop        sta       ,x+       zero a byte
                    cmpx      $0356,y   reached break
                    bcs       SbrkZeroLoop keep zeroing
                    puls      pc,d      return pointer

ArenaAlloc          ldd       $02,s     D = requested increment
                    addd      $0360,y   add to arena top
                    bcs       ArenaAllocFail overflow, fail
                    cmpd      $0362,y   compare to arena limit
                    bcc       ArenaAllocFail exceeds, fail
                    pshs      d         save new top
                    ldx       $0360,y   X = old top
                    clra                zero fill value
ArenaZeroLoop       cmpx      ,s        reached new top
                    bcc       ArenaAllocOk done zeroing
                    sta       ,x+       zero a byte
                    bra       ArenaZeroLoop keep zeroing

ArenaAllocOk        ldd       $0360,y   return old top pointer
                    puls      x         X = new top
                    stx       $0360,y   update arena top
                    rts                 return old pointer

ArenaAllocFail      ldd       #$FFFF    return failure
                    rts                 return -1

GetProcId           pshs      y         save Y
                    os9       F$ID      get process id
                    puls      y         restore Y
                    bcc       GetProcIdOk success
                    lbcs      ReturnError failed, return error
GetProcIdOk         tfr       a,b       process id into B
                    clra                clear high byte
                    rts                 return process id

GetUserId           pshs      y         save Y
                    os9       F$ID      get process ids
                    bcc       GetUserIdOk success
GetUserIdErr        puls      y         restore Y
                    lbra      ReturnError return error

GetUserIdOk         tfr       y,d       user id into D
                    puls      pc,y      restore and return

                    pshs      y         save Y
                    bsr       GetUserId get current user id
                    std       -$02,s    stash it below stack
                    beq       SetUserDo already superuser
                    ldb       #$D6      E$Permit not permitted
                    bra       GetUserIdErr return error

SetUserDo           ldy       $04,s     Y = target user id
                    os9       F$SUser   set user id
                    bcc       SetUserOk success
                    cmpb      #$D0      E$UnkSvc unsupported
                    bne       GetUserIdErr other error
                    tfr       y,d       user id into D
                    ldy       >$004B    load globals pointer
                    std       $09,y     cache user id in globals
SetUserOk           clra                success zero high
                    clrb                success zero low
                    puls      pc,y      restore and return

SetupIntercept      pshs      u         save U
                    tfr       y,u       U = global base
                    ldx       $04,s     X = handler address
                    stx       $08A3,y   save handler pointer
                    leax      >InterceptHandler,pcr X = intercept trampoline
                    os9       F$Icpt    install signal intercept
                    puls      u         restore U
                    lbra      ReturnStatus return status

InterceptHandler    tfr       u,y       restore global base
                    clra                clear high byte
                    pshs      d         push signal argument
                    jsr       [$08A3,y] call user signal handler
                    leas      $02,s     drop argument
                    rti                 return from intercept

ReturnError         clra                clear high byte
                    std       $0364,y   store errno
                    ldd       #$FFFF    return -1
                    rts                 return error

ReturnStatus        bcs       ReturnError carry set, return error
                    clra                clear high byte
                    clrb                success zero low
                    rts                 return success

exit                lbsr      ExitFlush run exit hook
                    lbsr      FlushAllBufs flush and close open files
DoExit              ldd       $02,s     D = exit status
                    os9       F$Exit    terminate process
ExitFlush           rts                 return stub

* ------------------------------------------------------------------
* WorkBlockInitImage - cc1-style init image for the work block (see _start):
* rts stub + count/block table + relocation dirs + module-name string.
* ------------------------------------------------------------------
WorkBlockInitImage  fcb       $00,$03,$00,$02 init table / work-block image
                    fcb       $46
                    fcb       $02,$9E,$00,$01,$00,$02,$00,$00
                    fcb       $00,$00,$00,$0C,$00,$00,$00,$00
                    fcb       $00,$00,$00,$00,$00,$00,$00,$00
                    fcb       $00,$00,$00,$00,$00,$00,$00,$8C
                    fcc       /cstr.XXXXX/
                    fcb       $00
                    fcc       /x expected/
                    fcb       $00,$06,$83
                    fcc       /XmXpXsXyX/
                    fcb       $7F
                    fcb       $58
                    fcb       $84,$00,$00,$00,$00,$00,$00,$00
                    fcb       $00,$00,$00,$00,$00,$00,$00,$00
                    fcb       $00,$00,$00,$00,$00,$00,$00,$00
                    fcb       $00,$00,$00,$00,$00,$00,$00,$00
                    fcb       $00
                    fcb       $6D,$40,$69
                    fcb       $00,$00
                    fcc       |TAh-.BP0CESkkkkkkkkkk/(]x_d|
                    fcb       $00
                    fcc       /jjjjjjjjjjjjjjjjjjjjjjjjjj+f,Yj/
